t.guides["forever/alliance/02-westfall"] = (function() return {
		["Back to {area:108}"] = "Zurück nach {area:108}",
		["Defias Pathstalkers and Knuckledusters walk {area:20}; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. {area:1581} entrance in the smithy is a group dungeon."] = "Pfadpirscher und Knöchelhauer der Defias streifen durch {area:20}; Straßenräuber der Defias (Stufe 17) patrouillieren paarweise durch die Hügel südlich und östlich davon: Zieh sie auseinander. Der Eingang zu {area:1581} in der Schmiede ist ein Gruppendungeon.",
		["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}."] = "Plünderer und Ausplünderer der Defias halten die Höfe westlich von {area:108}, zwischen der Küstenstraße und {area:20}.",
		["Fill the vial at the farm's well"] = "Füll die Phiole am Brunnen des Hofs",
		["Fill the vial at the well"] = "Füll die Phiole am Brunnen",
		["Fly or ride to {zone:1453}. {npc:376} is in the Cathedral of Light."] = "Flieg oder reite nach {zone:1453}. {npc:376} ist in der Kathedrale des Lichts.",
		["Fly or ride to {zone:1453}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "Flieg oder reite nach {zone:1453}. {npc:5480} bildet in {object:2100} Krieger aus; {npc:6089} und {npc:6090} stehen dort zusammen bei {object:2152}. {npc:6090} kämpft mit dir um seinen Krug.",
		["Follow the road north. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west."] = "Folge der Straße nach Norden. {npc:233} steht draußen, {npc:235} im Haus, {npc:253395} in der Scheune im Westen.",
		["For {npc:11026} in {zone:1453}'s {object:28027}"] = "Für {npc:11026} in {object:28027} in {zone:1453}",
		["For {npc:266} in {area:69}, Redridge"] = "Für {npc:266} in {area:69}, Rotkammgebirge",
		["Gnoll Paws"] = "Gnolltatzen",
		["Harvest Watchers"] = "Erntebehüter",
		["Hearthstone on cooldown? Follow the road north-east."] = "Ruhestein noch nicht bereit? Folge der Straße nach Nordosten.",
		["Kobold Diggers"] = "Koboldbuddler",
		["Level 12, 14 and 16 spells"] = "Zauber der Stufen 12, 14 und 16",
		["Longshore Murloc Gills"] = "Murlockiemen von Longshore",
		["Murloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time."] = "Murlocküstenläufer und Murlocräuber säumen den Strand nördlich der Mine. Bei wenig Gesundheit fliehen sie: Zieh einen nach dem anderen.",
		["Only if you looted a {item:1972} in Elwynn: right-click it"] = "Nur wenn du in Elwynn {item:1972} geplündert hast: Rechtsklicke sie",
		["Ride to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "Reite nach {zone:1453}. Dort gibt es keinen Schamanenlehrer: Nimm {area:2257} von {object:28027} nach {zone:1455}, trainiere bei {npc:258098} und fahr dann mit der Bahn zurück zum Schiff.",
		["Riverpaw Gnolls and Scouts roam the hills between the coast and the {area:916}."] = "Gnolle und Späher der Flusspfoten streifen durch die Hügel zwischen der Küste und {area:916}.",
		["Riverpaw Miners"] = "Minenarbeiter der Flusspfoten",
		["Sacks of Oats"] = "Hafersäcke",
		["Shaman training"] = "Schamanenausbildung",
		["The gnoll hills"] = "Die Gnollhügel",
		["The north coast"] = "Die Nordküste",
		["The western farms"] = "Die westlichen Höfe",
		["The {area:113}"] = "{area:113}",
		["West of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone. Keep killing Goretusks and Fleshrippers on every leg of this loop."] = "Westlich von Saldeans Hof. Erntebehüter und Erntegolems arbeiten auf den Feldern; sie lassen die Golemisofedern, Gyrostabilisatoren, {item:732} und manchmal {item:255155} fallen. {npc:573}, ein Rare der Stufe 20, läuft hier herum: Lass ihn in Ruhe. Töte auf jedem Abschnitt dieser Runde weiter Geiferzähne und Fleischreißer.",
		["Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way back."] = "Junge Geiferzähne und Fleischreißer streifen über die Felder um den Hof: Fang auf dem Rückweg schon mit Lebern und dem Fleisch für den Eintopf an.",
		["{area:20} and the Defias hills"] = "{area:20} und die Hügel der Defias",
		["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "{item:2449} für Das Heilmittel sammeln (6123) in {zone:1439}: {npc:1313}, Alchemiebedarf; Kräuterkundige pflücken es stattdessen dort",
		["{item:254676}, from the crates around {area:20}"] = "{item:254676}, aus den Kisten rund um {area:20}",
		["{item:6529}, from {npc:5494}"] = "{item:6529}, von {npc:5494}",
		["{item:729}: Fleshrippers"] = "{item:729}: Fleischreißer",
		["{npc:523}; skip the free flight it offers"] = "{npc:523}; überspring den kostenlosen Flug, den er anbietet",
		["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494} verkauft Angelbedarf am Kanal direkt westlich von {object:2096}; {npc:267118} angelt am Hafen, auf dem Weg zum Schiff.",
		["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}, Magiersanktum: {quest:1861}",
		["{quest:153}: every Defias drops them"] = "{quest:153}: Jeder Defias lässt sie fallen",
} end)()
t.guides["forever/alliance/03-darkshore"] = (function() return {
		["At the {area:2362}"] = "Am {area:2362}",
		["Back north-east into the mountains to the crystal."] = "Zurück nach Nordosten in die Berge zum Kristall.",
		["Back south"] = "Zurück nach Süden",
		["Back to {npc:11802}"] = "Zurück zu {npc:11802}",
		["Back to {npc:11802} in {area:2361}, then fly to {area:702} (by way of {area:442})."] = "Zurück zu {npc:11802} in {area:2361}, dann flieg nach {area:702} (über {area:442}).",
		["Bears and the Blackwood camp"] = "Bären und das Lager der Schwarzfelle",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "Pfadfinder und Windsprecher der Schwarzfelle halten das Lager südöstlich von {area:442}.",
		["Blackwood furbolgs"] = "Furbolgs der Schwarzfelle",
		["Boat to {zone:1453}"] = "Boot nach {zone:1453}",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} in the north-west, use it there and speak to {npc:11799}. Then fly back to {area:442} from {area:2361}."] = "Wirke {spell:18960}. {npc:11802} ist in {area:2361}. Schrein-Schmuckstücke liegen in den Behältern am Grund von {area:656}, unterhalb von {area:2361}: Bring eines zum {area:2362} im Nordwesten, benutze es dort und sprich mit {npc:11799}. Flieg dann von {area:2361} zurück nach {area:442}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; learn the flight path there if you do not have it."] = "Wirke {spell:18960}. {npc:11802} ist in {area:2361}; hol dir dort die Flugroute, falls du sie noch nicht hast.",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Klettere östlich von {area:447} in die östlichen Berge; der {object:175524} liegt auf einem Felsvorsprung.",
		["Crawler Legs"] = "Kriecherbeine",
		["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "Eskortiere sie aus der Gleve; Therysil nimmt die Abgabe in {zone:1440} entgegen",
		["Fill the tube at the moonwell in the village"] = "Fülle die Phiole am Mondbrunnen im Dorf",
		["Fine Moonstalker Pelts"] = "Feine Mondpirscherpelze",
		["Fly from {area:442} to {area:702} and take the portal up to {npc:4217} in the {area:1658}."] = "Flieg von {area:442} nach {area:702} und nimm das Portal hinauf zu {npc:4217} im Gebiet {area:1658}.",
		["Follow the road north."] = "Folge der Straße nach Norden.",
		["Follow the road south. {quest:948} is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "Folge der Straße nach Süden. {quest:948} ist der Uralte am Hain; {npc:270269} und {npc:11218} schlafen neben ihm.",
		["Grell Earrings"] = "Grell-Ohrringe",
		["Grizzled Scalps"] = "Ergraute Skalpe",
		["Grizzled Thistle Bears roam the hills around the Grove; {quest:1003} stands west of it among them."] = "Ergraute Distelbären streifen durch die Hügel rund um den Hain; {quest:1003} steht westlich davon zwischen ihnen.",
		["Hearth to {area:442}"] = "Ruhestein nach {area:442}",
		["Hearthstone on cooldown? Follow the coast road back south."] = "Ruhestein noch nicht bereit? Folge der Küstenstraße zurück nach Süden.",
		["Highborne Relics"] = "Hochgeborenenrelikte",
		["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "Töte Tollwütige Distelbären in den Hügeln östlich von {area:442} und geh dann hinauf zum Furbolglager südöstlich davon: Dort gibt es noch nichts zu töten.",
		["Moonstalker Fangs"] = "Mondpirscher-Fangzähne",
		["Moonstalker Sires prowl the woods around the glaive. The {object:10076} and the {object:12666} sit at the bottom of the crater; {npc:3584} stands on its north side."] = "Mondpirscherpatriarchen streifen durch die Wälder rund um die Gleve. Die {object:10076} und der {object:12666} stehen am Grund des Kraters; {npc:3584} steht an seiner Nordseite.",
		["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower."] = "Mondpirscher streifen durch die Hügel zwischen {quest:954} und dem Turm. {quest:1002} steht auf dem Hügel westlich des Turms.",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "Nachtelfen fliegen von {area:442} nach {area:702}; Himmelsgeborene nehmen das Boot von der Anlegestelle in {area:442} und holen sich dort die Flugroute von Rut'theran. Nimm das Portal hinauf zu {npc:4217} im Gebiet {area:1658}.",
		["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "Nur falls ein Jünger oder Rohling {item:5352} gedroppt hat: Rechtsklicke darauf",
		["Plagued bears"] = "Verseuchte Bären",
		["Rabid Thistle Bears roam the hills just east of {area:442}. Use {quest:2139} on one and lead it back to him."] = "Tollwütige Distelbären streifen durch die Hügel gleich östlich von {area:442}. Benutze {quest:2139} an einem und führe ihn zu ihm zurück.",
		["Scaber Stalks"] = "Schorfstänglinge",
		["She gives you the {item:15826}"] = "Sie gibt dir die {item:15826}",
		["Take the portal up to {npc:4217}, then fly back to {area:442} for the boat to {zone:1453}."] = "Nimm das Portal hinauf zu {npc:4217} und flieg dann zurück nach {area:442} zum Boot nach {zone:1453}.",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "Die Lunarfungusblüten wachsen in den Moonkinhöhlen in den Hügeln gleich östlich von {area:442}; die Moonkin dort sind reizbar. {item:2449} erfordert {skill:182}: Kräuterkundige pflücken es überall in {zone:1439}, alle anderen bringen es aus {zone:1453} ({npc:1313}) oder aus dem Auktionshaus mit.",
		["The WANTED poster"] = "Der Steckbrief",
		["The WANTED poster outside the inn"] = "Der Steckbrief vor dem Gasthaus",
		["The bay wrecks"] = "Die Wracks in der Bucht",
		["The beach"] = "Der Strand",
		["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "Das Boot legt westlich des Dorfes an. Der Flugmeister steht auf dem Hügel südlich des Gasthauses; die Questgeber sind entlang der Hauptstraße verteilt.",
		["The cave and the {npc:6788}"] = "Die Höhle und die {npc:6788}",
		["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls; {object:177624} lies at the satyr camp north of her."] = "Die Höhle liegt südlich der Fälle: Überall darin wachsen Schorfstängel, {item:5270} ganz hinten. {npc:6788} haust in den Hügeln südlich der Fälle; {object:177624} liegt im Satyrlager nördlich von ihr.",
		["The flame burns in the south of {area:447}."] = "Die Flamme brennt im Süden von {area:447}.",
		["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "Die Anhängerhälften liegen in {zone:1439} und {zone:1436}: später auf der Route",
		["The naga"] = "Die Naga",
		["The red crystal"] = "Der rote Kristall",
		["The relics of the Barrow Dens"] = "Die Relikte der Grabhügel",
		["The skeletal turtle"] = "Die Skelettschildkröte",
		["The southern beaches"] = "Die südlichen Strände",
		["The {area:443}"] = "Zum Gebiet {area:443}",
		["The {area:448}"] = "Zum Ort {area:448}",
		["The {object:10076}"] = "Die {object:10076}",
		["The {object:12666}"] = "Der {object:12666}",
		["The {object:16393}"] = "Die {object:16393}",
		["Thresher Eyes"] = "Drescheraugen",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Gezeitenkriecher krabbeln unterhalb des Dorfes am Ufer entlang; {quest:983} steht am Strand gleich südlich der Anlegestelle. Dunkelküstendrescher schwimmen im seichten Wasser. {object:175207} liegt gleich südlich des Dorfes am Ufer.",
		["Two wrecks lie on the sea floor in the bay north of {area:442}; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore."] = "Zwei Wracks liegen auf dem Meeresgrund in der Bucht nördlich von {area:442}; in jedem steckt eine Schließkassette. Riffkriecher und Verkrustete Gezeitenkriecher säumen dieses Ufer.",
		["{area:450} lies on the coast south of {npc:10323}'s beach. Protect the prospector while he searches for the fossil."] = "{area:450} liegt an der Küste südlich des Strands von {npc:10323}. Beschütze den Ausgrabungsleiter, während er nach dem Fossil sucht.",
		["{item:12238}: fish from the pier"] = "{item:12238}: vom Steg aus angeln",
		["{item:12289}, on the beach west of the docks"] = "{item:12289}, am Strand westlich der Anlegestelle",
		["{item:12349}, at the waterfall"] = "{item:12349}, am Wasserfall",
		["{item:12355}, in {object:177624}"] = "{item:12355}, in {object:177624}",
		["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845}: am Eingang der Höhle bei den Fällen",
		["{item:15851} and {item:2449}"] = "{item:15851} und {item:2449}",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, aus einem {object:177785} im See",
		["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883}: die {object:177792} unter Wasser vor der Nordküste, westlich der Ruinen",
		["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279}: Twilight-Jünger und -Rohlinge",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: Satyrn der Deth'ryll",
		["{item:5348}: Dark Strand Fanatics"] = "{item:5348}: Fanatikerinnen des dunklen Strangs",
		["{npc:10216}, on the pier: only with {skill:356}"] = "{npc:10216}, auf dem Steg: nur mit {skill:356}",
		["{npc:10323}'s beach"] = "Der Strand von {npc:10323}",
		["{npc:11218}: his escort to {area:413} is done on the {zone:1440} leg"] = "{npc:11218}: Seine Eskorte nach {area:413} erledigst du auf dem Abschnitt in {zone:1440}",
		["{npc:11802}: the welcome from Sheldras"] = "{npc:11802}: der Willkommensgruß von Sheldras",
		["{npc:12298}: use the {item:15826} on them; they roam all of {zone:1439}"] = "{npc:12298}: Benutze die {item:15826} an ihnen; sie streifen durch ganz {zone:1439}",
		["{npc:3616}, at the Grove"] = "{npc:3616}, am Hain",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639} steht am Nordrand der Ruinen. Verfluchte und Zuckende Hochgeborene sowie {npc:2178} spuken dort; der Geist von {npc:3667} wandelt zwischen ihnen, die Eule {npc:270196} kreist östlich davon. Die beiden Schrifttafeln liegen in den Ruinen; eine {quest:4722} liegt westlich davon am Ufer.",
		["{npc:3644}, on the pier"] = "{npc:3644}, auf dem Steg",
		["{npc:3649}, north end of the village"] = "{npc:3649}, am Nordende des Dorfes",
		["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}: für {npc:1646} in {zone:1453}",
		["{npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}."] = "{npc:3661} versteckt sich am Fuß des Turms zwischen den Fanatikerinnen des dunklen Strangs. Behalte seinen Brief für Delgren in {zone:1440}.",
		["{npc:3666}, by the inn"] = "{npc:3666}, beim Gasthaus",
		["{npc:3692} hides in the hills east of the {area:449}. Help him back to the road; he fights on his way out."] = "{npc:3692} versteckt sich in den Hügeln östlich vom Ort {area:449}. Hilf ihm zurück zur Straße; er kämpft sich hinaus.",
		["{npc:3694}: for {npc:3691} in {area:415}, on the later {zone:1440} leg"] = "{npc:3694}: für {npc:3691} in {area:415}, später auf dem Abschnitt in {zone:1440}",
		["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122}: Fülle das Probenfläschchen an den {area:445}",
		["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394} (Nachtelfen) und der {npc:272054} (Himmelsgeborene) warten im Süden von {area:493}. Die drei Relikte liegen östlich davon in {area:2363}. Berichten aus den ersten Wochen zufolge gibt ein Relikt keine Beute, während ein anderer Spieler es plündert: Warte einen Moment und versuch es erneut.",
} end)()
t.guides["forever/alliance/04-redridge-mountains"] = (function() return {
		["Back to {area:69}"] = "Zurück nach {area:69}",
		["Cross the long bridge north into town. {npc:341} and {npc:382} stand at the north end of the bridge, {npc:900} in the town hall, {npc:381} and {npc:266} on the docks, {npc:343} at the inn, {npc:342} in her garden at the west end."] = "Überquere die lange Brücke nach Norden in den Ort. {npc:341} und {npc:382} stehen am Nordende der Brücke, {npc:900} im Rathaus, {npc:381} und {npc:266} an den Docks, {npc:343} im Gasthaus, {npc:342} in ihrem Garten am Westende.",
		["East past the mill and across the river. Shadowhide gnolls fill the valley; {npc:703} (26, well above you) leads them at its north end: clear his escort first and fight him at full health. Stay out of {area:2099} to the south: its orcs are elite."] = "Nach Osten an der Mühle vorbei und über den Fluss. Gnolle der Schattenfelle füllen das Tal; {npc:703} (26, deutlich über dir) führt sie an dessen Nordende an: Räum zuerst seine Begleiter weg und kämpfe mit voller Gesundheit gegen ihn. Bleib aus {area:2099} im Süden fern: Dessen Orcs sind Elite.",
		["Fly to {area:108} and ride north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then ride east along the road through Elwynn to Redridge."] = "Flieg nach {area:108} und reite nach Nordwesten zur Küste: {object:177790} liegt vor dem Ufer auf dem Meeresgrund. Reite dann auf der Straße nach Osten durch den Wald von Elwynn ins Rotkammgebirge.",
		["Follow the road along the south shore of {area:68} to the gryphon master. {npc:1070} and {npc:903} stand by the road next to her."] = "Folge der Straße am Südufer von {area:68} zur Greifenmeisterin. {npc:1070} und {npc:903} stehen neben ihr an der Straße.",
		["For {npc:3649}, on the return to {area:442} (06-ashenvale)"] = "Für {npc:3649}, bei der Rückkehr nach {area:442} (06-ashenvale)",
		["Gnolls toward {area:1002}"] = "Gnolle Richtung {area:1002}",
		["Greater Tarantulas crawl on the slopes around the mill north-east of the lake; Blackrock Renegades hold the mill itself."] = "Große Taranteln krabbeln an den Hängen um die Mühle nordöstlich des Sees; Renegaten der Blackrock halten die Mühle selbst.",
		["Head north out of {area:69} up the {area:95} to {area:997}. Blackrock Champions camp in the valley."] = "Geh von {area:69} nach Norden die {area:95} hinauf ins {area:997}. Helden der Blackrock lagern im Tal.",
		["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to {area:69}; Blackrock orcs ambush you on the way."] = "Keeshan versteckt sich ganz am Nordende des Tals, an der Grenze zu {zone:1428}. Eskortiere ihn hinunter nach {area:69}; Orcs der Blackrock lauern dir unterwegs auf.",
		["Lake murlocs"] = "Murlocs am See",
		["Level 18 and 20 spells"] = "Zauber der Stufen 18 und 20",
		["Murloc Flesheaters and Tidecallers line the south shore east of the bridge. Any of them can carry a {item:1467} or a fin."] = "Murlocfleischfresser und Murlocgezeitenrufer säumen das Südufer östlich der Brücke. Jeder von ihnen kann {item:1467} oder eine Flosse tragen.",
		["Redridge Mongrels and other gnolls hold the hills east of {area:1002}, north of the road; Redridge Thrashers prowl among them, Poachers camp south of the road. Dire Condors and Great Goretusks roam the same hills."] = "Bastarde der Rotkammgnolle und andere Gnolle halten die Hügel östlich von {area:1002}, nördlich der Straße; Hauer der Rotkammgnolle streifen zwischen ihnen umher, Wilderer lagern südlich der Straße. Terrorkondore und Große Geiferzähne streifen durch dieselben Hügel.",
		["Shaman training"] = "Schamanentraining",
		["Swim east from the bridge into {area:68}; the chest lies on the lake bed."] = "Schwimm von der Brücke nach Osten in {area:68}; die Truhe liegt auf dem Seegrund.",
		["The Wanted poster by the inn: {npc:703}, in {area:1000}"] = "Der Steckbrief am Gasthaus: {npc:703}, im {area:1000}",
		["The road from Elwynn enters Redridge at {area:1002}. {npc:464} stands where the roads to Redridge and {zone:1431} meet."] = "Die Straße aus dem Wald von Elwynn erreicht das Rotkammgebirge bei {area:1002}. {npc:464} steht dort, wo sich die Straßen ins Rotkammgebirge und nach {zone:1431} treffen.",
		["The {area:442} boat docks at {area:17203}. Walk up into the city for training and {npc:1646}, then leave by the main gate and follow the road east through {zone:1429}."] = "Das Schiff aus {area:442} legt im {area:17203} an. Geh in die Stadt hinauf zum Training und zu {npc:1646}, verlass sie dann durchs Haupttor und folge der Straße nach Osten durch den {zone:1429}.",
		["{item:1075}: any Shadowhide gnoll"] = "{item:1075}: jeder Gnoll der Schattenfelle",
		["{item:15882}: the {object:177790}"] = "{item:15882}: {object:177790}",
		["{item:280911}: Redridge Thrashers"] = "{item:280911}: Hauer der Rotkammgnolle",
		["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}: Thundris' Brief aus {area:442}",
		["{npc:266}, by the docks"] = "{npc:266}, an den Docks",
		["{npc:332} is at SI:7 in {object:2100}, {npc:6122} in the {object:2164}'s cellar in the {object:2101}, {npc:376} in the Cathedral of Light."] = "{npc:332} ist bei SI:7 in {object:2100}, {npc:6122} im Keller von {object:2164} in {object:2101}, {npc:376} in der Kathedrale des Lichts.",
		["{npc:332}: {npc:7024} in {zone:1436} takes it, at the end of {zone:1431}"] = "{npc:332}: {npc:7024} in {zone:1436} nimmt sie an, am Ende von {zone:1431}",
		["{npc:344}, in the town hall"] = "{npc:344}, im Rathaus",
		["{npc:345} (level 24) roots around the pen just west of {area:69}. Pull him away from the other boars and fight at full health."] = "{npc:345} (Stufe 24) wühlt am Pferch gleich westlich von {area:69}. Lock ihn von den anderen Ebern weg und kämpfe mit voller Gesundheit.",
		["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376}: {npc:11401} in {zone:1457} nimmt sie an, später",
		["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376}: {npc:11406} in {zone:1455} nimmt sie an, später",
		["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376}: {npc:258785} in {zone:1455} nimmt sie an, später",
		["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122}: {npc:6244} in {zone:1413} nimmt sie an, später",
		["{npc:903}, by the gryphons south of the bridge"] = "{npc:903}, bei den Greifen südlich der Brücke",
		["{zone:1431} is next: follow the road west to {area:1002}, then south to {area:42}."] = "Als Nächstes {zone:1431}: Folge der Straße nach Westen bis {area:1002}, dann nach Süden nach {area:42}.",
		["{zone:1453} class quests"] = "Klassenquests in {zone:1453}",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back."] = "{zone:1453} hat keinen Schamanenlehrer: Nimm {area:2257} vom {object:28027} nach {zone:1455}, trainiere bei {npc:258098} und fahr dann mit der Bahn zurück.",
} end)()
t.guides["forever/alliance/05-duskwood"] = (function() return {
		["/lay down beside {npc:7207}"] = "/hinlegen neben {npc:7207}",
		["Back to {area:42}"] = "Zurück nach {area:42}",
		["Continue west to {area:94}. The {object:673515} glows by the ruined house south of the road."] = "Geh weiter nach Westen nach {area:94}. Die {object:673515} leuchtet beim zerstörten Haus südlich der Straße.",
		["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters."] = "Jeder Ghul der nördlichen Hälfte des {area:492} kann eine Rippe fallen lassen: Fleischfresser, Knochenkauer, Seuchenverbreiter und Hirnfresser.",
		["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "Folge der Straße nach Nordwesten am Friedhof vorbei zu {npc:311}s Lager am äußersten Westrand des Waldes. {npc:893} steht neben {npc:311}.",
		["Follow the road south from {area:1002} into {zone:1431}; {area:42} lies on the east side of the forest."] = "Folge der Straße von {area:1002} nach Süden in den {zone:1431}; {area:42} liegt auf der Ostseite des Waldes.",
		["Ghoul Ribs"] = "Ghulrippen",
		["Her house stands on the hill south-east of {area:42}, above the {area:121}."] = "Ihr Haus steht auf dem Hügel südöstlich von {area:42}, oberhalb des {area:121}.",
		["Level 22 and 24 spells"] = "Zauber der Stufen 22 und 24",
		["Next: {zone:1453} for training, then the boat from {area:17203} to {area:442} for {zone:1440}."] = "Als Nächstes: {zone:1453} zum Trainieren, dann das Boot vom {area:17203} nach {area:442} für {zone:1440}.",
		["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders crawl east of the cemetery and drop the venom. Every ghoul of the cemetery's northern half can drop a fang."] = "Tollwütige Terrorwölfe streifen durch den Wald um den Friedhof und {npc:289}, Ausgehungerte Terrorwölfe durch die Hügel nordöstlich von ihm. Zwerggiftweberspinnen krabbeln östlich des Friedhofs und lassen das Gift fallen. Jeder Ghul der nördlichen Friedhofshälfte kann einen Fangzahn fallen lassen.",
		["Ride back east along the road to the {area:245}."] = "Reite die Straße zurück nach Osten zum {area:245}.",
		["Ride back east to {area:42}."] = "Reite zurück nach Osten nach {area:42}.",
		["Ride north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "Reite nach Norden durch den Wald von Elwynn nach {zone:1453}; Mathias Shaw ist bei SI:7 in {object:2100}.",
		["Ride west along the road once more."] = "Reite noch einmal die Straße nach Westen.",
		["Ride west along the road out of {area:94} into {zone:1436}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "Reite die Straße nach Westen aus {area:94} hinaus nach {zone:1436}. {npc:7024} beobachtet den Turm von {npc:7053} von den Hügeln gleich hinter der Grenze. Die {npc:7051} (Stufe 23), die den Turm bewacht, trägt den Schlüssel; Klavens Tagebuch liegt in der Truhe ganz oben.",
		["Ride west to the hermit once more."] = "Reite noch einmal nach Westen zum Einsiedler.",
		["Rot Blossoms"] = "Fäulnisblüten",
		["Shaman training"] = "Schamanentraining",
		["Skeletal Horrors walk the hillside between {area:42} and the {area:121}, south-east of town; they drop the Rot Blossoms."] = "Skelettschrecken wandeln am Hang zwischen {area:42} und dem {area:121}, südöstlich des Orts; sie lassen die Fäulnisblüten fallen.",
		["Skeletal Warriors and Skeletal Mages walk among the graves south-east of {area:42}, below {npc:302}'s house on the hill. Every skeleton in {zone:1431} can drop a {item:2378}."] = "Skelettkrieger und Skelettmagier wandeln zwischen den Gräbern südöstlich von {area:42}, unterhalb des Hauses von {npc:302} auf dem Hügel. Jedes Skelett im {zone:1431} kann einen {item:2378} fallen lassen.",
		["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "Der Friedhof liegt nördlich des Dorfs. Skelettschrecken und Skelettsatanskreaturen wandeln in seiner südlichen Hälfte. {npc:522}, ein Elite, wandert zwischen den Gräbern: Halte dich von ihm fern.",
		["The hermit's shack stands in the woods north-east of the {area:492}."] = "Die Hütte des Einsiedlers steht im Wald nordöstlich des {area:492}.",
		["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "Der Haufen lockerer Erde liegt südlich des Bauernhauses, beim alten Baumstumpf.",
		["Train in {zone:1453}, north through {zone:1429}. Then take the boat from {area:17203} to {area:442}."] = "Trainiere in {zone:1453}, nach Norden durch den {zone:1429}. Nimm dann das Boot vom {area:17203} nach {area:442}.",
		["Wolves, spiders and ghouls"] = "Wölfe, Spinnen und Ghule",
		["{area:492}, south"] = "{area:492}, Süden",
		["{item:281046}, from the {object:673515}"] = "{item:281046}, von der {object:673515}",
		["{item:3372}: {npc:1313}, Alchemy Supplies"] = "{item:3372}: {npc:1313}, Alchemiebedarf",
		["{item:4371}, from {npc:3133}: limited stock. Sold out? {npc:1448} in {area:150} sells it too."] = "{item:4371}, von {npc:3133}: begrenzter Vorrat. Ausverkauft? {npc:1448} in {area:150} verkauft sie auch.",
		["{item:7908}, in the chest"] = "{item:7908}, in der Truhe",
		["{npc:2409}, at the north end of town"] = "{npc:2409}, am Nordende des Orts",
		["{npc:264}, in the town hall"] = "{npc:264}, im Rathaus",
		["{npc:265}, in her house by the tavern"] = "{npc:265}, in ihrem Haus bei der Taverne",
		["{npc:267}, in the town hall"] = "{npc:267}, im Rathaus",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, im Haus hinter dem Rathaus",
		["{npc:273}, in the tavern"] = "{npc:273}, in der Taverne",
		["{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "{npc:276}s Haus steht am Ostende des Orts. {npc:3133} verkauft Ingenieursbedarf im Haus daneben.",
		["{npc:288} hides in the house at the west end of {area:94}."] = "{npc:288} versteckt sich im Haus am Westende von {area:94}.",
		["{npc:332}: Poisons, and {item:18160}"] = "{npc:332}: Gifte und {item:18160}",
		["{npc:633}, at the south end of town"] = "{npc:633}, am Südende des Orts",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, Taverne Zum Scharlachroten Raben",
		["{npc:888} stands south of the road, at the {area:245}."] = "{npc:888} steht südlich der Straße, beim {area:245}.",
		["{quest:2607}: {npc:7207}, in the cellar of the Barracks"] = "{quest:2607}: {npc:7207}, im Keller der Kaserne",
		["{quest:337}: a rare drop from {zone:1431}'s mobs"] = "{quest:337}: seltene Beute von Gegnern im {zone:1431}",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the {area:442} boat."] = "{zone:1453} hat keinen Schamanenlehrer: Nimm die {area:2257} vom {object:28027} nach {zone:1455}, trainiere bei {npc:258098} und fahr dann mit der Bahn zurück zum Boot nach {area:442}.",
} end)()
t.guides["forever/alliance/06-ashenvale"] = (function() return {
		["Back to the Cathedral of Light: {npc:928} stands inside."] = "Zurück zur Kathedrale des Lichts: {npc:928} steht drinnen.",
		["Black Oozes"] = "Schwarze Brühschlammer",
		["Black Oozes creep through the marsh north of the {area:1025} road, west of {npc:2093}'s camp. Any ooze may hold {npc:2111}'s bag."] = "Schwarze Brühschlammer kriechen durch den Sumpf nördlich der Straße durch {area:1025}, westlich von {npc:2093}s Lager. Jeder Schlammer kann den Beutel von {npc:2111} haben.",
		["Boat to {area:150}"] = "Schiff nach {area:150}",
		["Cathedral of Light"] = "Kathedrale des Lichts",
		["Cave Stalkers and Leech Stalkers fill {area:1021}, the cave south-east of the excavation site."] = "Höhlenpirscher und Egelpirscher füllen {area:1021}, die Höhle südöstlich der Ausgrabungsstätte.",
		["Dragonmaw camp"] = "Lager der Dragonmaw",
		["Escort Kerlonian to {area:413} in {zone:1440}."] = "Eskortiere Kerlonian zu {area:413} in {zone:1440}.",
		["Fen Creepers"] = "Moorkrabbler",
		["Fen Creepers hide in the marsh pools north-west of the {area:1025}."] = "Moorkrabbler verstecken sich in den Sumpftümpeln nordwestlich von {area:1025}.",
		["Follow the coast north out of Menethil. Bluegill Murlocs fill the marsh; {npc:1259} walks with a pack in the middle of it."] = "Folge der Küste von Menethil aus nach Norden. Murlocs der Blaukiemen füllen den Sumpf; {npc:1259} zieht mit einer Gruppe mitten hindurch.",
		["Follow the coast north to the {area:414}. {npc:3846} camps on the beach; Wrathtail nagas fill the shore."] = "Folge der Küste nach Norden zum {area:414}. {npc:3846} lagert am Strand; Naga der Rächerflossen bevölkern das Ufer.",
		["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "Folge der Straße nach Osten zu {area:419}; {npc:3916} steht am Mondbrunnen.",
		["Follow the road east. Young Wetlands Crocolisks lurk in the pools north of the excavation site."] = "Folge der Straße nach Osten. Junge Sumpflandkrokilisken lauern in den Tümpeln nördlich der Ausgrabungsstätte.",
		["Follow the road north to {area:205}, at the foot of the {area:881}. {npc:1071} stands in the dwarves' camp."] = "Folge der Straße nach Norden nach {area:205}, am Fuß von {area:881}. {npc:1071} steht im Lager der Zwerge.",
		["Follow the road south-east to {area:415}, on the island in the lake."] = "Folge der Straße nach Südosten nach {area:415}, auf der Insel im See.",
		["For Bolvar Fordragon in {object:2117}: keep it"] = "Für Bolvar Fordragon in {object:2117}: behalte sie",
		["For the giant crocolisks of the north coast, on your next visit"] = "Für die Riesigen Sumpflandkrokilisken der Nordküste, bei deinem nächsten Besuch",
		["For {npc:2228} in {area:271}: keep it"] = "Für {npc:2228} in {area:271}: behalte es",
		["From {area:17203} take the boat to {area:442}; {npc:3649} stands at the north end of the village. Then ride south along the road through {zone:1439}."] = "Nimm vom {area:17203} das Schiff nach {area:442}; {npc:3649} steht am Nordende des Dorfes. Reite dann auf der Straße nach Süden durch {zone:1439}.",
		["Hearth to Menethil"] = "Ruhestein nach Menethil",
		["Hearthstone on cooldown? Ride back north through the {area:1276}."] = "Ruhestein noch nicht bereit? Reite nach Norden zurück durch {area:1276}.",
		["Kerlonian sleeps at the {area:448} in southern {zone:1439}. Use the {item:13536} to wake him and lead him south along the road into {zone:1440} to {npc:11219} at {area:413}; blow the horn again whenever he falls asleep."] = "Kerlonian schläft bei {area:448} im Süden von {zone:1439}. Benutze {item:13536}, um ihn zu wecken, und führe ihn auf der Straße nach Süden nach {zone:1440} zu {npc:11219} bei {area:413}; blas erneut ins Horn, wann immer er einschläft.",
		["Kill the elementals for 5 Intact Elemental Bracers, then use the {item:5456}"] = "Töte die Elementare für 5 intakte Elementararmschienen und benutze dann {item:5456}",
		["Mosshide Fenrunners and Mistweavers roam the riverbanks just west and south of {npc:1244}; almost every one drops flint."] = "Moorläufer der Moosfelle und Nebelwirker der Moosfelle streifen an den Flussufern gleich westlich und südlich von {npc:1244} umher; fast jeder lässt Feuerstein fallen.",
		["Mosshide Gnolls and Mongrels hold the hills south-east of the {area:1025}."] = "Gnolle der Moosfelle und Bastarde der Moosfelle halten die Hügel südöstlich von {area:1025}.",
		["Mottled Raptors and Screechers roam the hills west of the excavation site."] = "Scheckige Raptoren und Scheckige Kreischer streifen durch die Hügel westlich der Ausgrabungsstätte.",
		["Next: fly to {area:42}."] = "Als Nächstes: Flieg nach {area:42}.",
		["North of Maestra's Post, plant bundles lie around the ruins of {area:411}. Dark Strand cultists hold the ruins just south of them: any of them can drop the {item:5366}."] = "Nördlich von Maestras Posten liegen Pflanzenbündel um die Ruinen von {area:411}. Kultisten des dunklen Strangs halten die Ruinen gleich südlich davon: Jeder von ihnen kann {item:5366} fallen lassen.",
		["Only if you looted {quest:337} in {zone:1431}"] = "Nur wenn du {quest:337} in {zone:1431} erbeutet hast",
		["Only with {item:5352} from {zone:1439}: {npc:2786}, the {object:32383}"] = "Nur mit {item:5352} aus {zone:1439}: {npc:2786}, {object:32383}",
		["Raptor valley"] = "Raptorental",
		["Ride east along the {zone:1437} road, south through {area:836} into {zone:1432} and west through the tunnel into {zone:1426} to {area:1537}."] = "Reite auf der Straße durch {zone:1437} nach Osten, nach Süden durch {area:836} nach {zone:1432} und nach Westen durch den Tunnel nach {zone:1426} bis {area:1537}.",
		["Ride south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}. {npc:4080} and {npc:4077} camp on the {area:1076} south-west of the crag."] = "Reite nach Süden an {area:421} vorbei in den Tunnel {area:1276}; er führt im Steinkrallengebirge bei {area:461} heraus. {npc:4080} und {npc:4077} lagern am {area:1076} südwestlich der Klippe.",
		["Ride west to the shore of {area:441}. Teronis lies among the Saltspittle murlocs; any murloc can drop the {item:5463}."] = "Reite nach Westen ans Ufer von {area:441}. Teronis liegt zwischen den Murlocs der Salzflossen; jeder Murloc kann {item:5463} fallen lassen.",
		["South of the murlocs, {npc:3585} waits at the {area:416}."] = "Südlich der Murlocs wartet {npc:3585} bei {area:416}.",
		["Take the boat from {area:17203} to {area:442} and fly to {area:702}; {npc:11401} is in the Temple of the Moon. Then fly back to {area:442}."] = "Nimm das Schiff vom {area:17203} nach {area:442} und flieg nach {area:702}; {npc:11401} ist im Tempel des Mondes. Flieg dann zurück nach {area:442}.",
		["Take the boat from {area:17203} to {area:442}. Join the two half pendants into the {item:15885} and cast {spell:18960}: {npc:11802} is in {area:2361}. Then fly to {area:702} (by way of {area:442})."] = "Nimm das Schiff vom {area:17203} nach {area:442}. Füge die beiden Anhängerhälften zu {item:15885} zusammen und wirke {spell:18960}: {npc:11802} ist in {area:2361}. Flieg dann nach {area:702} (über {area:442}).",
		["Take the portal up to the {area:1658}, then fly back to {area:442}."] = "Nimm das Portal hinauf nach {area:1658} und flieg dann zurück nach {area:442}.",
		["Take the {area:2257} from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "Nimm {area:2257} von {object:171524} zu {object:28027} in {zone:1453} und geh dann zu {object:2098}.",
		["The Bluegill hovels"] = "Die Hütten der Blaukiemen",
		["The Dragonmaw camp lies south of the road, just west of the {area:1025}: Raiders, Swamprunners and Bonewarders. {npc:2092}'s quest in {zone:1426} needs level 28."] = "Das Lager der Dragonmaw liegt südlich der Straße, gleich westlich von {area:1025}: Räuber, Sumpfläufer und Knochenwärter der Dragonmaw. Die Quest von {npc:2092} in {zone:1426} erfordert Stufe 28.",
		["The Foulweald"] = "Die Fäulnisklauen",
		["The Foulweald furbolgs live in the woods south of the road, south-east of {area:415}. The Den Watcher and the Ursas guard the den."] = "Die Furbolgs der Fäulnisklauen leben in den Wäldern südlich der Straße, südöstlich von {area:415}. Der Höhlenbehüter und die Ursas bewachen die Höhle.",
		["The Mosshide gnolls"] = "Die Gnolle der Moosfelle",
		["The Venture Co. clear the forest of {area:461}. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints."] = "Die Venture Co. rodet den Wald von {area:461}. Holzarbeiter und Roder arbeiten überall; die Maschinenführer steuern die Schredder, und einer trägt die Baupläne.",
		["The bigger raptors hunt in the valley just west of the dig."] = "Die größeren Raptoren jagen im Tal gleich westlich der Ausgrabung.",
		["The excavation site sits on the hill south of the road."] = "Die Ausgrabungsstätte liegt auf dem Hügel südlich der Straße.",
		["The raptor hills"] = "Die Raptorenhügel",
		["The tears glow on the small isle east of {area:415}."] = "Die Tränen leuchten auf der kleinen Insel östlich von {area:415}.",
		["Three containers in the murloc hovels, south to north: the {object:261}, then the {object:142151}, then the {object:259} at the north end."] = "Drei Behälter in den Murlochütten, von Süden nach Norden: {object:261}, dann {object:142151}, dann {object:259} am Nordende.",
		["Timber and iron piles lie around the keep and along the harbor's walls."] = "Holz- und Eisenstapel liegen um die Burg und entlang der Hafenmauern.",
		["To {area:150}"] = "Nach {area:150}",
		["Venture Co. loggers"] = "Holzarbeiter der Venture Co.",
		["West of Mystral Lake, the stardust bushes grow among the ruins."] = "Westlich vom Mystralsee wachsen die Sternenstaubbüsche zwischen den Ruinen.",
		["Young crocolisks"] = "Junge Krokilisken",
		["grind on Dragonmaw Raiders and Swamprunners at the Dragonmaw camp, {zone:1437}"] = "grinde Räuber und Sumpfläufer der Dragonmaw im Lager der Dragonmaw, {zone:1437}",
		["{item:15885}: join the two halves"] = "{item:15885}: Füge die beiden Hälften zusammen",
		["{item:5424}, in the ruins on the shore"] = "{item:5424}, in den Ruinen am Ufer",
		["{npc:11406} and {npc:258785} are in the {object:32386}, in the {object:32362}."] = "{npc:11406} und {npc:258785} sind in {object:32386}, in {object:32362}.",
		["{npc:1239}, in the inn"] = "{npc:1239}, im Gasthaus",
		["{npc:1242}, on the pier north of the inn"] = "{npc:1242}, auf dem Pier nördlich des Gasthauses",
		["{npc:1242}: for {npc:2104} in the keep"] = "{npc:1242}: für {npc:2104} in der Burg",
		["{npc:1440}, in the Royal Library"] = "{npc:1440}, in der Königlichen Bibliothek",
		["{npc:1444}, in the {object:2098}"] = "{npc:1444}, auf {object:2098}",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}, bei {object:32372}",
		["{npc:2086}, by the keep"] = "{npc:2086}, bei der Burg",
		["{npc:2093} camps by the road; {npc:1244} stands farther east, by the river."] = "{npc:2093} lagert an der Straße; {npc:1244} steht weiter östlich am Fluss.",
		["{npc:2094}, by the north gate"] = "{npc:2094}, beim Nordtor",
		["{npc:2096}, by the north gate"] = "{npc:2096}, beim Nordtor",
		["{npc:2097}, by the north gate"] = "{npc:2097}, beim Nordtor",
		["{npc:2104} stands in {area:2103}, a short walk from {npc:1242}."] = "{npc:2104} steht in {area:2103}, ein kurzes Stück von {npc:1242} entfernt.",
		["{npc:3649}: Alexston's reply"] = "{npc:3649}: Alexstons Antwort",
		["{npc:3664} and his voidwalkers hold the {area:412} south of the shrine. Pull his guards first."] = "{npc:3664} und seine Leerwandler halten {area:412} südlich des Schreins. Lock zuerst seine Wachen.",
		["{npc:3691}, in the inn"] = "{npc:3691}, im Gasthaus",
		["{npc:3885} stands at the {area:420} on the east shore of {area:421}; {npc:210995} camps on its west shore. Befouled Water Elementals wade in the lake between them."] = "{npc:3885} steht bei {area:420} am Ostufer von {area:421}; {npc:210995} lagert an dessen Westufer. Beschmutzte Wasserelementare waten im See dazwischen.",
		["{npc:3987} (25) leads the Thistlefur gnolls at the camp north of {area:415}. Clear his guards first, one at a time."] = "{npc:3987} (25) führt die Gnolle der Distelfelle im Lager nördlich von {area:415} an. Räum zuerst seine Wachen weg, eine nach der anderen.",
		["{npc:4201}, in the hut north of them"] = "{npc:4201}, in der Hütte nördlich von ihnen",
		["{npc:4276} mines in the {area:2160} at the east end of the crag. Talk to him and fend off the Venture Co. raiders while he mines."] = "{npc:4276} schürft in der {area:2160} am Ostende der Klippe. Sprich mit ihm und wehre die Angreifer der Venture Co. ab, während er schürft.",
		["{npc:482}, the cheese shop in the {object:2096}"] = "{npc:482}, der Käseladen in {object:2096}",
		["{npc:4959} and {npc:482}"] = "{npc:4959} und {npc:482}",
		["{npc:4982}, in the Cathedral of Light"] = "{npc:4982}, in der Kathedrale des Lichts",
		["{object:2164} is in the {object:2101}."] = "{object:2164} ist in {object:2101}.",
		["{quest:1009} walks the northern tip of the {area:414} with Wrathtail guards."] = "{quest:1009} streift mit Wachen der Rächerflossen über die Nordspitze des {area:414}s.",
		["{quest:1010}, from the plant bundles"] = "{quest:1010}, von den Pflanzenbündeln",
		["{zone:1455} priests"] = "Priester in {zone:1455}",
} end)()
t.guides["forever/alliance/07-thousand-needles"] = (function() return {
		["Back to Menethil"] = "Zurück nach Menethil",
		["Back to {area:42}"] = "Zurück nach {area:42}",
		["Bluegill Raiders"] = "Räuber der Blaukiemen",
		["Dragonmaw camp"] = "Lager der Dragonmaw",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Folge den Schluchten nach Osten zur Salzebene. Die Goblins und Gnome der {area:2240} sind neutral und geben beiden Fraktionen Quests.",
		["Follow the coast north to the wrecked ship. Cursed Sailors walk the beach, Cursed Marines the deck; {npc:1159} stands on the beach by the bow. Giant Wetlands Crocolisks lurk on the coast just north of it."] = "Folge der Küste nach Norden zum Schiffswrack. Verfluchte Seemänner wandeln am Strand, Verfluchte Marinesoldaten an Deck; {npc:1159} steht am Strand beim Bug. Riesige Sumpflandkrokilisken lauern an der Küste gleich nördlich davon.",
		["Follow the coast north-east past the wreck: the Bluegill Raiders hold the marsh beyond the Giant Crocolisks."] = "Folge der Küste nach Nordosten am Wrack vorbei: Die Räuber der Blaukiemen halten den Sumpf hinter den Riesigen Krokilisken.",
		["Follow the road east to the excavation site."] = "Folge der Straße nach Osten zu Whelgars Ausgrabungsstätte.",
		["For {npc:1212} in {zone:1453}, in the next guide"] = "Für {npc:1212} in {zone:1453}, im nächsten Guide",
		["For {npc:1284} in {zone:1453}, in the next guide"] = "Für {npc:1284} in {zone:1453}, im nächsten Guide",
		["For {npc:4048} in {zone:1444}, much later"] = "Für {npc:4048} in {zone:1444}, viel später",
		["For {npc:482} in {zone:1453}, in the next guide"] = "Für {npc:482} in {zone:1453}, im nächsten Guide",
		["For {quest:5762} in Stranglethorn, later"] = "Für {quest:5762} im Schlingendorntal, später",
		["From Theramore follow the road west out of Dustwallow into the {zone:1413} and south along it; give {area:378} a wide berth. {area:485} at the {zone:1413}' south end takes you down into {zone:1441}. The journal lies at the foot of the lift."] = "Folge von Theramore der Straße nach Westen aus den Marschen von Dustwallow ins {zone:1413} und dann nach Süden; mach einen großen Bogen um {area:378}. {area:485} am Südende des {zone:1413} bringt dich hinab nach {zone:1441}. Das Tagebuch liegt am Fuß des Aufzugs.",
		["From {npc:352} in {zone:1453}"] = "Von {npc:352} in {zone:1453}",
		["Her house stands on the hill south-east of {area:42}."] = "Ihr Haus steht auf dem Hügel südöstlich von {area:42}.",
		["Nightbane Dark Runners"] = "Dunkelläufer der Nachtheuler",
		["Nightbane Shadow Weavers"] = "Schattenwirker der Nachtheuler",
		["Nightbane Vile Fangs and the {npc:511}"] = "Faulreißer der Nachtheuler und der {npc:511}",
		["No {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too."] = "Kein {item:4371} für {quest:174}? {npc:3133} verkauft sie im Haus neben {npc:276}, in begrenzter Menge; {npc:1448} in {area:150} verkauft sie auch.",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "Auf der Straße nach Süden durch das {zone:1413} lagert {npc:6244} östlich der Straße, nordöstlich von {area:378}; komm von Osten und halte dich von den Wachen der Horde fern.",
		["Only if a {npc:272273} dropped {quest:96138}: right-click it"] = "Nur falls ein {npc:272273} {quest:96138} fallen ließ: Rechtsklick darauf",
		["Plague Spreaders"] = "Seuchenverbreiter",
		["Ride back west along the road to {area:150}."] = "Reite die Straße zurück nach Westen nach {area:150}.",
		["Ride east to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "Reite nach Osten zum Ogerhügel. {object:119} steht im Lager an seinem Eingang; Oger der Splitterfäuste bewachen sie.",
		["Ride west along the road; the hermit's shack stands north-east of the {area:492}."] = "Reite die Straße nach Westen; die Hütte des Einsiedlers steht nordöstlich des {area:492}.",
		["Skeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of {npc:311}'s camp."] = "Skeletträuber, Skelettheiler und Skelettwärter halten den Westteil des Friedhofs, gleich östlich von {npc:311}s Lager.",
		["Take the boat from Menethil's pier to {area:513} in {zone:1445}."] = "Nimm das Boot vom Pier von Menethil nach {area:513} in den {zone:1445}.",
		["The Dark Runners prowl the woods south of the road, west of {area:42}."] = "Die Dunkelläufer streifen durch die Wälder südlich der Straße, westlich von {area:42}.",
		["The Defias camp lies in the south-west of {zone:1431}, south of {area:94} near the {zone:1436} border. The strongbox stands among the tents."] = "Das Lager der Defias liegt im Südwesten des {zone:1431}, südlich von {area:94} nahe der Grenze zu {zone:1436}. Die Geldkassette steht zwischen den Zelten.",
		["The Dragonmaw orcs camp east of the excavation site. Raiders and Swamprunners carry the war banners."] = "Die Orcs der Dragonmaw lagern östlich der Ausgrabungsstätte. Räuber und Sumpfläufer tragen die Kriegsbanner.",
		["The Plague Spreaders walk the northern half of the {area:492}. {npc:522}, an elite, wanders the graves: keep away from him."] = "Die Seuchenverbreiter wandeln in der nördlichen Hälfte des {area:492}. {npc:522}, ein Elite, wandert zwischen den Gräbern: Halte dich von ihm fern.",
		["The captain walks the deck of the wrecked ship; his strongbox sits in the hold."] = "Der Kapitän wandelt auf dem Deck des Schiffswracks; seine Geldkassette steht im Laderaum.",
		["The dig and {npc:1353}"] = "Die Ausgrabung und {npc:1353}",
		["The relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it."] = "Die Relikte liegen in der Ausgrabung selbst. {npc:1353}, ein großer Scharfzahn, streift durch das Raptorental gleich westlich davon.",
		["The salt flats"] = "Die Salzebene",
		["The strongest worgen roam the woods south of {area:42}, west and south of the {area:121}. The {npc:511} hides in the small crypt by the cemetery."] = "Die stärksten Worgen streifen durch die Wälder südlich von {area:42}, westlich und südlich des {area:121}. Der {npc:511} versteckt sich in der kleinen Gruft beim Friedhof.",
		["The worgen hold the woods of Brightwood, west of {area:42} and north of the road. Pull them one at a time."] = "Die Worgen halten die Wälder des Schattenhains, westlich von {area:42} und nördlich der Straße. Zieh sie einzeln.",
		["The wreck of the Third Fleet"] = "Das Wrack der Dritten Flotte",
		["To Theramore"] = "Nach Theramore",
		["Wait a moment, then speak with her again"] = "Warte einen Moment und sprich sie dann erneut an",
		["{area:492}, west"] = "{area:492}, Westen",
		["{item:2594}, from {npc:1464}"] = "{item:2594}, von {npc:1464}",
		["{item:2661}: the {object:331}"] = "{item:2661}: die {object:331}",
		["{item:4371}, from {npc:3133}, if you have none"] = "{item:4371}, von {npc:3133}, falls du keine hast",
		["{npc:1078} and Whelgar"] = "{npc:1078} und Whelgar",
		["{npc:1217}, upstairs in the inn"] = "{npc:1217}, oben im Gasthaus",
		["{npc:1239}, in the inn"] = "{npc:1239}, im Gasthaus",
		["{npc:2104}, by the keep"] = "{npc:2104}, bei der Burg",
		["{npc:263}, in the town hall"] = "{npc:263}, im Rathaus",
		["{npc:267}, in the town hall"] = "{npc:267}, im Rathaus",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, im Haus hinter dem Rathaus",
		["{npc:276}, at the east end of town"] = "{npc:276}, am Ostende des Orts",
		["{npc:311}'s Camp"] = "{npc:311}s Lager",
		["{npc:4454}: for Martek in the {zone:1418}, later"] = "{npc:4454}: für Martek im {zone:1418}, später",
		["{npc:661}, by {npc:633}'s house"] = "{npc:661}, beim Haus von {npc:633}",
		["{npc:663}, by the town hall"] = "{npc:663}, beim Rathaus",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, Taverne Zum Scharlachroten Raben",
		["{npc:840}, at the north entrance of town"] = "{npc:840}, am Nordeingang des Orts",
		["{object:19868} lies all over the flats. Scorpid Reavers, Sparkleshell Tortoises and Saltstone Basilisks roam the north half, Crystalhides, Scorpid Terrors and Snappers the middle, and the Gazers (34-35, five levels above you: one at a time) the far south. Vultures circle over all of it."] = "{object:19868} liegt überall in der Ebene. Skorpidhäscher, Spiegelpanzerschildkröten und Salzsteinbasilisken streifen durch die Nordhälfte, Salzsteinkristallhäute, Skorpidschrecker und Spiegelpanzerschnapper durch die Mitte und die Salzsteinstarrer (34-35, fünf Stufen über dir: einzeln) durch den äußersten Süden. Salzwüstengeier kreisen über allem.",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}: in {zone:1440}, auf dem Weg nach {zone:1443}",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}: der Inkubus, neben dem Sukkubus; das {item:190309} liegt nahe {quest:1738}",
} end)()
t.guides["forever/alliance/30-40/01-hillsbrad-foothills"] = (function() return {
		["A new {item:279996}, for the four titan watchers around the {zone:1437}"] = "Ein neuer {item:279996}, für die vier Titanenwächter rund um das {zone:1437}",
		["A report for {object:2117}"] = "Ein Bericht für {object:2117}",
		["Back south down the road to the excavation site."] = "Die Straße zurück nach Süden zur Ausgrabungsstätte.",
		["Back to the same murlocs; not every one drops a head."] = "Zurück zu denselben Murlocs; nicht jeder lässt einen Kopf fallen.",
		["Boat to {area:271}"] = "Schiff nach {area:271}",
		["Cathedral of Light"] = "Kathedrale des Lichts",
		["Daggerspine naga"] = "Naga der Säbelflossen",
		["Druid training"] = "Druidenausbildung",
		["Farren"] = "Farren",
		["Fly to {zone:1453}"] = "Flieg nach {zone:1453}",
		["Follow the road east to {area:118}."] = "Folge der Straße nach Osten zu {area:118}.",
		["Follow the road north-east into the {area:1025}: {npc:270637} camps beside it, {npc:1244} a short way east."] = "Folge der Straße nach Nordosten in {area:1025}: {npc:270637} lagert daneben, {npc:1244} ein Stück weiter östlich.",
		["For King Magni in {zone:1455}, at the end of this guide"] = "Für König Magni in {zone:1455}, am Ende dieses Guides",
		["For {npc:2916} in {zone:1455}, at the end of this guide"] = "Für {npc:2916} in {zone:1455}, am Ende dieses Guides",
		["From {npc:2432} in {area:271}"] = "Von {npc:2432} in {area:271}",
		["Level 30 and 32 spells"] = "Zauber der Stufen 30 und 32",
		["Murloc heads"] = "Murlocköpfe",
		["North along the road to {area:205}. {npc:271460} stands in the ruins (use the {item:279996}); the {npc:271481} is held on the west side: lead it out to {npc:1072}."] = "Nach Norden die Straße entlang nach {area:205}. {npc:271460} steht in den Ruinen (benutze {item:279996}); {npc:271481} wird auf der Westseite festgehalten: Führ ihn hinaus zu {npc:1072}.",
		["North-east to the {area:1038}: the {npc:271373} are held there, and {npc:271338} stands at the gates (use the {item:279996})."] = "Nach Nordosten zu {area:1038}: {npc:271373} werden dort festgehalten, und {npc:271338} steht an den Toren (benutze {item:279996}).",
		["Pick up everything in town before heading out. Off the boat, {npc:251493} is the first you meet, north-west of the flight master; {npc:2381} and {npc:2438} stand between the flight master and the inn, Farren and {npc:2366} at the inn, Maleb in the town hall."] = "Nimm im Ort alles mit, bevor du aufbrichst. Vom Schiff aus triffst du zuerst {npc:251493}, nordwestlich des Flugmeisters; {npc:2381} und {npc:2438} stehen zwischen Flugmeister und Gasthaus, Farren und {npc:2366} im Gasthaus, Maleb im Rathaus.",
		["Red whelps fill the hills west of the gates, Maddened Rotclaws the {area:1025}, Razormaws the northern slopes; {npc:271458} stands in the north-east (use the {item:279996}).\n{quest:98283} is elite: grouping up is advised."] = "Rote Welpen füllen die Hügel westlich der Tore, Wahnsinnige Faulklauen ({npc:271334}) {area:1025}, Scharfzähne die nördlichen Hänge; {npc:271458} steht im Nordosten (benutze {item:279996}).\n{quest:98283} ist Elite: Eine Gruppe wird empfohlen.",
		["Snapjaws"] = "Schnappkiefer",
		["Syndicate camp"] = "Syndikatslager",
		["Take the {area:2257} from the {object:28027} to {zone:1455}."] = "Nimm die {area:2257} vom {object:28027} nach {zone:1455}.",
		["The Goaz Warders stand just west of Whelgar's camp: use the {item:279996} he gave you beside one."] = "Die Goazwärter stehen gleich westlich von Whelgars Lager: Benutze neben einem davon {item:279996}, den er dir gegeben hat.",
		["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "Die Schnappkiefer-Schildkröten sonnen sich am Fluss östlich von {area:271}, südlich von {area:272} (Horde).",
		["The Syndicate camp sits on the Alterac border in northern {area:287}, west of {area:272} (Horde); the documents lie in the camp."] = "Das Syndikatslager liegt an der Grenze zu Alterac im Norden von {area:287}, westlich von {area:272} (Horde); die Dokumente liegen im Lager.",
		["The Torn Fin murlocs crowd the {area:295}, south-west of {area:271}."] = "Die Murlocs der Fetzenflossen drängen sich am {area:295}, südwestlich von {area:271}.",
		["The Villards"] = "Die Villards",
		["The cheese shop in the {object:2096}."] = "Der Käseladen im {object:2096}.",
		["The naga hold the shore south-east of {area:271}."] = "Die Naga halten das Ufer südöstlich von {area:271}.",
		["The yetis live in the cave in the hills north of {area:271}, on your way back south."] = "Die Yetis leben in der Höhle in den Hügeln nördlich von {area:271}, auf deinem Rückweg nach Süden.",
		["Torn Fin murlocs"] = "Murlocs der Fetzenflossen",
		["West along the road to Menethil."] = "Nach Westen die Straße entlang nach Menethil.",
		["West to the farms of {area:287}: place the {item:279386} on the bookkeeping table in the town hall, where {npc:2335} and the councilmen stand."] = "Nach Westen zu den Höfen von {area:287}: Leg {item:279386} auf den Buchhaltungstisch im Rathaus, wo {npc:2335} und die Ratsherren stehen.",
		["Whelps, raptors and {npc:271458}"] = "Welpen, Raptoren und {npc:271458}",
		["Yeti cave"] = "Yetihöhle",
		["{area:287} town hall"] = "Rathaus von {area:287}",
		["{area:287}'s town hall"] = "Rathaus von {area:287}",
		["{item:3713}, from {npc:2381}"] = "{item:3713}, von {npc:2381}",
		["{npc:1244}: {quest:98283}, an elite raptor"] = "{npc:1244}: {quest:98283}, ein Elite-Raptor",
		["{npc:2104}: for {npc:270637}"] = "{npc:2104}: für {npc:270637}",
		["{npc:2366}, in the inn: for {area:35} (04-stranglethorn-vale)"] = "{npc:2366}, im Gasthaus: für {area:35} (04-stranglethorn-vale)",
		["{npc:2382}: the lions come later"] = "{npc:2382}: Die Löwen kommen später",
		["{npc:2438} also wants a {item:3719}, a {item:2997} and {item:2321}: crafted or bought; the cloak is turned in when you are back in {area:271} later."] = "{npc:2438} will außerdem {item:3719}, {item:2997} und {item:2321}: hergestellt oder gekauft; den Umhang gibst du ab, wenn du später wieder in {area:271} bist.",
		["{npc:2708} is in the {object:2164}; {npc:211033} near the canal; {npc:5081} south of the {object:2101}."] = "{npc:2708} ist im {object:2164}; {npc:211033} nahe dem Kanal; {npc:5081} südlich vom {object:2101}.",
		["{npc:2711}: his trail leads to Arathi"] = "{npc:2711}: Seine Spur führt nach Arathi",
		["{npc:271462} stands in the south-eastern hills: use the {item:279996} beside it."] = "{npc:271462} steht in den südöstlichen Hügeln: Benutze daneben {item:279996}.",
		["{npc:2784}, the {object:171709}"] = "{npc:2784}, {object:171709}",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961} wartet in der Taverne „Zum Schwein und Pfeife“ in {object:2100}; er und seine zwei Schläger greifen dich an, hören aber auf, sobald sie besiegt sind.",
		["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (40-50/01)."] = "{npc:5479} bildet in {object:2100} Krieger aus, neben der Taverne „Zum Schwein und Pfeife“. {npc:6236} wartet auf {area:720} im {zone:1413}, auf dem Weg nach {area:392} viel später (40-50/01).",
		["{npc:5683} waits north of {area:205} by the {area:881}; {npc:271322} a short walk further north-east."] = "{npc:5683} wartet nördlich von {area:205} am {area:881}; {npc:271322} ein kurzes Stück weiter nordöstlich.",
		["{object:671518}: for {npc:2104}"] = "{object:671518}: für {npc:2104}",
		["{zone:1455} has no druid trainer: train with {npc:5504} in {zone:1453} before the tram."] = "{zone:1455} hat keinen Druidenlehrer: Trainiere vor der Bahn bei {npc:5504} in {zone:1453}.",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Escort the caravan"] = "Die Karawane eskortieren",
		["Escort {npc:5644}"] = "{npc:5644} eskortieren",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "Folge der Straße nach Westen an {area:460} (Horde) vorbei und nach Südwesten durch {area:465} nach {zone:1443}; {area:608} liegt oben am Pass.",
		["From {area:415} head south-west to the {area:1276}, a tunnel through the mountains into Stonetalon."] = "Reite von {area:415} nach Südwesten zum {area:1276}, einem Tunnel durch die Berge ins Steinkrallengebirge.",
		["From {area:415} ride north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then back past {area:415} to the {area:1276}."] = "Reite von {area:415} nach Nordwesten in die Hügel: {quest:1738} ist ein leuchtender Baum nördlich der Straße nach {area:413}. Falls du {quest:65602} angenommen hast, liegt {item:190309} in einem Haus zwischen den Bäumen nördlich von {area:413} (26.6,22.0). Dann zurück an {area:415} vorbei zum {area:1276}.",
		["From {zone:1455}'s {npc:1573}"] = "Von {npc:1573} in {zone:1455}",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building."] = "Ihr Bruder {npc:5643} (36) läuft mit den Kultisten der Burning Blade (30-33) durch die Festung: Zieh ihn allein. {npc:13019} hat das Zepter im Hauptgebäude der Festung.",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "Führ {npc:5644} aus der Festung; sie geht ihrer Wege, sobald ihr draußen seid. {npc:5642} nimmt die Abgabe am Ende des Guides in {area:608} entgegen.",
		["Malem chest"] = "Truhe der Malems",
		["Out of Thunder Axe Fortress"] = "Raus aus der Festung Thunder Axe",
		["Scorpashi venom"] = "Skorpashigift",
		["The Gizelton Caravan waits at {area:2407}."] = "Gizeltons Karawane wartet bei {area:2407}.",
		["The Hatefury satyrs hold the ruins of {area:603}, east of {area:608}."] = "Die Satyrn der Zornsäer halten die Ruinen von {area:603}, östlich von {area:608}.",
		["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "Die Kolkar streifen über die Ebenen um {area:609}; ihre Ohren sind für {npc:5752}.",
		["The Scorpashi scorpids hunt the hills around {area:2407} on the road south."] = "Die Skorpashi-Skorpide jagen in den Hügeln um {area:2407} an der Straße nach Süden.",
		["The chest lies in the ruins south-west of {area:608}."] = "Die Truhe liegt in den Ruinen südwestlich von {area:608}.",
		["Use {npc:11596}'s {item:13892} on an {npc:4700} and walk the tamed kodo back to his camp, five times; Aged Kodos also drop the hides."] = "Benutze {npc:11596}s {item:13892} an einem {npc:4700} und führ den gezähmten Kodo zu seinem Lager zurück, fünfmal; Gealterte Kodos lassen auch die Bälge fallen.",
		["Walk with the caravan south past {area:609}; Kolkar ambushers jump it on the way. Stay close until it stops at {area:2617}. The ambushers are 34-35 and come in waves: skip it if you are below 33."] = "Geh mit der Karawane nach Süden an {area:609} vorbei; unterwegs überfallen sie Wegelagerer der Kolkar. Bleib dicht dran, bis sie bei {area:2617} anhält. Die Wegelagerer sind Stufe 34-35 und kommen in Wellen: Überspring sie, wenn du unter 33 bist.",
		["{item:190309}, north of {area:413}"] = "{item:190309}, nördlich von {area:413}",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "{npc:11596}s Lager liegt an der Straße südlich von {area:609}, beim {area:596}.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "{npc:11863}s Turm steht auf dem Hügel westlich von {area:599}: Nimm zuerst seine Quest an, das Zepter, das er will, ist in der Festung.",
		["{npc:5643} and the Seer"] = "{npc:5643} und der Seher",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644} versteckt sich in der Festung der Burning Blade südwestlich von {area:608}.",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Dartol's Rod"] = "Dartols Rute der Transformation",
		["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "Folge der Straße nach Osten zu den Satyrlagern von {area:429}; {npc:3920} versteckt sich an ihrem Rand.",
		["Follow the road west out of {area:415}; {area:413} lies north of it."] = "Folge der Straße von {area:415} aus nach Westen; {area:413} liegt nördlich davon.",
		["From {area:608}"] = "Start: {area:608}",
		["Insane druids"] = "Wahnsinnige Druiden",
		["Lightforge Ingots"] = "Lichtschmiedeblöcke",
		["Melyria and {npc:3901}"] = "Melyria und {npc:3901}",
		["Rusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel."] = "Rostige Truhen stehen rund um die Furbolglager des Schattendickichts westlich der Verlassenen; öffne sie, bis eine den Knauf enthält.",
		["Take the boat to {area:150} from {area:442}'s docks."] = "{area:150}: Nimm das Boot vom Steg in {area:442}.",
		["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end."] = "Nimm den Tunnel ins Gebiet {area:419}; der Foliant liegt in den Ruinen an seinem Westende.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "Die Murlocs der Blaukiemen am Strand südwestlich von Menethil tragen die Blöcke.",
		["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "Die Wahnsinnigen und Welken Urtume nördlich des Mondbrunnens tragen den {item:5475}; die abgenutzte Truhe, die er öffnet, steht zwischen ihnen.",
		["The Forsaken's camp lies in the woods south of {area:2358}."] = "Das Lager der Verlassenen liegt in den Wäldern südlich von {area:2358}.",
		["The moonwell lies in the hills north-east of {area:415}."] = "Der Mondbrunnen liegt in den Hügeln nordöstlich von {area:415}.",
		["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "Der zweite {object:19901} liegt im Tal {area:428}, auf dem Weg nach Westen.",
		["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "Der Schrein liegt auf dem Hügel gleich südöstlich des Mondbrunnens; folge dem gewundenen Pfad hinauf.",
		["The three druids stand together at the Forsaken camp south of {area:2358}."] = "Die drei Druiden stehen zusammen im Lager der Verlassenen südlich von {area:2358}.",
		["The two stand together at the western end of the road."] = "Die beiden stehen zusammen am Westende der Straße.",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "Das Wrack der Flying Osprey liegt im seichten Wasser südlich der Burg.",
		["The {npc:3931} walks the shore of {quest:1035}, south-west of the chests; the {object:669176} lies north of the lake, on the way."] = "Das {npc:3931} läuft am Ufer des {quest:1035} entlang, südwestlich der Truhen; der {object:669176} liegt unterwegs nördlich des Sees.",
		["The {object:19901} stands in the satyr camp of {area:430}, further east along the road."] = "Der {object:19901} steht im Satyrlager von {area:430}, weiter östlich an der Straße.",
		["{npc:1217} stands on the upper floor of Menethil's keep."] = "{npc:1217} steht im oberen Stockwerk der Burg von Menethil.",
		["{npc:3696} and his guards camp just east of {npc:3897}."] = "{npc:3696} und seine Wachen lagern gleich östlich von {npc:3897}.",
		["{npc:3897}, a furbolg untouched by the corruption, sits south of the road below {area:421}."] = "{npc:3897}, ein Furbolg, den die Verderbnis nicht berührt hat, sitzt südlich der Straße unterhalb vom {area:421}.",
		["{npc:3970}: for {npc:1480} in Menethil, at the end of this guide"] = "{npc:3970}: für {npc:1480} in Menethil, am Ende dieses Guides",
		["{npc:4619} leads the {area:429} satyrs; he carries the branch."] = "{npc:4619} führt die Satyrn von {area:429} an; er trägt den Zweig.",
		["{npc:5082}, {npc:4963} and Tapoke Jahn are all at Menethil's inn; {npc:4962} fights you when you talk to {npc:4963}, but gives up once beaten. {npc:1480} stands a short walk north-east of the inn."] = "{npc:5082}, {npc:4963} und {npc:4962} Jahn sind alle im Gasthaus von Menethil; Tapoke greift dich an, wenn du mit {npc:4963} sprichst, gibt aber auf, sobald er besiegt ist. {npc:1480} steht ein kurzes Stück nordöstlich des Gasthauses.",
		["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176}: für {npc:3961} in {area:415}",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "Zurück nach Süden an Nesingwary vorbei: Panther und Schlingendornraptoren laufen auf den Lichtungen westlich des Lagers Richtung Küste; die Alten Schlingendorntiger halten die Hügel im Südwesten.",
		["Bloodscalp trolls"] = "Bloodscalp-Trolle",
		["Both roam the grass around the camp and along the road north."] = "Beide streifen durch das Gras um das Lager und entlang der Straße nach Norden.",
		["Down to {area:35}"] = "Hinab nach {area:35}",
		["Druid training"] = "Druidentraining",
		["Fly from {area:150} to {area:1537} and train."] = "Flieg von {area:150} nach {area:1537} und trainiere.",
		["Fly to {area:42}: {npc:1573} in {area:1537}'s {object:32372}, or {npc:352} in {zone:1453}'s {object:2096}."] = "Flieg nach {area:42}: {npc:1573} im {object:32372} von {area:1537} oder {npc:352} im {object:2096} von {zone:1453}.",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "Folge der Hauptstraße durch den ganzen Dschungel nach Süden, vorbei an der Abzweigung nach {object:3202}, bis {area:35} am Südkap.",
		["Follow the west coast north; the haunted island lies off the shore west of Nesingwary's camp. Just reach it."] = "Folge der Westküste nach Norden; die Spukinsel liegt vor der Küste westlich von Nesingwarys Lager. Erreiche sie einfach.",
		["For Archmage Ansirem in {zone:1416}"] = "Für Erzmagier Ansirem im {zone:1416}",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "Nimm vom {zone:1431} die Straße nach Süden ins Schlingendorntal; die Zelte der Jäger stehen gleich westlich der Straße hinter der Abzweigung zum {area:99}.",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Gluckser, ein seltener Murloc an der Küste westlich des Lagers, lässt den {item:4614} fallen: Nimm ihn mit, falls du ihm begegnest",
		["Gyll, on the top floor by the docks"] = "Gyll, im obersten Stockwerk bei den Docks",
		["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave. Pick up Green Hills pages as they drop."] = "Kurzens Kopfschrumpfer stehen tiefer im Lager; Kurzens Kommandosoldaten lauern getarnt darum herum und in der Höhle. Heb Seiten der Grünen Hügel auf, wenn sie fallen.",
		["Herod's records lie in a hut on the compound's west side; his strongbox sits farther east, by the cave mouth."] = "Herods Aufzeichnungen liegen in einer Hütte auf der Westseite des Lagers; seine Geldkassette steht weiter östlich beim Höhleneingang.",
		["Loop through the troll ruins of the north and centre: each holds one stone tablet of the troll legends. Shadowmaw Panthers prowl stealthed in the jungle around them; the Venture Co. camp on {area:37} carries the Tumbled Crystals."] = "Zieh eine Runde durch die Trollruinen im Norden und in der Mitte: Jede birgt eine Steintafel der Trolllegenden. Schattentatzenpanther schleichen getarnt im Dschungel darum herum; das Lager der Venture Co. auf {area:37} trägt die Gerommelten Kristalle.",
		["Panthers, raptors and elder tigers"] = "Panther, Raptoren und Alte Tiger",
		["River Crocolisks swim the river by the {area:99}."] = "Flusskrokilisken schwimmen im Fluss beim {area:99}.",
		["River crocolisks"] = "Flusskrokilisken",
		["Skullsplitter trolls"] = "Skullsplitter-Trolle",
		["Snapjaw Crocolisks"] = "Schnappkieferkrokilisken",
		["Snapjaw Crocolisks bask on the shore and islands along the coast north of {area:35}."] = "Schnappkieferkrokilisken sonnen sich an Ufer und Inseln entlang der Küste nördlich von {area:35}.",
		["Stranglethorn Tigers"] = "Schlingendorntiger",
		["The Bloodscalp trolls hold the ruins on the coast west of Nesingwary's camp."] = "Die Bloodscalp-Trolle halten die Ruinen an der Küste westlich von Nesingwarys Lager.",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents."] = "Die Rebellen von Kurzen halten das Lager östlich des {area:99}; arbeite dich am Außenrand entlang, wo Kurzens Dschungelkämpfer und Medizinmänner stehen, und plündere die Vorratskisten bei den Zelten.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Die Skullsplitter-Trolle halten die Ruinen östlich der Straße zwischen Nesingwary und {object:3202}.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Die ausgewachsenen Tiger streifen durch die Hügel gleich südlich und westlich des Lagers.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Die Alten Schlingendorntiger kommen später, auf dem Rückweg vom {area:99}",
		["The haunted island"] = "Die Spukinsel",
		["The jungle ruins"] = "Die Dschungelruinen",
		["The ore drops from Drywhisker kobolds in {zone:1417}"] = "Das Erz lassen Kobolde der Trockenstoppel im {zone:1417} fallen",
		["Thorsen patrols the road north of camp, toward the {area:99}."] = "Thorsen patrouilliert auf der Straße nördlich des Lagers, Richtung {area:99}.",
		["Walk back north; the {area:310} lies west of the road in the middle of the jungle. The Crystal Spine Basilisks there drop the shards."] = "Geh zurück nach Norden; die {area:310} liegt westlich der Straße mitten im Dschungel. Die Kristallrückenbasilisken dort lassen die Splitter fallen.",
		["Young tigers and panthers"] = "Junge Tiger und Panther",
		["{area:1537} has no druid trainer: take the {area:2257} from {object:171524} to {zone:1453} and train with {npc:5504}."] = "{area:1537} hat keinen Druidenlehrer: Nimm die {area:2257} von {object:171524} nach {zone:1453} und trainiere bei {npc:5504}.",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, aus einer Kiste von {object:263}",
		["{npc:2495}, by the bank"] = "{npc:2495}, bei der Bank",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, oben in der Taverne",
		["{npc:2832}, in the {object:56910}"] = "{npc:2832}, in der {object:56910}",
		["{npc:469}, in the hut"] = "{npc:469}, in der Hütte",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, aus {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} sammelt die {item:2755}: Die Seiten lässt fast jeder Humanoide im Dschungel fallen. Füg die Seiten unterwegs zu Kapiteln zusammen.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} und die Schmetterschwänze",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "{npc:729}, der große Tiger, haust auf der Hügelkuppe südwestlich des Lagers; Schmetterschwänze laufen südlich davon, auf dem Weg nach {area:35}.",
		["{npc:737}, in the tavern"] = "{npc:737}, in der Taverne",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}: für {npc:773} in {area:35}",
		["{npc:773}, in the tavern"] = "{npc:773}, in der Taverne",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: Sieh dich einfach im Lager der Jäger um",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks unseen on the edge of {area:271}; kill him and read the contract he carries."] = "Ein {npc:2434} lauert unsichtbar am Rand von {area:271}; töte ihn und lies den Vertrag, den er bei sich trägt.",
		["Back west through {zone:1430} to {area:42}."] = "Zurück nach Westen durch {zone:1430} nach {area:42}.",
		["Crushridge ogres"] = "Crushridge-Oger",
		["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}."] = "Jeder Schlüssel liegt an einem der Steinkreise des Hochlands: östlich der Splitter, nahe {area:320} und im Westen. {object:2702} steht westlich von {area:320}.",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals; Noboru walks the ruins and drops his cudgel."] = "Auf der Straße nach Osten zu {area:76}. Gegner vom Typ {npc:256028} lassen die Kristalle fallen; Noboru streift durch die Ruinen und lässt seinen Knüppel fallen.",
		["Ebenezer Rustlocke"] = "Ebenezer Rustlocke",
		["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves."] = "Eskortiere den Professor zum Strand nördlich der Bucht und beschütze ihn, während er arbeitet; Naga greifen in Wellen an.",
		["Fly to {area:271}"] = "Flieg nach {area:271}",
		["Fly to {area:42}"] = "Flieg nach {area:42}",
		["Fly to {zone:1453}"] = "Flieg nach {zone:1453}",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "Folge der Straße von {area:287} nach Osten über {area:1057} nach {area:320}.",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings, and {npc:2306} walks the manor grounds on the north side of town."] = "Folge der Straße von {area:271} nach Norden in die Berge. Berglöwen streifen über die Hänge; das Syndikat in {area:280} trägt die Siegelringe, und {npc:2306} geht auf dem Gutshof an der Nordseite des Orts umher.",
		["Follow the road north to the draenei of the {area:657}."] = "Folge der Straße nach Norden zu den Draenei in {area:657}.",
		["Follow the road south over the bridge to {area:205} at the {zone:1437} end, where {npc:1075} waits."] = "Folge der Straße nach Süden über die Brücke nach {area:205} am Ende im {zone:1437}, wo {npc:1075} wartet.",
		["For {npc:1440} in {zone:1453}: keep it"] = "Für {npc:1440} in {zone:1453}: behalten",
		["For {npc:2487} in {area:35}: keep it"] = "Für {npc:2487} in {area:35}: behalten",
		["For {npc:2542} in {area:35}: keep it"] = "Für {npc:2542} in {area:35}: behalten",
		["For {npc:2711} in {area:271}"] = "Für {npc:2711} in {area:271}",
		["From {area:42} follow the road east through {zone:1430} into the {zone:1435}; Biggs guards the road junction just inside it. {npc:217412} stands a short way north of him."] = "Folge von {area:42} aus der Straße nach Osten durch {zone:1430} in {zone:1435}; Biggs bewacht die Straßenkreuzung gleich hinter der Grenze. {npc:217412} steht ein kurzes Stück nördlich von ihm.",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "Nimm von {zone:1455} aus den Tunnel nach Osten durch {zone:1426} nach {zone:1432} und folge der Straße nach {area:144}.",
		["Gyll, {area:35}"] = "Gyll, {area:35}",
		["Head north past {area:314}; the shards glitter on the hill by the {area:333}."] = "Geh nach Norden an {area:314} vorbei; die Splitter glitzern auf dem Hügel bei {area:333}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Nur wenn Gluckser dir im Schlingendorntal den Anhänger gegeben hat",
		["Phizzlethorpe"] = "Phizzlethorpe",
		["Ride back north-east past {area:320}; {npc:2712} and {npc:2713} camp in the hills north of {area:314}."] = "Reite zurück nach Nordosten an {area:320} vorbei; {npc:2712} und {npc:2713} lagern in den Hügeln nördlich von {area:314}.",
		["Shaman training"] = "Schamanentraining",
		["South-east along the loch to the dig site."] = "Nach Südosten am See entlang zur Ausgrabungsstätte.",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "Nach Südwesten zum Lager der Kirin Tor am Seeufer westlich von {area:279}, gleich hinter der Grenze in {zone:1421}: Dort steht {npc:269127}. Erzmagier Ansirem steht südöstlich davon, bei der Kuppel.",
		["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way."] = "Bleib bei {npc:2713}, während sie sich nach {area:314} und zurück schleicht; Orcs der Horde fallen unterwegs über dich her.",
		["Subdue the succubus"] = "Bezwinge den Sukkubus",
		["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it."] = "Die Crushridge-Oger halten die Hügel nördlich von {area:280}. Weiter nördlich enthält eine abgenutzte Holztruhe {item:3706}; {npc:2320} aus {quest:537} steht direkt daneben.",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop both the motes and Krazek's ore."] = "Die Kobolde der Trockenstoppel graben in der Schlucht östlich von {area:321} (Horde); umgeh den Ort im Norden. Sie lassen sowohl die Partikel als auch Krazeks Erz fallen.",
		["The Syndicate hold the farm north-west of {area:320}. A {npc:217589} crawls about the farm: catch one with {npc:217412}'s Entomology Starter Kit, then tick it off."] = "Das Syndikat hält den Hof nordwestlich von {area:320}. Ein {npc:217589} krabbelt auf dem Hof herum: Fang einen mit dem Einsteigerpaket für Entomologen von {npc:217412} und hak ihn dann ab.",
		["The Witherbark trolls live in the hills south of {area:314}; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley."] = "Die Trolle der Witherbark leben in den Hügeln südlich von {area:314}; Hexendoktoren der Witherbark stehen im Dorf, Schattenjäger der Witherbark bewachen das hintere Ende des Tals.",
		["The courier walks the road west of {area:314} with two guards; pull them off the road."] = "Der Kurier geht mit zwei Wachen die Straße westlich von {area:314} entlang; lock sie von der Straße weg.",
		["The shards lie at the far end of {area:318}."] = "Die Splitter liegen am hinteren Ende von {area:318}.",
		["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins."] = "Die Folianten liegen in der zerstörten Burg westlich von {area:280}; Schattenmagier der Arguswacht halten die Ruinen.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Die beiden Wracks liegen in der Bucht westlich der Bucht der Goblins. Die Karten und Logbücher sind darin; die Edelsteine liegen um sie herum auf dem Meeresgrund. Naga der Säbelflossen schwimmen in der ganzen Bucht.",
		["The western swamp"] = "Der westliche Sumpf",
		["The wrecked caravan lies off the road near Biggs."] = "Die zerstörte Karawane liegt abseits der Straße nahe Biggs.",
		["The wrecks"] = "Die Wracks",
		["Walk back onto the span: Ebenezer lies under its Arathi end."] = "Geh zurück auf den Übergang: Ebenezer liegt unter dessen Ende im Arathihochland.",
		["West along the coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Nach Westen entlang der Küste zur Bucht der Goblins; Lolo hält auf den Felsen darüber Wache.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Junge Sägezahnkrokilisken, Trauerspinner und Sumpfjaguare streifen alle durch den Sumpf um die Straße.",
		["{item:2321} for {npc:2438}'s cloak, from {npc:2381}, if you have none"] = "{item:2321} für {npc:2438}s Umhang, von {npc:2381}, falls du keinen hast",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, Straße zum {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, Kathedrale des Lichts",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, die Königliche Bibliothek in der Burg",
		["{npc:185335}, at the same circle"] = "{npc:185335}, am selben Kreis",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: drei Kleintiere zum Fangen im Arathihochland, in {zone:1443} und im Schlingendorntal",
		["{npc:217589}: catch it, for {quest:93176}"] = "{npc:217589}: Fang ihn, für {quest:93176}",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} und {npc:2713}",
		["{npc:2713}'s errand"] = "Auftrag von {npc:2713}",
		["{npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "{npc:2793}, ein Ogermagier, hält die Höhle am Südende des Witherbark-Tals.",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391} ist am Nordende des Refugiums eingesperrt. Befreie ihn und halte ihn auf dem Weg hinaus am Leben; seine Geldkassette wartet danach an der Straße.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} bindet den Inkubus an dich",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} wartet im Keller von {object:2164} in {object:2101}. Benutze {item:6913} am Beschwörungskreis dort und besiege den herbeigerufenen Sukkubus. Wenn du {quest:65602} angenommen hast, gib ihm auch {item:190309}, stelle sie am selben Kreis ab und besiege den Inkubus.",
		["{quest:65602}, if you took it"] = "{quest:65602}, falls du sie angenommen hast",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455} and train with {npc:258098}. {npc:1573} in the {object:32372} flies to {area:271} too."] = "{zone:1453} hat keinen Schamanenlehrer: Nimm {area:2257} vom {object:28027} nach {zone:1455} und trainiere bei {npc:258098}. {npc:1573} bei {object:32372} fliegt ebenfalls nach {area:271}.",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Fly to Theramore"] = "Flieg nach Theramore",
		["Follow the road north to {area:608}."] = "Folge der Straße nach Norden zu {area:608}.",
		["Follow the road south to {area:2407}."] = "Folge der Straße nach Süden zu {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}; the wrecked ship's chest lies on the shore just west of them."] = "Folge der Straße nach Westen durch den Norden von {zone:1443} zu den Ruinen von {area:2405}; die Truhe des Schiffswracks liegt gleich westlich davon am Ufer.",
		["Greater Rock Elementals"] = "Große Felselementare",
		["Lesser Rock Elementals"] = "Kleine Felselementare",
		["Maraudine centaurs"] = "Zentauren der Maraudine",
		["Ogres and buzzards"] = "Oger und Bussarde",
		["Ride back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Reite zurück nach Westen zur Straße und folge ihr nach Süden aus {zone:1432} durch den Pass ins {zone:1418}. {npc:2910} und {npc:2860} lagern nebeneinander bei der Ausgrabung.",
		["Ride north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Reite nach Nordosten zur verlassenen Ausgrabung; die Vorratskiste liegt dort zwischen den Ogern der Staubspeier.",
		["Ride north-east to the dwarven ruins in the north of the {zone:1418}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "Reite nach Nordosten zu den Zwergenruinen im Norden des {zone:1418}; die Truhe steht zwischen den Zwergen der Schattenschmiede. {npc:2745} in der Nähe ist Elite: Halte Abstand.",
		["Ride south to {area:345}."] = "Reite nach Süden zur {area:345}.",
		["Ride west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "Reite nach Westen in {area:1878}; {npc:2921} arbeitet mitten darin an seinen Maschinen.",
		["Rock Elementals"] = "Felselementare",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "Ryedols nächster Auftrag führt nach {area:1517}: Überspring ihn.",
		["Shadowforge camp"] = "Lager der Schattenschmiede",
		["Take the boat to Theramore from the far pier."] = "Nimm vom hinteren Pier das Schiff nach Theramore.",
		["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east."] = "Die Oger der Staubspeier lagern gleich südlich des Tals; jeder von ihnen lässt Schrott fallen. Bussarde kreisen über der Ebene im Osten.",
		["The Greater Rock Elementals (level 42) walk the far south-west corner below {area:342}; pull them one at a time. The Dustbelcher Wyrmhunters and Maulers at {area:342} also drop scrap."] = "Die Großen Felselementare (Stufe 42) wandern in der äußersten Südwestecke unterhalb von {area:342}; zieh sie einzeln. Die Wyrmjäger und Raufer der Staubspeier bei {area:342} lassen auch Schrott fallen.",
		["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}."] = "Die Kleinen Felselementare streifen durch {area:1878} westlich von {npc:2921}.",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Die Zentauren der Maraudine halten das {area:607} westlich des Friedhofs; jede Art lässt die Totems fallen.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Die Felselementare streifen südöstlich von {npc:2921} umher; Riesenbussarde und Alte Klippenkojoten teilen sich die Ebene westlich davon.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Die Zwerge der Schattenschmiede lagern gleich nördlich der Ausgrabungsstätte; die zerknitterte Karte liegt zwischen ihren Zelten. Tunnelgräber und Dunkelwirker tragen Ryedols Spitzhacke. Klippenkojoten streifen über die Hänge drumherum.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "Das zerschlagene Skelett liegt gleich östlich der Oger, am Rand des Lagers der Steingrufttroggs; die Knochenknacker und Schamanen drumherum lassen die Splitter fallen. Theldurin sitzt weiter südlich beim zerstörten Lager.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Die Muscheln liegen an der Nordwestküste des Schlingendorntals, im nächsten Guide: Behalte sie",
		["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit."] = "Die Dämonen versammeln sich bei {area:602} im Süden von {zone:1443}: Teufelshunde (Manafresser, Magier- und Leyjäger), Nethermaiden und Netherschwestern und Captains der Verdammniswächter rund um die Grube.",
		["The excavation crate"] = "Die Ausgrabungskiste",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "Der Flugmeister steht am Tor von {area:514}; {npc:5083} und {npc:4964} sind in der Zitadelle.",
		["The next guide starts in Theramore."] = "Der nächste Guide beginnt in Theramore.",
		["The skeleton's next task, Murdaloc, waits until the later {zone:1418} guide at 43."] = "Die nächste Aufgabe des Skeletts, Murdaloc, wartet bis zum späteren Guide für das {zone:1418} mit 43.",
		["The {area:2657}"] = "{area:2657}",
		["The {object:126260}"] = "{object:126260}",
		["Theramore"] = "Theramore",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Untote Verheerer streifen über die Knochenfelder südlich des Dorfs der Magram, östlich des Kovens; ganz im Südosten benutzt du {item:15848}, um die Schreckgespenster der Magram anzulocken.",
		["escort {npc:12277} back toward the graveyard"] = "eskortiere {npc:12277} zurück zum Friedhof",
		["for the Dustwallow loop in the next guide"] = "für die Runde durch die Marschen von Dustwallow im nächsten Guide",
		["for {npc:2786} in {zone:1455}: keep it"] = "für {npc:2786} in {zone:1455}: behalte sie",
		["for {npc:3980} in {area:271}: keep it"] = "für {npc:3980} in {area:271}: behalte sie",
		["for {npc:4454} in the {area:439}: the {zone:1446} guide crosses them at 45, keep it"] = "für {npc:4454} in {area:439}: Der Guide für {zone:1446} kommt mit 45 dort vorbei, behalte sie",
		["for {npc:5637} in {zone:1455}: keep it"] = "für {npc:5637} in {zone:1455}: behalte sie",
		["only if you carry {item:2868} (a blacksmith's craft)"] = "nur wenn du {item:2868} dabeihast (von Schmieden hergestellt)",
		["{npc:11626}'s caravan stops on the road east of {area:606}. Take the quest and walk with the kodos past the {area:602}, killing the demons that jump them; talk to {npc:11596} at his camp east of the {area:596} afterwards."] = "Die Karawane von {npc:11626} hält an der Straße östlich von {area:606}. Nimm die Quest an und geh mit den Kodos an {area:602} vorbei; töte die Dämonen, die sie anspringen. Sprich danach mit {npc:11596} in seinem Lager östlich des {area:596}.",
		["{npc:11863}'s tower stands on the hill east of the wreck."] = "{npc:11863}s Turm steht auf dem Hügel östlich des Wracks.",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard."] = "{npc:12277} wird im Zentaurenlager westlich des Friedhofs gefangen gehalten. Befrei sie und halte sie auf dem Weg hinaus am Leben; sie hält beim Friedhof an.",
		["{npc:12369}, a centaur chieftain, camps on the north-west coast, north of {npc:11863}'s tower."] = "{npc:12369}, ein Zentaurenhäuptling, lagert an der Nordwestküste, nördlich von {npc:11863}s Turm.",
		["{npc:1470}, in the inn"] = "{npc:1470}, im Gasthaus",
		["{npc:217590}: catch it, for My Little Friends"] = "{npc:217590}: fang ihn, für My Little Friends",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, neben {npc:2921}",
		["{npc:2921}'s next test needs crafted gear: skip it."] = "{npc:2921}s nächster Test braucht hergestellte Ausrüstung: Überspring ihn.",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618} und {npc:2817} lagern zusammen im {area:1877}, mitten im {zone:1418}.",
		["{npc:5638}'s next task, {item:6245}, is a drop on the far coast: skip it."] = "{npc:5638}s nächste Aufgabe, {item:6245}, ist eine Beute an der fernen Küste: Überspring sie.",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons. A {npc:217590} crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off."] = "{npc:6019} steht am Rand des {area:596}, südwestlich von {area:2407}; {object:176751} liegen zwischen den Skeletten. Ein {npc:217590} krabbelt auf dem Friedhof herum: Fang einen mit dem Insektenfang-Set und hak ihn dann ab.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "Stinki Ignatz",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. No Skyborne riding trainer is known; the Forever client files {spell:1285849} under the one Riding skill, so {npc:4732} at {area:88} in eastern {zone:1429}, the nearest trainer to {zone:1453}, should teach it (unconfirmed). The Galestriders are sold by {npc:265756} in {area:16638} on Zephras Isle; Collectibles, Mounts · Level 40 lists them."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. Es ist kein Reitlehrer der Himmelsgeborenen bekannt; der Forever-Client führt {spell:1285849} unter der einen Reitfertigkeit, also sollte {npc:4732} in {area:88} im östlichen {zone:1429}, der nächste Lehrer bei {zone:1453}, es lehren (unbestätigt). Die Windschreiter verkauft {npc:265756} in {area:16638} auf der Insel Zephras; Sammelobjekte, Reittiere · Stufe 40 listet sie.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. {npc:4732} lehrt Menschen in {area:88} im östlichen {zone:1429}, neben den Pferden von {npc:384}. In Forever kann womöglich jedes Volk bei jedem Reitlehrer lernen (unbestätigt). Sammelobjekte, Reittiere · Stufe 40 listet alle Farben.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. {npc:4753} lehrt Nachtelfen in {zone:1457}, neben den Säblern von {npc:4730}: das Boot vom {area:17203} nach {area:442}, dann der Flug nach {area:702}. In Forever kann womöglich jedes Volk bei jedem Reitlehrer lernen (unbestätigt), etwa bei {npc:4732} in {area:88} im {zone:1429}. Sammelobjekte, Reittiere · Stufe 40 listet alle Farben.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. {npc:4772} lehrt Zwerge in {area:803}, östlich von {area:131} an der Straße nach {zone:1432}, neben den Widdern von {npc:1261}. In Forever kann womöglich jedes Volk bei jedem Reitlehrer lernen (unbestätigt). Sammelobjekte, Reittiere · Stufe 40 listet alle Farben.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. {npc:7954} lehrt Gnome in {area:189}, gleich östlich von {area:131}, neben den Roboschreitern von {npc:7955}. In Forever kann womöglich jedes Volk bei jedem Reitlehrer lernen (unbestätigt). Sammelobjekte, Reittiere · Stufe 40 listet alle Farben.",
		["Back in Theramore: Tervosh waits with Lady Jaina in the tower of {area:514}."] = "Zurück in Theramore: Tervosh wartet mit Lady Jaina im Turm von {area:514}.",
		["Bloodsail camp"] = "Lager der Blutsegelbukaniere",
		["Bloodsail pirates"] = "Piraten der Blutsegelbukaniere",
		["Boat to {area:35}"] = "Boot nach {area:35}",
		["Cold Eye Basilisks"] = "Kaltaugenbasilisken",
		["Defeat the challengers and {npc:6238}"] = "Besiege die Herausforderer und {npc:6238}",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "Jeder Blutsegelbukanier lässt Schnupftabak fallen, und einer trägt {npc:2493}s Auge; die Schwadroneure gehen gleich nördlich des Orts am Ufer entlang. Die Karten und Befehle liegen im Piratenlager an der {area:43} südlich von {area:35}.",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Jeder Anhänger von Zanzil kann die Mixtur fallen lassen; {npc:2537} geht im Süden des Lagers umher.",
		["Fly to {area:42} and ride east through {zone:1430} into the {zone:1435}; {npc:5476} stands by the road just past the border."] = "Flieg nach {area:42} und reite nach Osten durch den {zone:1430} in die {zone:1435}; {npc:5476} steht gleich hinter der Grenze an der Straße.",
		["Follow the road east back to Theramore. Tervosh, Lady Jaina and the officers are in the tower and {area:514}."] = "Folge der Straße nach Osten zurück nach Theramore. Tervosh, Lady Jaina und die Offiziere sind im Turm und in {area:514}.",
		["Follow the road north-east to the Venture Co. camp at the {area:310}; the miners, surveyors and foremen drop the crystals."] = "Folge der Straße nach Nordosten zum Lager der Venture Co. an der {area:310}; Minenarbeiter, Feldmesser und Großknechte lassen die Kristalle fallen.",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it."] = "Folge der Straße nach Nordwesten aus Theramore hinaus zum Wachturm bei {area:503}. Schlammpanzereinbuddler streifen durch den Sumpf darum herum.",
		["Galestriders: {npc:265756}, in {area:16638} on Zephras Isle."] = "Windschreiter: {npc:265756}, in {area:16638} auf der Insel Zephras.",
		["Gorilla hills"] = "Gorillahügel",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "Gib die Fangzähne ab und bleib: Drei Wellen Gorillas kommen, {npc:1514} zuletzt. Kämpfe mit voller Gesundheit.",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "Verlass den Ort durch den Tunnel und folge der Küste nach Norden; der Brief liegt im Lager der Blutsegelbukaniere am Strand, wo Schönling Duncan umhergeht.",
		["MacKinley's next task sends you after elite ogres: skip it."] = "MacKinleys nächster Auftrag schickt dich zu Elite-Ogern: Überspring ihn.",
		["Mirefin murlocs"] = "Murlocs der Schlammflossen",
		["Mudrock tortoises"] = "Schlammpanzerschildkröten",
		["Naga Explorers"] = "Forscher der Naga",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "Auf dem Ritt nach Norden nach {area:392} liegt {area:720} vor der {area:391} südlich des Orts: Wate über die Untiefen der Sandbank. {npc:6236} schickt dir nacheinander vier Herausforderer und dann {npc:6238} (Stufe 33) entgegen.",
		["Paladin: {quest:1661}"] = "Paladin: {quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "Reite zurück hinab in den Ort; Zitterhand steht am Tunneleingang.",
		["Ride back west along the road; {npc:217412} stands a short way north of Biggs."] = "Reite die Straße zurück nach Westen; {npc:217412} steht ein kurzes Stück nördlich von Biggs.",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Reite nach Osten; die Wuchernden Schrecken unterwegs lassen auch die Aufsätze fallen. Durchsuche den Rand des {area:74}, wo die Ruinen des Tempels aus dem Wasser ragen.",
		["Ride from Theramore west along the Dustwallow road into the {zone:1413} and north to {area:392} on the coast. Learn the flight path from {npc:16227}, then take the boat to {area:35} from the dock."] = "Reite von Theramore nach Westen über die Straße der Marschen ins {zone:1413} und nach Norden nach {area:392} an der Küste. Hol dir die Flugroute bei {npc:16227}, dann nimm am Steg das Boot nach {area:35}.",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "Reite ins Landesinnere zu den Gorillahügeln im Nebeltal. Alte Nebeltalgorillas lassen die Innereien fallen; {npc:1449} sitzt zwischen ihnen.",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "Reite nach Norden in die Hügel westlich der Straße. {npc:2535} und {npc:2536} stehen zusammen gleich nördlich von Zanzils Dorf.",
		["Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale. On the way, an {npc:217588} crawls in the jungle south-east of Nesingwary's camp: catch one with the Entomology Starter Kit, then tick it off."] = "Reite nach Nordosten an Nesingwarys Lager vorbei und folge der Straße nach Norden zum Lager am oberen Ende des Tals. Unterwegs krabbelt eine {npc:217588} im Dschungel südöstlich von Nesingwarys Lager: Fang eine mit dem Entomologie-Startset und hak sie dann ab.",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Reite von der Mine nach Nordwesten zur Bucht an der Nordwestküste. Die Riesenmuscheln liegen auf ihrem Grund und enthalten die Perlen; {npc:2624} schwimmt zwischen ihnen und lässt {item:4034} fallen.",
		["Ride south to the giant's hut in the middle of the marsh."] = "Reite nach Süden zur Hütte des Riesen mitten im Sumpf.",
		["Riding at 40"] = "Reiten mit 40",
		["Seahorn's next errand goes back to Arathi: skip it."] = "Seehorns nächster Auftrag führt zurück nach Arathi: Überspring ihn.",
		["Skullsplitter ruins"] = "Ruinen der Skullsplitter",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Stinki wartet westlich des Anwesens, im Sumpf unterhalb von {area:504}. Führ ihn zu seinen Sumpfbohnenblättern und halte die Sumpfkreaturen von ihm fern.",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house."] = "Nimm die Straße nach Norden zum zerstörten Anwesen; Jarl wohnt in der Hütte daneben, und die lockere Erde ist an der Hausecke.",
		["Take the {area:2257} from the {object:28027}. {npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:1356} in the hall itself, {npc:2786} in the {object:32383}. The next guide flies on to {area:144}."] = "Nimm die {area:2257} vom {object:28027}. {npc:5637} ist in der Halle der Forscherliga beim {object:32356}, {npc:1356} in der Halle selbst, {npc:2786} im {object:32383}. Der nächste Guide fliegt weiter nach {area:144}.",
		["The Bloodsail captains"] = "Die Kapitäne der Blutsegelbukaniere",
		["The Cold Eye Basilisks lie on the rocks west of the mine."] = "Die Kaltaugenbasilisken liegen auf den Felsen westlich der Mine.",
		["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes."] = "Die Graunebelspinnen nisten um die Höhle im Nordwesten des Sumpfs; jede Spinne lässt Augen fallen.",
		["The Mirefin murlocs crowd the north coast past {area:497}; finish the tongues on the tortoises beside them."] = "Die Murlocs der Schlammflossen drängen sich an der Nordküste hinter {area:497}; sammle die restlichen Zungen bei den Schildkröten daneben.",
		["The Mudrock Tortoises and Spikeshells sun themselves on the shore north-east of the manor."] = "Die Schlammpanzerschildkröten und Dornenschlammpanzer sonnen sich am Ufer nordöstlich des Anwesens.",
		["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do."] = "Die Skullsplitter-Trolle halten die Ruinen gleich östlich der Mine; jeder von ihnen kann Hauer fallen lassen, ihre Panther immer.",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes and the hoofprints are in the mud beside the inn."] = "Das abgebrannte Gasthaus Zur süßen Ruh steht an der Straße nach Westen, Richtung {zone:1413}; die Plakette der Wache liegt in der Asche, und die Hufabdrücke sind im Schlamm neben dem Gasthaus.",
		["The captains stand on the ships anchored off the {area:43}, each with a crew of 42-45 pirates: Stillwater (45) and Keelhaul (46) on the nearer decks, {npc:2546} (48) on the flagship. At 42 this is a fight for a group or for the end of the guide; clear each deck first if you go. Cortello's scroll lies on the wreck by the shore."] = "Die Kapitäne stehen auf den Schiffen vor der {area:43}, jeder mit einer Mannschaft aus Piraten der Stufe 42-45: Stillwasser (45) und Kielhol (46) auf den näheren Decks, {npc:2546} (48) auf dem Flaggschiff. Mit 42 ist das ein Kampf für eine Gruppe oder fürs Ende des Guides; säubere jedes Deck vorher, falls du gehst. Cortellos Schriftrolle liegt auf dem Wrack am Ufer.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Die Deserteure lagern südlich der Straße, westlich von {npc:4503}s Hütte.",
		["The driftwood washes up along the eastern shore."] = "Das Treibholz wird am Ostufer angeschwemmt.",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "Die Naga durchkämmen die Strände nördlich des Lagers der Blutsegelbukaniere; sie lassen das Schilf fallen.",
		["The north-west coast"] = "Die Nordwestküste",
		["The riddle's next scroll lies in western Dustwallow: skip it."] = "Die nächste Schriftrolle des Rätsels liegt im Westen der Marschen von Dustwallow: Überspring sie.",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "Die Schriftrolle liegt im Sumpf nördlich von Biggs. Die Sumpfwandler nördlich davon können Khadgars Aufsätze fallen lassen.",
		["The sunken temple"] = "Der versunkene Tempel",
		["Theramore"] = "Theramore",
		["Unbagwa's ritual"] = "Unbagwas Ritual",
		["Warlock: {quest:3631}"] = "Hexenmeister: {quest:3631}",
		["Zanzil's village"] = "Zanzils Dorf",
		["for Stoley in {zone:1446}: keep it"] = "für Stoley in {zone:1446}: Behalte es",
		["for the {zone:1435} later"] = "für die {zone:1435} später",
		["for {area:1438}: keep it"] = "für {area:1438}: Behalte es",
		["for {npc:2616} in Theramore: keep it"] = "für {npc:2616} in Theramore: Behalte es",
		["for {npc:5635} at {area:348}: keep it"] = "für {npc:5635} in {area:348}: Behalte es",
		["for {npc:770} at the {area:99}, on the northern loop"] = "für {npc:770} beim {area:99}, auf der nördlichen Runde",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "nur wenn du einen {item:3853} dabeihast (von Schmieden hergestellt)",
		["with the spices from Theramore"] = "mit den Gewürzen aus Theramore",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, für Sumpfauge Jarl",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} kocht im {object:2169}; {npc:5384} ist im {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: andere Farben, 20g",
		["{npc:1356}: for {npc:1344} in {zone:1432}, keep it"] = "{npc:1356}: für {npc:1344} in {zone:1432}, behalte es",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, Königliche Bibliothek in {object:2117}",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}: {quest:93176}, aus 30-40/05-arathi-highlands",
		["{npc:217588}: catch it, for {quest:93176}"] = "{npc:217588}: Fang sie, für {quest:93176}",
		["{npc:2487}, top floor"] = "{npc:2487}, oberstes Stockwerk",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "{npc:2498}s nächster Zanzil-Auftrag beginnt in {zone:1441}: Überspring ihn.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} und {npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} schwimmt vor der Nordwestküste, auf der nördlichen Runde",
		["{npc:384}: other colours, 20g"] = "{npc:384}: andere Farben, 20g",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, im {object:2164}: {npc:6251} in {area:392} nimmt es am Ende des nächsten Guides an",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: andere Farben, 20g",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields."] = "{npc:4966} hält den Turm mit ein paar Deserteuren. Er wendet sich gegen dich: Schlag ihn, bis er aufgibt.",
		["{npc:5694}: for {area:1438}, keep it"] = "{npc:5694}: für {area:1438}, behalte es",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, in der Kathedrale des Lichts",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236} bietet als Nächstes Der Windbehüter (1791) an: Die Questreihe um die Waffe für Wirbelwind, mit einem Elite am Ende, steht im Kriegerklassen-Guide „Wirbelwaffe“.",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: für {quest:2864} in {zone:1446}, behalte es",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: andere Farben, 20g",
		["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910} ist das hohe Gebäude über dem Hafen; die meisten Questgeber sind auf seinen Stockwerken oder unten an den Docks.",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} steht nahe dem Gasthaus; {npc:4897}, ein Handwerkswarenhändler ein paar Schritte südlich, verkauft die Gewürze, die Jarl will.",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} hat keinen Schamanenlehrer",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Blue Pearls from Stranglethorn"] = "Blaue Perlen aus dem Schlingendorntal",
		["Fly to {area:392}; {npc:6251} teaches in the house by the bank. Fly back to Theramore afterwards."] = "Flieg nach {area:392}; {npc:6251} lehrt im Haus bei der Bank. Flieg danach zurück nach Theramore.",
		["Fly to {area:608}, ride south through {zone:1443} into {zone:1444} and follow the road to the dock on the {area:1108}; the boat crosses to {area:1116}, where the next guide starts."] = "Flieg nach {area:608}, reite nach Süden durch {zone:1443} nach {zone:1444} und folge der Straße zum Steg an der {area:1108}; das Schiff fährt hinüber zur {area:1116}, wo der nächste Guide beginnt.",
		["On to Feathermoon"] = "Weiter nach Feathermoon",
		["Raleigh's next errand is in the {area:796}: skip it."] = "Raleighs nächster Auftrag ist im {area:796}: Überspring ihn.",
		["Ride back east to {area:1898}."] = "Reite zurück nach Osten zu {area:1898}.",
		["Ride north to {area:144} and fly to {area:271}. {npc:3980} preaches by the inn."] = "Reite nach Norden nach {area:144} und flieg nach {area:271}. {npc:3980} predigt beim Gasthaus.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Reite auf der Straße nach Nordosten aus {area:271} ins {zone:1425}; {area:348} liegt gleich hinter der Grenze. {npc:5635} hält oben Hof, {quest:1450} kümmert sich um den Greifenhorst und {npc:7884} steht beim Gasthaus.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Reite nach Süden aus {zone:1432} durch den Pass ins {zone:1418}; {npc:2860} lagert bei der Ausgrabung.",
		["Ride west across the {zone:1418} to the Dustbelcher camp at {area:342}. {npc:2944} stands in its middle with Wyrmhunters and Maulers around him."] = "Reite nach Westen durch das {zone:1418} zum Lager der Staubspeier bei {area:342}. {npc:2944} steht in der Mitte, umgeben von Wyrmjägern und Raufern.",
		["Ride west to the {area:1877} in the middle of the {zone:1418}; {npc:2817} camps beside Martek."] = "Reite nach Westen ins {area:1877} mitten im {zone:1418}; {npc:2817} lagert neben Martek.",
		["Take the boat to Theramore from the far pier."] = "Nimm vom hinteren Pier das Schiff nach Theramore.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "Talonaxes nächste Aufgabe wartet auf einen späteren Guide für das {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Die Brühenden Welpen nisten in der Klamm östlich von {npc:2888}; lass die Versengten Wächter (Elite) in Ruhe. {item:4612} fällt selten: Nimm es mit, wenn es beim Grinden kommt.",
		["The battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers."] = "Das zerschlagene Skelett liegt am Rand des Lagers der Steingrufttroggs; {quest:739}, Agmonds Mörder, läuft zwischen den Knochenknackern herum.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "Die ersten beiden Käfige stehen zusammen im Dorf der Witherbark südlich von {npc:5634}; der dritte ist im nächsten Dorf östlich davon. Jeder Troll der Witherbark kann eine Halskette fallen lassen.",
		["Theramore"] = "Theramore",
		["Warlock: {quest:3631}"] = "Hexenmeister: {quest:3631}",
		["Witherbark villages"] = "Dörfer der Witherbark",
		["grind on {npc:2725} at {area:339}, {zone:1418}"] = "grinde {npc:2725} in {area:339}, {zone:1418}",
		["{npc:1573}, the {object:32372}"] = "{npc:1573}, {object:32372}",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} steht an den Docks, wo das Schiff anlegt.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "Die nächste Quest von {npc:2817} gibt keine Erfahrung: Überspring sie.",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} lagert allein in {area:1898}, südöstlich der Ausgrabungsstätte.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "Die nächste Aufgabe von {npc:2888} ist eine Elitejagd: Überspring sie.",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} lagert an der Straße östlich von {area:348}.",
		["{npc:5634}'s cocktail needs parts from Kalimdor: skip it."] = "{npc:5634}s Cocktail braucht Zutaten aus Kalimdor: Überspring ihn.",
		["{npc:5636}, beside the flight master at the top"] = "{npc:5636}, oben neben dem Flugmeister",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884} zahlt weiter für Halsketten: Gib alle übrigen ab",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Zurück zu den {area:1117}. Jeder Naga der Hasskämme dort kann Schuppen droppen.",
		["Boat to the {area:1108} and ride east across {zone:1444} to the Grimtotem camp north of the road. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "Nimm das Boot zum Gebiet {area:1108} und reite nach Osten durch {zone:1444} zum Lager der Grimmtotem nördlich der Straße. {npc:7956} wartet davor; befreie die Grimmlingflitzer aus dem Pferch in der Mitte und halte {npc:7956} und mindestens sechs von ihnen am Leben.",
		["Boat to the {area:1108} and ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45."] = "Nimm das Boot zum Gebiet {area:1108} und reite nach Osten ins {area:1105}. {npc:14637}s Quests an der Küste erfordern Stufe 45.",
		["From Theramore, fly to {area:608} and ride south out of {zone:1443} into {zone:1444}; the road leads west to the {area:1108} dock, where the boat crosses to Feathermoon on {area:1120}."] = "Flug ab Theramore: {area:608}. Reite dann südlich aus {zone:1443} hinaus nach {zone:1444}; die Straße führt nach Westen zum Steg im Gebiet {area:1108}, wo das Boot nach Feathermoon zur {area:1120} übersetzt.",
		["Giants and elementals"] = "Riesen und Elementare",
		["Gordunni ogres"] = "Oger der Gordunni",
		["Grimtotem camp"] = "Lager der Grimmtotem",
		["Grimtotem tauren"] = "Tauren der Grimmtotem",
		["Grind to 45"] = "Grinde bis 45",
		["Hatecrest naga"] = "Naga der Hasskämme",
		["Hearth to Feathermoon."] = "Ruhestein nach Feathermoon.",
		["Rage Scar yetis"] = "Wutschrammyetis",
		["Ride back north-west to the {area:1108} dock and take the boat to the island."] = "Reite zurück nach Nordwesten zum Steg im Gebiet {area:1108} und nimm das Boot zur Insel.",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "Reite zurück zum Gebiet {area:1108}; der Goblin steht beim Steg.",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "Reite auf der Straße zurück nach Westen, dann nach Norden in die Hügel der Wutschrammyetis. Jeder Yeti hier kann einen Balg droppen; einer droppt vielleicht einen {quest:7735}, den {npc:7852} ebenfalls bezahlt.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Reite nach Osten zum Lager der Gordunni in den Hügeln südöstlich des Yetitals: Hexenmeister und Schamanen halten das Lager, Schläger streifen über die Hänge drumherum und weiter nördlich.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Reite nach Norden ins Yetital. Jeder Wildschrammyeti kann einen dicken Yetibalg droppen; {npc:5346} (Stufe 48) streift durch die Mitte.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Reite nach Nordosten zum Außenposten der Nachtelfen an der Grenze zu {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Reite nach Südosten zu den Gnollen der Waldpfoten; die Rucksäcke des Kuriers liegen in ihrem südlichen Lager, und ein Paket darin startet eine Lieferung nach {area:489}. Der Stock der Zukk'ash liegt gleich südlich: Kämpf dich hinunter zur Kapsel, in der Raschal steckt, befreie ihn und halte ihn auf dem Weg nach draußen am Leben.",
		["Ride west to the friendly mountain giant at the foot of the hills. Land Walkers and Cliff Giants around him are elite: give them room."] = "Reite nach Westen zum freundlichen Bergriesen am Fuß der Hügel. Die Landgänger und Klippenriesen um ihn herum sind Elite: Halte Abstand.",
		["Ring the bell whenever {npc:7774} stops to wander, and lead her south to {npc:7765}."] = "Läute die Glocke, wann immer {npc:7774} stehen bleibt und umherwandert, und führe sie nach Süden zu {npc:7765}.",
		["Running {area:978} instead of grinding gets you there faster in a group. The troll city lies in northern {zone:1446}, the next zone on the route; come back to {npc:14637} on the {area:1108} afterwards."] = "Mit einer Gruppe kommst du schneller ans Ziel, wenn du {area:978} läufst, statt zu grinden. Die Trollstadt liegt im Norden von {zone:1446}, dem nächsten Gebiet der Route; komm danach zurück zu {npc:14637} im Gebiet {area:1108}.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Uferschreiter, Tiefenschreiter und Wellenschreiter (Elite-Riesen) waten nördlich des Stegs an der Küste entlang: Triff einen mit dem {item:18904} und töte den geschrumpften Riesen. Meereselementare und Meeresschauer treiben in derselben Brandung.",
		["Swim south from the island to the {area:1121}. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "Schwimm von der Insel nach Süden zum Gebiet {area:1121}. Schlangenwachen und Zauberhexerinnen der Hasskämme halten es; {npc:8136} (Stufe 47) wartet in der Höhle an seinem Südende. Zieh zuerst seine Wachen.",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Nimm das Boot zum Gebiet {area:1108} und folge dem Ufer nach Süden zum zerstörten Ruderboot am Strand.",
		["The courier's boat"] = "Das Boot des Kuriers",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Geh auf der Insel nach Süden zu den Ruinen der Naga; der Pavillon steht zwischen ihnen.",
		["You end at the {area:1108} dock: the {zone:1446} guide starts with the trip east from here."] = "Du endest am Steg im Gebiet {area:1108}: Der Guide für {zone:1446} beginnt mit der Reise von hier nach Osten.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "für Tyrande in {zone:1457}: Die Route führt dich mit 47 dorthin",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "grinde an {npc:5292} im {area:1105}, {zone:1444}",
		["if you carry {quest:1100} from {zone:1441}"] = "falls du {quest:1100} aus {zone:1441} dabeihast",
		["{area:978} instead of grinding"] = "{area:978} statt Grinden",
		["{item:11463}, from the backpacks"] = "{item:11463}, aus den Rucksäcken",
		["{npc:14637}'s refills are level 55: skip them."] = "{npc:14637}s Folgequests sind Stufe 55: Überspring sie.",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "{npc:3936} bittet dich dann, Nachrichten nach {zone:1457} zu bringen: Überspring das, {area:976} schickt dich stattdessen dorthin.",
		["{npc:3936}, beside him"] = "{npc:3936}, neben ihm",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: Seine Antwort wartet später in {area:702}",
		["{npc:7774} wanders the hills north of {npc:7765}, among the Northspring harpies; her bell is in the chest beside her."] = "{npc:7774} wandert durch die Hügel nördlich von {npc:7765}, zwischen den Harpyien der Nordschwingen; ihre Glocke liegt in der Truhe neben ihr.",
		["{npc:7774}'s escort"] = "{npc:7774}s Eskorte",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, oben in der Festung",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} wartet bis zum Ende der Runde auf dem Festland.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Fly from {area:976} to Theramore, take the boat to {area:150} and fly to {area:1537}. Train."] = "Flieg von {area:976} nach Theramore, nimm das Boot zum Ort {area:150} und flieg nach {area:1537}. Trainiere.",
		["Fly to {area:348}. {zone:1425} guide starts here."] = "Flieg nach {area:348}. Der Guide für {zone:1425} beginnt hier.",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp."] = "Folge der Küste nach Süden zur Piratenbucht. Piraten der Südmeerfreibeuter drängen sich am Strand und auf den Booten: Arbeite dich am Rand entlang und zieh einen nach dem anderen. {npc:7883} steht auf der anderen Seite; die gestohlene Fracht von {npc:7881} liegt im Lager.",
		["From the {area:1108} dock, boat to Feathermoon and fly to {area:489}, then ride east through {zone:1441} to the {area:2240} on the {area:439}. {npc:4454} and {npc:4630} are in the camps beside the track; {npc:4709} stands by the goblin camp."] = "Nimm vom Steg im Gebiet {area:1108} das Boot nach Feathermoon und flieg nach {area:489}, dann reite nach Osten durch {zone:1441} zur {area:2240} im Gebiet {area:439}. {npc:4454} und {npc:4630} sind in den Lagern neben der Rennstrecke; {npc:4709} steht beim Goblinlager.",
		["Gives the {item:8585}"] = "Gibt dir den {item:8585}",
		["He runs off to keep Rizzle busy"] = "Er läuft los, um Rizzle abzulenken",
		["Hearth to {area:976}."] = "Ruhestein nach {area:976}.",
		["Pool by {area:979}"] = "Teich bei der {area:979}",
		["Ride back west to {area:976}."] = "Reite zurück nach Westen nach {area:976}.",
		["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch."] = "Reite zurück nach Westen Richtung {area:976}. Die Banditen und Diebe der Wüstenläufer halten unterwegs die Dünen; jeder von ihnen kann einen Wasserbeutel tragen.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Reite nach Osten über die Dünen zum Goblinhafen an der Nordostküste.",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts."] = "Reite nach Nordwesten zum Stock der Centipaar in den Dünen. Jeder Centipaar kann Insektenteile droppen.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "Reite nach Nordwesten zum Trolllager der Sandfury bei der {area:979}. Benutze den {item:8584} am Rand des Teichs; die Trolle stehen dicht beieinander, also zieh zuerst den nächsten.",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time."] = "Reite nach Süden ins {quest:3362}. Die Disteltausammler droppen die Drüsen; nur manche sind gefüllt, also behalte die Gefüllte Taudrüse. Knorrige Distelwandler und Distelwurzelformer teilen sich das Tal. Die Distelwandler sind Stufe 48-50, über dir: Zieh einen nach dem anderen.",
		["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside."] = "Reite nach Süden an {area:1938} vorbei zu {area:981}, den Tunneln der Hazzali; Scrimshanks Ausrüstung liegt tief darin.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Reite nach Süden zum Grabungslager an der {area:1938}. {npc:7771} gibt dir einen Detektorhelm: Trag ihn, um die Hügel von {quest:3161} zu sehen, die dicht im Sand rund um das Lager und nach Südwesten Richtung Oger liegen.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "Reite vom Gebiet {area:439} nach Südosten nach {zone:1446}. {area:976} liegt gleich hinter der Grenze.",
		["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first."] = "Reite nach Südosten zum {area:985}. {npc:7847} steht in der Mitte des südlichen Lagers der Wüstenläufer: Räum zuerst um ihn herum.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Reite nach Südwesten zum Lager der Oger. Schläger und Vollstrecker (46-48) füllen es; {npc:12046} (49) steht mit Wachen um sich herum in der Mitte: Räum sie zuerst weg.",
		["Rizzle's plans"] = "Rizzles Pläne",
		["The Wanted poster beside him"] = "Der Steckbrief neben ihm",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "Die kleine Schildkröte {npc:5955} versteckt sich am Nordende des Tals. Führe ihn heim zu seiner Frau {npc:6015}, am Wasser gleich östlich von {area:977}: Er läuft langsam und die Bestien der Wüste greifen ihn an, also halte ihn am Leben.",
		["The pool by {area:979}"] = "Der Teich bei der {area:979}",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later."] = "Die stärkeren Schurken, Schattenmagier und Auftragsmörder der Wüstenläufer lagern südöstlich von {area:976}, südlich der Banditen. Lass {npc:7847} in der Mitte des südlichen Lagers für später.",
		["The {area:1938}"] = "Die {area:1938}",
		["Wastewander bandits"] = "Banditen der Wüstenläufer",
		["While {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "Während {npc:4709} Rizzle in ein Gespräch verwickelt, liegen dessen Pläne unbewacht im Gnomenlager auf der anderen Seite der Rennstrecke.",
		["for {zone:1457}: the route takes you there at 47"] = "für {zone:1457}: Die Route führt dich mit 47 dorthin",
		["{npc:11758}, on the east side of town"] = "{npc:11758}, an der Ostseite der Stadt",
		["{npc:5955}'s escort"] = "Eskorte von {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, beim Wasserturm",
		["{npc:7408}, next to him"] = "{npc:7408}, neben ihm",
		["{npc:7583}'s next ingredient grows in the {zone:1425}, and the route never brings it back: skip it."] = "Die nächste Zutat von {npc:7583} wächst im {zone:1425}, und die Route führt dich nie wieder dorthin: Überspring sie.",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: Seine Kiste geht später nach {area:702}",
		["{npc:7881}'s next delivery goes back to {area:35}: skip it."] = "Die nächste Lieferung von {npc:7881} geht zurück nach {area:35}: Überspring sie.",
		["{npc:7881}, in the port's tavern"] = "{npc:7881}, in der Taverne des Hafens",
		["{quest:2864}, north side of town"] = "{quest:2864}, an der Nordseite der Stadt",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Ashmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52."] = "Aschmähneneber und Rotsteinbasilisken teilen sich die Hänge südwestlich der Burg. Halte dich von den Höllenebern weiter südlich fern: Sie sind Stufe 52.",
		["Back to {area:144}"] = "Zurück nach {area:144}",
		["Boars and basilisks"] = "Eber und Basilisken",
		["Fly from {area:144} to {area:150}, take the boat to {area:442} and fly to {area:702}."] = "Flieg von {area:144} zum Ort {area:150}, nimm das Boot nach {area:442} und flieg nach {area:702}.",
		["Fly from {area:348} to {area:42}."] = "Flieg von {area:348} nach {area:42}.",
		["Hearth to {area:144}. The {zone:1427} guide starts at {area:1446}: from here, ride south into the {zone:1418}, west past the Horde town of {area:340} and up the trail into the gorge."] = "Ruhestein nach {area:144}. Der Guide für {zone:1427} beginnt an der {area:1446}: Reite von hier nach Süden ins {zone:1418}, nach Westen an der Hordestadt {area:340} vorbei und den Pfad hinauf in die Schlucht.",
		["Hearth to {area:348}."] = "Ruhestein nach {area:348}.",
		["Hearthstone on cooldown? Ride back north-west."] = "Ruhestein noch nicht bereit? Reite zurück nach Nordwesten.",
		["Ride back east to {area:1438} and fly to {area:144}."] = "Reite zurück nach Osten zur {area:1438} und flieg nach {area:144}.",
		["Ride back north to Ironband's camp."] = "Reite zurück nach Norden zu Ironbands Lager.",
		["Ride east along the south shore of the loch to Ironband's camp."] = "Reite am Südufer des Sees entlang nach Osten zu Ironbands Lager.",
		["Ride east through {zone:1430} into the {zone:1435} and south down the road into the {zone:1419}. The bloodmages' camp is the first stop beside the road."] = "Reite nach Osten durch den {zone:1430} in die {zone:1435} und auf der Straße nach Süden ins Gebiet {zone:1419}. Das Lager der Blutmagier ist der erste Halt an der Straße.",
		["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it."] = "Reite nach Norden zum {area:351} in der Mitte des {zone:1425}. Grüne Schlämme und Jadegrüne Brühschlammer kriechen überall drumherum.",
		["Ride on east along the road to the keep first: the {item:6091} expires an hour after {area:42}, and the bloodmages' beasts take longer than that."] = "Reite zuerst weiter nach Osten auf der Straße zur Burg: Die {item:6091} verfällt eine Stunde nach {area:42}, und die Bestien für die Blutmagier dauern länger.",
		["Ride south through the pass into the {zone:1418}' northern edge: the Stonevault troggs dig outside {area:1517} there. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "Reite nach Süden durch den Pass zum Nordrand des Gebiets {zone:1418}: Dort graben die Steingrufttroggs vor {area:1517}. Die verzierten Urnen und die magentafarbenen Pilzbüschel liegen in ihren Höhlen und Tunneln, außerhalb des Dungeons selbst.",
		["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down."] = "Reite nach Südosten zum Ort {area:355}, dem gestuften Tempel der Vilebranch im Süden des {zone:1425}, und steig ganz nach oben. Qiaga und {npc:8636} (Elite, 50) stehen dort oben: Berühre die Spitze und komm sofort wieder herunter.",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time."] = "Reite nach Westen: Verhungernde Kicherfänge streifen durch die trockenen Hügel gleich südlich des Lagers der Blutmagier; Skorpokstecher (Stufe 50) krabbeln durch die Mitte des Nordens. Geier ({npc:5982}) kreisen über allem. Zieh einen nach dem anderen.",
		["Scorpoks and snickerfangs"] = "Skorpoks und Kicherfänge",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Geh durch das Portal nach {zone:1457}. Der Tempel des Mondes liegt im Süden der Stadt.",
		["Temple of the Moon"] = "Der Tempel des Mondes",
		["The bloodmages"] = "Die Blutmagier",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "Die zweite Stufe der Blutmagier bezahlt dieselben Teile mit einem Buff-Gegenstand und ohne Erfahrung: Überspring sie.",
		["The druid trainers stand in the Enclave; {zone:1455} has none"] = "Die Druidenlehrer stehen in der Enklave; {zone:1455} hat keine",
		["The {area:1517} dig"] = "Die Ausgrabung bei {area:1517}",
		["for {quest:2990} at {area:1438}, later"] = "für {quest:2990} in der {area:1438}, später",
		["the book on her table"] = "das Buch auf ihrem Tisch",
		["the soil comes from {zone:1449}, later"] = "die Erde kommt später aus dem {zone:1449}",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, oben im Baum",
		["{npc:7740}, beside her"] = "{npc:7740}, neben ihr",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "{npc:7907}s nächster Auftrag führt nach {zone:1446}: Überspring ihn.",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916}: Behalte sie, die Federn kommen am Ende des Guides für {zone:1428}",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "Die nächste Aufgabe von {npc:8022}, {item:9471}, ist eine Quest für {area:978}: Überspring sie.",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, oben in der Burg",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["For {npc:8256} in {zone:1455}, later"] = "Für {npc:8256} in {zone:1455}, später",
		["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {zone:1427}. {area:1446} is the scaffolded camp on the north-west rim."] = "Reite von {area:144} nach Süden ins {zone:1418}, dann nach Westen an der Hordestadt {area:340} vorbei (halte Abstand) und den Pfad hinauf in die {zone:1427}. Die {area:1446} ist das eingerüstete Lager am Nordwestrand.",
		["Golems and elementals"] = "Golems und Elementare",
		["Greater Lava Spiders"] = "Versengende Lavaspinnen",
		["Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "Schwere Kriegsgolems patrouillieren unterhalb von Kalaran über den Boden des Kessels; Magmaelementare treiben zwischen ihnen. Golems und Elementare droppen das Öl, Elementare die Herzen.",
		["Kalaran stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "Kalaran steht am Rand des Kessels, südlich der {area:1446}. Hör dir seine Geschichte an.",
		["Ride east across the Cauldron to the {area:247} in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one."] = "Reite nach Osten über den Kessel zur {area:247} im Südosten. Der Gefangene im hölzernen Abort will 15 {item:4306} und acht tote Geologen der Dunkeleisenzwerge von der Grabungsstätte drumherum. Der Abort lässt sich auch mit dem Schlüssel öffnen, falls du einen gefunden hast.",
		["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it."] = "Zuchtmeister und Sklavenhändler treiben die Sklaven überall im Kessel an, und jeder von ihnen kann einen {item:10551} tragen. Die Dampfschmiede arbeiten an den Schmelzöfen in der Mitte (die {item:18959}), die Ausgucke stehen auf den südlichen Graten (das Handfernrohr). Jeder {object:147516}-Zwerg kann den {item:11818} droppen: Behalte ihn.",
		["The Grimesilt outhouse"] = "Das Grimesilt-Nebengebäude",
		["The dwarf stands by the road at the dig site. Follow him north along the road and fight off the {object:147516} ambushes. When it is over, read the {object:175704} he leaves on the road in {area:1959}."] = "Der Zwerg steht an der Straße bei der Grabungsstätte. Folge ihm auf der Straße nach Norden und wehr die Hinterhalte der {object:147516}-Zwerge ab. Wenn es vorbei ist, lies den {object:175704}, den er im {area:1959} auf der Straße zurücklässt.",
		["The night elf stands alone west of {area:1446}. Hear his story."] = "Der Nachtelf steht allein westlich der {area:1446}. Hör dir seine Geschichte an.",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "Die nächste Aufgabe des Gefangenen, Geschäftsbuch aus {zone:1446}, schickt dich in die {zone:1435} und in die {zone:1445}: Überspring sie.",
		["The spiders roam the plateaus and lava pools in the south-west of the gorge."] = "Die Spinnen streifen über die Plateaus und Lavateiche im Südwesten der Schlucht.",
		["The {object:179827} board"] = "Das Brett {object:179827}",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443} öffnet sich im Norden des Kessels. Die Geheimpläne liegen auf ihrem oberen Vorsprung; Incendosaurier schwimmen weiter drinnen in den Lavateichen, also zieh sie an den Rand. Halte dich von {npc:14621} und seinen Elitewachen tief drinnen fern.",
		["{object:147516} dwarves"] = "{object:147516}-Zwerge",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Archesonus steht neben König Magni im {object:171709}.",
		["Bind and train"] = "Binden und trainieren",
		["Bones and equipment"] = "Knochen und Ausrüstung",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Durchquere den Süden des Kraters zu {npc:9619} an der Rampe.",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "Dinosaurierknochen liegen im Südwesten auf dem Boden, zwischen den Stegodons: Die sind Elite, sammle die Knochen um sie herum auf und hol den Rest von Dimetrodons. Die {item:11112} der Expedition liegt im südwestlichen Dschungel.",
		["Eastern Pylon"] = "Östlicher Kristallpylon",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Endet bei {npc:9298} in {zone:1452}: Behalte es",
		["Escort {npc:9999}"] = "Eskortiere {npc:9999}",
		["Fly from {area:144} to {area:1537}."] = "Flieg von {area:144} nach {area:1537}.",
		["For {npc:7775} in {zone:1444}: keep it"] = "Für {npc:7775} in {zone:1444}: Behalte es",
		["Four rune rubbings in {zone:1447}: keep it"] = "Vier Runenabriebe in {zone:1447}: Behalte es",
		["From {area:144} fly to {area:150}, take the boat to Theramore and fly on to {area:976}. {npc:9619}'s first quest in the crater needs level 48: finish the level here if you are short."] = "Flieg von {area:144} nach {area:150}, nimm das Boot nach Theramore und flieg weiter nach {area:976}. {npc:9619}s erste Quest im Krater erfordert Stufe 48: Mach die Stufe hier voll, falls dir etwas fehlt.",
		["Grind to 50"] = "Grinde bis 50",
		["Grind to 51"] = "Grinde bis 51",
		["Gryfe"] = "Gryfe",
		["Lar'korwi Mates and the raft"] = "Lar'korwi-Weibchen und das Floß",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Führ {npc:9999} nach Norden zu {area:541}. Wenn er ohnmächtig wird, benutze {item:11804} an ihm, um ihn zu wecken.",
		["Northern Pylon"] = "Nördlicher Kristallpylon",
		["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "Reite die Rampe hinab in den Krater: {npc:9619} lagert an ihrem Fuß.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "Reite nach Osten zum {area:537}, klettere hinauf und benutze {npc:10541} an den Lavaschloten nahe dem Gipfel.",
		["Ride north along the east side of the crater to {area:541}, the camp in the caves of the northern cliff. Give the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and {object:157936} you pass from here on."] = "Reite an der Ostseite des Kraters nach Norden zu {area:541}, dem Lager in den Höhlen der Nordklippe. Mach einen großen Bogen um die Elite-Teufelssaurier und Stegodons. Sammle ab hier jeden Machtkristall und jede {object:157936} ein, an denen du vorbeikommst.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Reite an der Ostseite nach Norden zum Gorillaplateau. {npc:9622}, ein Gorilla der Stufe 55, sitzt in dessen tiefster Höhle: Säubere zuerst die Gorillas am Höhleneingang.",
		["Ride north along the western jungle back to the refuge."] = "Reite durch den westlichen Dschungel nach Norden zurück zur Zuflucht.",
		["Ride north to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "Reite nach Norden zum {area:1943}, wo der Roboter zwischen den Gorillas steht. Bleib dort aus der tiefen Höhle fern.",
		["Ride south along the eastern cliffs to {npc:9619} at the foot of the ramp."] = "Reite an den östlichen Klippen entlang nach Süden zu {npc:9619} am Fuß der Rampe.",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales."] = "Reite an der Ostseite nach Süden. Junge Dimetrodons grasen im östlichen Dschungel, und {npc:9165} fliegen nahe den östlichen Klippen; beide lassen die Schuppen für {npc:9998} fallen.",
		["Ride south to {area:537} in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around {area:537}: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "Reite nach Süden zum {area:537} in der Mitte des Kraters, dann nach Osten in den östlichen Dschungel. Kristallhaufen stehen überall im Krater, viele davon um den {area:537}: Nimm von jeder Farbe ein paar extra. Blutblütenpeitscher und Blutblütendrescher lassen die Blütenblätter fallen; die {item:11113} der Expedition liegt in einem verlassenen Lager im östlichen Dschungel.",
		["Ride west back to the refuge."] = "Reite nach Westen zurück zur Zuflucht.",
		["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; {npc:9166} nest on the southern cliffs if you still need kills."] = "Reite von {npc:9619} nach Westen: Der Silithidenbau füllt den Süden des Kraters. Benutze die Kratzphiole an einer Brutstätte, einer Kammer mit hängenden Larven. Wespen und Arbeiter der Gorishi lassen {quest:3764} fallen; {npc:9166} nisten an den Südklippen, falls dir noch Kills fehlen.",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "Reite nach Westen aus {area:976} hinaus zur langen Rampe hinab in den {zone:1449}. {npc:9619} lagert am Fuß der Rampe, in der Südostecke des Kraters.",
		["Ride west past {area:541} and south down the western side to {area:543}: {npc:10302} the goblin sits by the water."] = "Reite nach Westen an {area:541} vorbei und an der Westseite nach Süden zu {area:543}: {npc:10302}, der Goblin, sitzt am Wasser.",
		["Running the {area:1417} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Der {area:1417} statt Grinden bringt dich in einer Gruppe schneller ans Ziel. Überspring diesen Schritt, um allein zu grinden.",
		["Running {area:978} instead of grinding gets you there faster in a group. The troll city lies in the north-west of {zone:1446}, just north of {area:976}."] = "{area:978} statt Grinden bringt dich in einer Gruppe schneller ans Ziel. Die Trollstadt liegt im Nordwesten von {zone:1446}, gleich nördlich von {area:976}.",
		["The Centipaar silithid crawl around the {area:982} in western {zone:1446}, just east of the crater ramp. The Workers are the easiest pulls."] = "Die Silithiden der Centipaar krabbeln um die {area:982} im Westen von {zone:1446}, gleich östlich der Kraterrampe. Die Arbeiter sind am leichtesten zu ziehen.",
		["The Gorishi hive"] = "Der Gorishi-Bau",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "Die Lar'korwi-Weibchen streifen durch den Dschungel westlich von {npc:9619}. Das zerstörte Floß liegt dort am Seeufer; das kleine Bündel liegt daneben im Wasser. Behalte Kompass, Karte und Schlüssel für {npc:8737}. Jedes Wildtier im Krater kann {item:11116} fallen lassen: Rechtsklick darauf.",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "Der tote Dreschadon liegt am Wasser nördlich von {npc:9619}.",
		["The east side"] = "Die Ostseite",
		["The gorillas live on {area:1943}, east of {area:541}. Keep their pelts for {npc:9619}. Stay out of the deepest cave: {npc:9622} is level 55."] = "Die Gorillas leben auf dem {area:1943}, östlich von {area:541}. Behalte ihre Felle für {npc:9619}. Bleib aus der tiefsten Höhle fern: {npc:9622} ist Stufe 55.",
		["The gorillas of {area:1943} come in small groups and drop nothing for you yet; {npc:9619}'s pelt quest comes later. Stay out of the deepest cave: {npc:9622} is level 55."] = "Die Gorillas vom {area:1943} kommen in kleinen Gruppen und lassen für dich noch nichts fallen; {npc:9619}s Fellquest kommt später. Bleib aus der tiefsten Höhle fern: {npc:9622} ist Stufe 55.",
		["The pelts come after loop 2, on the gorilla plateau"] = "Die Felle kommen nach Runde 2, auf dem Gorillaplateau",
		["The pylon stands on the eastern cliffs."] = "Der Pylon steht auf den östlichen Klippen.",
		["The pylon stands on the slope east of the refuge. {npc:9166} circle the slopes around it: they count for {npc:9997} and drop {npc:9998}'s scales."] = "Der Pylon steht am Hang östlich der Zuflucht. {npc:9166} kreisen über den Hängen darum: Sie zählen für {npc:9997} und lassen die Schuppen für {npc:9998} fallen.",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "Der Pylon steht auf den westlichen Klippen. {npc:9167} fliegen über die ganze Westseite.",
		["The relics are in the {zone:1428}: keep it"] = "Die Relikte sind in der {zone:1428}: Behalte es",
		["The wooden sign beside {npc:9997}"] = "Das Holzschild neben {npc:9997}",
		["Western Pylon"] = "Westlicher Kristallpylon",
		["Xiggs waits in the {object:32359}."] = "Xiggs wartet im {object:32359}.",
		["grind on the Wastewanderers or Dunemaul ogres around {area:976}"] = "Grinde an den Wüstenläufern oder den Ogern der Dünenbrecher um {area:976}",
		["grind on {npc:5458} at {area:982}, {zone:1446}"] = "Grinde an {npc:5458} bei {area:982}, {zone:1446}",
		["grind on {npc:6514} at {area:1943}, {zone:1449}"] = "Grinde an {npc:6514} auf dem {area:1943}, {zone:1449}",
		["{area:537} and the eastern jungle"] = "{area:537} und der östliche Dschungel",
		["{area:978} (optional)"] = "{area:978} (optional)",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}: für Ogtinc in {zone:1447}, behalte es",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}, hinten in der Höhle",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: Die Schlammbestien sind in {zone:1448}, behalte es",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618} steht gleich vor der Zuflucht.",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "Der Bau von {npc:9684} liegt im Dschungel nördlich von {npc:9619}, unterhalb der östlichen Klippen: Benutze dort {item:11568}. {npc:9684} ist Stufe 56: Fang mit voller Gesundheit an.",
		["{npc:9997}'s friend {npc:9999} has gone missing."] = "{npc:9997}s Freund {npc:9999} wird vermisst.",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, am Eingang der Zuflucht",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}, am Eingang der Zuflucht",
		["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999} sitzt am Südosthang des {area:537}, in der Mitte des Kraters.",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Climb back to {npc:8405} at the {area:1224}, above the ruins."] = "Klettere zurück zu {npc:8405} beim {area:1224}, oberhalb der Ruinen.",
		["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "Klettere auf den {area:249} und pflanze den Kopf in den Haufen weicher Erde.",
		["Druid training"] = "Druidentraining",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "Endet bei {quest:4808} in {area:2255}, {zone:1452}: Behalte es",
		["Fly from {zone:1455} to {area:150} and take the boat to {area:442}."] = "Flieg von {zone:1455} nach {area:150} und nimm das Boot nach {area:442}.",
		["Fly from {zone:1455} to {area:69}."] = "Flieg von {zone:1455} nach {area:69}.",
		["Fly to {area:1438}."] = "Flieg nach {area:1438}.",
		["Fly to {area:150} and take the boat to {area:442}, then the boat on to {area:702}."] = "Flieg nach {area:150} und nimm das Boot nach {area:442}, dann das Boot weiter nach {area:702}.",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "Folge der Straße nach Westen und klettere dann nach Norden zum Goblinlager am {area:251}.",
		["From the {area:442} dock, fly to {area:415}."] = "Flieg vom Steg in {area:442} nach {area:415}.",
		["Mosshoof Coursers"] = "Mooshufrenner",
		["Optional: {npc:8395} wants two Undamaged Hippogryph Feathers from the hippogryphs around his camp. The data lists no experience for it."] = "Optional: {npc:8395} will zwei Unbeschädigte Hippogryphenfedern von den Hippogryphen um sein Lager. Die Daten nennen dafür keine Erfahrung.",
		["Optional: {npc:8888}'s ghost stands on his tomb on the great chain inside {area:254}, and only the dead can see him. If you die near the mountain anyway, run your spirit to him before resurrecting."] = "Optional: {npc:8888}s Geist steht auf seinem Grab an der großen Kette im {area:254}, und nur Tote können ihn sehen. Stirbst du ohnehin nahe dem Berg, lauf als Geist zu ihm, bevor du wiederbelebt wirst.",
		["Read the tablet in the {object:147516} camp among the ruins, south-west of {area:251}, to copy the transcript."] = "Lies die Tafel im Lager von {object:147516} zwischen den Ruinen südwestlich des {area:251}, um die Abschrift anzufertigen.",
		["Ride back east along the road to the Vigil."] = "Reite die Straße zurück nach Osten zur Wacht.",
		["Ride back to {area:1438} and fly to {area:348}. The Wildkin Feathers lie on the ground across the {zone:1425}, south and east of {area:348}, where the owlbeasts roam; the mobs here are well below you now."] = "Reite zurück nach {area:1438} und flieg nach {area:348}. Die Wildekinfedern liegen überall im {zone:1425} auf dem Boden, südlich und östlich von {area:348}, wo die Eulenbestien umherstreifen; die Gegner hier sind jetzt weit unter dir.",
		["Ride east along the road out of {zone:1440} into {zone:1447} to the Sentinels' camp at {area:3137}."] = "Reite die Straße nach Osten aus {zone:1440} hinaus nach {zone:1447} zum Lager der Schildwachen bei {area:3137}.",
		["Ride north out of {area:69} through the pass into the {zone:1428}; {area:2418} sits at the top, in the south-east of the Steppes."] = "Reite nach Norden aus {area:69} durch den Pass in die {zone:1428}; {area:2418} liegt oben, im Südosten der Steppe.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "Reite vom Schrein nach Nordosten: {npc:8405} lagert beim {area:1224}, in den Hügeln über der Straße.",
		["Swim to the small island off the southern tip of {zone:1447}: {npc:8392} waits by the monument."] = "Schwimm zur kleinen Insel vor der Südspitze von {zone:1447}: {npc:8392} wartet beim Denkmal.",
		["Thaurissan Relics"] = "Thauris-Relikte",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "Die Oger der Feuermägen halten den großen Felsen nördlich der Wacht, mit den Schlägern auf seiner Ostseite.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "Die Geister der Hochgeborenen spuken in den Ruinen um den Schrein; die Satyrn der Haldarr halten das Lager gleich nördlich davon.",
		["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "Die Naga der Grollflossen in {area:1221} tragen {item:13815}. Die vier Runen von {npc:8507} stehen zwischen den Ruinen: Benutze sein {item:10445} an jeder.",
		["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "Die nächsten Mooshufrenner grasen in den Hügeln nordöstlich des {area:1224}, Richtung {area:1219}; eine größere Herde streift durch das offene Gelände im Süden.",
		["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered."] = "Die Relikte sind die behauenen Steine, verstreut in den {area:250} um den {area:251}: Klick sie an, bis die Informationen geborgen sind.",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "Der Schrein liegt in der Südwestecke von {zone:1447}, südlich von {area:3137}.",
		["The wildkin are in {zone:1452}: keep it"] = "Die Wildekin sind in {zone:1452}: Behalte es",
		["The {area:1221}"] = "{area:1221}",
		["The {quest:4296}"] = "{quest:4296}",
		["Use the {item:12284} on a {npc:7047} on the slopes east of {area:251} just before it dies, then loot the essence it leaves."] = "Benutze die {item:12284} an einem {npc:7047} an den Hängen östlich des {area:251} kurz vor seinem Tod und plündere dann die Essenz, die er hinterlässt.",
		["Wildkin feathers"] = "Wildekinfedern",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}: der {npc:7864}, etwa 10%",
		["{npc:7363} waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have."] = "{npc:7363} wartet beim {area:2517}, dem Hügel südwestlich der Burg. Die Gegner der {zone:1419} unterwegs lassen die Unvollständigen Draenethystfragmente fallen; bring ihr, was du hast.",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420} lagert bei {area:1219} im Norden; seine Ausrüstung liegt überall in {area:1220} gleich südöstlich von ihm verstreut.",
		["{npc:9176} and the Blackrock orcs hold the camps and the stronghold at the foot of {area:254}, west of {area:251}. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty."] = "{npc:9176} und die Orcs der Blackrock halten die Lager und die Festung am Fuß des {area:254}, westlich des {area:251}. Zieh sie einzeln; jeder Orc und Worg kann ein Medaillon fallen lassen, töte sie also, bis du fünfzig hast.",
		["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177}: Die Orcs der Blackrock lassen die Medaillons fallen, lass sie die ganze Steppe über offen",
		["{zone:1455} has no druid trainer: take the portal up to {zone:1457} and train in the {area:1658}, then come back down to {area:702}."] = "{zone:1455} hat keinen Druidenlehrer: Nimm das Portal hinauf nach {zone:1457} und trainiere im {area:1658}, dann komm zurück hinab nach {area:702}.",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Ends in the {zone:1413}: keep it"] = "Endet im {zone:1413}: Behalte es",
		["First crater"] = "Erster Krater",
		["Five feathers buy a little Timbermaw reputation"] = "Fünf Federn bringen ein wenig Ruf bei der Holzschlundfeste",
		["Fly from {area:1998} to the Sanctuary's end of the road, or ride south along it."] = "Flieg von {area:1998} zum Ende der Straße beim Refugium oder reite sie nach Süden entlang.",
		["Follow the road north to the cave mouth of {area:1769}; {npc:15395} guards it."] = "Folge der Straße nach Norden zum Höhleneingang der {area:1769}; {npc:15395} bewacht ihn.",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "Folge der Straße nach Norden ins Kratertal und geh zu jedem Krater; töte dabei die Entropischen Bestien und Schrecken dazwischen.",
		["Keep her alive until she is out of the cave"] = "Halte sie am Leben, bis sie aus der Höhle ist",
		["Oozes"] = "Schlammbestien",
		["Ride east to the night elf camp at {area:1998}."] = "Reite nach Osten zum Nachtelfenlager in {area:1998}.",
		["Ride north out of {area:415} into {zone:1448}. {npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "Reite nach Norden aus {area:415} hinaus in den {zone:1448}. {npc:11554}, der Furbolg, steht an der Straße gleich südlich des {area:2479}.",
		["Ride north to {area:1769} (or fly back to {area:1998} first) and through the tunnel into {zone:1452}; follow the road east to the goblin town of {area:2255}."] = "Reite nach Norden zur {area:1769} (oder flieg erst zurück nach {area:1998}) und durch den Tunnel nach {zone:1452}; folge der Straße nach Osten zur Goblinstadt {area:2255}.",
		["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "Salfa steht am Ende des Tunnels in {zone:1452}: Behalte es",
		["Second crater"] = "Zweiter Krater",
		["Step into the cave: {npc:11558} and {npc:11557} stand just inside."] = "Betritt die Höhle: {npc:11558} und {npc:11557} stehen gleich hinter dem Eingang.",
		["Take the boat from {area:702} to {area:442} and fly to {area:415}."] = "Nimm das Boot von {area:702} nach {area:442} und flieg nach {area:415}.",
		["The Cursed and Tainted Oozes slide about the streams and fel pools around {area:1763} and {area:1765}: kill them and use Laris's Empty Ooze Jars on their remains."] = "Die Verfluchten und Besudelten Brühschlammer gleiten durch die Bäche und Teufelstümpel um {area:1763} und {area:1765}: Töte sie und benutze Laris' leere Schlammgefäße an ihren Überresten.",
		["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "Die Furbolgs der Totenwaldfelle leben im Dorf gleich südwestlich von {npc:11554}; behalte die Kopfputzfedern der Totenwaldfelle, die sie fallen lassen.",
		["The Deadwood furbolgs of {area:1762} fill the hills west of the cave. The Avengers can drop a {quest:8470}."] = "Die Furbolgs der Totenwaldfelle im {area:1762} füllen die Hügel westlich der Höhle. Die Rächer können ein {quest:8470} fallen lassen.",
		["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back."] = "Die Jadefeuersatyrn halten das Tal westlich der Straße, mit {npc:9454} im hinteren Teil.",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "Die Wucherborkentreants im {area:1767}, östlich der {area:2618}, tragen die {item:11503}.",
		["The vial is filled in {zone:1457}: keep it"] = "Die Phiole wird in {zone:1457} gefüllt: Behalte es",
		["The {area:2479}"] = "{area:2479}",
		["Third crater"] = "Dritter Krater",
		["Use the {item:12922} at the corrupted moonwell in the middle of {area:1763}. If you freed {npc:11018}, go back into {area:1770} for the succubus {npc:9518}; Trey Lightforge's remains lie beside her."] = "Benutze die {item:12922} am verderbten Mondbrunnen mitten in {area:1763}. Hast du {npc:11018} befreit, geh zurück in {area:1770} zum Sukkubus {npc:9518}; die Überreste von Trey Lightforge liegen neben ihr.",
		["{area:1763} again"] = "Wieder {area:1763}",
		["{area:1763} is the ruined temple north of the glen. Some of its cultists drop a {item:13140}, about one kill in thirty: it opens {npc:11018}'s cell in {area:1770}, the cave at the back. If it drops, clear the way out before you free her; if not, skip her quests."] = "{area:1763} ist der verfallene Tempel nördlich des Tals. Manche seiner Kultisten lassen einen {item:13140} fallen, etwa einer von dreißig: Er öffnet die Zelle von {npc:11018} in {area:1770}, der Höhle im hinteren Teil. Fällt er, säubere den Weg nach draußen, bevor du sie befreist; sonst überspring ihre Quests.",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "{area:2618} ist das Satyrtal im Nordwesten, mit {npc:10648} an seinem hinteren Ende. Er lässt {quest:939} fallen; jeder Jadefeuersatyr kann {item:11674} fallen lassen.",
		["{item:13140}, a rare drop"] = "{item:13140}, seltene Beute",
		["{npc:11016}, in {area:1770}"] = "{npc:11016}, in {area:1770}",
		["{npc:11557}: thirty {quest:6031}, handed in when you pass through again at 57"] = "{npc:11557}: dreißig {quest:6031}, abgegeben, wenn du mit 57 wieder durchkommst",
		["{npc:11558}: the Timbermaw speak to you only from Neutral"] = "{npc:11558}: Die Holzschlundfeste spricht erst ab Neutral mit dir",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395} wartet am Nordende des {zone:1448}",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}, in den Ruinen gleich östlich von {npc:11554}",
		["{quest:8470}, a rare drop"] = "{quest:8470}, seltene Beute",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Back to the hills: only the Ice Thistle Matriarchs and Patriarchs carry the horns. Keep killing yetis until level 54: Harlo's wildkin quests are red before that."] = "Zurück in die Hügel: Nur die Eisdistelmatriarchinnen und Eisdistelpatriarchen tragen die Hörner. Töte weiter Yetis bis Stufe 54: Harlos Wildekinquests sind vorher rot.",
		["Follow the road east across the zone to the chapel."] = "Folge der Straße nach Osten durch das Gebiet zur Kapelle.",
		["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "Folge der Straße nach Westen zu {npc:9298}s Lager neben den heißen Quellen.",
		["Follow the southern road east into the {zone:1423}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "Folge der südlichen Straße nach Osten nach {zone:1423}; die Ruinen von {area:2262} liegen südlich davon. {npc:10926}s Geist spielt beim zerstörten Haus am Südende.",
		["Follow {npc:9298}'s directions to the mouth of {area:2256}, past the Frostmaul giants: pass them one at a time."] = "Folge {npc:9298}s Wegbeschreibung zum Eingang von {area:2256}, vorbei an den Frosthagelriesen: Passiere sie einzeln.",
		["For Kernda in {area:1769}: keep it"] = "Für Kernda in {area:1769}: behalten",
		["Free Darrowshire Spirits: talk to them"] = "Befreie Geister von Darrowshire: Sprich mit ihnen",
		["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}."] = "Eisdistelyetis leben in den Hügeln südlich von {area:2244}, Eiswindschimären im Tal Richtung {area:2255}.",
		["Keep it: Gregan in {zone:1444} brews the elixir later"] = "Behalten: Gregan in {zone:1444} braut das Elixier später",
		["On {npc:10978}, by the inn"] = "Bei {npc:10978}, am Gasthaus",
		["Optional: {area:1417}"] = "Optional: {area:1417}",
		["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "Sammle die Vorräte um den Wagen auf und hol dir {npc:10301}s Amulett von den Eulenbestien in der Nähe zurück.",
		["Pristine Yeti Horns"] = "Makellose Yetihörner",
		["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby."] = "Reite nach Norden nach {area:2627}. {npc:12384} lebt in der zerstörten Hütte, sein Quittungsbuch liegt im zerstörten Gasthaus in der Nähe.",
		["Ride north-west back to the village."] = "Reite nach Nordwesten zurück ins Dorf.",
		["Ride south-east down the valley to {npc:10301}'s damaged crate in the snow at {area:2245}, with his wrecked wagon just east of it."] = "Reite nach Südosten das Tal hinunter zu {npc:10301}s beschädigter Kiste im Schnee bei {area:2245}; sein zerstörter Wagen steht gleich östlich davon.",
		["Ride west along the road to the night elf village."] = "Reite auf der Straße nach Westen zum Nachtelfendorf.",
		["Ride west along the road to {npc:10301}."] = "Reite auf der Straße nach Westen zu {npc:10301}.",
		["Short of level 54 after the yetis? Running the {area:1417} (50-54) instead of grinding gets you there faster in a group. Come back to {area:2255} afterwards."] = "Nach den Yetis noch nicht Stufe 54? {area:1417} (50-54) in einer Gruppe statt Grinden bringt dich schneller dorthin. Kehr danach nach {area:2255} zurück.",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "Der Kessel der Totenwaldfelle in {zone:1448}: behalten",
		["The Scourge around {area:2264}, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it."] = "Die Geißel um {area:2264}, westlich der Kapelle, lässt beide Arten von Geißelsteinen fallen; aus ihnen erheben sich Geister von Darrowshire: Sprich mit jedem, um ihn zu befreien.",
		["The Winterfall camp"] = "Das Lager der Winterfelle",
		["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "Das Furbolgdorf der Winterfelle liegt östlich von {area:2255}: Schamanen (56-57), Höhlenbehüter (55-56) und Ursas (57-58), alle über deiner Stufe. Töte zuerst die Schamanen, sie heilen, und lock vom Rand aus. {npc:10738} in der Höhle hinten ist Elite: Bleib draußen.",
		["The next guide starts here and flies to {area:3197}."] = "Der nächste Guide beginnt hier und fliegt nach {area:3197}.",
		["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "Die Ruinen liegen um den gefrorenen See südlich von {area:2253}. Sammle die vier Reliktfragmente in den Ruinen und die Mondbestrahlten Federn am Boden, wo die Wildekin umherstreifen.",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "Die drei Teile der Puppe liegen in den zerstörten Häusern von {area:2262}; beim Aufheben können Geister erscheinen. Füge sie zur Puppe zusammen.",
		["The western Winterfall camp sits in the hills between {npc:11556} and {npc:9298}. Any furbolg here can drop an {item:12771} (about one in ten) and, rarely, a {quest:8471}: right-click whichever drops. Keep the {quest:6031} the furbolgs drop for Meilosh."] = "Das westliche Lager der Winterfelle liegt in den Hügeln zwischen {npc:11556} und {npc:9298}. Jeder Furbolg hier kann {item:12771} (etwa einer von zehn) und selten {quest:8471} fallen lassen: Rechtsklicke, was immer fällt. Behalte {quest:6031}, das die Furbolgs fallen lassen, für Meilosh.",
		["The western Winterfall furbolgs drop the beads."] = "Die westlichen Furbolgs der Winterfelle lassen die Perlen fallen.",
		["The {area:2247}"] = "{area:2247}",
		["Walk through {area:1769} to {zone:1448} and fly on to the Eastern Kingdoms ({area:442}, the boat to {area:150}). Fly to {area:271} and ride north up the road through Alterac to {area:3197}."] = "Geh durch {area:1769} nach {zone:1448} und flieg weiter in die Östlichen Königreiche ({area:442}, das Schiff nach {area:150}). Flieg nach {area:271} und reite auf der Straße nach Norden durch das Alteracgebirge nach {area:3197}.",
		["grind on {npc:7460} at the {area:2247}, {zone:1452}"] = "grinde {npc:7460} bei {area:2247}, {zone:1452}",
		["{item:12771}, a rare drop"] = "{item:12771}, eine seltene Beute",
		["{npc:10301}'s camp"] = "{npc:10301}s Lager",
		["{npc:10301}'s supplies"] = "{npc:10301}s Vorräte",
		["{npc:10431}: keep both for the Plaguelands"] = "{npc:10431}: beide für die Pestländer behalten",
		["{npc:10926}'s doll"] = "{npc:10926}s Puppe",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}: {npc:7583} und {npc:10977} folgen später",
		["{npc:11038}: {npc:12250} is a level 54 elite"] = "{npc:11038}: {npc:12250} ist ein Elitegegner der Stufe 54",
		["{npc:11556} guards the mouth of {area:1769}, north-west of {npc:9298}."] = "{npc:11556} bewacht den Eingang von {area:1769}, nordwestlich von {npc:9298}.",
		["{npc:11629}: keep it for {area:2262}"] = "{npc:11629}: für {area:2262} behalten",
		["{npc:12250} is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "{npc:12250} ist Elite: Eine Gruppe wird empfohlen. Er wartet ganz unten im {area:2261}, der Krypta im Südwesten des Gebiets.",
		["{quest:5152}, in the {zone:1422}: keep it"] = "{quest:5152}, in {zone:1422}: behalten",
		["{quest:6031}, for Meilosh later"] = "{quest:6031}, später für Meilosh",
		["{quest:8471}, a rare drop"] = "{quest:8471}, eine seltene Beute",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["Andorhal"] = "Andorhal",
		["Andorhal Watches"] = "Andorhal-Uhren",
		["Back north to the {area:202}: the cauldron offers its own task now. The ghouls nearby drop Somatic Intensifiers."] = "Zurück nach Norden zum Ort {area:202}: Der Kessel bietet jetzt eine eigene Aufgabe an. Die Ghule in der Nähe droppen Somatische Verstärker.",
		["Buy one {item:13320} from {npc:11056} for Felstone's cauldron, right before you go: the quickeners vanish after 30 minutes."] = "Kaufe für den Kessel im Teufelssteinfeld einen {item:13320} bei {npc:11056}, direkt bevor du losgehst: Die Beschleuniger verschwinden nach 30 Minuten.",
		["Buy two more Arcane Quickeners for the {area:202}'s and Dalson's cauldrons, and ride straight there: they vanish after 30 minutes."] = "Kaufe zwei weitere Arkanbeschleuniger für die Kessel am Ort {area:202} und bei Dalsons Tränenfeld und reite direkt dorthin: Sie verschwinden nach 30 Minuten.",
		["Climb the hill west of {area:190} to look down on the town."] = "Steig auf den Hügel westlich von {area:190} und blick auf die Stadt hinunter.",
		["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "Überquere den Fluss nach Osten zum {area:2261}, der Gruft im Südwesten des Gebiets. {object:177667} liegt drinnen: Ihr Schlüssel ist bei {npc:12248} ganz im Nordosten, was im nächsten Guide erledigt wird.",
		["Cross the river west to {npc:1855}'s hut."] = "Überquere den Fluss nach Westen zu {npc:1855}s Hütte.",
		["Diseased Grizzlies"] = "Kranke Grizzlys",
		["Diseased Wolves"] = "Kranke Wölfe",
		["Fly to {area:392}."] = "Flieg nach {area:392}.",
		["For the druids of {zone:1457}: keep it"] = "Für die Druiden von {zone:1457}: Behalte es",
		["For {zone:1448}: keep it"] = "Für {zone:1448}: Behalte es",
		["For {zone:1451}: keep it"] = "Für {zone:1451}: Behalte es",
		["For {zone:1453}: keep it"] = "Für {zone:1453}: Behalte es",
		["From {area:392}, fly to {area:2255} and ride south to {area:2250}."] = "Flieg von {area:392} nach {area:2255} und reite nach Süden zum {area:2250}.",
		["From {area:702}, fly to {area:1116}."] = "Flieg von {area:702} zur {area:1116}.",
		["Gaeriyan in {area:976}: keep it"] = "Gaeriyan in {area:976}: Behalte es",
		["Horgus' skull lies at {area:2624} and Marduk's sword in the {area:2623}, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "Horgus' Schädel liegt am {area:2624} und Marduks Schwert im Gebiet {area:2623}, jeweils dort, wo Geister kämpfen; ausgewachsene Seuchenhunde jagen auf den Ebenen dazwischen.",
		["Listen to his story"] = "Hör dir seine Geschichte an",
		["Mark {npc:10902} with the {item:12815}"] = "Markiere {npc:10902} mit der {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Markiere {npc:10903} mit der {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Markiere {npc:10904} mit der {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Markiere {npc:10905} mit der {item:12815}",
		["More watches"] = "Mehr Uhren",
		["Radley and Durgen"] = "Radley und Durgen",
		["Ride back south to the camp."] = "Reite zurück nach Süden zum Lager.",
		["Ride back to {area:3197} and fly to {area:150}, take the boat to {area:442} and fly to {area:702}; the portal leads up to {zone:1457}."] = "Reite zurück zum {area:3197} und flieg zum Ort {area:150}, nimm das Boot nach {area:442} und flieg nach {area:702}; das Portal führt hinauf nach {zone:1457}.",
		["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "Reite nach Osten zum Grenzfluss: {npc:1855} lebt in einer kleinen Hütte am Ufer.",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "Reite auf der Straße nach Norden zum Holzlager Northridge; {npc:11610} versteckt sich am Rand des Lagers.",
		["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "Reite nach Nordwesten zu Dalsons Hof. Das Tagebuch liegt in der Scheune; ein umherwanderndes Skelett trägt den Schlüssel für das Nebengebäude, und {npc:10836} wartet im Nebengebäude mit dem Schrankschlüssel.",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "Reite nach Nordwesten zur {area:2276}, am Rand des Gebiets {area:2277}.",
		["Ride south to {area:201}, where {npc:11078} guards the cauldron."] = "Reite nach Süden nach {area:201}, wo {npc:11078} den Kessel bewacht.",
		["Ride south-west to the camp."] = "Reite nach Südwesten zum Lager.",
		["Ride west along the road to the hot springs."] = "Reite auf der Straße nach Westen zu den heißen Quellen.",
		["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "Reite nach Westen ins {area:2627}. Kleine Seuchenhunde, Seuchenfledermäuse und Aaslarven streifen durch seine Wälder; füll {item:15042} an den großen Termitenhügeln und töte weiter nördlich die Rasenden Seuchenhunde.",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones."] = "Skelettschinder und Sabbernde Ghule streifen über die Felder nördlich des Lagers; die ganze Geißel hier droppt Geißelsteine.",
		["Small lockboxes lie in the rubble all over Andorhal; each holds a watch."] = "Kleine Schließkassetten liegen überall in Andorhal im Schutt; in jeder steckt eine Uhr.",
		["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "Nimm das Boot zum Festland und reite nach Nordosten zu {npc:14637}s Lager beim Ort {area:1119}.",
		["Temple of the Moon"] = "Der Tempel des Mondes",
		["Ten {item:11040} from the {item:11020}"] = "Zehn {item:11040} aus dem {item:11020}",
		["The Andorhal watchtowers"] = "Die Wachtürme von Andorhal",
		["The Scarlet Crusade"] = "Der Scharlachrote Kreuzzug",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "Scharlachrote Sanitäter, Jäger, Ritter und Magier patrouillieren durch das Holzlager und auf der Straße Richtung {area:190}.",
		["The cauldron now offers its own task; the skeletons around it drop Osseous Agitators."] = "Der Kessel bietet jetzt eine eigene Aufgabe an; die Skelette um ihn herum droppen Knöcherne Aufstachler.",
		["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "Der Kessel steht am Ort {area:202}, bei {npc:10739}' Hof.",
		["The cauldron sits at {area:200}, north-east of Felstone; its Cauldron Lord stands beside it."] = "Der Kessel steht bei {area:200}, nordöstlich vom Teufelssteinfeld; sein Kessellord steht daneben.",
		["The fields"] = "Die Felder",
		["The next guide starts here in {area:392} and flies on to {area:976}."] = "Der nächste Guide beginnt hier in {area:392} und fliegt weiter nach {area:976}.",
		["The shrunken giants roam the {area:1119}; the sea elementals wade along the coast to the west."] = "Die geschrumpften Riesen streifen durch das Gebiet {area:1119}; die Meereselementare waten westlich davon an der Küste entlang.",
		["Use the {item:12627} by the grain silos to draw out Temporal Parasites. {quest:5154} is one of the musty tomes in the town hall. Every skeleton in town drops {quest:5537}."] = "Benutze den {item:12627} bei den Getreidesilos, um Temporale Parasiten hervorzulocken. {quest:5154} ist einer der muffigen Folianten im Rathaus. Jedes Skelett in der Stadt droppt {quest:5537}.",
		["Use the {item:12815} at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp."] = "Benutze die {item:12815} am Fuß jedes der vier Wachtürme rund um den Rand von Andorhal, nördlich des Lagers.",
		["Walk into {area:1769} and take the {zone:1450} branch of the tunnel to {area:2361}."] = "Geh in die {area:1769} und nimm den Tunnelzweig nach {zone:1450} bis nach {area:2361}.",
		["Zapped giants and sea elementals"] = "Geschrumpfte Riesen und Meereselementare",
		["grind on {npc:1796} at the {area:202}, {zone:1422}"] = "grinde an {npc:1796} am Ort {area:202}, {zone:1422}",
		["{area:190} overlook"] = "Aussichtspunkt über {area:190}",
		["{area:199} cauldron"] = "Kessel im {area:199}",
		["{area:200} cauldron"] = "Kessel bei {area:200}",
		["{area:201} cauldron"] = "Kessel bei {area:201}",
		["{area:202} cauldron"] = "Kessel: {area:202}",
		["{item:12894}, at the monument"] = "{item:12894}, am Denkmal",
		["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "{item:12954} liegt im Rathaus von {area:190}, westlich von {npc:1855}: Die scharlachroten Wachen stehen dicht beieinander.",
		["{item:12955} lies east of the barn at {area:201}."] = "{item:12955} liegt östlich der Scheune bei {area:201}.",
		["{item:13320}, from {npc:11056}"] = "{item:13320}, von {npc:11056}",
		["{npc:10300} in {zone:1452}: keep it"] = "{npc:10300} in {zone:1452}: Behalte es",
		["{npc:10300}: her escort comes later on the route"] = "{npc:10300}: Ihre Eskorte kommt später auf der Route",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal."] = "{npc:10667} wartet im zerstörten Gasthaus auf der Westseite von Andorhal.",
		["{npc:10739} stands by the farm at the {area:202}, north-east of the fields."] = "{npc:10739} steht beim Hof am Ort {area:202}, nordöstlich der Felder.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "{npc:10778}s Geist wandert beim Bauernhaus im {area:199} umher, westlich von {area:200}; ihr Paket liegt drinnen.",
		["{npc:10878} and {npc:7740} stand by the Temple of the Moon; fill {item:11682} at the moonwell inside."] = "{npc:10878} und {npc:7740} stehen beim Tempel des Mondes; fülle {item:11682} am Mondbrunnen darin.",
		["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "{npc:10927}s Bauernhaus steht auf dem Hügel östlich des Lagers; das Denkmal von {npc:10936} liegt gleich nördlich davon.",
		["{npc:11038}, by the graves south of the chapel"] = "{npc:11038}, bei den Gräbern südlich der Kapelle",
		["{npc:11075} guards the cauldron in {area:199}, west of Andorhal."] = "{npc:11075} bewacht den Kessel im {area:199}, westlich von Andorhal.",
		["{npc:11140} stands by Augustus' hut in {area:2627}."] = "{npc:11140} steht bei der Hütte von Augustus im {area:2627}.",
		["{npc:11613} walks the Northridge camp east of {npc:11610}; {npc:11611} guards the tower at {area:190}'s southern approach."] = "{npc:11613} läuft durch das Holzlager Northridge östlich von {npc:11610}; {npc:11611} bewacht den Turm am südlichen Zugang von {area:190}.",
		["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616}: Die Termiten kommen später, im {area:2627}",
		["{npc:11886} is elite: grouping up is advised"] = "{npc:11886} ist Elite: Eine Gruppe wird empfohlen",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} ist ein Elite der Stufe 61",
		["{npc:1852} is elite: grouping up is advised. He guards his phylactery in the middle of Andorhal."] = "{npc:1852} ist Elite: Eine Gruppe wird empfohlen. Er bewacht sein Phylakterium in der Mitte von Andorhal.",
		["{npc:5411} in {area:976}: keep it"] = "{npc:5411} in {area:976}: Behalte es",
		["{npc:5901}, on the coast north of town"] = "{npc:5901}, an der Küste nördlich der Stadt",
		["{npc:7740}: keep it for {area:976}"] = "{npc:7740}: Behalte es für {area:976}",
		["{npc:7775}'s camp lies north of the {area:1119}. He sells the {item:11243} once he has his bait."] = "{npc:7775}s Lager liegt nördlich vom Ort {area:1119}. Er verkauft das {item:11243}, sobald er seinen Köder hat.",
		["{npc:7900}: keep it for {zone:1446}"] = "{npc:7900}: Behalte es für {zone:1446}",
		["{npc:8496}: keep it for Un'Goro"] = "{npc:8496}: Behalte es für Un'Goro",
		["{npc:9047}, in the {area:1658}"] = "{npc:9047}, im Gebiet {area:1658}",
		["{object:175924}, in the farmhouse"] = "{object:175924}, im Bauernhaus",
		["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210}, bei der {area:2268}: Behalte es",
		["{quest:6762} in {zone:1450}: keep it"] = "{quest:6762} in {zone:1450}: Behalte es",
		["{zone:1455}, where the next guide trains, has no druid trainer"] = "{zone:1455}, wo im nächsten Guide trainiert wird, hat keinen Druidenlehrer",
} end)()
t.guides["forever/alliance/50-60/05-silithus"] = (function() return {
		["Chromie in Andorhal: keep it"] = "Chromie in Andorhal: Behalte es",
		["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "Baggerbrecher graben weiter westlich; Steinpanzerzangen, Steinpanzerschinder und Felspirscher jagen im selben Sand.",
		["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "Baggerschläger graben in den Dünen nordwestlich der Burg; Steinpanzerskorpide und Sandhuscher streifen überall umher.",
		["Dredge and scorpids"] = "Bagger und Skorpide",
		["Fly from {area:976} to {area:541}. {npc:8737}'s hut stands at the {area:538}, west of the refuge; {npc:9117} is up the hill behind it."] = "Flieg von {area:976} nach {area:541}. Die Hütte von {npc:8737} steht bei {area:538}, westlich der Zuflucht; {npc:9117} ist den Hügel dahinter hinauf.",
		["Fly to {area:271} and ride north up the road toward Alterac: Haggerdin camps at {area:1056} beside it."] = "Flieg nach {area:271} und reite die Straße nach Norden Richtung Alterac: Haggerdin lagert bei {area:1056} daneben.",
		["For {area:3197}: keep it"] = "Für {area:3197}: Behalte es",
		["For {npc:10778}: keep it"] = "Für {npc:10778}: Behalte es",
		["For {zone:1448}: keep it"] = "Für {zone:1448}: Behalte es",
		["From {area:392}, fly to {area:976}."] = "Flieg von {area:392} nach {area:976}.",
		["Its jars are filled on the next Un'Goro visit"] = "Die Gefäße werden beim nächsten Besuch in Un'Goro gefüllt",
		["On {npc:7583}"] = "Bei {npc:7583}",
		["Ride back to {area:3425} and fly to {area:392}."] = "Reite zurück nach {area:3425} und flieg nach {area:392}.",
		["Ride east to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "Reite nach Osten zum Turm von {area:2742} in {area:2738}; klettere hinauf und töte die Angreifer, die beim Verkrusteten Silithidenobjekt auftauchen.",
		["Ride east to {npc:13220}."] = "Reite nach Osten zu {npc:13220}.",
		["Ride north to the {area:2277}'s north-eastern edge."] = "Reite nach Norden zum nordöstlichen Rand von {area:2277}.",
		["Ride on north to {area:3197} and fly to {area:2268}."] = "Reite weiter nach Norden zum {area:3197} und flieg zur {area:2268}.",
		["Ride out of the crater's north-western pass into {zone:1451} and on to {area:3425}."] = "Reite durch den Nordwestpass des Kraters hinaus nach {zone:1451} und weiter nach {area:3425}.",
		["Ride south-west to the {area:2261}. The mound of dirt lies inside. {npc:11886} is elite: grouping up is advised."] = "Reite nach Südwesten zum {area:2261}. Der Erdhaufen liegt drinnen. {npc:11886} ist Elite: Eine Gruppe wird empfohlen.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Reite nach Südwesten zum Lager von {npc:7771} bei {area:1938}.",
		["Scourge Champions"] = "Champions der Geißel",
		["Scourge Champions (59) roam the {area:2270}, north of {area:2268}. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time."] = "Champions der Geißel (59) streifen durch {area:2270}, nördlich der {area:2268}. Halte {npc:11063}s {item:13156} über jeden, den du tötest: Die Schädel, die mitschwingen, sind die, die er will. Zieh sie einzeln.",
		["Sixty {item:2592}, if you carry them"] = "Sechzig {item:2592}, falls du sie dabeihast",
		["Take the boat from {area:392} to {area:35} and fly to {zone:1453}."] = "Nimm das Boot von {area:392} nach {area:35} und flieg nach {zone:1453}.",
		["Take the {area:2257} to {zone:1455}."] = "Nimm die {area:2257} nach {zone:1455}.",
		["Tar Beasts wallow in the {area:538}; the fire elementals of {area:537} in the middle carry the ash; the Gorishi wasps of the {area:540} in the south carry the gland. Every creature in the crater can drop {item:11018}."] = "Teerbestien suhlen sich in {area:538}; die Feuerelementare des {area:537} in der Mitte tragen die Asche; die Wespen der Gorishi in {area:540} im Süden tragen die Drüse. Jede Kreatur im Krater kann {item:11018} fallen lassen.",
		["The crater"] = "Der Krater",
		["The next guide starts here in {area:392}."] = "Der nächste Guide beginnt hier in {area:392}.",
		["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "Die Gequälten Druiden und Schildwachen spuken im verfallenen Südwindposten südwestlich von {npc:13220}.",
		["The western dunes"] = "Die westlichen Dünen",
		["The {area:2742} tower"] = "Der Turm von {area:2742}",
		["Umber in {zone:1450}: keep it"] = "Umber in {zone:1450}: Behalte es",
		["grind on {npc:8532} at the {area:2258}, {zone:1423}"] = "Grinde an {npc:8532} im {area:2258}, {zone:1423}",
		["{item:13155}, from the Scourge Champions"] = "{item:13155}, von den Champions der Geißel",
		["{item:14613}, from {npc:11886}"] = "{item:14613}, von {npc:11886}",
		["{npc:14724}, by the tram"] = "{npc:14724}, bei der Bahn",
		["{npc:332}, in SI:7"] = "{npc:332}, bei SI:7",
		["{npc:3520}, who walks the canals"] = "{npc:3520}, der an den Kanälen entlanggeht",
		["{npc:9299} waits at the graveyard just east of town; the gravestone stands nearby."] = "{npc:9299} wartet auf dem Friedhof gleich östlich des Orts; der Grabstein steht in der Nähe.",
		["{quest:3444} is in {area:392}"] = "{quest:3444} ist in {area:392}",
		["{quest:6184} at {area:3197}: keep it"] = "{quest:6184} bei {area:3197}: Behalte es",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Andorhal"] = "Andorhal",
		["Angerclaw bears and Felpaw wolves"] = "Wutklauenbären und Teufelspfotenwölfe",
		["Araj is elite: grouping up is advised."] = "Araj ist Elite: Eine Gruppe wird empfohlen.",
		["Back into {area:1770}: {npc:9861} and {npc:9860} guard {npc:9517} in its deepest chamber."] = "Zurück in {area:1770}: {npc:9861} und {npc:9860} bewachen {npc:9517} in der tiefsten Kammer.",
		["Bronzebeard's Encampment"] = "Bronzebeards Lager",
		["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "Klettere auf den {area:537} in der Mitte des Kraters und benutze {item:14644} am Lavasee oben, mit zwei Thoriumbarren im Gepäck. Füll {npc:9616}' Leere reine Probenkrüge an den Urzeitbrühschlammern in den Tümpeln um den Grat.",
		["Cross the river east of {npc:1855} into {area:2627}. The Terrordale Spirits haunt the woods there."] = "Überquere den Fluss östlich von {npc:1855} nach {area:2627}. Die Schreckenstalgeister spuken dort in den Wäldern.",
		["Dredge Crushers roam the dunes between {area:2743} and {area:3425}, on your way back. {npc:15181} only offers {quest:8304} from level 58."] = "Baggerbrecher streifen durch die Dünen zwischen {area:2743} und {area:3425}, auf deinem Rückweg. {npc:15181} bietet {quest:8304} erst ab Stufe 58 an.",
		["Fly to {area:3137} in {zone:1447} and ride west along the road to {area:2358}, just over the {zone:1440} border."] = "Flieg nach {area:3137} in {zone:1447} und reite die Straße nach Westen nach {area:2358}, gleich hinter der Grenze zu {zone:1440}.",
		["Fly to {area:976}."] = "Flieg nach {area:976}.",
		["Follow the road north to {area:1767}. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north."] = "Folge der Straße nach Norden zum {area:1767}. Die Donnerstampfer der Eisenstämme tragen das Herz; sammle die restlichen Klauen bei den Wutklauengrizzlys und Teufelspfotenverheerern im Norden.",
		["Follow the road south-west out of the pass to {area:3425}."] = "Folge der Straße aus dem Pass nach Südwesten zur {area:3425}.",
		["Go back down to {area:702}, take the boat to {area:442} and the boat on to {area:17203}. Bring sixty Silk, sixty Mageweave and sixty {item:14047} for {npc:14722}: buy what you lack at the Auction House."] = "Geh zurück hinab nach {area:702}, nimm das Boot nach {area:442} und dann das Boot weiter zum {area:17203}. Bring je sechzig Seidenstoff, Magiestoff und {item:14047} für {npc:14722} mit: Kauf, was dir fehlt, im Auktionshaus.",
		["Grind to 58"] = "Grinde bis 58",
		["Grind to 59"] = "Grinde bis 59",
		["Grind to 60"] = "Grinde bis 60",
		["Hand him the ten texts you kept"] = "Gib ihm die zehn Texte, die du behalten hast",
		["Havunth's camp sits just west of {area:3425}."] = "Havunths Lager liegt gleich westlich der {area:3425}.",
		["Hearth to {area:1519} and train your level 60 spells. This is the end of the leveling route: look at the reputation and dungeon guides next."] = "Ruhestein nach {area:1519} und trainiere deine Zauber der Stufe 60. Hier endet die Levelroute: Sieh dir als Nächstes die Ruf- und Dungeon-Guides an.",
		["Hearth to {area:392} and fly to {area:976}. Buy two Thorium Bars at the Auction House here for {quest:5801}."] = "Ruhestein nach {area:392} und flieg nach {area:976}. Kauf hier im Auktionshaus zwei Thoriumbarren für {quest:5801}.",
		["Into {zone:1451}"] = "Nach {zone:1451}",
		["Irontree Stompers"] = "Donnerstampfer der Eisenstämme",
		["Keep the {item:11169}, the claws and the heart he hands back"] = "Behalte {item:11169}, die Klauen und das Herz, die er dir zurückgibt",
		["Keep west on the road to {npc:9298}'s camp beside the hot springs."] = "Bleib auf der Straße nach Westen bis zu {npc:9298}s Lager neben den heißen Quellen.",
		["Level 60"] = "Stufe 60",
		["Ride back north to {area:2255} and west along the road to the night elf village."] = "Reite zurück nach Norden nach {area:2255} und die Straße nach Westen zum Nachtelfendorf.",
		["Ride back south along the road to the Sanctuary."] = "Reite die Straße zurück nach Süden zum Refugium.",
		["Ride back south-east to the hermit."] = "Reite zurück nach Südosten zum Einsiedler.",
		["Ride back south-west to {area:3197}."] = "Reite zurück nach Südwesten zum {area:3197}.",
		["Ride back to {area:3137} and fly to {area:2255}."] = "Reite zurück nach {area:3137} und flieg nach {area:2255}.",
		["Ride east into the hills. Use the {item:11169} to summon {quest:4005}, then defeat him for the totem."] = "Reite nach Osten in die Hügel. Benutze {item:11169}, um {quest:4005} zu beschwören, und besiege ihn für das Totem.",
		["Ride east to the ruins of {area:2738}. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "Reite nach Osten zu den Ruinen von {area:2738}. {object:179565} liegt zwischen den verfallenen Gebäuden, bewacht von Gequälten Schildwachen.",
		["Ride north along the west side to Mayna's small camp."] = "Reite an der Westseite nach Norden zu Maynas kleinem Lager.",
		["Ride north out of {area:415} into {zone:1448} to the druids' camp on the road just past the border."] = "Reite nach Norden aus {area:415} hinaus in den {zone:1448} zum Lager der Druiden an der Straße gleich hinter der Grenze.",
		["Ride north to the Deadwood furbolgs' village by the {area:1769} cave mouth."] = "Reite nach Norden zum Dorf der Furbolgs der Totenwaldfelle beim Höhleneingang der {area:1769}.",
		["Ride north to {area:541}. Use {npc:10980} beside {npc:10977}."] = "Reite nach Norden zu {area:541}. Benutze {npc:10980} neben {npc:10977}.",
		["Ride north up the road to the lumber mill and set the termite barrel down in the middle of it."] = "Reite die Straße nach Norden zum Holzlager und stell das Termitenfass in dessen Mitte ab.",
		["Ride south to {area:2250}. Protect {npc:10300} while she lights the torches on the way to the {object:177404}."] = "Reite nach Süden nach {area:2250}. Beschütze {npc:10300}, während sie auf dem Weg zum {object:177404} die Fackeln entzündet.",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand just south-east of the camp."] = "Reite nach Südwesten zum Lager der Zwerge nahe den südlichen Bergen und befrag {npc:15171} und {npc:15170}. {npc:15190}s Ranzen liegt im Sand gleich südöstlich des Lagers.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Reite nach Südwesten zum Lager von {npc:7771} bei {area:1938}.",
		["Ride west along the crater's northern wall to the pass in the north-west corner that climbs into {zone:1451}."] = "Reite an der Nordwand des Kraters nach Westen zum Pass in der Nordwestecke, der nach {zone:1451} hinaufführt.",
		["Running {area:2057} ({area:2298}, south-east {zone:1422}) or {area:2279} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "{area:2057} ({area:2298}, Südosten der {zone:1422}) oder {area:2279} statt Grinden bringt dich in einer Gruppe schneller ans Ziel. Überspring diesen Schritt, um allein zu grinden.",
		["Running {area:2577} in {zone:1444} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "{area:2577} in {zone:1444} statt Grinden bringt dich in einer Gruppe schneller ans Ziel. Überspring diesen Schritt, um allein zu grinden.",
		["Shaman training"] = "Schamanentraining",
		["Take the boat from {area:442} to {area:702}."] = "Nimm das Boot von {area:442} nach {area:702}.",
		["Take the flight path in {area:2361} and fly to {area:442}."] = "Nimm die Flugroute in {area:2361} und flieg nach {area:442}.",
		["Take the portal up to {zone:1457}."] = "Nimm das Portal hinauf nach {zone:1457}.",
		["Take the road west down into the crater and ride to the {area:540}, the silithid cave in the south. The {npc:10041} waits in its deepest chamber."] = "Nimm die Straße nach Westen hinab in den Krater und reite zu {area:540}, der Silithidenhöhle im Süden. {npc:10041} wartet in ihrer tiefsten Kammer.",
		["Take the {area:1769} tunnel from its {zone:1452} mouth, west of {npc:9298}, and follow the {area:493} branch to {area:2361}. {npc:11939} studies by the lake shore."] = "Nimm den Tunnel der {area:1769} von seinem Eingang in {zone:1452}, westlich von {npc:9298}, und folge dem Abzweig nach {area:493} bis {area:2361}. {npc:11939} forscht am Seeufer.",
		["Take the {area:2257} to {zone:1455}. {npc:14724} and {npc:14723} each want sixty Wool, sixty Silk and sixty Mageweave, then sixty {item:14047}: 120 of each in all, from your bags or the Auction House."] = "Nimm die {area:2257} nach {zone:1455}. {npc:14724} und {npc:14723} wollen je sechzig Wollstoff, Seidenstoff und Magiestoff, dann sechzig {item:14047}: insgesamt je 120, aus deinem Gepäck oder dem Auktionshaus.",
		["Ten more for {quest:8323}"] = "Zehn weitere für {quest:8323}",
		["The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an {item:20404}: keep twenty, ten for {npc:15306} and ten for {npc:15194} later."] = "Die Grabung der Twilight füllt die Nordwestecke: Schrifttafelfragmente liegen auf dem Boden, und auch die Staubstürmer und Wüstenrumpler tragen welche. Jeder Kultist kann einen {item:20404} fallen lassen: Behalte zwanzig, zehn für {npc:15306} und zehn für {npc:15194} später.",
		["The hermit hides among the rocks south-east of {area:2738}."] = "Der Einsiedler versteckt sich zwischen den Felsen südöstlich von {area:2738}.",
		["The {area:2479}"] = "{area:2479}",
		["The {area:2739}"] = "{area:2739}",
		["The {area:3098}"] = "{area:3098}",
		["The {npc:7446} bears roam the snowy valley south of {area:2250}."] = "Die Bären ({npc:7446}) streifen durch das verschneite Tal südlich von {area:2250}.",
		["Toward the north-west pass"] = "Richtung Nordwestpass",
		["Twilight Tablet Fragments"] = "Schrifttafelfragmente der Twilight",
		["Twilight's Hammer cultists"] = "Kultisten der Twilight",
		["Use the jars on slain oozes"] = "Benutze die Krüge an getöteten Brühschlammern",
		["Wait a moment for {npc:9116}"] = "Warte kurz auf {npc:9116}",
		["You start in {area:392}, where the previous guide hearthed you. Fly to {area:415}."] = "Du beginnst in {area:392}, wohin dich der vorige Guide per Ruhestein gebracht hat. Flieg nach {area:415}.",
		["grind on {npc:11741} at the dunes east of {area:2743}, {zone:1451}"] = "Grinde an {npc:11741} in den Dünen östlich von {area:2743}, {zone:1451}",
		["grind on {npc:14564} at {area:2627}, {zone:1423}"] = "Grinde an {npc:14564} in {area:2627}, {zone:1423}",
		["grind on {npc:7446} at the valley south of {area:2250}, {zone:1452}"] = "Grinde an {npc:7446} im Tal südlich von {area:2250}, {zone:1452}",
		["{area:1770} braziers"] = "Kohlenbecken in {area:1770}",
		["{area:1770} is the cave at the back of {area:1763}, west of the road. Use the {item:12906} on the four braziers inside. Kill the Angerclaw bears and Felpaw wolves you pass for the {item:11172}."] = "{area:1770} ist die Höhle im hinteren Teil von {area:1763}, westlich der Straße. Benutze das {item:12906} an den vier Kohlenbecken darin. Töte die Wutklauenbären und Teufelspfotenwölfe unterwegs für {item:11172}.",
		["{area:2057} (optional)"] = "{area:2057} (optional)",
		["{area:2057} fits levels 58 to 60; {quest:5505} is handed in at {area:3197} below."] = "{area:2057} passt für Stufe 58 bis 60; {quest:5505} wird unten beim {area:3197} abgegeben.",
		["{area:2577} (optional)"] = "{area:2577} (optional)",
		["{area:2577} fits levels 55 to 60; the {npc:7446} grind below gets you to 59 alone."] = "{area:2577} passt für Stufe 55 bis 60; das Grinden an {npc:7446} unten bringt dich allein auf 59.",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. {npc:1852} guards his phylactery in the middle of the town."] = "{npc:10667} wartet im verfallenen Gasthaus auf der Westseite von Andorhal, der verfallenen Stadt nördlich des Lagers. {npc:1852} bewacht seine Phylakterie mitten in der Stadt.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves."] = "{npc:10778}s Geist wandert beim Bauernhaus von {area:199}, westlich von Andorhal. Die Plappernden Ghule auf dem Feld tragen die andere Hälfte des Talismans: Füg die beiden Hälften zusammen.",
		["{npc:10924}: ends in {zone:1452}, keep it"] = "{npc:10924}: endet in {zone:1452}, behalte es",
		["{npc:11557}, if you have thirty {quest:6031}"] = "{npc:11557}, falls du dreißig {quest:6031} hast",
		["{npc:11558}, just inside the cave: only from Neutral with the Timbermaw"] = "{npc:11558}, gleich in der Höhle: erst ab Neutral bei der Holzschlundfeste",
		["{npc:11801}'s house stands in {area:2361}, east of {npc:11939}."] = "Das Haus von {npc:11801} steht in {area:2361}, östlich von {npc:11939}.",
		["{npc:11803} holds the cultists' camp in the far south-west."] = "{npc:11803} hält das Lager der Kultisten im äußersten Südwesten.",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722}, im {object:2096}",
		["{npc:15174}, the innkeeper"] = "{npc:15174}, der Gastwirt",
		["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp."] = "{npc:17080} lagert vor {area:2743}, dem westlichen Bau. Heb an einem der roten Geysire in der Nähe ein Silithyst auf und trag es zum Extraktor der Allianz in seinem Lager.",
		["{npc:17082}, at the Alliance tents"] = "{npc:17082}, bei den Zelten der Allianz",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} ist ein Elite der Stufe 61",
		["{npc:1855} (optional)"] = "{npc:1855} (optional)",
		["{npc:1855} lives in a small hut on the border river, north-east of the lumber camp. Hand in {quest:5781} if you finished it."] = "{npc:1855} lebt in einer kleinen Hütte am Grenzfluss, nordöstlich des Holzlagers. Gib {quest:5781} ab, falls du sie abgeschlossen hast.",
		["{npc:3516}, atop the {area:1658}"] = "{npc:3516}, oben im {area:1658}",
		["{npc:4155}, in the bank"] = "{npc:4155}, in der Bank",
		["{npc:7740} in {zone:1457}: keep it"] = "{npc:7740} in {zone:1457}: Behalte es",
		["{npc:7740}, in the Temple of the Moon"] = "{npc:7740}, im Tempel des Mondes",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}, hinten in der Zuflucht",
		["{npc:9598} waits in {area:1767}. Escort her out of the woods and keep her alive."] = "{npc:9598} wartet im {area:1767}. Eskortiere sie aus dem Wald und halte sie am Leben.",
		["{object:176091}, if you found the Firewater flask in {zone:1452}"] = "{object:176091}, falls du das Feuerwasserfläschchen in {zone:1452} gefunden hast",
		["{quest:5085}: {npc:9298} in {zone:1452}, keep it"] = "{quest:5085}: {npc:9298} in {zone:1452}, behalte es",
		["{zone:1451}, {zone:1448}, {zone:1452} & the Plaguelands"] = "{zone:1451}, {zone:1448}, {zone:1452} & die Pestländer",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} hat keinen Schamanenlehrer",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455} and train your level 60 spells with {npc:258098}."] = "{zone:1453} hat keinen Schamanenlehrer: Nimm die {area:2257} vom {object:28027} nach {zone:1455} und trainiere deine Zauber der Stufe 60 bei {npc:258098}.",
} end)()
t.guides["forever/alliance/dwarf-gnome/01-dun-morogh"] = (function() return {
		["A few Frostmane Troll Whelps if you are short"] = "Ein paar Trollwelpen der Frostmane, falls dir welche fehlen",
		["A few more troggs outside if you are short"] = "Draußen noch ein paar Troggs, falls dir welche fehlen",
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "Zurück durch den Tunnel zu {npc:257597}' Höhle über dem Hof.",
		["Back to {area:77}"] = "Zurück nach {area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "Zurück zu {npc:257446} in {area:77}. Er gibt dir {item:6635}: Nimm den mit Geröll markierten Pfad, der im Süden des Tals nach Westen zum Geisterstein auf dem Grat hinaufführt, trink das Sapta daneben und sprich mit {npc:5891}, dann bring {item:6656} zurück zu Teo.",
		["Back to {npc:257597}"] = "Zurück zu {npc:257597}",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {zone:1436} is next, west of {area:87}."] = "Zurück zu {npc:6122}. Benutze {item:6928} am Beschwörungskreis im Keller von {object:2164} und besiege den herbeigerufenen Leerwandler. Als Nächstes {zone:1436}, westlich von {area:87}.",
		["Boars and bears"] = "Eber und Bären",
		["Cornelius is missing in the {area:136}: find him inside, then go back to Gretchen."] = "Cornelius wird in {area:136} vermisst: Finde ihn drinnen und geh dann zurück zu Gretchen.",
		["Crag Boars and Young Black Bears roam the fields around {area:131} and the depot."] = "Klippeneber und Junge Schwarzbären streifen über die Felder um {area:131} und das Depot.",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "Jede Quest von Grif Wildheart gibt dir {item:15908}: Benutze sie an dem Tier, das er nennt, und bring die Rute dann zu ihm zur Schmiede in {area:131} zurück. Große Klippeneber, Schneeleoparden und Eisklauenbären streifen alle über die Felder gleich südlich und östlich von {area:131}.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen lagert auf dem Grat, der von Westen auf {area:134} blickt. Sprich mit ihm für seine Fernsicht.",
		["Feather Charms, from the Frostmane Novices"] = "Federglücksbringer, von den Novizen der Frostmane",
		["Firewood"] = "Feuerholz",
		["Follow the road all the way east to the {area:806} at the {zone:1432} tunnel."] = "Folge der Straße ganz nach Osten zu {area:806} am Tunnel nach {zone:1432}.",
		["Follow the road east past the depot to {area:138}."] = "Folge der Straße nach Osten am Depot vorbei nach {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Folge der Straße von {area:131} nach Nordosten zum Depot unterhalb der Straße nach {zone:1455}.",
		["Follow the road through the tunnel and north-east to {area:131}. Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. {npc:1252}, Eric and his campfire are outside the {area:2102}. {npc:6806}, {npc:1226} and {npc:1267} are inside. {npc:1872} works the forge."] = "Folge der Straße durch den Tunnel und nach Nordosten nach {area:131}. Töte unterwegs die Klippeneber: Ihre Rippchen fallen schon, bevor du {npc:1267}s Quest hast, und zählen dafür. {npc:1252}, Eric und sein Lagerfeuer sind vor {area:2102}. {npc:6806}, {npc:1226} und {npc:1267} sind drinnen. {npc:1872} arbeitet an der Schmiede.",
		["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {zone:1426} drop it, and the Auction House sells it."] = "Folge der Straße hinauf nach {zone:1455} und nimm {object:32362}: {npc:5149}, {npc:6179} und {npc:6178} sind in {object:32386}. {npc:6175}, ein Bettler, wandert durch die Stadt. Er will zehn {item:2589}: Die Troggs und Trolle in {zone:1426} lassen es fallen, und das Auktionshaus verkauft es.",
		["Follow the road up to {zone:1455} and train with your class trainer. The {area:2257} leaves from {object:171524}, in the east of the city. Ride it to {zone:1453}."] = "Folge der Straße hinauf nach {zone:1455} und trainiere bei deinem Klassenlehrer. {area:2257} fährt von {object:171524} im Osten der Stadt ab. Fahr damit nach {zone:1453}.",
		["From the {quest:2997} she gives you"] = "Aus {quest:2997}, den sie dir gibt",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Trollwelpen der Frostmane füllen die Hänge südlich und östlich von {npc:786}s Lager.",
		["Gnomes, bears and leopards"] = "Gnome, Bären und Leoparden",
		["Go through the tunnel into {zone:1432}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "Geh durch den Tunnel nach {zone:1432}. Gleich dahinter führt rechts der Straße ein mit Steinen markierter Pfad nach Norden die Hügel hinauf zu {npc:257808}s Lager.",
		["Hearth to {area:131}"] = "Ruhestein nach {area:131}",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Eiskrallenbärenanhänger, von den Trollwelpen der Frostmane an den Hängen über dem Lager",
		["Inside {area:77}"] = "In {area:77}",
		["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Verlass {zone:1453} durchs Haupttor, geh nach Süden nach {area:87} und auf der Straße nach Osten zu {area:62}. {npc:881} (Stufe 9) steht bei dessen Bauernhaus.",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Verlass {zone:1453} durchs Haupttor. Der Wasserfall von {quest:1861} liegt südwestlich der Tore, auf dem Weg nach Westen nach {zone:1436}: Füll {item:7207} an seinem Fuß.",
		["Leopards and boars"] = "Leoparden und Eber",
		["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "Lepragnome um Brewnall und an der Straße nach {area:133} tragen die Zahnräder und Getriebe. Eisklauenbären, Alte Klippeneber und Schneeleoparden streifen durch die Hügel um den See.",
		["Level 4 spells, before Gozwin's camp"] = "Zauber der Stufe 4, vor Gozwins Lager",
		["Minor Ice Elementals drift around the frozen lake by the refuge. The three rifles are in the snow around it."] = "Kleine Eiselementare treiben um den gefrorenen See bei der Zuflucht. Die drei Gewehre liegen im Schnee drumherum.",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Struppige junge Wölfe streifen durch den Schnee gleich südlich von {area:77}.",
		["Ride back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "Reite zurück aus {zone:1455} hinaus und auf der Straße nach Osten zu {area:212}. {npc:6177} liegt tot an dessen Ufer: Benutze {item:6866} an ihm. Die Spione der Dunkeleisenzwerge, die um den See schleichen, tragen die Schrift.",
		["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}."] = "Wegelagerer der Felsenkiefer bei {area:212}, nördlich des Steinbruchs, und Kreuzbrecher der Felsenkiefer weiter östlich lassen {quest:95214} fallen.",
		["Rockjaw Bonesnappers prowl the quarry and {area:212}; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "Knochenknacker der Felsenkiefer streifen durch den Steinbruch und um {area:212}; Spione der Dunkeleisenzwerge schleichen am Seeufer umher. Ein Spion lässt {item:274268} fallen.",
		["Rockjaw Skullthumpers fill the quarry; Rockjaw Ambushers by {area:212} drop the {item:268548}."] = "Schädelhauer der Felsenkiefer füllen den Steinbruch; Wegelagerer der Felsenkiefer bei {area:212} lassen {item:268548} fallen.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Troggs der Felsenkiefer und Bullige Troggs der Felsenkiefer graben überall auf dem Talboden südlich von {area:77}.",
		["Sit by Eric's campfire (type /sit) and wait for the buff, then {npc:1699} in the distillery teaches you cooking."] = "Setz dich an Erics Lagerfeuer (gib /sit ein) und warte auf den Buff, dann bringt dir {npc:1699} in der Brauerei Kochen bei.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Kleine Klippeneber grasen um {npc:714}s Lager und entlang der Westseite des Tals.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Schneeleoparden und Eber streifen durch den Schnee zwischen der Ranch und dem Steinbruch. Schmiede: Kupferbarren bekommst du durch Verhütten von {item:2770} oder bei den Handwerkshändlern.",
		["Speak with {npc:1699}"] = "Sprich mit {npc:1699}",
		["Spies and Bonesnappers"] = "Spione und Knochenknacker",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "Seher der Splittersteintroggs (Stufe 13) stehen zwischen den Troggs im Süden von {area:923}, südlich von {npc:257808}; Geomanten der Tunnelratten (Stufe 12) arbeiten in {area:149} am Nordende des Sees. Die Troggs kommen in Gruppen, und einige werfen aus der Ferne: Lock einzeln.",
		["Subdue the voidwalker"] = "Bezwinge den Leerwandler",
		["The Fire Spirit Stone"] = "Der Geisterstein des Feuers",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "Das kochend heiße Morgengebräu hält fünf Minuten: Geh direkt nach Norden zu {npc:836} in {area:77}.",
		["The boars"] = "Die Eber",
		["The cold"] = "Die Kälte",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "Das Feuerholz liegt im Schnee um den gefrorenen See bei der Zuflucht.",
		["The quarry lies south-east of the ranch."] = "Der Steinbruch liegt südöstlich der Ranch.",
		["The quarry troggs"] = "Die Troggs im Steinbruch",
		["The tram arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "Die Bahn kommt in {object:28027} an. {npc:5480} bildet Krieger in {object:2100} aus; {npc:6089} und {npc:6090} stehen dort zusammen bei {object:2152}. {npc:6090} kämpft mit dir um seinen Krug.",
		["The troggs"] = "Die Troggs",
		["The troll cave"] = "Die Trollhöhle",
		["The tunnel"] = "Der Tunnel",
		["The {area:2257}"] = "{area:2257}",
		["The {object:269} in the basement"] = "{object:269} im Keller",
		["The {object:270} in the distillery"] = "{object:270} in der Brauerei",
		["Use the {item:6866} on {npc:6177}"] = "Benutze {item:6866} an {npc:6177}",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Du beginnst vor {area:77}, der Steinhalle am Nordende des Tals. {npc:658} wartet vor der Tür.",
		["Young wolves"] = "Junge Wölfe",
		["{area:131} and the depot"] = "{area:131} und das Depot",
		["{area:135} is the troll cave in the hills west of {area:137}. Kill Headhunters at its mouth and walk through to its far end."] = "{area:135} ist die Trollhöhle in den Hügeln westlich von {area:137}. Töte Kopfjäger der Frostmane an ihrem Eingang und geh bis zu ihrem hinteren Ende durch.",
		["{area:137} sits on the lake north-west of {area:135}."] = "{area:137} liegt am See nordwestlich von {area:135}.",
		["{item:2676} bushes grow on the hills around {area:137}."] = "Büsche mit {item:2676} wachsen auf den Hügeln um {area:137}.",
		["{item:2686}, from {npc:1247} in the distillery"] = "{item:2686}, von {npc:1247} in der Brauerei",
		["{item:277976}, in the camp"] = "{item:277976}, im Lager",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "{item:286325} ist am gefrorenen See, zwischen den Eiselementaren.",
		["{item:2894}, from {npc:1247}"] = "{item:2894}, von {npc:1247}",
		["{item:5026} and the {item:6652}"] = "{item:5026} und {item:6652}",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}: Geomanten der Tunnelratten",
