t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "Tantchen Bernice Stonefield",
		["Back south to the {area:120}, by the road to {zone:1436}. {npc:963} stands outside the barracks, {npc:955} beside him."] = "Zurück nach Süden zu {area:120}, an der Straße nach {zone:1436}. {npc:963} steht vor der Kaserne, {npc:955} neben ihm.",
		["Back to the Cathedral of Light."] = "Zurück zur Kathedrale des Lichts.",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Zurück zu {npc:6122}. Benutze {item:6928} am Beschwörungskreis im Keller von {object:2164} und besiege den Leerwandler, den er ruft.",
		["Bait ingredients"] = "Köderzutaten",
		["Billy plays in the {area:64}, east of the mine."] = "Billy spielt in {area:64}, östlich der Mine.",
		["Boar meat"] = "Eberfleisch",
		["Chunks of Boar Meat"] = "Brocken Eberfleisch",
		["Crystal Kelp Fronds"] = "Kristalltangwedel",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Abtrünnige Hexer der Defias lagern an den Ufern von {area:86}; sie lassen auch die Roten Leinenkopftücher fallen. {object:56} liegt im Murlocdorf am Nordostufer.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Rohlinge der Defias lagern auf der Lichtung östlich der Abtei und entlang der Ostseite des Tals.",
		["Follow the hills south to the tower, on the road west."] = "Folge den Hügeln nach Süden zum Turm, an der Straße nach Westen.",
		["Follow the hills south to the tower."] = "Folge den Hügeln nach Süden zum Turm.",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "Folge dem Weg nach Norden zur Mine. Davor wimmelt es von Koboldtagelöhnern; jeder Kobold im Tal kann {object:83763} fallen lassen.",
		["Follow the road east past the {area:91} to the bridge."] = "Folge der Straße nach Osten an {area:91} vorbei zur Brücke.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Folge der Straße nach Norden von {area:87} nach {zone:1453}. {npc:5497} steht im Magiersanktum, dem Turm in {object:2101}; sie gibt dir eine Flasche für den Wasserfall am {quest:1861}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Folge der Straße nach Norden von {area:87} nach {zone:1453}. {npc:6122} wartet im Keller von {object:2164} in {object:2101}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6171} and {npc:6173} are in the Cathedral of Light; {npc:6174} stands in {object:2100} and asks for ten {item:2589} (humanoids drop it; the Auction House sells it)."] = "Folge der Straße nach Norden von {area:87} nach {zone:1453}. {npc:6171} und {npc:6173} sind in der Kathedrale des Lichts; {npc:6174} steht in {object:2100} und bittet um zehn {item:2589} (Humanoide lassen ihn fallen; das Auktionshaus verkauft ihn).",
		["Follow the road south out of the valley to {area:87}. {npc:295} is in the Lion's Pride Inn; {npc:240} stands outside the smithy across the road, {npc:253} at the inn's front and {npc:241} by the road south of it."] = "Folge der Straße nach Süden aus dem Tal nach {area:87}. {npc:295} ist im Gasthaus „Zur Höhle des Löwen“; {npc:240} steht vor der Schmiede auf der anderen Straßenseite, {npc:253} vor dem Gasthaus und {npc:241} an der Straße südlich davon.",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Folge der Straße nach Süden aus {area:87} hinaus zu {area:64}. {npc:251} wartet beim Haus.",
		["Follow the road west back to {area:87}."] = "Folge der Straße nach Westen zurück nach {area:87}.",
		["Follow the road west back to {area:87}; {npc:6306} and Jason stand on the lake shore before town."] = "Folge der Straße nach Westen zurück nach {area:87}; {npc:6306} und Jason stehen vor dem Ort am Seeufer.",
		["Follow the road west past Westbrook into {zone:1436}, then south along it to {area:108}. Thor, the gryphon master, stands on the hill."] = "Folge der Straße nach Westen an Weststrom vorbei nach {zone:1436} und dann auf ihr nach Süden nach {area:108}. Thor, der Greifenmeister, steht auf dem Hügel.",
		["From the {quest:2998} he gives you"] = "Aus {quest:2998}, den er dir gibt",
		["Fun with Elementals: {npc:248464}"] = "Spaß mit Elementaren: {npc:248464}",
		["He stands by the river west of the farm."] = "Er steht am Fluss westlich des Hofs.",
		["Head north-west across the fields to the {quest:91736}, north of the {area:120}. Hand it four Shiny Red Apples for a {item:247824}."] = "Geh nach Nordwesten über die Felder zu {quest:91736}, nördlich von {area:120}. Leg vier Glänzende rote Äpfel hinein für {item:247824}.",
		["Inside {area:34}"] = "In {area:34}",
		["It lies by the river north-west of the logging camp."] = "Er liegt am Fluss nordwestlich des Holzfällerlagers.",
		["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right."] = "Koboldhilfsarbeiter arbeiten in den Tunneln der Mine. {npc:248362} wartet hinter der zweiten Abzweigung rechts.",
		["Large Candles"] = "Große Kerzen",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Verlass {zone:1453} durch das Haupttor. Der Wasserfall am {quest:1861} liegt südwestlich der Tore, auf dem Weg nach Westen nach {zone:1436}: Füll {item:7207} an seinem Fuß.",
		["Lost Books: Kobold Miners and Tunnelers"] = "Verlorene Bücher: Koboldminenarbeiter und Koboldtunnelgräber",
		["Murloc Foragers and Lurkers line the river south of the bridge. {npc:473}, a Defias, walks the {area:62} west of it. Finish the Prowlers and Young Forest Bears on the way."] = "Murlocfutterwühler und Murloclauerer säumen den Fluss südlich der Brücke. {npc:473}, ein Defias, streift durch {area:62} westlich davon. Erledige unterwegs die Streuner und Jungen Waldbären.",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp."] = "Murlocs und Murlocbachläufer halten das Ostufer; die Schrotthaufen liegen in ihrem Lager.",
		["Murlocs and the Collector"] = "Murlocs und der Sammler",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake."] = "Nordöstlich des Holzfällerlagers. Abtrünnige Hexer der Defias lagern an den Ufern des Sees.",
		["Painted Gnoll Armbands"] = "Bemalte Gnollarmbinden",
		["Red Burlap Bandanas"] = "Rote Sackleinenkopftücher",
		["Red Linen Bandanas"] = "Rote Leinenkopftücher",
		["Ride back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Reite zurück durch {area:87} und auf der Straße nach Osten zu {area:62}. {npc:881} (Stufe 9) steht bei dem Bauernhaus.",
		["Ride back out through {area:87} and east to {area:86}. {npc:6172} lies south of the lake: use the {item:6866} on him. The Defias Rogue Wizards around him carry the {item:6846}."] = "Reite zurück durch {area:87} und nach Osten zu {area:86}. {npc:6172} liegt südlich des Sees: Benutze {item:6866} an ihm. Die Abtrünnigen Hexer der Defias um ihn herum tragen {item:6846} bei sich.",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border. {npc:100}, a level 12 gnoll, walks among them and carries the {item:1307}: right-click it."] = "Wichte und Kundschafter der Flusspfoten halten die Hügel südlich der Garnison entlang der Grenze zu {zone:1436}. {npc:100}, ein Gnoll der Stufe 12, läuft zwischen ihnen umher und trägt {item:1307} bei sich: Rechtsklicke ihn.",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Gnolle der Flusspfoten lagern in den Hügeln westlich von {area:86}; {quest:91725} liegen in ihren Lagern.",
		["She sits inside the farmhouse."] = "Sie sitzt im Bauernhaus.",
		["She stands by her cart at the vineyard east of the Abbey."] = "Sie steht bei ihrem Karren am Weinberg östlich der Abtei.",
		["She stands outside the mine entrance. {npc:248362}, inside, is elite: grouping up is advised."] = "Sie steht vor dem Mineneingang. {npc:248362} drinnen ist Elite: Eine Gruppe wird empfohlen.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Glänzende rote Äpfel von {npc:894} für {quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Setz dich (/sit) an sein Lagerfeuer, bis du {spell:1229451} hast",
		["South down the road to the {area:64}."] = "Die Straße hinunter nach Süden zu {area:64}.",
		["Speak with {npc:1430}"] = "Sprich mit {npc:1430}",
		["Stonetusk Boars graze between the vineyards and the farm."] = "Steinhauereber grasen zwischen den Weinbergen und dem Hof.",
		["Subdue the voidwalker"] = "Bezwinge den Leerwandler",
		["The Defias camp"] = "Das Lager der Defias",
		["The Fishing Traps sit along the west shore of the lake."] = "Die Fischfallen ({object:694772}) stehen am Westufer des Sees.",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house."] = "Der Hof der Steinfelds liegt westlich der Mine. Mutter Stonefield und Tantchen Bernice stehen beim Haus.",
		["The bridge"] = "Die Brücke",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "Das Lager liegt nordöstlich der Brücke. Kleinholzbündel liegen rund um das Lager und in den Wäldern nördlich davon.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Die Traubenkisten liegen in den Weinbergen hinter den Defias. {npc:103} wartet bei der Hütte am Ostende des Tals.",
		["The gnoll camps"] = "Die Gnolllager",
		["The kobold camp"] = "Das Koboldlager",
		["The lake shore"] = "Das Seeufer",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels."] = "Die Mine liegt südwestlich der Gnolllager. {item:247816} liegen nahe dem Eingang; Koboldgeomanten halten die Tunnel.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "Die Mine liegt westlich der Weinberge. Koboldminenarbeiter und Koboldtunnelgräber füllen beide Ebenen; {npc:248464}, ein Kobold mit Namen, hat das Bilderbuch in den unteren Tunneln. {npc:248464} ist Elite: Eine Gruppe wird empfohlen.",
		["The murloc camp"] = "Das Murloclager",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too."] = "Die Murlocs am Ostufer lassen den Tang fallen. Kürschner: Graue Forstwölfe streifen durch die Wälder zwischen dem See und {area:91}; Streuner weiter östlich liefern ebenfalls Felle.",
		["The vineyards and {npc:103}"] = "Die Weinberge und {npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Prowlers and Young Forest Bears on the way."] = "{item:247813}, die Durchnässte Axt und der Durchnässte Werkzeugkasten liegen im Fluss südlich der Brücke. {npc:330}, ein großer Eber, wühlt in {area:62} westlich des Flusses mit ihrem {npc:390}: Lock zuerst die Ferkel weg. Töte unterwegs Streuner und Junge Waldbären.",
		["The {quest:91736}"] = "{quest:91736}",
		["Torn Murloc Fins"] = "Zerrissene Murlocflossen",
		["Use the {item:6866} on {npc:6172}"] = "Benutze {item:6866} an {npc:6172}",
		["Walk into the mine"] = "Geh in die Mine",
		["Walk through the mine"] = "Geh durch die Mine",
		["Wolves"] = "Wölfe",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Du beginnst vor der Abtei. {npc:823} steht am Fuß der Treppe, {npc:197} drinnen in der Halle, {npc:951} und {npc:247229} in der Bibliothek rechts, {npc:196} draußen an der Nordwestecke.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Junge Wölfe und Wilde Waldwölfe streifen über die Felder direkt um die Abtei.",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "sein Koboldaufspürer zeigt die Kobolde zum Anklicken auf der Straße nach {area:87}",
		["{area:18} and the wolves"] = "{area:18} und die Wölfe",
		["{item:247824}, from the still"] = "{item:247824}, aus dem Brenner",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}: Steinhauereber",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}: {object:83763} im Lager der Defias",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}: Abtrünnige Hexer der Defias",
		["{npc:1430} cooks in the inn's kitchen."] = "{npc:1430} kocht in der Küche des Gasthauses.",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: Zähme ihn mit {item:15908}",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, der Magierlehrer, in der Abtei",
		["{npc:247229}, in the library"] = "{npc:247229}, in der Bibliothek",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242} und {npc:248248} stehen am Fuß des Turms.",
		["{npc:248415} stands behind the Abbey, by the stables."] = "{npc:248415} steht hinter der Abtei, bei den Ställen.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, bei der Abtei",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507} steht bei den Lehrern in {area:87}. Jede ihrer Quests gibt dir {item:15908}: Benutze ihn an dem Wildtier, das sie nennt, und bring den Stab dann zu ihr zurück. Steinhauteber und Junge Waldbären streifen durch die Hügel südlich von {area:64}, Graue Forstwölfe durch die Wälder östlich von {area:18}.",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, neben ihr: {spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261} bewacht die Brücke an der Straße nach Osten; {npc:248265} steht direkt auf der anderen Seite.",
		["{npc:263399} camps north-east of the inn; {npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:263399} lagert nordöstlich des Gasthauses; {npc:6306}, {npc:383} und {npc:1651} stehen am Ufer von {area:18} östlich des Ortes.",
		["{npc:279} in {zone:1453} takes it (02-westfall)"] = "{npc:279} in {zone:1453} nimmt sie an (02-westfall)",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}: {npc:5497} in {zone:1453} nimmt sie an",
		["{npc:375}, the priest trainer"] = "{npc:375}, die Priesterlehrerin",
		["{npc:377}: {npc:376} in {zone:1453} takes both"] = "{npc:377}: {npc:376} in {zone:1453} nimmt beide an",
		["{npc:459}, outside the Abbey"] = "{npc:459}, vor der Abtei",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}: Zähme ihn mit {item:15908}",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}: {npc:6122} in {zone:1453} nimmt sie an",
		["{npc:6171}: Redemption"] = "{npc:6171}: Erlösung",
		["{npc:6306}: skinners only, the pelts are skinned"] = "{npc:6306}: nur für Kürschner, die Felle werden gehäutet",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, bei den Ställen südlich der Abtei",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6} graben in den Weinbergen nordöstlich der Abtei. Ab und zu lässt einer {quest:91741} fallen: Rechtsklicke es.",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}: Zähme ihn mit {item:15908}",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, zurück an der Treppe der Abtei",
		["{npc:911}, the warrior trainer"] = "{npc:911}, der Kriegerlehrer",
		["{npc:915}, the rogue trainer"] = "{npc:915}, der Schurkenlehrer",
		["{npc:925}, the paladin trainer"] = "{npc:925}, der Paladinlehrer",
		["{npc:927}: {npc:6171} in {zone:1453} takes it"] = "{npc:927}: {npc:6171} in {zone:1453} nimmt sie an",
		["{npc:952}, upstairs"] = "{npc:952}, oben",
		["{npc:955}: he wants your {item:247824}"] = "{npc:955}: Er will deinen {item:247824}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood."] = "{object:694855} wächst auf den Feldern rund um die Weinberge und den Hof der Steinfelds; Steinhauereber in der Umgebung liefern das Blut.",
		["{quest:76}'s entrance"] = "Eingang von {quest:76}",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it."] = "{quest:87} ist in {area:57}, nicht auf dem Hügel darüber: Geh am Eingang hinein und halte dich links bis zum hinteren Ende der Minensohle; nimm nicht die Treppe nach oben. Banditen der Defias rund um die Weinberge lassen ab und zu {item:1972} fallen: Rechtsklicke sie.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} und {npc:330}",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/sit an {npc:265811}s Lagerfeuer, bis du {spell:1229451} erhältst",
		["Back at {area:256}"] = "Zurück bei {area:256}",
		["Back to the moonwell."] = "Zurück zum Mondbrunnen.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "Zurück nach oben auf {area:256}. Die {object:654846} liegt neben ihm.",
		["Bloodfeather harpies"] = "Harpyien der Blutfedern",
		["Boat to {zone:1453}"] = "Boot nach {zone:1453}",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Jede Quest von Dazalar gibt dir eine {item:15908}: Benutze sie an dem Wildtier, das er nennt, und bring den Stab dann zu ihm nach {area:186} zurück. Waldweberlauerer schleichen um das Dorf, Pirschende Nachtsäbler und Strigidkreischer streifen durch die Wälder südlich davon.",
		["East to {area:260}"] = "Nach Osten nach {area:260}",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Eskortiere {npc:275744} aus dem Grabhügel; {npc:2081} in {area:186} nimmt den Bericht an.",
		["Fandral in {zone:1457} takes it"] = "Fandral in {zone:1457} nimmt sie an",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}. Nightsabers and Webwood Lurkers keep roaming the road east. {object:126158} is in the house on the hill at the east end of the village."] = "Teufelszapfen liegen unter den Bäumen rund um {area:186} und {npc:2150}. Nachtsäbler und Waldweberlauerer streifen weiter entlang der Straße nach Osten. {object:126158} ist im Haus auf dem Hügel am Ostende des Dorfs.",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442} for the boat."] = "Flieg noch einmal nach {area:702} und nimm das Portal hinauf zu {npc:4217}, dann flieg zurück nach {area:442} zum Boot.",
		["Follow the road south-west out of {area:188} to {area:186}."] = "Folge der Straße nach Südwesten aus {area:188} hinaus nach {area:186}.",
		["Follow the road west into {zone:1457}. {npc:4241} stands on the {area:1659} just inside the city. {npc:3516} is in the {area:1658} at the north end of the city, {quest:922} just south of it; {npc:4092} and {npc:7999} are in the Temple of the Moon at the south end. {npc:7316} is in the west of the city, on the way to the pink portal down to Rut'theran."] = "Folge der Straße nach Westen nach {zone:1457}. {npc:4241} steht auf der {area:1659} gleich hinter dem Stadteingang. {npc:3516} ist im {area:1658} am Nordende der Stadt, {quest:922} gleich südlich davon; {npc:4092} und {npc:7999} sind im Tempel des Mondes am Südende. {npc:7316} ist im Westen der Stadt, auf dem Weg zum rosa Portal hinab nach Rut'theran.",
		["From the harbour walk into {object:2100}. {npc:5480} trains warriors there; {npc:6089} and {npc:6090} stand together by the {object:2152}. {npc:6090} fights you for his mug."] = "Geh vom Hafen in {object:2100}. {npc:5480} bildet dort Krieger aus; {npc:6089} und {npc:6090} stehen zusammen beim {object:2152}. {npc:6090} kämpft mit dir um seinen Krug.",
		["From {area:17203}, ride through the city gates into {zone:1429} and follow the road west to {zone:1436}."] = "Reite vom {area:17203} durch die Stadttore in den {zone:1429} und folge der Straße nach Westen nach {zone:1436}.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Wegelagerer der Knarzklauen verstecken sich entlang der Straße westlich des {area:258}.",
		["Gnarlpine Mystics and Ferocitas camp north-east of {area:260}. Ferocitas drops the {item:8049}: open it for the jewel."] = "Mystiker der Knarzklauen und Ferocitas der Traumfresser lagern nordöstlich von {area:260}. Ferocitas lässt den {item:8049} fallen: Öffne ihn für das Juwel.",
		["Gnarlpine Shamans"] = "Schamanen der Knarzklauen",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Geh zurück hinab nach {area:702} und flieg nach {area:442}. Der {object:177525} steht in den Hügeln gleich östlich des Dorfs: Benutze dort den {item:15208}, besiege Mondklaue und sprich mit dem {npc:12144}.",
		["Hearth to {area:186}"] = "Ruhestein nach {area:186}",
		["Learn the {area:442} flight path on the hill south of the inn, then cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn the {area:493} flight path in {area:2361} and fly to {area:702} (by way of {area:442})."] = "Hol dir die Flugroute von {area:442} auf dem Hügel südlich des Gasthauses, dann wirke {spell:18960}. {npc:11802} ist in {area:2361}; {quest:5929} sitzt im Wald im Nordwesten. Hol dir die Flugroute von {area:493} in {area:2361} und flieg nach {area:702} (über {area:442}).",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Verlass {area:188} über den Pfad südöstlich von {area:256}: {npc:6780} steht daneben, wo er hinab zur Straße nach {area:186} führt.",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:8584} waits in the trees west of the cave mouth; {npc:1994} sits deep inside."] = "Räudige Nachtsäbler und Disteleber streifen nördlich von {area:256} umher, auf dem Weg zur Höhle. {npc:8584} wartet zwischen den Bäumen westlich des Höhleneingangs; {npc:1994} sitzt tief drinnen.",
		["Nightsabers"] = "Nachtsäbler",
		["Nightsabers, Strigid Owls and Webwood Lurkers live along the road east. The moonwell is at the west edge of {area:260}."] = "Nachtsäbler, Strigideulen und Waldweberlauerer leben entlang der Straße nach Osten. Der Mondbrunnen liegt am Westrand von {area:260}.",
		["North to {area:257}"] = "Nach Norden zur {area:257}",
		["North-east from Ursal's den, back to {area:186}."] = "Von Ursals Bau nach Nordosten, zurück nach {area:186}.",
		["Sentinel Arynia again"] = "Wieder zu Schildwache Arynia",
		["South of Zenn. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "Südlich von Zenn. {npc:2080} pflegt seine Setzlinge am Ufer; Wildschlagsetzlinge und Bäumlinge wandern um ihn herum, und die {quest:919} wachsen zwischen ihnen.",
		["South of the pools. The {object:6751} grows by the Hold."] = "Südlich der Teiche. Die {object:6751} wächst bei der Höhle der Knarzklauen.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "Südöstlich von Dolanaar, zu {npc:2080}. Wildschlagsetzlinge wandern am Ufer um ihn herum.",
		["South-west of the barrow. The moonwell sits by the pools."] = "Südwestlich des Grabhügels. Der Mondbrunnen liegt bei den Teichen.",
		["Speak with the {quest:5929}"] = "Sprich mit dem {quest:5929}",
		["Speak with {npc:6286}, south of the inn"] = "Sprich mit {npc:6286}, südlich des Gasthauses",
		["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs."] = "Nimm das Portal hinab nach {area:702}. {npc:10118} steht am Steg, {npc:3838} bei den Hippogryphen.",
		["Take the portal up from {area:702} to {npc:4217} in the {area:1658}."] = "Nimm das Portal von {area:702} hinauf zu {npc:4217} im {area:1658}.",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Nimm wieder die Straße von {area:186} nach Nordwesten; sie liegt noch daneben, auf dem Weg nach {zone:1457}.",
		["Take the road north-west from {area:186} towards the {area:264}; she lies hurt beside it."] = "Nimm die Straße von {area:186} nach Nordwesten in Richtung {area:264}; sie liegt verletzt daneben.",
		["The Bloodfeather harpies nest on the slopes west and north of the glade."] = "Die Harpyien der Blutfedern nisten an den Hängen westlich und nördlich der Lichtung.",
		["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms."] = "Der Grabhügel liegt südlich der Straße. {npc:275744} wird darin festgehalten, {npc:7317} schläft in seinen Tiefen, und die vier Reliquientruhen stehen in den unteren Räumen.",
		["The moonwell and {npc:8584}"] = "Der Mondbrunnen und {npc:8584}",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "Der Mondbrunnen liegt mitten auf der Lichtung. Die {object:6752} wächst an ihrem Nordende.",
		["The moonwell sits north of {area:256}; {npc:8584} is a little further north-west. {quest:3522} lasts five minutes: fill the phial and go straight on to him."] = "Der Mondbrunnen liegt nördlich von {area:256}; {npc:8584} ist etwas weiter nordwestlich. {quest:3522} dauert fünf Minuten: Füll die Phiole und geh direkt weiter zu ihm.",
		["The named harpies"] = "Die benannten Harpyien",
		["The road to {zone:1457}"] = "Die Straße nach {zone:1457}",
		["The {area:478}"] = "Die {area:478}",
		["The {object:177525}"] = "Der {object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "Die {object:4406} liegen hinten in der {area:257}: Nimm den mittleren Pfad, dann links an der Gabelung, hinauf zum hohen Felsvorsprung. Hyazinth-Pilze lassen Grells fallen, Mondblütenlilien wachsen an den Teichen nördlich von {area:256}.",
		["Use the {item:5185} at the moonwell"] = "Benutze die {item:5185} am Mondbrunnen",
		["Use the {item:5619} at the moonwell"] = "Benutze die {item:5619} am Mondbrunnen",
		["Use the {item:5621} at the moonwell"] = "Benutze die {item:5621} am Mondbrunnen",
		["Use the {item:5623} at the moonwell"] = "Benutze die {item:5623} am Mondbrunnen",
		["Walk Lynessa out and keep her alive"] = "Führ Lynessa hinaus und halte sie am Leben",
		["Walk south along the west side of the island. Ursal prowls the far south, below the {area:478}."] = "Geh an der Westseite der Insel entlang nach Süden. Ursal der Raufer streift durch den äußersten Süden, unterhalb der {area:478}.",
		["Webwood Lurkers"] = "Waldweberlauerer",
		["Webwood Spiders"] = "Waldweberspinnen",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "Du beginnst am Fuß von {area:256}, dem großen Baum von {area:188}.",
		["Young Nightsabers and Young Thistle Boars roam around {area:256}. Grells carry {item:3297} in the woods west of the tree, where the Gnarlpine Totems stand."] = "Junge Nachtsäbler und Junge Disteleber streifen um {area:256} herum. Grells tragen {item:3297} in den Wäldern westlich des Baums, wo die Totems der Knarzklauen stehen.",
		["{area:186} again"] = "Wieder {area:186}",
		["{area:186} quests"] = "Quests in {area:186}",
		["{area:258}'s mouth"] = "Eingang des {area:258}",
		["{area:736}, outside the barrow"] = "{area:736}, außerhalb des Grabhügels",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "{item:159} von {npc:6736}, für {npc:6094}",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "{item:3371} von {npc:3614}, neben {npc:6094}",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}, im Tempel des Mondes: Sternensplitter",
		["{npc:1992}, south of the tree"] = "{npc:1992}, südlich des Baums",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}: Zähme ihn mit der {item:15908}",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}: Zähme ihn mit der {item:15908}",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038} wartet in der Höhle, unten oder oben auf dem Felsvorsprung; halte dich rechts.",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}: Zähme ihn mit der {item:15908}",
		["{npc:2077}, by the path"] = "{npc:2077}, am Pfad",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}: ein Siegel für {npc:3596}",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}: {quest:922} in {zone:1457} nimmt sie an",
		["{npc:2082}, on the tree's ramp"] = "{npc:2082}, auf der Rampe des Baums",
		["{npc:2150} sits by the road just east of {area:186}, on the way to {area:260}."] = "{npc:2150} sitzt an der Straße gleich östlich von {area:186}, auf dem Weg nach {area:260}.",
		["{npc:2150}, on the way back"] = "{npc:2150}, auf dem Rückweg",
		["{npc:2151}, on the road west of the village"] = "{npc:2151}, an der Straße westlich des Dorfs",
		["{npc:265811}, by the campfire"] = "{npc:265811}, am Lagerfeuer",
		["{npc:272034} and {npc:272044} fly just west of the moonwell, {npc:272046} further north."] = "{npc:272034} und {npc:272044} fliegen gleich westlich des Mondbrunnens, {npc:272046} weiter nördlich.",
		["{npc:3514}, at the top of the tree"] = "{npc:3514}, oben im Baum",
		["{npc:3515}, south of the inn"] = "{npc:3515}, südlich des Gasthauses",
		["{npc:3516}, in the {area:1658}"] = "{npc:3516}, im {area:1658}",
		["{npc:3519}, by the moonwell"] = "{npc:3519}, am Mondbrunnen",
		["{npc:3567}, back in {area:186}"] = "{npc:3567}, zurück in {area:186}",
		["{npc:3593}, the warrior trainer"] = "{npc:3593}, die Kriegerlehrerin",
		["{npc:3594}, the rogue trainer"] = "{npc:3594}, der Schurkenlehrer",
		["{npc:3595}, inside the tree"] = "{npc:3595}, im Baum",
		["{npc:3595}, the priest trainer, inside the tree"] = "{npc:3595}, die Priesterlehrerin, im Baum",
		["{npc:3596}, the hunter trainer"] = "{npc:3596}, die Jägerlehrerin",
		["{npc:3597}, the druid trainer at {area:256}"] = "{npc:3597}, der Druidenlehrer bei {area:256}",
		["{npc:3600}: {npc:11401} in {zone:1457} takes it"] = "{npc:3600}: {npc:11401} in {zone:1457} nimmt sie an",
		["{npc:3602}: {npc:4217} in {zone:1457} takes it"] = "{npc:3602}: {npc:4217} in {zone:1457} nimmt sie an",
		["{npc:4092}, in the Temple of the Moon"] = "{npc:4092}, im Tempel des Mondes",
		["{npc:4146} in {zone:1457} takes it"] = "{npc:4146} in {zone:1457} nimmt sie an",
		["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{npc:4146}, in {area:1658}: {spell:5149}",
		["{npc:4200}'s fish stall is by the docks. Then take the boat to {zone:1453}."] = "Der Fischstand von {npc:4200} ist bei den Docks. Nimm dann das Boot nach {zone:1453}.",
		["{npc:4217}, in the {area:1658}"] = "{npc:4217}, im {area:1658}",
		["{npc:7318}, in the den"] = "{npc:7318}, im Bau",
		["{npc:7999}, above {npc:4092}"] = "{npc:7999}, über {npc:4092}",
		["{npc:8583}, east of the tree"] = "{npc:8583}, östlich des Baums",
		["{object:673378}, just west of the moonwell"] = "{object:673378}, gleich westlich des Mondbrunnens",
		["{object:7510}, beside him"] = "{object:7510}, neben ihm",
		["{quest:488} and the Starbreeze moonwell"] = "{quest:488} und der Mondbrunnen von Starbreeze",
		["{quest:917} and the antidote"] = "{quest:917} und das Gegengift",
		["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979}: Wirke {spell:1259799} und Schattenmimik, dann gib sie bei {npc:3595} ab",
} end)()
t.guides["forever/alliance/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sit an {npc:263664}s Lagerfeuer, bis du {spell:1229451} bekommst",
		["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "Sturmjäger und Fußsoldaten der Al'Aketh lagern direkt nördlich von {npc:257944} und lassen das Erbstück fallen; die Schattenwindkreischlinge westlich von ihr lassen die Federn und Krallen fallen; das {item:265105} wächst am Bach westlich von ihr.",
		["Back in {quest:92529}: Stormcallers and {npc:251662} fill the village, the Stormcallers carry the stolen supplies, and {npc:251966} stands at its south end."] = "Zurück in {quest:92529}: Sturmrufer der Al'Aketh und {npc:251662} füllen das Dorf, die Sturmrufer tragen die gestohlenen Vorräte, und {npc:251966} steht am Südende.",
		["Back to Shen'dar"] = "Zurück nach Shen'dar",
		["Back to the Hermit"] = "Zurück zum Einsiedler",
		["Back to {area:16622}"] = "Zurück zum {area:16622}",
		["Back to {npc:255853} by the falls north-east of {area:16638}, on the way north to the shrine."] = "Zurück zu {npc:255853} an den Wasserfällen nordöstlich von {area:16638}, auf dem Weg nach Norden zum Schrein.",
		["Bandit Highwaymen"] = "Banditenstraßenräuber",
		["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {zone:1436}."] = "Bolvar Fordragon steht im Thronsaal von {object:2117}, am Nordende der Stadt. Verlass die Stadt dann durch das Haupttor nach {zone:1436}.",
		["Cast {spell:1259705} at the {object:460002}"] = "Wirk {spell:1259705} auf die Leylinie",
		["Desperate times"] = "Verzweifelte Zeiten",
		["Each of Quel'ana's quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her in {area:16638}. Windsong Crawlers line the shore west of town; Vuldren Alphas and Ornery Galestriders roam the {area:16626} around the Windfield farm. Her sister {npc:254411} stands beside her."] = "Jede Quest von Quel'ana gibt dir eine {item:15908}: Benutze sie am genannten Wildtier und bring die Rute dann zu ihr nach {area:16638} zurück. Windweisenkriecher säumen das Ufer westlich der Stadt; Vuldrenalphas und Störrische Windschreiter streifen im Gebiet {area:16626} rund um den Hof der Windfields. Ihre Schwester {npc:254411} steht neben ihr.",
		["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Kämpf dich nach Norden zum {area:16629} durch. Wächter, Geisterrufer und Klingenmeister halten den Zugang; {npc:253576} wartet an der Tür des Schreins, {npc:253590} im inneren Sanktum.",
		["Find Fillion and his bedroll"] = "Finde Fillion und seine Deckenrolle",
		["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "Folge der Straße nach Süden nach {area:16624}. {npc:263664} lagert am Feuer westlich des Dorfes; {npc:251523} und {npc:251903} stehen in der Dorfmitte.",
		["For {npc:234} at {area:108}"] = "Für {npc:234} auf der {area:108}",
		["Havoc in Falaath"] = "Chaos in Falaath",
		["Head north into {area:16631}. {npc:257944} camps in its east."] = "Geh nach Norden in den {area:16631}. {npc:257944} lagert im Osten.",
		["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them."] = "Geh nach Nordwesten zu den Hippogryphennestern an den westlichen Klippen. {item:263493} liegen rund um die Nester; die Hippogryphenmatriarchin patrouilliert zwischen ihnen.",
		["Heal 7 druids in the Nightfang Den, then find {npc:258130}"] = "Heile 7 Druiden im Nightfang Den und finde dann {npc:258130}",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Verlass {zone:1453} durch das Haupttor. Der Wasserfall am {quest:1861} liegt südwestlich der Tore, auf dem Weg nach Westen nach {zone:1436}: Fülle {item:7207} an seinem Fuß.",
		["Level 4 spells"] = "Zauber der Stufe 4",
		["Level 6 spells"] = "Zauber der Stufe 6",
		["Listen to {npc:257554}"] = "Hör {npc:257554} zu",
		["Lorthuna waits on the eastern shore of the isle, east of the {area:16629}."] = "Lorthuna wartet am Ostufer der Insel, östlich des {area:16629}.",
		["Meet Valennia at the gate"] = "Triff Valennia am Tor",
		["North of the cones: the Wind Hollows drift around the refugees' camp, the {item:266433} lie between the tents, and {npc:259013} lies at its north end."] = "Nördlich der Zapfen: Die Windhüllen treiben um das Flüchtlingslager, die {item:266433} liegt zwischen den Zelten, und {npc:259013} liegt am Nordende.",
		["North-west of Valanaar along the road: {npc:273017} watches the {quest:98512}; the dead cultist lies just north of him."] = "Nordwestlich von Valanaar an der Straße: {npc:273017} beobachtet die {quest:98512}; der tote Kultist liegt direkt nördlich von ihm.",
		["Prideclaws and Galestriders"] = "Rudelkrallen und Windschreiter",
		["Prideclaws and Galestriders roam the grasslands south of the village. Galestriders drop both the eggs and the meat."] = "Rudelkrallen und Windschreiter streifen durch das Grasland südlich des Dorfes. Windschreiter lassen sowohl die Eier als auch das Fleisch fallen.",
		["Rally Valennia, {npc:251968} (west of town) and {npc:252475}"] = "Sammle Valennia, {npc:251968} (westlich der Stadt) und {npc:252475}",
		["Raw Windstones and the {npc:251404}"] = "Rohe Windsteine und die {npc:251404}",
		["Ripe Stormapples and Hungry Bandits are in the orchard by the farm, {quest:92683} in the fields north-east of it, Ornery Galestriders all around. The {npc:250929} stands in the field north-east of the farm."] = "Reife Sturmäpfel und Hungrige Banditen findest du im Obstgarten beim Hof, {quest:92683} auf den Feldern nordöstlich davon, Störrische Windschreiter überall ringsum. Das {npc:250929} steht auf dem Feld nordöstlich des Hofs.",
		["Search the dead cultist"] = "Durchsuche den toten Kultisten",
		["Search the wardrobe"] = "Durchsuche den Kleiderschrank",
		["Shen'dar turn-ins"] = "Shen'dar: Quests abgeben",
		["Skycutter to {area:279}"] = "Himmelssegler nach {area:279}",
		["Skyhoppers"] = "Himmelshüpfer",
		["Skyhoppers swarm the fields west of {area:16638}."] = "Himmelshüpfer schwärmen über die Felder westlich von {area:16638}.",
		["Speak with {npc:251903} and {npc:254089}, north-west of the village"] = "Sprich mit {npc:251903} und {npc:254089}, nordwestlich des Dorfes",
		["Stand with {npc:252800} against {npc:252863}"] = "Kämpfe an {npc:252800}s Seite gegen {npc:252863}",
		["Standing our ground"] = "Standhalten",
		["Take the road south-east. {npc:257006} and {npc:252448} stand by the road west of {area:16638}; Windsong Crawlers line the shore further west, around 51,70."] = "Nimm die Straße nach Südosten. {npc:257006} und {npc:252448} stehen an der Straße westlich von {area:16638}; Windweisenkriecher säumen weiter westlich das Ufer, bei 51,70.",
		["Tame it with the {item:15908}"] = "Zähme es mit der {item:15908}",
		["The Bandit Highwaymen hold the hills north of the farm."] = "Die Banditenstraßenräuber halten die Hügel nördlich des Hofs.",
		["The Highlands Bandits camp north-east of the village. \"Badwind\" Bennic waits at the far north end of their camp."] = "Die Hochlandbanditen lagern nordöstlich des Dorfes. „Übelwind“ Bennic wartet am äußersten Nordende ihres Lagers.",
		["The Highlands bandits"] = "Die Hochlandbanditen",
		["The Novice Seers practise in the clearing west of Shen'dar."] = "Die Sehernovizen üben auf der Lichtung westlich von Shen'dar.",
		["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "Die Rohen Windsteine glitzern auf dem Boden direkt südlich des Hains. {quest:92463} schwebt weiter östlich über der Wiese, auf dem Weg zu {npc:249363}.",
		["The Windfield farm"] = "Der Hof der Windfields",
		["The Windstone Formations"] = "Die Windsteinformationen",
		["The Windstone Formations stand on the rise west of Fillion's camp."] = "Die Windsteinformationen stehen auf der Anhöhe westlich von Fillions Lager.",
		["The bounty board"] = "Das Kopfgeldbrett",
		["The class trainers stand together in the grove"] = "Die Klassenlehrer stehen zusammen im Hain",
		["The dead cultist"] = "Der tote Kultist",
		["The eastern watchtower"] = "Der östliche Wachturm",
		["The hippogryph roost"] = "Der Hippogryphenhorst",
		["The missing scholar"] = "Der vermisste Gelehrte",
		["The refugees' camp"] = "Das Flüchtlingslager",
		["The road to {area:16638}"] = "Die Straße nach {area:16638}",
		["The skycutter"] = "Der Himmelssegler",
		["The skycutter docks at the tower south of {area:16638}. It lands by the Kirin Tor camp on the lake shore west of {area:279}."] = "Der Himmelssegler legt am Turm südlich von {area:16638} ab. Er landet beim Lager der Kirin Tor am Seeufer westlich von {area:279}.",
		["The {area:16629}"] = "Der {area:16629}",
		["The {item:254871}"] = "Die {item:254871}",
		["The {object:581822}"] = "Der {object:581822}",
		["The {object:581822} lies by the path west of {area:16638}; Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "Der {object:581822} liegt am Weg westlich von {area:16638}; Fillions Lager ist nordwestlich davon, und die Kreischlingmatriarchinnen nisten direkt westlich des Lagers.",
		["Use {spell:1259416}"] = "Benutze {spell:1259416}",
		["Village quests"] = "Dorfquests",
		["Vuldren and Cirrusflies"] = "Vuldren und Zirrusfliegen",
		["Windshaper Novice Seers"] = "Sehernovizen der Windformer",
		["You wake in {area:16622}. {npc:251362} stands beside you; {npc:251361} is a few steps west, {npc:251368} by the south edge of the grove."] = "Du erwachst im {area:16622}. {npc:251362} steht neben dir; {npc:251361} ist ein paar Schritte westlich, {npc:251368} am Südrand des Hains.",
		["{area:16622} turn-ins"] = "{area:16622}: Quests abgeben",
		["{area:16624} again"] = "Wieder nach {area:16624}",
		["{area:16638} turn-ins"] = "{area:16638}: Quests abgeben",
		["{area:16638}, the fate of Zephras"] = "{area:16638}, das Schicksal von Zephras",
		["{area:16638}, the turncoat"] = "{area:16638}, der Verräter",
		["{item:262668}: by the wind shrine south of {quest:92529}"] = "{item:262668}: am Windschrein südlich von {quest:92529}",
		["{item:263993}: {npc:257196}, west of the shrine's approach"] = "{item:263993}: {npc:257196}, westlich des Zugangs zum Schrein",
		["{npc:249363} keeps watch east of the grove. The {npc:251143} and Al'Aketh Converts gather just north of her; the {object:460002} rises further north: cast your {spell:1259705} racial ability at it."] = "{npc:249363} hält östlich des Hains Wache. {npc:251143} und Konvertiten der Al'Aketh sammeln sich direkt nördlich von ihr; die Leylinie erhebt sich weiter nördlich: Wirk dort deine Volksfähigkeit {spell:1259705}.",
		["{npc:250873} and Pesky Cirrusflies roam the meadow just south-east of the grove."] = "{npc:250873} und Lästige Zirrusfliegen streifen über die Wiese südöstlich des Hains.",
		["{npc:250926} and {npc:251115}"] = "{npc:250926} und {npc:251115}",
		["{npc:250926} prowl the woods just west of the grove; the Ursera Scavengers den further west, with {npc:251115}, the matriarch, at the back of the den."] = "{npc:250926} streifen durch den Wald direkt westlich des Hains; die Urseraplünderer hausen weiter westlich, mit {npc:251115}, der Matriarchin, hinten im Bau.",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: eine Notiz von deinem Lehrer",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: Lies die {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: die {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, der Druidenlehrer, im Erdgeschoss des Baumes hinter {npc:251361}",
		["{npc:251379}, the mage trainer: read the {item:282416} first"] = "{npc:251379}, die Magierlehrerin: Lies zuerst den {item:282416}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, im Wachturm",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, im Wachturm",
		["{npc:252095} camps south of the Ursera den. The Al'Aketh thugs hold the camp south-west of her; {npc:256935} stands in its middle."] = "{npc:252095} lagert südlich des Urserabaus. Die Schläger der Al'Aketh halten das Lager südwestlich von ihr; {npc:256935} steht in der Mitte.",
		["{npc:252155} holds the western watch, south-west of Falaath. {npc:256966} and the fallen guards lie just south of her."] = "{npc:252155} hält die westliche Wacht, südwestlich von Falaath. {npc:256966} und die gefallenen Wachen liegen direkt südlich von ihr.",
		["{npc:252373}, the mage trainer"] = "{npc:252373}, der Magierlehrer",
		["{npc:252377}: {npc:257196} waits at the {area:16629}"] = "{npc:252377}: {npc:257196} wartet am {area:16629}",
		["{npc:252378} holds the watchtower north of {area:16638}. The Al'Aketh camp is just west of the tower, its healers around 65,68 and 65,65; {npc:252666} stands at its north end. The Al'Aketh there drop Windstone Charms."] = "{npc:252378} hält den Wachturm nördlich von {area:16638}. Das Lager der Al'Aketh liegt direkt westlich des Turms, die Heiler bei 65,68 und 65,65; {npc:252666} steht am Nordende. Die Al'Aketh dort lassen Windsteinamulette der Al'Aketh fallen.",
		["{npc:252383} and {npc:252476} stand at the north end of {area:16638}, {npc:252475} and {npc:253204} at the south end."] = "{npc:252383} und {npc:252476} stehen am Nordende von {area:16638}, {npc:252475} und {npc:253204} am Südende.",
		["{npc:252475}: {npc:259084} waits by the Skyborne portal"] = "{npc:252475}: {npc:259084} wartet beim Portal der Himmelsgeborenen",
		["{npc:252800} again"] = "Wieder zu {npc:252800}",
		["{npc:252800} runs the farm in the south-west lowlands."] = "{npc:252800} bewirtschaftet den Hof im südwestlichen Tiefland.",
		["{npc:253590}, in the sanctum"] = "{npc:253590}, im Sanktum",
		["{npc:254151}, {npc:258130} and {npc:258134} are north-east of {npc:257944}; {npc:253622} stands east of them. Haalien also drops a {quest:94490}."] = "{npc:254151}, {npc:258130} und {npc:258134} sind nordöstlich von {npc:257944}; {npc:253622} steht östlich von ihnen. Haalien lässt auch ein {quest:94490} fallen.",
		["{npc:254588}: tame it with the {item:15908}"] = "{npc:254588}: Zähme ihn mit der {item:15908}",
		["{npc:254589} lurks in the hills south-west of the village, on the way back. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} lauert auf dem Rückweg in den Hügeln südwestlich des Dorfes. {npc:254589} ist Elite: Eine Gruppe wird empfohlen.",
		["{npc:255853} waits by the falls north-east of {area:16638}. {npc:258443} prowls the {area:16623} west of {area:16638}, by the road you take next."] = "{npc:255853} wartet an den Wasserfällen nordöstlich von {area:16638}. {npc:258443} streift im Gebiet {area:16623} westlich von {area:16638} umher, an der Straße, die du als Nächstes nimmst.",
		["{npc:257065} waits at the entrance to {quest:92529}, south of Shen'dar. The {spell:1254832} lets you walk in among the faithful."] = "{npc:257065} wartet am Eingang von {quest:92529}, südlich von Shen'dar. Mit {spell:1254832} kannst du dich unter die Gläubigen mischen.",
		["{npc:257944} again"] = "Wieder zu {npc:257944}",
		["{npc:257944}, the missive"] = "{npc:257944}, das Schreiben",
		["{npc:258443}, in the highlands south-west of the cultist"] = "{npc:258443}, im Hochland südwestlich des Kultisten",
		["{npc:259084} stands beside the Skyborne Portal where the zeppelin lands. The portal takes you to {zone:1453}."] = "{npc:259084} steht neben dem Portal der Himmelsgeborenen, wo der Zeppelin landet. Das Portal bringt dich nach {zone:1453}.",
		["{npc:270459}, beside {npc:259084}: for {npc:5504} in {zone:1453}"] = "{npc:270459}, neben {npc:259084}: für {npc:5504} in {zone:1453}",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} steht im Magiersanktum, dem Turm im Gebiet {object:2101}; sie gibt dir ein Fläschchen für den Wasserfall am {quest:1861}.",
		["{npc:5504}, {zone:1453}'s druid trainer, teaches you {spell:18960}. {npc:11802}'s welcome waits for your {spell:499} trip at the end of {zone:1439}."] = "{npc:5504}, der Druidenlehrer von {zone:1453}, lehrt dich {spell:18960}. Der Willkommensgruß von {npc:11802} wartet am Ende von {zone:1439} auf deine Reise für {spell:499}.",
		["{quest:93159} lives west of {npc:257944}. The Zephyrseed Cones lie in the woods between his hut and {npc:257944}."] = "{quest:93159} lebt westlich von {npc:257944}. Die Zephyrzapfen liegen im Wald zwischen seiner Hütte und {npc:257944}.",
} end)()
t.guides["forever/class/druid/aquatic-form"] = (function() return {
		["At the {area:2362}"] = "Am {area:2362}",
		["Cast {spell:18960}. Join the two halves into the {item:15885} near the {area:2362}, on the north-west shore of the lake, then see {npc:11802} in {area:2361}. Fly to {area:702} afterwards."] = "Wirke {spell:18960}. Füge die beiden Hälften beim {area:2362} am Nordwestufer des Sees zu {item:15885} zusammen und geh dann zu {npc:11802} in {area:2361}. Flieg danach nach {area:702}.",
		["Cast {spell:18960}. Join the two halves into the {item:15885} near the {area:2362}, on the north-west shore of the lake, then see {npc:11802} in {area:2361}. {npc:11798} flies druids to {area:1638}."] = "Wirke {spell:18960}. Füge die beiden Hälften beim {area:2362} am Nordwestufer des Sees zu {item:15885} zusammen und geh dann zu {npc:11802} in {area:2361}. {npc:11798} fliegt Druiden nach {area:1638}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "Wirke {spell:18960}. {npc:11802} ist in {area:2361}. Schrein-Schmuckstücke liegen in den Behältern am Grund von {area:656}, unterhalb von {area:2361}: Bring eins zum {area:2362} am Nordwestufer, benutze es dort und sprich mit {npc:11799}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "Wirke {spell:18960}. {npc:11802} ist in {area:2361}. Die Schrein-Schmuckstücke liegen am Grund von {area:656} und vergehen binnen Minuten: Schwimm mit einem direkt zum {area:2362} am Nordwestufer, benutze es dort und sprich mit {npc:11799}.",
		["Fly from {area:2361} to {area:442}. The {object:177792} lies under the water off the north coast, west of the {area:443}."] = "Flieg von {area:2361} nach {area:442}. Die {object:177792} liegt unter Wasser vor der Nordküste, westlich der {area:443}.",
		["Take the boat from {area:442} to {zone:1453} and fly to {area:108}. Ride north-west to the coast: the {object:177790} lies on the sea floor off the shore."] = "Nimm das Boot von {area:442} nach {zone:1453} und flieg zur {area:108}. Reite nach Nordwesten zur Küste: Die {object:177790} liegt vor dem Ufer auf dem Meeresgrund.",
		["Take the portal up to {npc:4217} in the {area:1658}."] = "Nimm das Portal hinauf zu {npc:4217} in der {area:1658}.",
		["Take {npc:11798}'s flight to {zone:1456}, fly to {zone:1454} and take the zeppelin to {zone:1420}; {zone:1421} is south of the {zone:1458}. The {object:177790} lies on the coast west of the {area:240}, north of the {area:228}."] = "Nimm den Flug von {npc:11798} nach {zone:1456}, flieg nach {zone:1454} und nimm den Zeppelin nach {zone:1420}; {zone:1421} liegt südlich von {zone:1458}. Die {object:177790} liegt an der Küste westlich von {area:240}, nördlich von {area:228}.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower, north of the {area:380}."] = "Die {object:177792} liegt am Nordrand von {area:382} beim Turm der Venture Co., nördlich von {area:380}.",
		["Your water travel form: swim fast and breathe underwater, with a belt and an idol besides."] = "Deine Reisegestalt fürs Wasser: schnell schwimmen und unter Wasser atmen, dazu ein Gürtel und ein Götze.",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, aus einem {object:177785} im See",
		["{item:15885}: join the halves at the shrine"] = "{item:15885}: Füge die Hälften am Schrein zusammen",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} steht auf der {area:1639}.",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217} steht in der {area:1658}.",
} end)()
t.guides["forever/class/druid/bear-form"] = (function() return {
		["At 10 a druid's call reaches you: {npc:3064} in {area:222} or {npc:6746} in {zone:1456} ({npc:6929}'s letter in {zone:1454} works too). Any one of them sends you to {npc:3033} on {area:1639} in {zone:1456}."] = "Mit Stufe 10 erreicht dich der Ruf eines Druiden: {npc:3064} in {area:222} oder {npc:6746} in {zone:1456} (der Brief von {npc:6929} in {zone:1454} geht auch). Jeder von ihnen schickt dich zu {npc:3033} im Gebiet {area:1639} in {zone:1456}.",
		["At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus."] = "Mit Stufe 10 erreicht dich der Ruf eines Druiden: {npc:3602} in {area:186}, Denatharion in {zone:1457} oder Theridran in {zone:1453}. Jeder von ihnen schickt dich zu {npc:4217} in der Enklave des Cenarius in Darnassus.",
		["Back to {npc:255853} by the falls."] = "Zurück zu {npc:255853} an den Wasserfällen.",
		["Back to {npc:3033} on {area:1639}."] = "Zurück zu {npc:3033} im Gebiet {area:1639}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Learn the {area:493} flight path while you are here."] = "Wirke {spell:18960}. {npc:11802} ist in {area:2361}. Hol dir hier gleich die Flugroute von {area:493}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn the {area:493} flight path, then fly to {area:702} (by way of {area:442}) and take the portal up to {zone:1457}."] = "Wirke {spell:18960}. {npc:11802} ist in {area:2361}; {quest:5929} sitzt im Wald im Nordwesten. Hol dir die Flugroute von {area:493}, flieg dann nach {area:702} (über {area:442}) und nimm das Portal hinauf nach {zone:1457}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the woods to the north-west. {npc:11798} in {area:2361} flies druids to {area:1638}."] = "Wirke {spell:18960}. {npc:11802} ist in {area:2361}; {quest:5930} sitzt im Wald im Nordwesten. {npc:11798} in {area:2361} fliegt Druiden nach {area:1638}.",
		["Fly back to {area:702} and take the portal up to {npc:4217}."] = "Flieg zurück nach {area:702} und nimm das Portal hinauf zu {npc:4217}.",
		["Fly from {area:702} to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Flieg von {area:702} nach {area:442}. Der {object:177525} steht in den Hügeln direkt östlich des Dorfes: Benutze dort den {item:15208}, besiege Mondklaue und sprich mit dem {npc:12144}.",
		["Skyboat from {area:279}"] = "Himmelsboot ab {area:279}",
		["Skyboat from {zone:1456}"] = "Himmelsboot ab {zone:1456}",
		["Skyboat to {zone:2521}"] = "Himmelsboot nach {zone:2521}",
		["Speak with the {quest:5929}"] = "Sprich mit dem {quest:5929}",
		["Speak with the {quest:5930}"] = "Sprich mit dem {quest:5930}",
		["The Skyborne Portal takes you to {zone:1453}. {npc:5504} is the city's druid trainer."] = "Das Portal der Himmelsgeborenen bringt dich nach {zone:1453}. {npc:5504} ist der Druidenlehrer der Stadt.",
		["The {object:177525}"] = "Der {object:177525}",
		["The {object:177525} stands in the pass from {zone:1412} into the {zone:1413}. Use the {item:15710} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Der {object:177525} steht im Pass von {zone:1412} ins {zone:1413}. Benutze dort den {item:15710}, besiege Mondklaue und sprich mit dem {npc:12144}.",
		["Your tanking form: Forever no longer trains {spell:5487}, these quests give it. Opens {area:493} too."] = "Deine Tankgestalt: Forever lehrt {spell:5487} nicht mehr beim Lehrer, diese Quests geben sie dir. Schaltet auch {area:493} frei.",
		["or whichever of the three letters you carry"] = "oder welchen der drei Briefe du auch hast",
		["{npc:252359} stands in {area:16638}."] = "{npc:252359} steht in {area:16638}.",
		["{npc:255853} and {npc:258443}"] = "{npc:255853} und {npc:258443}",
		["{npc:255853} waits by the falls north-east of {area:16638}. {npc:258443} prowls the {area:16623}, west of {area:16638}."] = "{npc:255853} wartet an den Wasserfällen nordöstlich von {area:16638}. {npc:258443} streift durchs {area:16623}, westlich von {area:16638}.",
		["{npc:259118} waits where the airship from {zone:2521} lands, in northern {zone:1412} beside {zone:1456}."] = "{npc:259118} wartet dort, wo das Luftschiff von {zone:2521} landet, im Norden von {zone:1412} neben {zone:1456}.",
		["{npc:270459} stands beside {npc:259084} and the Skyborne Portal, west of {area:279}, where the skycutter from {zone:2521} lands. {npc:2543} offers the same quest."] = "{npc:270459} steht neben {npc:259084} und dem Portal der Himmelsgeborenen, westlich von {area:279}, wo der Himmelssegler von {zone:2521} landet. {npc:2543} bietet dieselbe Quest an.",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} steht im Gebiet {area:1639}.",
		["{npc:3033} trains druids on {area:1639}."] = "{npc:3033} bildet Druiden im Gebiet {area:1639} aus.",
		["{npc:3064}, {area:222}; Pala's and Gryshka's letters lead to the same place"] = "{npc:3064}, {area:222}; die Briefe von Pala und Gryshka führen zum selben Ort",
		["{npc:3602}, {area:186}; Denatharion's and Theridran's letters lead to the same place"] = "{npc:3602}, {area:186}; die Briefe von Denatharion und Theridran führen zum selben Ort",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217} steht im Gebiet {area:1658}.",
		["{spell:5487} and {area:493}"] = "{spell:5487} und {area:493}",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the cliffs south of {area:17045}, north of {zone:1456}."] = "{spell:5487} wird auf {zone:2521} gelehrt. Überspring das, wenn du noch auf der Insel bist; sonst nimm das Himmelsboot an den Klippen südlich des {area:17045}, nördlich von {zone:1456}.",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the north side of {area:279}."] = "{spell:5487} wird auf {zone:2521} gelehrt. Überspring das, wenn du noch auf der Insel bist; sonst nimm das Himmelsboot an der Nordseite von {area:279}.",
} end)()
t.guides["forever/class/druid/bloodpetal-poison"] = (function() return {
		["Back to {npc:9619} in the south-east corner of {zone:1449}."] = "Zurück zu {npc:9619} in der Südostecke des {zone:1449}.",
		["Cast {spell:18960}. {npc:12042} stands in {area:2361}; your class trainer offers the same quest."] = "Wirke {spell:18960}. {npc:12042} steht in {area:2361}; dein Klassenlehrer bietet dieselbe Quest an.",
		["Experience in Un'Goro at 50 and two healing potions; Forever removed the Classic item choice."] = "Erfahrung in Un'Goro mit 50 und zwei Heiltränke; Forever hat die Gegenstandswahl aus Classic entfernt.",
		["Fly to {area:976}, ride west to the long ramp down into {zone:1449}: {npc:9619} camps at its foot, in the south-east corner of the crater."] = "Flieg nach {area:976} und reite nach Westen zur langen Rampe hinab in den {zone:1449}: {npc:9619} lagert an ihrem Fuß, in der Südostecke des Kraters.",
		["Gorishi Stings and {item:22434}"] = "Gorishistachel und {item:22434}",
		["The Gorishi wasps, workers and reavers of the hive in the south of the crater drop the stings; the Bloodpetal Sprouts that give the {item:22434} grow all over the crater's western half."] = "Die Wespen, Arbeiter und Häscher der Gorishi im Stock im Süden des Kraters lassen die Stachel fallen; die Blutblütensprösslinge, die {item:22434} geben, wachsen überall in der Westhälfte des Kraters.",
		["The {area:1417}"] = "{area:1417}",
		["Use the {item:22432} on a {npc:6498}. Devilsaurs are elite (level 54-55) and roam the crater: grouping up is advised."] = "Benutze {item:22432} an einem {npc:6498}. Teufelssaurier sind Elite (Stufe 54-55) und streifen durch den Krater: Eine Gruppe wird empfohlen.",
		["{area:1477} lies in the {area:74} in the {zone:1435}. {npc:8580} guards the bottom of the temple: a dungeon boss, so bring a group."] = "{area:1477} liegt im {area:74} in den {zone:1435}. {npc:8580} bewacht den Grund des Tempels: ein Dungeonboss, also bring eine Gruppe mit.",
		["{npc:6498}: stab it with the {item:22432}"] = "{npc:6498}: Stich ihn mit {item:22432}",
} end)()
