		["The relics of the Barrow Dens"] = "Die Relikte der Grabhügel",
		["The {area:2363}"] = "Die {area:2363}",
		["Your stealth and melee form: in Forever this chain gives {spell:768} at 20, not the trainer."] = "Deine Tarn- und Nahkampfgestalt: In Forever gibt diese Questreihe {spell:768} auf Stufe 20, nicht der Lehrer.",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} steht auf der {area:1639}.",
		["{npc:4217} stands in the {area:1658}. Skyborne without the Rut'theran flight path: take the boat from {area:442}."] = "{npc:4217} steht im {area:1658}. Himmelsgeborene ohne die Flugroute nach Rut'theran: Nimm das Boot von {area:442}.",
		["{quest:98342} (Tauren) waits on the southern hill above the bridge, the {npc:272054} (Skyborne) south of the twin bridges. The relics lie in the {area:2363} east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. A relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98342} (Tauren) wartet auf dem südlichen Hügel über der Brücke, der {npc:272054} (Himmelsgeborene) südlich der Zwillingsbrücken. Die Relikte liegen in den {area:2363} östlich des Sees: Verlasse deine Gestalt, klick die Statue am Eingang für fünf Minuten Verstohlenheit, halte dich von den Geistern drinnen fern und nimm je ein Relikt; das {item:280680} liegt am Fuß der weißen Katzenstatue. Ein Relikt gibt keine Beute, solange ein anderer Spieler es plündert: Warte kurz und versuch es erneut.",
		["{quest:98394} (Night Elves) waits on the southern hill above the bridge, the {npc:272054} (Skyborne) south of the twin bridges. The relics lie in the {area:2363} east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. A relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394} (Nachtelfen) wartet auf dem südlichen Hügel über der Brücke, der {npc:272054} (Himmelsgeborene) südlich der Zwillingsbrücken. Die Relikte liegen in den {area:2363} östlich des Sees: Verlasse deine Gestalt, klick die Statue am Eingang für fünf Minuten Verstohlenheit, halte dich von den Geistern drinnen fern und nimm je ein Relikt; das {item:280680} liegt am Fuß der weißen Katzenstatue. Ein Relikt gibt keine Beute, solange ein anderer Spieler es plündert: Warte kurz und versuch es erneut.",
} end)()
t.guides["forever/class/druid/cure-poison"] = (function() return {
		["Back in {area:442}."] = "Zurück in {area:442}.",
		["Cast {spell:18960} and see {npc:11802}, then fly to {area:702} and take the portal up to {zone:1457}."] = "Wirke {spell:18960} und sprich mit {npc:11802}, flieg dann nach {area:702} und nimm das Portal hinauf nach {zone:1457}.",
		["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}."] = "Wirke {spell:18960} und sprich mit {npc:11802}, nimm dann den Flug von {npc:11798} nach {area:1638}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Then fly to {area:442}."] = "Wirke {spell:18960}. {npc:11802} ist in {area:2361}. Flieg dann nach {area:442}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. {npc:11798} flies druids to {area:1638}; fly on to the {area:380} from there."] = "Wirke {spell:18960}. {npc:11802} ist in {area:2361}. {npc:11798} fliegt Druiden nach {area:1638}; flieg von dort weiter nach {area:380}.",
		["From the {area:380} ride north to {area:384} and fill the {item:15842} at the {object:19464}."] = "Reite von {area:380} nach Norden zum {area:384} und fülle den {item:15842} am {object:19464}.",
		["Lost Barrens Kodos roam the plains north and west of the {area:380} and around the {area:388}; each drops a horn. Herbalists find {item:2449} all over the northern {zone:1413}."] = "Verirrte Brachlandkodos streifen durch die Ebenen nördlich und westlich von {area:380} und um {area:388}; jeder lässt ein Horn fallen. Kräuterkundige finden {item:2449} überall im nördlichen {zone:1413}.",
		["Ride north-east from {area:442} to {area:445} and fill the {item:15844} at the mouth of the cave by the falls."] = "Reite von {area:442} nach Nordosten zu den {area:445} und fülle den {item:15844} am Höhleneingang bei den Wasserfällen.",
		["Sickly Gazelles"] = "Kränkliche Gazellen",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else buys it from {npc:1313} (Alchemy Supplies) in {zone:1453} or on the Auction House."] = "Die Lunarfungusblüten wachsen in den Mondkinhöhlen in den Hügeln gleich östlich von {area:442}; die Mondkin dort sind reizbar. {item:2449} erfordert {skill:182}: Kräuterkundige pflücken es überall in {zone:1439}, alle anderen kaufen es bei {npc:1313} (Alchemiebedarf) in {zone:1453} oder im Auktionshaus.",
		["Use the {item:15826} on Sickly Gazelles: they graze north of the road that runs east and west through the {area:380}."] = "Benutze die {item:15826} an Kränklichen Gazellen: Sie grasen nördlich der Straße, die von Ost nach West durch {area:380} führt.",
		["Use the {item:15826} on {npc:12298}. They roam {zone:1439} from the {area:456} in the north to the {zone:1440} border in the south."] = "Benutze die {item:15826} an {npc:12298}. Sie streifen durch {zone:1439}, vom {area:456} im Norden bis zur Grenze von {zone:1440} im Süden.",
		["{item:15851} and {item:2449}"] = "{item:15851} und {item:2449}",
		["{item:2449} and Kodo Horns"] = "{item:2449} und Kodohörner",
		["{item:2449}; herbalists pick it on the plains"] = "{item:2449}; Kräuterkundige pflücken es in den Ebenen",
		["{npc:12296}: use the salve on them"] = "{npc:12296}: Benutze die Salbe an ihnen",
		["{npc:12298}: use the salve on them"] = "{npc:12298}: Benutze die Salbe an ihnen",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} steht auf der {area:1639}.",
		["{npc:3448} stands in the {area:380}. No {skill:182}? {npc:3490}, a few steps away, sells {item:2449}, three at a time until he restocks."] = "{npc:3448} steht in {area:380}. Kein {skill:182}? {npc:3490}, ein paar Schritte entfernt, verkauft {item:2449}, je drei, bis er nachfüllt.",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217} steht im {area:1658}.",
		["{spell:8946} is no longer trained in Forever: this chain teaches it, with a medicine bag on the way."] = "{spell:8946} wird in Forever nicht mehr gelehrt: Diese Questreihe bringt es dir bei, mit einem Medizinbeutel unterwegs.",
} end)()
t.guides["forever/class/hunter/rhokdelar"] = (function() return {
		["Back to the Ancients"] = "Zurück zu den Uralten",
		["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, roams the south of {zone:1447} and drops it most of the time; the Cobalt dragonkin of {zone:1452} drop it very rarely. Skip the rest of this guide if you do not want the quiver."] = "Der Köcher von Hastat dem Uralten braucht {item:18704}. {npc:6109}, ein Weltboss für einen Schlachtzug, streift durch den Süden von {zone:1447} und lässt sie meistens fallen; die kobaltblauen Drachkin in {zone:1452} nur sehr selten. Überspringe den Rest dieses Guides, wenn du den Köcher nicht willst.",
		["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and Vartrus then gave {item:18715} ({spell:425121})."] = "In Forever nicht bestätigt. In Classic ergab {item:18707} mit {item:18724} in den Taschen benutzt Rhok'delar, und Vartrus der Uralte gab dann {item:18715} ({spell:425121}).",
		["Onyxia"] = "Onyxia",
		["Onyxia drops the {item:18705}; she is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}."] = "Onyxia lässt {item:18705} fallen; sie ist der Schlachtzugsboss für 40 Spieler in {area:2159}, einer Höhle im {area:511} im Süden der {zone:1445}.",
		["Rhok'delar and Lok'delar"] = "Rhok'delar und Lok'delar",
		["The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever)."] = "Die epische Bogen-Questreihe der Jäger: In Classic wurden aus Stab und Sehne Rhok'delar und Lok'delar (in Forever unbestätigt).",
		["The {item:18703}"] = "{item:18703}",
		["The {object:179703} appears in {area:2717} when {npc:12018} yields; it holds the {item:18703} about half the time. {area:2717} is a 40-player raid inside {area:254}. Right-click the leaf to start the quest."] = "{object:179703} erscheint im {area:2717}, wenn {npc:12018} aufgibt; in etwa jedem zweiten Fall enthält er {item:18703}. {area:2717} ist ein Schlachtzug für 40 Spieler im {area:254}. Rechtsklicke das Blatt, um die Quest zu starten.",
		["Vartrus, Stoma and {npc:14526} stand together in the north of {zone:1448}. Alliance: {area:1998} is the nearest flight point; Horde: {area:1997}."] = "Vartrus der Uralte, Stoma der Uralte und {npc:14526} stehen zusammen im Norden von {zone:1448}. Allianz: {area:1998} ist der nächste Flugpunkt; Horde: {area:1997}.",
		["from the {item:18703}"] = "von {item:18703}",
		["{item:18704}, from {npc:6109}"] = "{item:18704}, von {npc:6109}",
		["{item:18705}, from Onyxia"] = "{item:18705}, von Onyxia",
		["{item:18707}, by Vartrus"] = "{item:18707}, bei Vartrus dem Uralten",
		["{npc:14524}: Lok'delar in Classic"] = "{npc:14524}: Lok'delar in Classic",
		["{npc:14526}: the quiver, last in this guide"] = "{npc:14526}: der Köcher, zuletzt in diesem Guide",
		["{npc:14527}, a troll, stands in the west of {zone:1449}. Talk to her and she becomes {npc:14533}, with a pet of her own. Alone, without your pet."] = "{npc:14527}, eine Trollin, steht im Westen des {zone:1449}. Sprich mit ihr, und sie wird zu {npc:14533}, mit eigenem Begleiter. Allein, ohne deinen Begleiter.",
		["{npc:14529}, a human, stands in the west of the {zone:1428}. Talk to him and he becomes {npc:14534}. Alone, without your pet."] = "{npc:14529}, ein Mensch, steht im Westen der {zone:1428}. Sprich mit ihm, und er wird zu {npc:14534}. Allein, ohne deinen Begleiter.",
		["{npc:14531}, a tauren, waits in the north-east of {zone:1452}. Talk to him and he becomes {npc:14535}. Fight every demon alone and without your pet: help of any kind makes it vanish. Loot the head."] = "{npc:14531}, ein Tauren, wartet im Nordosten von {zone:1452}. Sprich mit ihm, und er wird zu {npc:14535}. Kämpfe gegen jeden Dämon allein und ohne Begleiter: Jede Art von Hilfe lässt ihn verschwinden. Plündere den Kopf.",
		["{npc:14536}, a gnome, stands in the south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. Alone, without your pet; keep away from the beetles he calls."] = "{npc:14536}, ein Gnom, steht im Südwesten von {zone:1451}. Sprich mit ihm, und er wird zu {npc:14530}. Allein, ohne deinen Begleiter; halte dich von den Käfern fern, die er ruft.",
} end)()
t.guides["forever/class/hunter/the-hunters-charm"] = (function() return {
		["At 50 any Alliance hunter trainer offers it: {npc:5516} in {zone:1453}'s {object:28027}, {npc:5116} in {zone:1455}'s {object:32390} or Dorion in {zone:1457}' Cenarion Enclave."] = "Mit 50 bietet sie jeder Jägerlehrer der Allianz an: {npc:5516} im {object:28027} von {zone:1453}, {npc:5116} in der {object:32390} von {zone:1455} oder Dorion in der Enklave des Cenarius von {zone:1457}.",
		["At 50 any Horde hunter trainer offers it: {npc:3352} in {zone:1454}'s {object:172958} or {npc:3039} on {area:1641} in {zone:1456}."] = "Mit 50 bietet sie jeder Jägerlehrer der Horde an: {npc:3352} im {object:172958} von {zone:1454} oder {npc:3039} auf der {area:1641} in {zone:1456}.",
		["Experience"] = "Erfahrung",
		["Experience at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "Erfahrung mit 50 durch {zone:1447} und {area:1417}; Forever hat die Gegenstandswahl aus Classic entfernt.",
		["Morphaz in the {area:1417}"] = "Morphaz im {area:1417}",
		["Morphaz is an elite dragon boss inside the {area:1417}, a five-player dungeon: bring a group. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance. Horde: fly to {area:75}; Alliance: fly to {area:42} or {area:1438} and ride on."] = "Morphaz ist ein Elite-Drachenboss im {area:1417}, einem Dungeon für fünf Spieler: Bring eine Gruppe mit. Der Tempel steht mitten im {area:74}; tauch hinab, um den Eingang zu erreichen. Horde: Flieg nach {area:75}; Allianz: Flieg nach {area:42} oder zur {area:1438} und reite weiter.",
		["Mosshoof Coursers graze all over {zone:1447}; one in a dozen or so drops a pair of Perfect Courser Antlers."] = "Mooshufrenner grasen überall in {zone:1447}; etwa jeder zwölfte lässt ein Paar Perfekte Rennergeweihe fallen.",
		["Wavethrashers crawl along {zone:1447}'s coasts: Young Wavethrashers on the north-east shore and Wavethrashers on the east coast drop the scales about twice as often as the Great Wavethrashers of the south shore."] = "Wellenhauer kriechen an den Küsten von {zone:1447} entlang: Junge Wellenhauer am Nordostufer und Wellenhauer an der Ostküste lassen die Schuppen etwa doppelt so oft fallen wie die Großen Wellenhauer am Südufer.",
		["{item:20019}, inside the {area:1417}"] = "{item:20019}, im {area:1417}",
		["{npc:8405} lives atop the cliffs north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}."] = "{npc:8405} lebt oben auf den Klippen nordöstlich der {area:1221}. Allianz: Flieg zur {area:3137}; Horde: Flieg nach {area:1237}.",
		["{quest:8151} (Alliance)"] = "{quest:8151} (Allianz)",
		["{quest:8151} (Horde)"] = "{quest:8151} (Horde)",
} end)()
t.guides["forever/class/mage/arcane-refreshment"] = (function() return {
		["Back to Lydros"] = "Zurück zu Lydros",
		["Fly to Feathermoon (Alliance) or {area:1099} (Horde) and ride to {area:2577} in central {zone:1444}. {npc:14368} waits in the Athenaeum, the library, reached through the West wing (or the North wing with a {item:18249})."] = "Flieg nach Feathermoon (Allianz) oder {area:1099} (Horde) und reite nach {area:2577} im Zentrum von {zone:1444}. {npc:14368} wartet im Athenaeum, der Bibliothek, erreichbar durch den Westflügel (oder den Nordflügel mit einem {item:18249}).",
		["Hydrospawn"] = "Hydrobrut",
		["Hydrospawn, a water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool."] = "Hydrobrut, ein Wasserelementar, lebt im Wucherborkenviertel (Düsterbruch Ost): Jag den Wichtel Pusillin, bis er sich zum Kampf stellt, säubere den Satyrraum und nimm dann die Wendelrampe hinab zum Becken.",
		["Shen'dralar reputation"] = "Ruf bei den Shen'dralar",
		["The level 60 {spell:10140}, from a {area:2577} library: drink for you and your group."] = "{spell:10140} der Stufe 60, aus einer Bibliothek in {area:2577}: Getränke für dich und deine Gruppe.",
		["{item:18299}: Hydrospawn"] = "{item:18299}: Hydrobrut",
} end)()
t.guides["forever/class/mage/astral-knot-garment"] = (function() return {
		["A robe or a blouse for Human and Gnome mages in their late 20s."] = "Eine Robe oder eine Bluse für menschliche und gnomische Magier gegen Ende 20.",
		["Back to Andromath"] = "Zurück zu Andromath",
		["Carrion Recluses"] = "Aaskrabbler",
		["Carrion Recluses lurk in the woods of western {zone:1431} and each one drops the silk. The Black Widow Hatchlings further east drop it now and then."] = "Aaskrabbler lauern in den Wäldern im Westen von {zone:1431}, und jeder lässt die Seide fallen. Die Jungen einer Schwarzen Witwe weiter östlich lassen sie ab und zu fallen.",
		["Ride east through {zone:1429} into Redridge. The fallen mage's tower of Ilgalar stands in the east of the zone; the treatise is in his library."] = "Reite nach Osten durch {zone:1429} ins Rotkammgebirge. Der Turm des gefallenen Magiers Ilgalar steht im Osten des Gebiets; die Abhandlung liegt in seiner Bibliothek.",
		["The {area:96}"] = "{area:96}",
		["{npc:1309} works at {object:23296} in the {object:2101}."] = "{npc:1309} arbeitet bei {object:23296} in {object:2101}.",
		["{npc:5144} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:5144} unterrichtet Magier in {object:32362} in {zone:1455}. Nimm danach {area:2257} von {object:171524} nach {zone:1453}.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}."] = "{npc:5497} steht im Magiersanktum, dem Turm in {object:2101}.",
		["{quest:1939} is in the Wizard's Sanctum too."] = "{quest:1939} ist ebenfalls im Magiersanktum.",
} end)()
t.guides["forever/class/mage/celestial-orb"] = (function() return {
		["An off-hand orb or a staff for the late 30s, your pick."] = "Eine Schildhand-Kugel oder ein Stab für die späten 30er, nach deiner Wahl.",
		["Back to {npc:6546}. She opens a mana rift beside her cottage: kill twelve {quest:1957} within ten minutes."] = "Zurück zu {npc:6546}. Sie öffnet neben ihrer Hütte einen Manariss: Töte innerhalb von zehn Minuten zwölf {quest:1957}.",
		["The Burning Blade Summoners work the {area:602} in southern {zone:1443}; any of them carries an {item:7291}."] = "Die Beschwörer der Burning Blade treiben im {area:602} im Süden von {zone:1443} ihr Werk; jeder von ihnen trägt eine {item:7291}.",
		["{area:1517} is a dungeon in the northern {zone:1418}, by the {object:178824}: a group of five. Defeat the {npc:7023} inside for its power source."] = "{area:1517} ist ein Dungeon im Norden des {zone:1418} beim {object:178824}: eine Gruppe für fünf. Besiege drinnen {npc:7023} für seine Energiequelle.",
		["{item:7515} and Stave"] = "{item:7515} und Stab",
		["{npc:5497} in the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you back to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{npc:5497} im Wizard's Sanctum im {object:2101} von {zone:1453} schickt dich zurück zu {npc:6546}; Bink in {zone:1455} gibt dieselbe Quest.",
		["{npc:5885}, one of {zone:1454}'s mage trainers, sends you back to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{npc:5885}, einer der Magierlehrer von {zone:1454}, schickt dich zurück zu {npc:6546}; {npc:4568} in {zone:1458} und {npc:3048} in {zone:1456} geben dieselbe Quest.",
		["{npc:6546} draws the demon out of the orb beside her cottage. The {npc:6549} is elite: grouping up is advised. You have three minutes before it slips back into the orb."] = "{npc:6546} zieht den Dämon neben ihrer Hütte aus der Kugel. {npc:6549} ist Elite: Eine Gruppe wird empfohlen. Du hast drei Minuten, bevor er in die Kugel zurückschlüpft.",
		["{npc:6546}'s cottage is deep in the marsh west of Theramore, just north of the {area:508}."] = "Die Hütte von {npc:6546} liegt tief im Marschland westlich von Theramore, knapp nördlich der {area:508}.",
} end)()
t.guides["forever/class/mage/destroy-morphaz"] = (function() return {
		["Back to {npc:8395} and up to the tower."] = "Zurück zu {npc:8395} und hinauf zum Turm.",
		["Back to {npc:8395}, who teleports you up to the tower."] = "Zurück zu {npc:8395}, der dich hinauf zum Turm teleportiert.",
		["Back to {zone:1447}, {npc:8395} and the tower."] = "Zurück nach {zone:1447}, zu {npc:8395} und zum Turm.",
		["Experience"] = "Erfahrung",
		["Experience at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "Erfahrung mit Stufe 50 durch {zone:1447} und den {area:1417}; Forever hat die Gegenstandsauswahl aus Classic entfernt.",
		["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below his master's tower: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. He teleports you up to {npc:8379}."] = "Flieg zur {area:3137} (Allianz) oder nach {area:1237} (Horde). {npc:8395} lagert unterhalb des Turms seines Meisters: Geh von der Gabelung der Hauptstraße von {zone:1447} im Gebiet {area:1221} geradeaus nach Norden zu den Klippen. Er teleportiert dich hinauf zu {npc:8379}.",
		["Morphaz"] = "Morphaz",
		["Morphaz, a green drake, waits deep in the {area:1477}, the {area:1417} in the {area:74}: a group of five, level 50-54. Kill him for the {item:20085}."] = "Morphaz, ein grüner Drache, wartet tief im Gebiet {area:1477}, dem {area:1417} im {area:74}: eine Gruppe aus fünf, Stufe 50-54. Töte ihn für den {item:20085}.",
		["The Spitelash Sirens walk the ruins and beaches around the {area:1221} and the bay; they carry the coral."] = "Die Sirenen der Grollflossen streifen durch die Ruinen und Strände im Gebiet {area:1221} und an der Bucht; sie tragen die Koralle.",
		["The blood elves camp along the cliffs of north-eastern {zone:1447}; Blood Elf Surveyors and Reclaimers drop the dust."] = "Die Blutelfen lagern an den Klippen im Nordosten von {zone:1447}; Blutelfenfeldmesser und Blutelfenwiederbeschafferinnen lassen den Staub fallen.",
		["The {item:20085}"] = "Der {item:20085}",
		["{item:20085}: Morphaz"] = "{item:20085}: Morphaz",
		["{npc:331}, the Master Mage, stands in the Wizard's Sanctum in {zone:1453}'s {object:2101}; Dink in {zone:1455} gives the same quest."] = "{npc:331}, der Meistermagier, steht im Magiersanktum im Gebiet {object:2101} in {zone:1453}; Dink in {zone:1455} gibt dieselbe Quest.",
		["{npc:7311}, one of {zone:1454}'s mage trainers, gives it; so do {npc:4567} in the {zone:1458} and {npc:3047} in {zone:1456}."] = "{npc:7311}, einer der Magierlehrer in {zone:1454}, gibt sie; ebenso {npc:4567} in {zone:1458} und {npc:3047} in {zone:1456}.",
		["{npc:8379} again"] = "Wieder zu {npc:8379}",
		["{npc:8379}, in the tower"] = "{npc:8379}, im Turm",
} end)()
t.guides["forever/class/mage/ju-ju-heaps"] = (function() return {
		["A staff or an orb at 10 for Horde mages, worth a short trip back to the {area:368}."] = "Ein Stab oder eine Kugel mit Stufe 10 für Hordemagier, einen kurzen Abstecher zurück nach {area:368} wert.",
		["Back to Un'thuwa"] = "Zurück zu Un'Thuwa",
		["The {quest:1884}"] = "{quest:1884}",
		["Un'thuwa"] = "Un'Thuwa",
		["Un'thuwa stands in {area:367}, on the {zone:1411} coast south of {area:362}."] = "Un'Thuwa steht in {area:367}, an der Küste von {zone:1411} südlich von {area:362}.",
		["Wade across to the {area:368}, south-east of Sen'jin. Zalazane placed the heaps among his huts on the main isle: click a heap to destroy it."] = "Wate hinüber nach {area:368}, südöstlich von Sen'jin. Zalazane hat die Jujuhaufen zwischen seinen Hütten auf der Hauptinsel platziert: Klicke einen Haufen an, um ihn zu zerstören.",
} end)()
t.guides["forever/class/mage/mages-wand"] = (function() return {
		["\"Plucky\" Johnson"] = "Eisenherz Johnson",
		["A wand of your school for the 30s: frost, arcane or fire."] = "Ein Zauberstab deiner Schule für Stufe 30+: Frost, Arkan oder Feuer.",
		["Back to {npc:6546}"] = "Zurück zu {npc:6546}",
		["The Witherbark trolls hold south-eastern {zone:1417}; every one of them can drop a {item:7273}. Then take the ten sticks north-west to the binding circle where they become the {item:7272}. {npc:6546} also wants a {item:1529}: buy one at an Auction House on the way; miners sometimes find one in Tin Veins."] = "Die Trolle der Witherbark halten den Südosten von {zone:1417}; jeder von ihnen kann einen {item:7273} fallen lassen. Bring die zehn Stecken dann nach Nordwesten zum Bindungskreis, wo sie zum {item:7272} werden. {npc:6546} will auch einen {item:1529}: Kauf ihn unterwegs in einem Auktionshaus; Bergleute finden manchmal einen in Zinnvorkommen.",
		["Tirth sold the book to the Scarlet Brotherhood. The {area:796} stands in north-eastern {zone:1420}; take the Library wing. The book juts out of the wall on the left as you enter the Athenaeum, before {npc:6487}."] = "Tirth hat das Buch an den Scharlachroten Kreuzzug verkauft. {area:796} steht im Nordosten von {zone:1420}; nimm den Flügel Bibliothek. Das Buch ragt links aus der Wand, wenn du das Athenaeum betrittst, vor {npc:6487}.",
		["Tirth's apprentice is \"Plucky\" Johnson, a small grey chicken by the race track. Target him and type /beckon: he turns human for a moment, long enough to talk to him."] = "Tirths Lehrling ist Eisenherz Johnson, ein kleines graues Huhn an der Rennstrecke. Nimm ihn ins Ziel und tippe /beckon: Er wird kurz wieder menschlich, lange genug, um mit ihm zu reden.",
		["Witherbark trolls"] = "Trolle der Witherbark",
		["{npc:5497} in the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{npc:5497} im Magiersanktum im Gebiet {object:2101} in {zone:1453} schickt dich zu {npc:6546}; Bink in {zone:1455} gibt dieselbe Quest.",
		["{npc:5885}, one of {zone:1454}'s mage trainers, sends you to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{npc:5885}, einer der Magierlehrer in {zone:1454}, schickt dich zu {npc:6546}; {npc:4568} in {zone:1458} und {npc:3048} in {zone:1456} geben dieselbe Quest.",
		["{npc:6546}'s ritual"] = "Das Ritual von {npc:6546}",
		["{npc:6546}, a hermit, lives in a cottage deep in the marsh west of Theramore, just north of the {area:508}."] = "{npc:6546}, eine Einsiedlerin, lebt in einer Hütte tief im Sumpf westlich von Theramore, direkt nördlich des Gebiets {area:508}.",
		["{npc:6548} spends his days at the race track in the {area:439}, south-east {zone:1441}."] = "{npc:6548} verbringt seine Tage an der Rennstrecke im Gebiet {area:439}, im Südosten von {zone:1441}.",
		["{quest:1951}: Scarlet Monastery Library"] = "{quest:1951}: Das Scharlachrote Kloster, Bibliothek",
} end)()
t.guides["forever/class/mage/manaweave-robe"] = (function() return {
		["A robe at 15 for Alliance mages, from {zone:1453} and {zone:1432}."] = "Eine Robe mit Stufe 15 für Allianzmagier, aus {zone:1453} und {zone:1432}.",
		["Back to {npc:5497}"] = "Zurück zu {npc:5497}",
		["Back to {zone:1453} by the tram. {npc:1309} works at {object:23296} in the {object:2101}."] = "Mit der Bahn zurück nach {zone:1453}. {npc:1309} arbeitet bei {object:23296} in {object:2101}.",
		["Humanoids drop {item:2589}; the Auction House in the {object:2096} sells it."] = "Humanoide lassen {item:2589} fallen; das Auktionshaus in {object:2096} verkauft es.",
		["Take the {area:2257} to {zone:1455}, then the road east through the South Gate tunnel into {zone:1432}. The dwarven miners' league left the crates in the {area:149} at the north end of the loch; Tunnel Rat troggs hold the mine."] = "Nimm {area:2257} nach {zone:1455}, dann die Straße nach Osten durch den Tunnel am Südtor nach {zone:1432}. Die Minenarbeiterliga der Zwerge hat die Kisten in {area:149} am Nordende des Sees zurückgelassen; Troggs der Tunnelratten halten die Mine.",
		["The {area:149}"] = "{area:149}",
		["{npc:328} is the {area:87} mage trainer."] = "{npc:328} ist der Magierlehrer in {area:87}.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}. The {item:7247} and the {item:7308} lie behind her."] = "{npc:5497} steht im Magiersanktum, dem Turm in {object:2101}. {item:7247} und {item:7308} liegen hinter ihr.",
		["{npc:7312} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:7312} unterrichtet Magier in {object:32362} in {zone:1455}. Nimm danach {area:2257} von {object:171524} nach {zone:1453}.",
		["{object:2169} is the tavern in the {object:2101}. Use the {item:7308} inside to make the {npc:6492} visible, subdue one with your spells, then use the {item:7247} to throw down a coffer and capture it."] = "{object:2169} ist die Taverne in {object:2101}. Benutze dort {item:7308}, um {npc:6492} sichtbar zu machen, bezwinge eine mit deinen Zaubern und benutze dann {item:7247}, um einen Kasten hinzuwerfen und sie einzufangen.",
} end)()
