t.guides["forever/class/paladin/lumina-windsinger"] = (function() return {
		["Back to the {area:228}"] = "Zurück zum {area:228}",
		["Free her with the key, then stay close while she fights her way out of the keep."] = "Befreie sie mit dem Schlüssel und bleib dann in ihrer Nähe, während sie sich aus der Burg kämpft.",
		["Free {npc:248755}"] = "Befreie {npc:248755}",
		["No item yet: a Forsaken paladin rescue story; its sequel, the {item:268484}, cannot be finished yet."] = "Noch kein Gegenstand: eine Rettungsgeschichte für Paladine der Verlassenen; die Fortsetzung, die {item:268484}, kann noch nicht abgeschlossen werden.",
		["Once she is clear of {area:235}, {npc:259620} waits for you in the {area:228}. Speak with her again to hear what really happened on the road."] = "Sobald sie aus {area:235} heraus ist, wartet {npc:259620} im {area:228} auf dich. Sprich erneut mit ihr, um zu erfahren, was auf der Straße wirklich geschah.",
		["Rescuing {quest:91862}"] = "{quest:91862} retten",
		["Ride south through {zone:1421} to the {area:228}. {npc:248840} stands in the town; {npc:259611} keeps watch near its entrance."] = "Reite nach Süden durch {zone:1421} zum {area:228}. {npc:248840} steht im Ort; {npc:259611} hält nahe dem Eingang Wache.",
		["The pyre on {area:172}"] = "Der Scheiterhaufen auf der {area:172}",
		["from the {object:566037}"] = "von den {object:566037}",
		["{area:172} lies in the lake east of the {area:228}. The charred remains are on its shore."] = "Die {area:172} liegt im See östlich vom {area:228}. Die verkohlten Überreste sind am Ufer.",
		["{item:267412}, from the Rot Hide gnolls"] = "{item:267412}, von den Gnollen der Moderfelle",
		["{npc:246378} leads the Paladins of Tyr's Watch from inside {area:16602}, on the bluffs north-west of the {area:156}."] = "{npc:246378} führt die Paladine von Tyrs Wacht aus {area:16602} heraus, auf den Klippen nordwestlich von {area:156}.",
		["{npc:259620}, the {area:228}"] = "{npc:259620}, das {area:228}",
		["{quest:91862} is caged inside {area:235}, at the north end of the isle. The Rot Hide gnolls around her carry the key."] = "{quest:91862} ist in {area:235} eingesperrt, am Nordende der Insel. Die Gnolle der Moderfelle um sie herum tragen den Schlüssel.",
		["{zone:1458} and Earthen Ring reputation"] = "Ruf bei {zone:1458} und beim Irdenen Ring",
} end)()
t.guides["forever/class/paladin/tyrs-watch"] = (function() return {
		["Back to the keep"] = "Zurück zur Feste",
		["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep."] = "Zurück nach {area:16602}. {npc:246378} gibt dir {item:6866}; {npc:257655} wartet unten in der Feste.",
		["Back to {area:16602}: Billmuth takes the plans, {npc:246378} teaches you {spell:7328}."] = "Zurück nach {area:16602}: Billmuth nimmt die Pläne, {npc:246378} lehrt dich {spell:7328}.",
		["Tarnished Drudges"] = "Befleckte Akkordarbeiter",
		["Tarnished Zealots"] = "Befleckte Fanatiker",
		["The Scarlet Crusaders camped around {area:812} carry the attack plans."] = "Die Scharlachroten Kreuzfahrer, die rund um {area:812} lagern, tragen die Angriffspläne.",
		["The Scarlet attack plans"] = "Die Angriffspläne des Scharlachroten Kreuzzugs",
		["The Vile Fin murlocs lurk on the bluffs along the road east of the keep and in the camps around the lake to the west."] = "Die Murlocs der Finsterflossen lauern auf den Klippen entlang der Straße östlich der Feste und in den Lagern rund um den See im Westen.",
		["The {item:6866}"] = "{item:6866}",
		["Tyr's Watch and {spell:7328}"] = "Tyr's Watch und {spell:7328}",
		["Vile Fin Attackers"] = "Angreifer der Finsterflossen",
		["Vile Fin Seers"] = "Seher der Finsterflossen",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:10181} holds court in the {object:36126}; {npc:257648} begs in the {object:36078}."] = "Geh von {area:159} nach Süden zu {area:153} und hinab nach {zone:1458}. {npc:10181} hält in {object:36126} Hof; {npc:257648} bettelt in {object:36078}.",
		["{area:16602} stands on the bluffs north-west of the {area:156}. {npc:246349} waits at the gate."] = "{area:16602} steht auf den Klippen nordwestlich von {area:156}. {npc:246349} wartet am Tor.",
		["{area:812} is at the far east end of the glades. Use the {item:6866} on {npc:257663}, then speak to him. If you lose the symbol, {npc:246378} gives you another."] = "{area:812} liegt am äußersten Ostende der Lichtungen. Benutze {item:6866} an {npc:257663} und sprich dann mit ihm. Verlierst du das Symbol, gibt dir {npc:246378} ein neues.",
		["{npc:246152}, who trains Paladins in {area:159}, sends you to the order's keep on the west coast."] = "{npc:246152}, die in {area:159} Paladine ausbildet, schickt dich zur Feste des Ordens an der Westküste.",
		["{npc:246378} leads the order from inside the keep; {npc:246393} stands beside it."] = "{npc:246378} führt den Orden aus dem Inneren der Feste; {npc:246393} steht daneben.",
		["{npc:246378} offers the first Lesson in Divinity at level 12."] = "{npc:246378} bietet die erste Lektion in Sachen Göttlichkeit mit Stufe 12 an.",
		["{npc:257648} needs 10 {item:2589}. Scarlet Zealots and Scarlet Friars drop it about three times in ten; bring it along if you already carry some."] = "{npc:257648} braucht 10 {item:2589}. Scharlachrote Zeloten und Scharlachrote Ordensmitglieder lassen es etwa dreimal von zehn fallen; bring es mit, falls du schon welches dabeihast.",
		["{object:554626}, in the root cellar"] = "{object:554626}, im Wurzelkeller",
		["{quest:91317} hold the ruined village of {area:16881} in the {area:16616}, south-west of the keep. The {item:246213} is piled in the root cellar of one of its houses; Commander {npc:259431} walks among his Tarnished."] = "{quest:91317} halten das zerstörte Dorf {area:16881} in {area:16616}, südwestlich der Feste. {item:246213} ist im Wurzelkeller eines der Häuser gestapelt; Kommandant {npc:259431} geht zwischen seinen Befleckten umher.",
		["{spell:7328} to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin."] = "{spell:7328}, um gefallene Verbündete wiederzubeleben, dazu eine Waffe und ein Schild für einen neuen verlassenen Paladin.",
} end)()
t.guides["forever/class/paladin/verigans-fist"] = (function() return {
		["At 20 {npc:6179} in the {object:32362} gives you the {item:6776}; it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the tram from {zone:1455} to {zone:1453}."] = "Mit 20 gibt dir {npc:6179} in der {object:32362} {item:6776}; er schickt dich zu {npc:6171} in der Kathedrale des Lichts in {zone:1453}. Nimm die Tiefenbahn von {zone:1455} nach {zone:1453}.",
		["Back to {npc:3649} in {area:442}: he purifies the gem."] = "Zurück zu {npc:3649} in {area:442}: Er reinigt den Edelstein.",
		["Back to {npc:6241}"] = "Zurück zu {npc:6241}",
		["Bring the four parts to {npc:6181} outside {zone:1455}."] = "Bring die vier Teile zu {npc:6181} vor {zone:1455}.",
		["Goblin Woodcarvers, inside"] = "Goblin-Holzschnitzer, drinnen",
		["Protect {npc:6182}"] = "Beschütze {npc:6182}",
		["The Alliance paladin's rare two-handed mace for the 20s, with a shield on the way."] = "Der seltene Zweihandstreitkolben der Allianz-Paladine für die 20er, mit einem Schild unterwegs.",
		["The Blackfathom naga by the entrance of {area:2797} on {zone:1440}'s north-west coast drop the {item:6995}. They are elite: grouping up is advised."] = "Die Blackfathom-Naga am Eingang der {area:2797} an der Nordwestküste von {zone:1440} lassen {item:6995} fallen. Sie sind Elite: Eine Gruppe wird empfohlen.",
		["The ore crate lies by the trees in the middle of the Mo'grosh ogre camp in north-east {zone:1432}. The Mo'grosh ogres are elite: grouping up is advised."] = "Die Erzkiste liegt bei den Bäumen mitten im Lager der Oger der Mo'grosh im Nordosten von {zone:1432}. Die Oger der Mo'grosh sind Elite: Eine Gruppe wird empfohlen.",
		["The {item:6995}"] = "{item:6995}",
		["The {item:7083}"] = "{item:7083}",
		["from the {item:6776}"] = "von {item:6776}",
		["{area:1581} is a group of five under {area:20}; the instance portal is inside the {area:20} mine. The Goblin Woodcarvers in the Mast Room, with Sneed, drop the lumber."] = "{area:1581} ist für eine Gruppe von fünf unter {area:20}; das Instanzportal liegt in der Mine von {area:20}. Die Goblin-Holzschnitzer bei Sneed in der Mast Room lassen das Holz fallen.",
		["{area:1581}, in the {area:20} mine"] = "{area:1581}, in der Mine von {area:20}",
		["{area:236} is a level 20-30 dungeon in southern {zone:1421}. The hammer lies on a box inside the stables, at the far end of the courtyard before the ramp up."] = "{area:236} ist ein Dungeon der Stufe 20-30 im Süden des {zone:1421}. Der Hammer liegt auf einer Kiste in den Ställen, am hinteren Ende des Hofs vor der Rampe nach oben.",
		["{npc:3649} is in {area:442}."] = "{npc:3649} ist in {area:442}.",
		["{npc:6171} stands in the Cathedral of Light. Right-click the {item:6776} to start its quest."] = "{npc:6171} steht in der Kathedrale des Lichts. Rechtsklicke {item:6776}, um seine Quest zu starten.",
		["{npc:6181} stands outside the gates of {zone:1455}. He gives you {item:6996}, which list the four parts."] = "{npc:6181} steht vor den Toren von {zone:1455}. Er gibt dir {item:6996}, in denen die vier Teile aufgeführt sind.",
		["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}. Waves of Defias attack it during her quest: keep her alive, and heal her if she needs it."] = "Das Bauernhaus von {npc:6182} steht an der Südwestküste von {zone:1436}. Während ihrer Quest greifen es Wellen von Defias an: Halte sie am Leben und heile sie, wenn nötig.",
		["{npc:6241} is in {area:144}."] = "{npc:6241} ist in {area:144}.",
