		["At 16 {npc:3599} in {area:186} sends you to {quest:2259} in {zone:1457}."] = "Mit Stufe 16 schickt dich {npc:3599} in {area:186} zu {quest:2259} in {zone:1457}.",
		["At 16 {npc:917}, the rogue trainer in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}."] = "Mit Stufe 16 schickt dich {npc:917}, der Schurkenlehrer im Gasthaus Zur Höhle des Löwen in {area:87}, zu {npc:6946} in {zone:1453}.",
		["Back to {npc:6966}"] = "Zurück zu {npc:6966}",
		["Ride east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} waits on the west side of {area:69} and gives you {item:5060}."] = "Reite nach Osten durch {zone:1429} ins Rotkammgebirge oder flieg nach {area:69}. {npc:6966} wartet auf der Westseite von {area:69} und gibt dir {item:5060}.",
		["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}."] = "Dein erster Schlossknacker-Auftrag mit Stufe 16: die Kassette von {npc:6966} bei {quest:2282}, für {quest:2300}.",
		["{npc:6946} stands beside {npc:332} at {quest:2300} in {object:2100}. Dwarves and Gnomes take the {area:2257} from {zone:1455}; Night Elves take the boat from {area:442} to {area:17203}."] = "{npc:6946} steht neben {npc:332} beim {quest:2300} in der {object:2100}. Zwerge und Gnome nehmen die Bahn {area:2257} ab {zone:1455}; Nachtelfen nehmen das Boot von {area:442} zum {area:17203}.",
		["{quest:2282} stands east of {area:69}, up off the road. Open {object:121264} there."] = "{quest:2282} steht östlich von {area:69}, etwas abseits der Straße. Öffne dort {object:121264}.",
} end)()
t.guides["forever/class/rogue/plundering-the-plunderers"] = (function() return {
		["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "Auf Stufe 16 schickt dich {npc:3170}, der Schurkenlehrer in {area:362}, zu {npc:3401} in {zone:1454}.",
		["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "Auf Stufe 16 schickt dich {npc:6467} im {object:36073} zu {npc:3401} in {zone:1454}. Nimm bei ihm auch {quest:1998} an; sie wird am Ende dieses Guides in {zone:1421} erledigt.",
		["Back to {npc:6467}"] = "Zurück zu {npc:6467}",
		["Back to {npc:7161}"] = "Zurück zu {npc:7161}",
		["Fly or ride to {area:392} on the {zone:1413} coast. {npc:7161} stands in town with his Gizmotronic Apparatus: buy an {item:7970} and {item:5060} from the apparatus before you go."] = "Flieg oder reite nach {area:392} an der Küste von {zone:1413}. {npc:7161} steht mit Wrenix' Elektrodingsda-Apparat im Ort: Kauf vor dem Aufbruch einen {item:7970} und {item:5060} am Apparat.",
		["South along the coast from {area:392}, at the Southsea pirates' camp. If an unusually hostile parrot attacks you, use the {item:7970} on it (the quest's own advice)."] = "Südlich entlang der Küste von {area:392}, im Lager der Südmeerfreibeuter. Greift dich ein ungewöhnlich feindseliger Papagei an, benutze den {item:7970} an ihm (der eigene Rat der Quest).",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and ride south into Silverpine. {quest:1998} stands north-east of the {area:228}."] = "Nimm den Zeppelin von {zone:1454} nach {zone:1458} und reite nach Süden in den Silberwald. {quest:1998} steht nordöstlich von {area:228}.",
		["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "Zehn {item:7676}, das Energiegetränk der Schurken, aus den Schlossknack-Aufträgen der Horde auf Stufe 16.",
		["The Kirin Tor keep their reports at {area:233}, in south-east Silverpine: pick the lock on the {object:103815}."] = "Die Kirin Tor bewahren ihre Berichte in {area:233} auf, im Südosten des Silberwalds: Knack das Schloss des {object:103815}.",
		["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}."] = "Untote nehmen den Zeppelin von den Türmen außerhalb von {zone:1458} nach {zone:1411}. {npc:3401} und {quest:2379} stehen in der {object:172960}, der Schlucht unter dem {object:172982}.",
		["{npc:3401} and {quest:2379}"] = "{npc:3401} und {quest:2379}",
		["{npc:7161}: ten {item:7676}"] = "{npc:7161}: zehn {item:7676}",
} end)()
t.guides["forever/class/rogue/poisons-alliance"] = (function() return {
		["/lay down"] = "/hinlegen",
		["At 20 {npc:332} at SI:7 in {object:2100} sends you to {npc:7024} in {zone:1436}."] = "Auf Stufe 20 schickt dich {npc:332} bei SI:7 in {object:2100} zu {npc:7024} in {zone:1436}.",
		["Back to {npc:7207}"] = "Zurück zu {npc:7207}",
		["Everything is in {zone:1453}: the Gumps sell {item:3421}, the {item:8431} lies in the city, and the nearest vendors sell a {item:3372} and a {item:4371}."] = "Alles gibt es in {zone:1453}: Die Gumps verkaufen {item:3421}, die {item:8431} liegt in der Stadt, und die nächsten Händler verkaufen eine {item:3372} und eine {item:4371}.",
		["Forever teaches {spell:2842} through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever lehrt {spell:2842} über diese Questreihe, nicht beim Lehrer; das Rezept für {item:7676} gibt es dazu.",
		["Ride north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "Reite nach Norden durch den Wald von Elwynn nach {zone:1453}; Mathias Shaw ist bei SI:7 in {object:2100}.",
		["The cure's ingredients"] = "Die Zutaten für das Heilmittel",
		["{item:7908}, in the {object:123214}"] = "{item:7908}, in der {object:123214}",
		["{npc:7024} watches {npc:7053}'s tower from the hills in the far east of {zone:1436}, by the {zone:1431} border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "{npc:7024} beobachtet den Turm von {npc:7053} von den Hügeln im äußersten Osten von {zone:1436}, an der Grenze zu {zone:1431}. Die {npc:7051} (Stufe 23), die den Turm bewacht, trägt den Schlüssel; Klavens Tagebuch liegt in der Truhe ganz oben.",
		["{npc:7207} works in the cellar of SI:7, the Barracks. Type /lay down beside him to be examined."] = "{npc:7207} arbeitet im Keller von SI:7, der Kaserne. Gib neben ihm /hinlegen ein, um dich untersuchen zu lassen.",
		["{spell:2842} (Alliance)"] = "{spell:2842} (Allianz)",
} end)()
t.guides["forever/class/rogue/poisons-horde"] = (function() return {
		["/salute {npc:3401}"] = "/salutieren: {npc:3401}",
		["At 20 {npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Target him and type /salute."] = "Mit 20 steht {npc:3401} in der {object:172960}, der Schlucht unter dem {object:172982}. Nimm ihn ins Ziel und gib /salutieren ein.",
		["Back to {npc:3401}"] = "Zurück zu {npc:3401}",
		["Fly back to {zone:1454}."] = "Flieg zurück nach {zone:1454}.",
		["Fly to the {area:380} and ride north to the Venture Co. tower north of the {area:382}. In sight of the tower, fire the {item:8051} twice, then /salute {npc:7233} before he attacks you."] = "Flieg zum {area:380} und reite nach Norden zum Turm der Venture Co. nördlich von {area:382}. Feuere in Sichtweite des Turms zweimal {item:8051} ab und salutiere dann vor {npc:7233} (/salutieren), bevor er dich angreift.",
		["Forever teaches {spell:2842} through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever lehrt {spell:2842} über diese Questreihe, nicht beim Lehrer; das Rezept für {item:7676} gibt es dazu.",
		["Stay stealthed. {npc:7287} carries the tower key; Gallywix (elite) and his lockbox are at the top of the tower. Kill two each of the drones, patrollers and lookouts around it."] = "Bleib verstohlen. {npc:7287} trägt den Turmschlüssel; Gallywix (Elite) und seine Schließkassette sind oben im Turm. Töte je zwei Drohnen, Patrouillen und Ausgucke der Venture Co. rund um den Turm.",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and ride south through {zone:1421} to {area:272} in {area:287}. {npc:2391} stands in {area:272}; wait beside him while he brews the cure."] = "Nimm den Zeppelin von {zone:1454} nach {zone:1458} und reite nach Süden durch den {zone:1421} nach {area:272} in {area:287}. {npc:2391} steht in {area:272}; warte neben ihm, während er das Heilmittel braut.",
		["Wait for the cure"] = "Warte auf das Heilmittel",
		["{item:8051}, twice, in sight of the tower"] = "{item:8051}, zweimal, in Sichtweite des Turms",
		["{item:8074}: {npc:7288} (elite)"] = "{item:8074}: {npc:7288} (Elite)",
		["{quest:2458}: keep the {item:8051}"] = "{quest:2458}: Behalte {item:8051}",
		["{spell:2842} (Horde)"] = "{spell:2842} (Horde)",
} end)()
t.guides["forever/class/rogue/ravenholdt"] = (function() return {
		["At 24 an {item:17126} from {npc:13936} starts this; the data gives it to you through {npc:332} or {npc:918} in {zone:1453}, or Gest or Ormok in {zone:1454}. The quest hands you the {item:17125} for {npc:6707}."] = "Auf Stufe 24 startet ein {item:17126} von {npc:13936} das Ganze; laut Daten erhältst du ihn über {npc:332} oder {npc:918} in {zone:1453} oder Gest oder Ormok in {zone:1454}. Die Quest gibt dir das {item:17125} für {npc:6707}.",
		["At 36, {npc:13085} sends you after Barton's scouting report. Barton leads a Syndicate party at {area:280}, in the east of the {zone:1416}: pick his pocket, do not kill him."] = "Auf Stufe 36 schickt dich {npc:13085} nach Bartons Erkundungsbericht. Barton führt einen Trupp des Syndikats in {area:280} im Osten des {zone:1416}: Bestiehl ihn, töte ihn nicht.",
		["Back to {npc:13085}"] = "Zurück zu {npc:13085}",
		["Horde fly to {area:272}, Alliance to {area:271}. The manor hides in the hills east of {area:272}, up a path into the {zone:1416}; the Rite of Cunning is passing its way in."] = "Horde fliegt nach {area:272}, Allianz nach {area:271}. Das Anwesen versteckt sich in den Hügeln östlich von {area:272}, einen Pfad hinauf ins {zone:1416}; der Rite of Cunning führt dich hinein.",
		["Opens {area:3486}, the hidden rogue house in the Alterac hills, and its first jobs."] = "Öffnet {area:3486}, das versteckte Schurkenhaus in den Hügeln von Alterac, und seine ersten Aufträge.",
		["Rite of Cunning"] = "Rite of Cunning",
		["The {item:17126}"] = "Der {item:17126}",
		["{item:275482}: pickpocket Barton"] = "{item:275482}: Barton bestehlen",
		["{npc:13936} reputation"] = "Ruf bei {npc:13936}",
		["{npc:266216} is inside {area:275}, the Syndicate fortress in eastern {area:287}, south of the manor. Quick and quiet, says {npc:13085}."] = "{npc:266216} ist in {area:275}, der Festung des Syndikats im Osten von {area:287}, südlich des Anwesens. Schnell und leise, sagt {npc:13085}.",
		["{npc:6766}: {quest:6701}, repeatable"] = "{npc:6766}: {quest:6701}, wiederholbar",
} end)()
t.guides["forever/class/rogue/the-azure-key"] = (function() return {
		["Alliance fly to {area:3137}, Horde to {area:1237}. The Timbermaw Shamans in {zone:1447}'s northern hills drop the bag, about one in thirty."] = "Allianz fliegt nach {area:3137}, Horde nach {area:1237}. Die Schamanen der Holzschlundfeste in den nördlichen Hügeln von {zone:1447} lassen die Tasche fallen, etwa eine von dreißig.",
		["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "Auf Stufe 50 hat {npc:3328} in der {object:172960} sie; ebenso {npc:4583} im {object:36073} von {zone:1458}.",
		["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} and Fenthwick in {zone:1455}."] = "Auf Stufe 50 hat {npc:918} in {object:2100} in {zone:1453} sie; ebenso Syurna in {zone:1457} sowie {npc:5165} und Fenthwick in {zone:1455}.",
		["Back to Xylem"] = "Zurück zu Xylem",
		["Lord Ravenholdt"] = "Lord Ravenholdt",
		["Morphaz in the {area:1417}"] = "Morphaz im {area:1417}",
		["Morphaz, a green drake, is an elite boss deep in the {area:1417}, a level 50 dungeon: bring a group of five. The temple stands in the {area:74}; swim down to the entrance. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on."] = "Morphaz, ein grüner Drache, ist ein Elite-Boss tief im {area:1417}, einem Dungeon der Stufe 50: Bring eine Gruppe von fünf mit. Der Tempel steht im {area:74}; schwimm hinab zum Eingang. Horde: Flieg nach {area:75}; Allianz: Flieg nach {area:1438} und reite weiter.",
		["Ravenholdt reputation"] = "Ruf bei Ravenholdt",
		["Ravenholdt reputation and experience at 50; Forever removed the Classic item choice."] = "Ruf bei Ravenholdt und Erfahrung auf Stufe 50; Forever hat die Gegenstandsauswahl aus Classic entfernt.",
		["The Forest Oozes of southern {zone:1447} drop the fragments."] = "Die Waldbrühschlammer im südlichen {zone:1447} lassen die Fragmente fallen.",
		["{area:3486} hides in the hills east of {area:272}, up a path into the {zone:1416}. Horde fly to {area:272}, Alliance to {area:271}."] = "{area:3486} versteckt sich in den Hügeln östlich von {area:272}, einen Pfad hinauf ins {zone:1416}. Horde fliegt nach {area:272}, Allianz nach {area:271}.",
		["{item:20022}: Morphaz, inside the temple"] = "{item:20022}: Morphaz, im Tempel",
		["{npc:6768}: no item choices in Forever"] = "{npc:6768}: In Forever keine Gegenstandsauswahl",
		["{quest:8233} (Alliance)"] = "{quest:8233} (Allianz)",
		["{quest:8233} (Horde)"] = "{quest:8233} (Horde)",
} end)()
t.guides["forever/class/rogue/the-eye-of-bhossca"] = (function() return {
		["Back to the dead drop"] = "Zurück zum toten Briefkasten",
		["C's dead drop"] = "Der tote Briefkasten von C",
		["Find the Eye of Bhossca inside the {area:796}."] = "Finde das Auge von Bhossca im Gebiet {area:796}.",
		["Place the eye in the {object:410369} near Pyrewood. C's payment is the second Eye of Bhossca quest at the same chest."] = "Leg das Auge in den {object:410369} nahe Pyrewood. Die Bezahlung von C ist die zweite Quest „Das Auge von Bhossca“ an derselben Truhe.",
		["The monastery stands in the far north-east of {zone:1420}. Go in alone; C advises a disguise from the monastery's grounds before you enter."] = "Das Kloster steht im äußersten Nordosten von {zone:1420}. Geh allein hinein; C rät dir, dich vor dem Betreten auf dem Klostergelände zu verkleiden.",
		["The {area:796}"] = "{area:796}",
		["The {item:277246}, C's payment for a solo job inside the {area:796}."] = "Die {item:277246}, die Bezahlung von C für einen Soloauftrag im Gebiet {area:796}.",
		["The {object:410369} is a chest near {area:204} in southern Silverpine, just south of {area:236}. C's next note waits there once you are 25."] = "Der {object:410369} ist eine Truhe nahe {area:204} im Süden von Silberwald, direkt südlich von {area:236}. Die nächste Nachricht von C wartet dort, sobald du Stufe 25 bist.",
} end)()
t.guides["forever/class/rogue/the-horn-of-xelthos"] = (function() return {
		["Back to the dead drop"] = "Zurück zum toten Briefkasten",
		["C's dead drop"] = "Cs toter Briefkasten",
		["Go in alone. The {item:210186} gets you past the courtyard gate; the data does not say where in the keep the horn lies."] = "Geh allein hinein. {item:210186} bringt dich durch das Tor zum Innenhof; die Daten verraten nicht, wo in der Burg das Horn liegt.",
		["Place the horn in the {object:410369} near Pyrewood. C's payment is the second {item:210183} quest at the same chest."] = "Leg das Horn in {object:410369} nahe Pyrewood. Cs Bezahlung ist die zweite Quest {item:210183} an derselben Truhe.",
		["The {item:277210}, C's payment for a solo job inside {area:236}."] = "{item:277210}, Cs Bezahlung für einen Soloauftrag in {area:236}.",
		["The {object:410369} is a chest near {area:204} in southern Silverpine, just south of {area:236}. Read C's note."] = "{object:410369} ist eine Truhe nahe {area:204} im Süden des Silberwalds, direkt südlich von {area:236}. Lies Cs Notiz.",
		["{item:210183}, inside {area:236}"] = "{item:210183}, in {area:236}",
		["{npc:4086}, a goblin friendly to both factions, stands among the Venture Co. in the {area:461}, east Stonetalon. Horde fly to {area:460}; Alliance to {area:467}. He wants a {item:210187} before he hands over explosives: the Venture Co. Loggers around him carry them."] = "{npc:4086}, ein Goblin, der beiden Fraktionen freundlich gesinnt ist, steht zwischen der Venture Co. in {area:461} im Osten des Steinkrallengebirges. Horde fliegt nach {area:460}, Allianz nach {area:467}. Er will {item:210187}, bevor er Sprengstoff herausgibt: Die Holzarbeiter der Venture Co. um ihn herum tragen sie bei sich.",
} end)()
t.guides["forever/class/shaman/call-of-air-alliance"] = (function() return {
		["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}."] = "Auf Stufe 30 schickt dich {npc:258098}, der Schamanenlehrer in {zone:1455}, zu {npc:259023} im {zone:1417}.",
		["The Lost Ones in the north of the {zone:1435} carry the Twisted Earth Totems."] = "Die Verlorenen im Norden der {zone:1435} tragen die Verdrehten Erdtotems.",
		["The Maraudine centaurs of western {zone:1443} carry the Twisted Air Totems."] = "Die Zentauren der Maraudine im westlichen {zone:1443} tragen die Verdrehten Lufttotems.",
		["The Mirefin murlocs of northern {zone:1445} carry the Twisted Water Totems."] = "Die Murlocs der Schlammflossen in den nördlichen {zone:1445} tragen die Verdrehten Wassertotems.",
		["The Stonevault troggs in the south of the {zone:1418} carry the Twisted Fire Totems."] = "Die Steingrufttroggs im Süden des {zone:1418} tragen die Verdrehten Feuertotems.",
		["The steam pools"] = "Die Dampfbecken",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "Das {item:5178}, mit dem du Lufttotems aufstellst, dann eine Waffe deiner Wahl auf Stufe 40.",
		["Twisted Air Totems"] = "Verdrehte Lufttotems",
		["Twisted Earth Totems"] = "Verdrehte Erdtotems",
		["Twisted Fire Totems"] = "Verdrehte Feuertotems",
		["Twisted Water Totems"] = "Verdrehte Wassertotems",
		["{area:1717} is a dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} is its last boss. Bring a group."] = "{area:1717} ist ein Dungeon am Südrand von {zone:1413} (der Pfeil zeigt auf den Eingang); {npc:4421} ist der letzte Boss. Bring eine Gruppe mit.",
		["{item:212792}, from the {npc:216474}"] = "{item:212792}, vom {npc:216474}",
		["{item:274463}, from {npc:4421}"] = "{item:274463}, von {npc:4421}",
		["{npc:259023} camps in the northern hills of {zone:1417}."] = "{npc:259023} lagert in den nördlichen Hügeln des {zone:1417}.",
		["{npc:259023} hands you the {item:268582}: place them at the steam pools of {zone:1441} and defeat the {npc:216474} they call. {quest:96135} is an elite quest: grouping up is advised."] = "{npc:259023} gibt dir die {item:268582}: Stell sie an den Dampfbecken von {zone:1441} auf und besiege den {npc:216474}, den sie rufen. {quest:96135} ist eine Elite-Quest: Eine Gruppe wird empfohlen.",
		["{npc:259023}: your {item:5178}"] = "{npc:259023}: dein {item:5178}",
		["{npc:6176} camps in the east of {zone:1416}, north-east of {area:272}."] = "{npc:6176} lagert im Osten des {zone:1416}, nordöstlich von {area:272}.",
		["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}: {item:280696} und deine Waffe",
		["{quest:94789} and the Tempest's Weapons (Alliance)"] = "{quest:94789} und die Waffen des Sturms (Allianz)",
} end)()
t.guides["forever/class/shaman/call-of-air-horde"] = (function() return {
		["At 30 {npc:5892} in the {object:172957} sends you to {npc:5905} in {zone:1441}."] = "Mit 30 schickt dich {npc:5892} im {object:172957} zu {npc:5905} in {zone:1441}.",
