		["Helboars"] = "Hölleneber",
		["Shadowsworn camps"] = "Lager der Schattenanbeter",
		["The Helboars roam the north of the {zone:1419}, south of the {npc:10996}."] = "Die Hölleneber streifen durch den Norden von {zone:1419}, südlich von {npc:10996}.",
		["The Shadowsworn cultists hold the east of the {zone:1419}."] = "Die Kultisten der Schattenanbeter halten den Osten von {zone:1419}.",
		["The {area:1417}"] = "{area:1417}",
		["The {area:1417} lies under the {area:74} in the east of the {zone:1435}. Each of the six Atal'ai trolls on the balcony drops a voodoo feather: Gasher or {npc:5716} the amber, Hukku or Mijan the blue, Zolo or Loro the green. The {area:1417} is a dungeon and the trolls are elite: grouping up is advised."] = "{area:1417} liegt unter {area:74} im Osten von {zone:1435}. Jeder der sechs Trolle der Atal'ai auf dem Balkon lässt eine Voodoofeder fallen: Schlitzer oder {npc:5716} die bernsteinfarbene, Hukku oder Mijan die blaue, Zolo oder Loro die grüne. {area:1417} ist ein Dungeon und die Trolle sind Elite: Eine Gruppe wird empfohlen.",
		["The {npc:7572}"] = "{npc:7572}",
		["The {npc:7572} stands in the south-west of the {zone:1435}, at the entrance to the {zone:1419}."] = "{npc:7572} steht im Südwesten von {zone:1435}, am Eingang zu {zone:1419}.",
} end)()
