		["Leave {zone:1426} east through the gate tunnel; it opens into {zone:1432} at {area:925}."] = "Verlass {zone:1426} nach Osten durch den Tortunnel; er öffnet sich bei {area:925} nach {zone:1432}.",
		["Redridge starts at {area:1002}, where the roads from {zone:1429} and {zone:1431} meet."] = "Das Rotkammgebirge beginnt bei {area:1002}, wo sich die Straßen aus {zone:1429} und {zone:1431} treffen.",
		["Silverpine's road north leads into {zone:1420}. {area:159}, {area:154} and the {zone:1458} ruins are Horde ground."] = "Die Straße des Silberwalds führt nach Norden nach {zone:1420}. {area:159}, {area:154} und die Ruinen von {zone:1458} sind Hordegebiet.",
		["Take the {area:2257} from {zone:1453}'s {object:28027} to {zone:1455} (or fly to {zone:1455}), then leave the city through its gates."] = "Nimm die Bahn ({area:2257}) vom {object:28027} in {zone:1453} nach {zone:1455} (oder flieg nach {zone:1455}) und verlass die Stadt durch ihre Tore.",
		["The {area:836} pass in south-eastern {zone:1437} leads down into {zone:1432} by {area:925}."] = "Der Pass {area:836} im Südosten des {zone:1437} führt bei {area:925} hinunter nach {zone:1432}.",
		["Walk east from {area:287} into the {zone:1417} (level 30+ creatures off the road), south to the {area:881} bridge, and across it into the {zone:1437}. {area:150} is an Alliance town."] = "Geh von {area:287} nach Osten ins {zone:1417} (abseits der Straße Kreaturen ab Stufe 30), nach Süden zur Brücke {area:881} und über sie ins {zone:1437}. {area:150} ist ein Ort der Allianz.",
		["any one of these names counts"] = "jeder dieser Namen zählt",
		["the discovery triggers at the {area:1038}: do not go into {area:1037} itself"] = "die Entdeckung löst an den {area:1038} aus: Geh nicht nach {area:1037} selbst hinein",
		["{area:154} opens onto {zone:1420}; {area:159} is east along the road. Orcs, trolls and tauren arrive at the zeppelin tower by the {zone:1458}."] = "{area:154} öffnet sich nach {zone:1420}; {area:159} liegt östlich an der Straße. Orcs, Trolle und Tauren kommen am Zeppelinturm bei {zone:1458} an.",
		["{area:9} opens onto {zone:1429}; {area:87} is south down the road."] = "{area:9} öffnet sich nach {zone:1429}; {area:87} liegt südlich die Straße hinunter.",
		["{zone:1421} is south of {zone:1420}: follow the road south from {area:159}."] = "{zone:1421} liegt südlich von {zone:1420}: Folge der Straße von {area:159} nach Süden.",
		["{zone:1429} is north of {zone:1436} and {zone:1431}. {area:87}, {area:9} and {zone:1453}'s gates are Alliance ground with guards."] = "Der {zone:1429} liegt nördlich von {zone:1436} und {zone:1431}. {area:87}, {area:9} und die Tore von {zone:1453} sind Allianzgebiet mit Wachen.",
		["{zone:1431} is east of {zone:1436} and south of {zone:1429}. Its road runs east to {area:42}."] = "{zone:1431} liegt östlich von {zone:1436} und südlich von {zone:1429}. Die Straße führt nach Osten nach {area:42}.",
		["{zone:1436} borders {zone:1429} to the west: follow the road out past the {area:120}."] = "{zone:1436} grenzt im Westen an {zone:1429}: Folge der Straße hinaus an der {area:120} vorbei.",
		["{zone:1436} borders {zone:1431} to the west. {area:108} is an Alliance town."] = "{zone:1436} grenzt im Westen an den {zone:1431}. {area:108} ist ein Ort der Allianz.",
} end)()
