		["19 areas to discover here, levels 42-55."] = "Hier gibt es 19 Gebiete zu entdecken, Stufe 42-55.",
		["7 areas to discover here, level 55."] = "Hier gibt es 7 Gebiete zu entdecken, Stufe 55.",
		["7 areas to discover here, levels 48-55."] = "Hier gibt es 7 Gebiete zu entdecken, Stufe 48-55.",
		["9 areas to discover here."] = "Hier gibt es 9 Gebiete zu entdecken.",
		["Alliance town: Horde characters only need to touch its edge (guards)"] = "Allianzort: Hordencharaktere müssen nur den Rand berühren (Wachen)",
		["Exploration: {zone:1414} 45-60"] = "Erkundung: {zone:1414} 45-60",
		["Exploring the entire world map on one character is a Forever Legacy Challenge (1 account-wide Legacy Point)."] = "Die ganze Weltkarte mit einem Charakter zu erkunden ist eine Forever-Vermächtnisherausforderung (1 accountweiter Vermächtnispunkt).",
		["Flight path here: {area:1237} (Kroum)."] = "Flugroute hier: {area:1237} (Kroum).",
		["Flight path here: {area:1997} (Brakkar)."] = "Flugroute hier: {area:1997} (Brakkar).",
		["Flight path here: {area:1998} (Mishellena)."] = "Flugroute hier: {area:1998} (Mishellena).",
		["Flight path here: {area:2255} (Maethrya)."] = "Flugroute hier: {area:2255} (Maethrya).",
		["Flight path here: {area:2255} (Yugrek)."] = "Flugroute hier: {area:2255} (Yugrek).",
		["Flight path here: {area:3137} (Jarrodenus)."] = "Flugroute hier: {area:3137} (Jarrodenus).",
		["Flight path here: {area:3425} ({npc:15177})."] = "Flugroute hier: {area:3425} ({npc:15177}).",
		["Flight path here: {area:3425} ({npc:15178})."] = "Flugroute hier: {area:3425} ({npc:15178}).",
		["Flight path here: {area:541} (Gryfe)."] = "Flugroute hier: {area:541} (Gryfe).",
		["Flight path here: {area:976} ({npc:7823})."] = "Flugroute hier: {area:976} ({npc:7823}).",
		["Flight path here: {area:976} ({npc:7824})."] = "Flugroute hier: {area:976} ({npc:7824}).",
		["Flight path here: {zone:1450} (Faustron)."] = "Flugroute hier: {zone:1450} (Faustron).",
		["Flight path here: {zone:1450} (Sindrayl)."] = "Flugroute hier: {zone:1450} (Sindrayl).",
		["Fly to {area:1237} if you have it, otherwise to {area:431}, and walk east out of {zone:1440} into {zone:1447}."] = "Flieg nach {area:1237}, falls du die Route hast, sonst zum {area:431}, und lauf nach Osten aus {zone:1440} hinaus nach {zone:1447}.",
		["Fly to {area:3137} if you have it, otherwise to {area:415}, and walk east out of {zone:1440} into {zone:1447}."] = "Flieg nach {area:3137}, falls du die Route hast, sonst nach {area:415}, und lauf nach Osten aus {zone:1440} hinaus nach {zone:1447}.",
		["From western {zone:1446} take the path down into {zone:1449}. {area:541} in the north is a neutral camp."] = "Nimm vom westlichen {zone:1446} den Pfad hinab in den {zone:1449}. {area:541} im Norden ist ein neutrales Lager.",
		["Horde town: Alliance characters only need to touch its edge (guards)"] = "Hordenort: Allianzcharaktere müssen nur den Rand berühren (Wachen)",
		["Starts in {zone:1446}, south of {zone:1445}. The last area of this guide completes the {zone:1414} map. 20 areas to discover here, levels 40-50."] = "Beginnt in {zone:1446}, südlich der {zone:1445}. Das letzte Gebiet dieses Guides vervollständigt die Karte von {zone:1414}. Hier gibt es 20 Gebiete zu entdecken, Stufe 40-50.",
		["Take the {area:1769} tunnel in northern {zone:1448} through to {zone:1450} (druids: {spell:18960}). {area:2361} is neutral."] = "Nimm den Tunnel der {area:1769} im nördlichen {zone:1448} hindurch nach {zone:1450} (Druiden: {spell:18960}). {area:2361} ist neutral.",
		["The other exit of the {area:1769} tunnel leads into {zone:1452}. {area:2255} is a neutral goblin town with flight masters for both factions."] = "Der andere Ausgang des Tunnels der {area:1769} führt nach {zone:1452}. {area:2255} ist eine neutrale Goblinstadt mit Flugmeistern für beide Fraktionen.",
		["any one of these names counts"] = "jeder dieser Namen zählt",
		["{zone:1446} is south of {zone:1445} and {zone:1441}. {area:976} is a neutral goblin town."] = "{zone:1446} liegt südlich der {zone:1445} und von {zone:1441}. {area:976} ist eine neutrale Goblinstadt.",
		["{zone:1448} is north of {zone:1440}."] = "Der {zone:1448} liegt nördlich von {zone:1440}.",
		["{zone:1451} is west of {zone:1449}. {area:3425} is neutral."] = "{zone:1451} liegt westlich des {zone:1449}. {area:3425} ist neutral.",
		["{zone:2482} is reached from {zone:1452} through {area:2256} in the south. It is Forever's endgame leveling zone."] = "{zone:2482} erreichst du von {zone:1452} aus durch die {area:2256} im Süden. Es ist das Endgame-Levelgebiet von Forever.",
} end)()
t.guides["forever/exploration/zephras-isle"] = (function() return {
		["Exploration: {zone:2521}"] = "Erkundung: {zone:2521}",
		["Exploring the entire world map on one character is a Forever Legacy Challenge (1 account-wide Legacy Point)."] = "Die ganze Weltkarte mit einem Charakter zu erkunden ist eine Forever-Vermächtnisherausforderung (1 accountweiter Vermächtnispunkt).",
		["Skyborne start here. Everyone else takes a skyboat, about every five minutes; either faction may take either one."] = "Himmelsgeborene starten hier. Alle anderen nehmen ein Himmelsboot, etwa alle fünf Minuten; jede Fraktion darf jedes nehmen.",
		["The skyboat leaves the cliffs south of {area:17045}, north of {zone:1456} (another flies from {area:279})."] = "Das Himmelsboot legt an den Klippen südlich des {area:17045} ab, nördlich von {zone:1456} (ein weiteres fliegt von {area:279}).",
		["The skyboat leaves the north side of {area:279} in the {zone:1416} (another flies from north of {zone:1456})."] = "Das Himmelsboot legt an der Nordseite von {area:279} im {zone:1416} ab (ein weiteres fliegt nördlich von {zone:1456}).",
		["any one of these names counts"] = "jeder dieser Namen zählt",
		["{zone:2521} is the Skyborne starting island, a world of its own in {area:17221}; anyone may visit, and its map counts towards exploring the world. 20 areas to discover here, levels 3-12."] = "{zone:2521} ist die Startinsel der Himmelsgeborenen, eine eigene Welt in {area:17221}; jeder kann sie besuchen, und ihre Karte zählt zur Erkundung der Welt. Hier gibt es 20 Gebiete zu entdecken, Stufe 3-12.",
} end)()
t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Back down the beach, past the pirate camp: the crate of boots and the fragile crate with the lens sit at its south end."] = "Zurück den Strand hinunter, am Piratenlager vorbei: Die Kiste mit Stiefeln und die zerbrechliche Kiste mit der Linse stehen an seinem Südende.",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "Zurück zum Lager der Grimmhauer. Geomanten und Verteidiger halten die östliche Hälfte; {npc:3438} läuft zwischen ihnen herum.",
		["Back west along the road."] = "Die Straße zurück nach Westen.",
		["Burning Blade Cultists hold {area:1898} in northern {zone:1411}; they drop the {item:6652}. The {item:5026} comes from the Razormane on your next visit to their camp."] = "Kultisten der Burning Blade halten {area:1898} im Norden von {zone:1411}; sie lassen {item:6652} fallen. {item:5026} bekommst du bei deinem nächsten Besuch im Lager der Grimmhauer.",
		["East to the {area:1703}; {npc:9316} stands at the camp just south of it."] = "Nach Osten zum {area:1703}; {npc:9316} steht im Lager gleich südlich davon.",
		["East to {area:392}, on the coast."] = "Nach Osten nach {area:392} an der Küste.",
		["Follow the road east to the outpost above the {area:814}."] = "Folge der Straße nach Osten zum Außenposten über dem {area:814}.",
		["Follow the road south-east to {area:392} on the coast."] = "Folge der Straße nach Südosten nach {area:392} an der Küste.",
		["Keep it: {quest:3923} stands outside {zone:1454}; a later guide hands it in"] = "Behalte sie: {quest:3923} steht vor {zone:1454}; ein späterer Guide gibt sie ab",
		["Kolkar Wranglers and Stormers hold the camps south of {npc:3389}."] = "Zänker und Sturmruferinnen der Kolkar halten die Lager südlich von {npc:3389}.",
		["Kolkar camps"] = "Lager der Kolkar",
		["Oasis Snapjaws crawl around {area:387}, south-west of the {area:380}, and around the {area:388}."] = "Oasenschnappkiefer kriechen um {area:387}, südwestlich von {area:380}, und um {area:388}.",
		["Plainstriders and Sunscale raptors roam the plains all around the {area:380}, thickest to the north."] = "Ebenenschreiter und Raptoren der Bluthorn streifen überall um {area:380} über die Ebenen, am dichtesten im Norden.",
		["Plainstriders and raptors"] = "Ebenenschreiter und Raptoren",
		["Raptor nests"] = "Raptornester",
		["Razormane camp"] = "Lager der Grimmhauer",
		["South to {npc:3389}'s watch post on the Kolkar border."] = "Nach Süden zu {npc:3389}s Wachposten an der Grenze zu den Kolkar.",
		["South-east of the {area:380}. Test the seeds at the bubbling fissure on the oasis' east bank."] = "Südöstlich von {area:380}. Teste die Samen an der blubbernden Spalte am Ostufer der Oase.",
		["Southsea beach"] = "Strand der Südmeerfreibeuter",
		["The Savannah Prowlers hunt the plains between town and the Razormane camp to the east. In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end."] = "Die Savannenstreuner jagen auf den Ebenen zwischen dem Ort und dem Lager der Grimmhauer im Osten. Im Lager halten Wassersucher und Dornenwirker die westliche Hälfte, Jäger die Mitte; die Vorratskisten stehen am östlichen Ende.",
		["The Witchwing Slayers hold the western {area:383}; they wear the rings."] = "Die Töterinnen der Hexenschwingen halten den Westen von {area:383}; sie tragen die Ringe.",
		["The pirates camp on the beach south of {area:392}. The piles of complicated parts lie in the sand among them."] = "Die Piraten lagern am Strand südlich von {area:392}. Die Haufen komplizierter Teile liegen zwischen ihnen im Sand.",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers."] = "Die Teiche liegen gleich nördlich von {npc:3389}. Geh ins Wasser, um sie zu erkunden; die Potenten Pilze für Helbrim wachsen drumherum. Töte jeden Kolkar auf dem Weg für Armschienen.",
		["The three nests sit together in the {area:1697} south-west of the oasis; Sunscale Scytheclaws guard them."] = "Die drei Nester liegen zusammen in {area:1697} südwestlich der Oase; Bluthornsensenklauen bewachen sie.",
		["The tool buckets with the slugs lie around the Venture Co. drill site in the {area:382}, east of {npc:9316}."] = "Die Werkzeugkisten mit den Patronen liegen um die Bohrstelle der Venture Co. in {area:382}, östlich von {npc:9316}.",
		["The {object:4141} stands at the Venture Co. research site west of the {area:382}. Close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471} beside it."] = "{object:4141} steht bei der Forschungsstätte der Venture Co. westlich von {area:382}. Schließ die drei Ventile um den Bohrer, benutze die Konsole erneut und nimm dann {item:5089} von {npc:3471} daneben.",
		["Thunder Lizards and Lightning Hides graze just across the bridge below {area:379}."] = "Donnerechsen und Blitzechsen grasen gleich jenseits der Brücke unterhalb von {area:379}.",
		["Thunder lizards across the river"] = "Donnerechsen jenseits des Flusses",
		["Walk back south to the {area:380}. The next guide starts here and takes you to {zone:1454} and the zeppelin to {zone:1420}."] = "Geh zurück nach Süden nach {area:380}. Der nächste Guide beginnt hier und bringt dich nach {zone:1454} und zum Zeppelin nach {zone:1420}.",
		["Walk back west along the road to the {area:380}."] = "Geh die Straße zurück nach Westen nach {area:380}.",
		["West to the {area:383}. The Witchwing harpies nest all over them; any of them can drop a talon. {quest:819} lies in their hills."] = "Nach Westen in {area:383}. Die Harpyien der Hexenschwingen nisten überall dort; jede kann eine Klaue fallen lassen. {quest:819} liegt in ihren Hügeln.",
		["Zhevra"] = "Zhevras",
		["Zhevra Runners graze north and east of town."] = "Zhevra-Läufer grasen nördlich und östlich des Orts.",
		["{area:1898} cultists"] = "Kultisten in {area:1898}",
		["{area:380} is your base for this guide. Everyone you need stands within a few steps of the inn."] = "{area:380} ist deine Basis für diesen Guide. Alle, die du brauchst, stehen nur wenige Schritte vom Gasthaus entfernt.",
		["{npc:3442} in {area:392}: later, on the way"] = "{npc:3442} in {area:392}: später, auf dem Weg",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}: Die Konsole ist in {area:382}, später",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}: Die Harpyien kommen später, in {area:383}",
		["{npc:3615}, the wind rider master"] = "{npc:3615}, der Windreitermeister",
		["{npc:5878} camps beside the road from the {area:380} to {area:392}. The {object:58369} sits in the south of the Razormane camp just north of him."] = "{npc:5878} lagert an der Straße von {area:380} nach {area:392}. {object:58369} steht im Süden des Lagers der Grimmhauer gleich nördlich von ihm.",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900} macht aus dem Teer und dem Beutel {item:6636}. Benutze es am Kohlenbecken neben ihm, um {npc:5893} sichtbar zu machen, töte sie für {item:6655} und leg die Glut dann ins Kohlenbecken.",
		["{npc:5900} waits on the riverbank south of {area:379}, across the bridge."] = "{npc:5900} wartet am Flussufer südlich von {area:379}, jenseits der Brücke.",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907} steht auf dem Kamm nördlich des Lagers der Grimmhauer.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, dein {item:5176} und {item:263412}",
		["{quest:1492}, on the dock"] = "{quest:1492}, am Kai",
		["{quest:3301}: the {area:228} in {zone:1421}, next guide"] = "{quest:3301}: {area:228} in {zone:1421}, nächster Guide",
		["{quest:881}, a white lion, prowls the plains north of the Razormane camp."] = "{quest:881}, ein weißer Löwe, streift über die Ebenen nördlich des Lagers der Grimmhauer.",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["Cast {spell:18960}; {npc:11802} is in {area:2361}. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "Wirke {spell:18960}; {npc:11802} ist in {area:2361}. Die Schrein-Schmuckstücke liegen am Grund von {area:656} und vergehen binnen Minuten: Schwimm mit einem direkt zum {area:2362} am Nordwestufer, benutze es dort und sprich mit {npc:11799}.",
		["Fly to {area:1638}: {npc:3033} trains you on {area:1639}. Skyborne: fly back to {zone:1454} for the zeppelin afterwards."] = "Flieg nach {area:1638}: {npc:3033} bildet dich aus ({area:1639}). Himmelsgeborene: Flieg danach für den Zeppelin zurück nach {zone:1454}.",
		["Follow the lake shore south-east and swim out to {area:172}. Rot Hide gnolls cover the island; every type drops ichor. Stay out of {area:235} on its north side unless you go for the optional niche: the gnolls there are level 18-22."] = "Folge dem Seeufer nach Südosten und schwimm hinaus zur {area:172}. Gnolle der Moderfelle bevölkern die Insel; jede Art lässt Sekret fallen. Meide {area:235} auf der Nordseite, außer du willst die optionale Nische: Die Gnolle dort sind Stufe 18-22.",
		["Follow the road north out of Silverpine into {zone:1420} and east to the zeppelin towers outside the {area:153}. Take the zeppelin to {zone:1454}."] = "Folge der Straße nach Norden aus dem Silberwald nach {zone:1420} und nach Osten zu den Zeppelintürmen vor den {area:153}. Nimm den Zeppelin nach {zone:1454}.",
		["Follow the road north out of Silverpine into {zone:1420} and on to {area:159}: {npc:246152} trains Paladins there. The zeppelin towers are a short walk south down the road."] = "Folge der Straße nach Norden aus dem Silberwald nach {zone:1420} und weiter nach {area:159}: {npc:246152} bildet dort Paladine aus. Die Zeppelintürme liegen ein kurzes Stück die Straße hinunter nach Süden.",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "Folge der Straße nach Nordosten zum Haus der Yoricks bei {area:238}.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood."] = "Folge der Straße nach Süden. Die {object:1627} steht daneben, nördlich von Pyrewood.",
		["From the {area:380}, follow the road north-east to {area:1637} and walk in by the main gate. {npc:3310}, the wind rider master, stands on the tower in the {object:172982}."] = "Folge von {area:380} aus der Straße nach Nordosten bis {area:1637} und geh durch das Haupttor hinein. {npc:3310}, der Windreitermeister, steht auf dem Turm im {object:172982}.",
		["Hearth to the {area:228}"] = "Ruhestein: {area:228}",
		["Into Silverpine"] = "In den Silberwald",
		["Keep it: Thork at the {area:380}"] = "Behalte sie: Thork in {area:380}",
		["Keep it: {npc:2216} in {area:272}, a later guide"] = "Behalte sie: {npc:2216} in {area:272}, ein späterer Guide",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field."] = "Nördlich von {area:228}. {npc:1983} spukt auf dem {area:240}: Töte sie und geh dann über das Feld.",
		["Road to Silverpine"] = "Straße zum Silberwald",
		["South-east down the road to {area:233}. Protectors guard the outskirts and Mages the town; both drop pendants. Wizards and Watchers patrol the roads around it. Stay out of the middle, where {npc:2120} stands."] = "Die Straße nach Südosten hinunter nach {area:233}. Beschützer von Dalaran bewachen den Ortsrand und Magier von Dalaran den Ort; beide lassen Anhänger fallen. Hexer und Behüter von Dalaran patrouillieren auf den Straßen ringsum. Meide die Mitte, wo {npc:2120} steht.",
		["Speak with {npc:10540}, in Grommash Hold"] = "Sprich mit {npc:10540} in Grommash Hold",
		["Speak with {npc:3230}, in Grommash Hold"] = "Sprich mit {npc:3230} in Grommash Hold",
		["Swim back and follow the road west to the {area:228}."] = "Schwimm zurück und folge der Straße nach Westen bis zum Grabmal ({area:228}).",
		["The Vile Fin Lakestalkers and Oracles sit on the lake shore south of the {area:237}, east of the {area:228}."] = "Die Seepirscher und Orakel der Finsterflossen sitzen am Seeufer südlich der Fähre ({area:237}), östlich vom Grabmal ({area:228}).",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Rohrkolben und Speergras wachsen am Wasser im {object:172958}, östlich der Gasse.",
		["The zeppelin lands at the towers outside the {area:153}. Walk west along the road past the ruins and south into {zone:1421}; follow the road to the {area:228}."] = "Der Zeppelin landet an den Türmen vor den {area:153}. Geh die Straße nach Westen an den Ruinen vorbei und nach Süden in den {zone:1421}; folge der Straße bis zum Ziel {area:228}.",
		["The zeppelin towers stand just outside {zone:1454}'s main gate. Take the zeppelin to {zone:1420} (the other one goes to {object:3202})."] = "Die Zeppelintürme stehen direkt vor dem Haupttor von {zone:1454}. Nimm den Zeppelin nach {zone:1420} (der andere fliegt nach {object:3202}).",
		["The {object:1593} lies at the ferry landing on the lake shore east of the {area:228}."] = "Das {object:1593} liegt an der Fähranlegestelle am Seeufer östlich vom Grabmal ({area:228}).",
		["The {object:172960} is the canyon under the {object:172982}; {npc:3216} stands at its far end."] = "{object:172960} ist die Schlucht unter dem {object:172982}; {npc:3216} steht an ihrem hinteren Ende.",
		["The {object:177790} lies on the coast west of the {area:240}. It holds the {item:15882} for {quest:30}."] = "Die {object:177790} liegt an der Küste westlich vom {area:240}. Sie enthält den {item:15882} für {quest:30}.",
		["To {area:1637}"] = "Nach {area:1637}",
		["Walk in through the main gate. {npc:268701} stands in the {object:172982}; {object:173016} is a few steps north."] = "Geh durch das Haupttor hinein. {npc:268701} steht im {object:172982}; {object:173016} ist ein paar Schritte nördlich.",
		["Zeppelin to {zone:1420}"] = "Zeppelin nach {zone:1420}",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["Zeppelin tower"] = "Zeppelinturm",
		["grind on {npc:1909} at {area:1338}, {zone:1421}"] = "{npc:1909} grinden: {area:1338}, {zone:1421}",
		["{area:1338} shore"] = "Ufer: {area:1338}",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228} ist die Gruftstadt der Verlassenen mitten im Wald. Alle, die du brauchst, stehen um den Grufteingang; {npc:2226}, der Fledermausführer, steht gleich östlich davon.",
		["{area:233} comes later, on the southern loop"] = "{area:233} kommt später, auf der südlichen Runde",
		["{item:3317}: a rare drop from the gnolls"] = "{item:3317}: seltene Beute von den Gnollen",
		["{npc:11798} in {area:2361} flies druids there; then fly on to {zone:1454} for the zeppelin"] = "{npc:11798} in {area:2361} fliegt Druiden dorthin; flieg dann weiter nach {zone:1454} zum Zeppelin",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}, am Schrein: {area:2362}",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978} wartet nordöstlich des Hauses. Eskortiere ihn zurück zu {npc:1950}; unterwegs greifen Worgs an.",
		["{npc:2121}: {quest:516}, on the south loop"] = "{npc:2121}: {quest:516}, auf der südlichen Runde",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} bildet in {area:159} Paladine aus, ein kurzer Weg die Straße hinauf nach Norden von den Zeppelintürmen. Für den Silberwald kommst du dieselbe Straße zurück.",
		["{npc:268684} and {npc:268682} sit behind Grommash Hold in the {object:172957}; the Smooth Boulders lie around them. Train while you are in the city (Druids and Paladins have no trainer here). The next guide starts at {npc:3310}, the wind rider master in the {object:172982}."] = "{npc:268684} und {npc:268682} sitzen hinter Grommash Hold im {object:172957}; die Glatten Felsen liegen um sie herum. Trainiere, solange du in der Stadt bist (Druiden und Paladine haben hier keinen Lehrer). Der nächste Guide beginnt bei {npc:3310}, dem Windreitermeister im {object:172982}.",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348} und {npc:3347} führen den Alchemieladen in der Gasse; {npc:11046} ist nebenan.",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, in Grommash Hold",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}: {quest:93739}, eine Tour zu den Anführern der Horde",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018} steht im {object:172961} auf der Westseite der Stadt.",
		["{object:112888}, inside the keep"] = "{object:112888}, in der Burg",
		["{object:1599}, just east of the keep"] = "{object:1599}, gleich östlich der Burg",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}: {area:384}, nächster Guide",
		["{zone:1454} class quests"] = "Klassenquests in {zone:1454}",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "Hilf {npc:261366}: Bleib bei ihm, wenn {npc:261367} und die Marinesoldaten von {area:21} den Kamm heraufkommen",
		["Back to the {area:380}"] = "Zurück nach {area:380}",
		["Bael'dun fortress"] = "Festung von Bael'dun",
		["Bristleback camps"] = "Lager der Borstennacken",
		["Cast {spell:18960}. Tauren: join the two pendant halves at the {area:2362}, on the north-west shore of the lake, before you see {npc:11802} in {area:2361}."] = "Wirke {spell:18960}. Tauren: Füge die beiden Anhängerhälften beim {area:2362} am Nordwestufer des Sees zusammen, bevor du zu {npc:11802} in {area:2361} gehst.",
		["Dogran is chained up in the quilboar camp west of the road."] = "Dogran ist im Stacheleberlager westlich der Straße angekettet.",
		["Doras, the wind rider master, stands on the tower in the {object:172982}."] = "Doras, der Windreitermeister, steht auf dem Turm im {object:172982}.",
		["Down the {area:458} to {area:378} again."] = "Die {area:458} wieder hinunter zum {area:378}.",
		["East across the plains toward the coast: the stolen silver lies in a raptor nest north-west of {area:385}."] = "Nach Osten über die Ebenen Richtung Küste: Das gestohlene Silber liegt in einem Raptornest nordwestlich von {area:385}.",
		["East to the {area:382}. {npc:3439} stands inside the Venture Co. camp; {npc:3445} carries the key."] = "Nach Osten zu {area:382}. {npc:3439} steht im Lager der Venture Co.; {npc:3445} trägt den Schlüssel.",
		["Fill the {item:7766} at the quilboar watering hole"] = "Füll {item:7766} am Wasserloch der Stacheleber",
		["Fizzule runs the Venture Co. camp at the east end of the {area:382}. He attacks strangers: target him and /salute before he does."] = "Fizzule leitet das Lager der Venture Co. am Ostende von {area:382}. Er greift Fremde an: Nimm ihn ins Ziel und mach /salute, bevor er es tut.",
		["Fly back to the {area:380}. The next guide starts here and takes the road north to the {area:1703} and {zone:1440}."] = "Flieg zurück nach {area:380}. Der nächste Guide beginnt hier und nimmt die Straße nach Norden zum {area:1703} und nach {zone:1440}.",
		["Fly to {area:1637} to train your level 20 ranks. {npc:3354} is in the {object:172958}, {npc:5892} in the {object:172957}."] = "Flieg nach {area:1637}, um deine Ränge der Stufe 20 zu trainieren. {npc:3354} ist im {object:172958}, {npc:5892} im {object:172957}.",
		["Fly to {area:1637} to train."] = "Flieg zum Trainieren nach {area:1637}.",
		["Fly to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}."] = "Flieg nach {area:1638} und trainiere deine Ränge der Stufe 20: {npc:3033} ist auf der {area:1639}.",
		["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "Flieg zum Trainieren nach {area:1638}: {npc:3033} ist auf der {area:1639}.",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Follow the {area:458} south to {area:378}."] = "Folge der {area:458} nach Süden zum {area:378}.",
		["He gives you the {item:15826}"] = "Er gibt dir {item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "Als Nächstes bietet er {quest:1838} an (1838, Stufe 30): Sie erfordert {area:1717} und schickt dich durch ganz Kalimdor und die Östlichen Königreiche. Der Kriegerklassen-Guide {quest:1838} deckt sie ab.",
		["Hearth to the {area:380}"] = "Ruhestein nach {area:380}",
		["Keep it: the {object:107045} is beside {area:272}"] = "Behalte sie: {object:107045} ist neben {area:272}",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "Behalte sie: {npc:12696} in {zone:1440}, nächster Guide",
		["Keep it: {npc:5875} in {zone:1454}, at the end of this guide"] = "Behalte sie: {npc:5875} in {zone:1454}, am Ende dieses Guides",
		["Level 20"] = "Stufe 20",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "Nach Norden zu {area:383}. {npc:3682} lagert unterhalb der Hügel; {npc:261366}, der Einsiedler auf dem Kamm hinter ihm, hat erst Arbeit für dich, wenn {npc:3682} dich hinaufschickt.",
		["On the way back down the {area:458} to {area:378}: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry {item:277277}. Hand them to {npc:3432} on your last {area:380} stop."] = "Auf dem Weg die {area:458} zurück hinunter zum {area:378}: Die Räuber der Grimmhauer zwischen den Lagern der Borstennacken, zu beiden Seiten der Straße nördlich des Lagers, tragen {item:277277}. Gib sie bei deinem letzten Halt in {area:380} an {npc:3432}.",
		["Ride north from the {area:380} to {area:384} and fill the {item:15842} at the {object:19464}, then back to {npc:3448} in the {area:380}. No {skill:182}? {npc:3490} beside him sells {item:2449}, three at a time until he restocks."] = "Reite von {area:380} nach Norden zum {area:384} und füll {item:15842} am {object:19464}, dann zurück zu {npc:3448} in {area:380}. Kein {skill:182}? {npc:3490} neben ihm verkauft {item:2449}, je drei, bis er nachfüllt.",
		["Savannah Patriarchs roam the plains east of the hills, and the Sprung Traps lie among them. {quest:876} leads the Witchwing harpies in the hills to the west."] = "Savannenpatriarchen streifen über die Ebenen östlich der Hügel, und die Ausgelösten Fallen liegen zwischen ihnen. {quest:876} führt die Harpyien der Hexenschwingen in den Hügeln im Westen an.",
		["South of Camp Taurajo the Silithid Mounds dot the {area:390}; the eggs lie in them, and Silithid Swarmers come out to defend them. Silithid Harvesters are rare: if you see one, kill it for its head."] = "Südlich von Camp Taurajo verteilen sich die Silithid-Buckel über {area:390}; die Eier liegen darin, und Silithidschwärmer kommen heraus, um sie zu verteidigen. Silithidernter sind selten: Siehst du einen, töte ihn für seinen Kopf.",
		["South of Gann, the Bael'dun dwarves dig at {area:359}. Excavators and Foremen work the pit; {npc:3392} (26) carries the journal: pull him alone."] = "Südlich von Gann graben die Zwerge von Bael'dun bei {area:359}. Ausgräber und Großknechte arbeiten in der Grube; {npc:3392} (26) trägt das Tagebuch: Zieh ihn allein.",
		["Stay stealthed: {npc:7287} carries the key to the tower; Gallywix and his lockbox are at the top. Gallywix is elite: grouping up is advised."] = "Bleib verstohlen: {npc:7287} trägt den Schlüssel zum Turm; Gallywix und seine Schließkassette sind oben. Gallywix ist Elite: Such dir am besten eine Gruppe.",
		["Sunscale Scytheclaws hunt the plains south of the {area:380}, around the {area:1697}; they drop the horns. Hand them in on your next pass through {area:392}."] = "Bluthornsensenklauen jagen auf den Ebenen südlich von {area:380}, um {area:1697}; sie lassen die Hörner fallen. Gib sie ab, wenn du das nächste Mal durch {area:392} kommst.",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "Tauren: {npc:11957} wartet auf dem südlichen Hügel über der Brücke. Himmelsgeborene: {npc:272054} steht südlich der Zwillingsbrücken. Dann die Grabhügel östlich des Sees: Verlass deine Gestalt, klick die Statue am Eingang an für fünf Minuten Verstohlenheit, halte dich von den Geistern darin fern und nimm von jedem Relikt eins; {item:280680} liegt am Fuß der weißen Katzenstatue.",
		["The Bael'dun Soldiers, Riflemen and Officers guard the fortress on the east side of the dig; all three items drop from them."] = "Die Soldaten, Scharfschützen und Offiziere von Bael'dun bewachen die Festung auf der Ostseite der Grabung; alle drei Gegenstände kommen von ihnen.",
		["The Bristleback quilboar camps spread over the plains north of {area:378}, either side of the {area:458}. Every Bristleback drops a tusk; {npc:3432}'s wife lies at the north edge. Keep one {item:5075}. {quest:883}, a grey kodo, sometimes wanders here: his hoof starts a quest."] = "Die Lager der Borstennacken verteilen sich über die Ebenen nördlich vom {area:378}, zu beiden Seiten der {area:458}. Jeder Borstennacken lässt einen Hauer fallen; die Frau von {npc:3432} liegt am Nordrand. Behalte einen {item:5075}. {quest:883}, ein grauer Kodo, wandert manchmal hier: Sein Huf startet eine Quest.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "Die Vorarbeiter und Vollstrecker der Venture Co. an der Mine in der Nordostecke des Gebiets lassen {item:5097} fallen.",
		["The antennae vanish fifteen minutes after they drop, so gather them now, on the way back north: kill the Silithid Swarmers and Creepers at the {area:390}' mounds until you have five, then hearth to {area:378} straight away."] = "Die Fühler verschwinden fünfzehn Minuten nachdem sie fallen, also sammle sie jetzt, auf dem Rückweg nach Norden: Töte die Silithidschwärmer und Silithidkrabbler an den Buckeln im {area:390}, bis du fünf hast, und nimm dann sofort deinen Ruhestein zum {area:378}.",
		["The dwarves' flying machine sits on its platform inside the dig site."] = "Die Flugmaschine der Zwerge steht auf ihrer Plattform in der Grabungsstätte.",
		["The flying machine"] = "Die Flugmaschine",
		["The level-20 class quests in {zone:1454} ({npc:3354}, {npc:5892}, the Warlock and Rogue trainers) are only offered from level 20, so finish the level here before you fly. The Thunderhawk Hatchlings (18) on the plains south-west of the {area:380} and the Kolkar (14-15) at the {area:388} are the nearest mobs worth killing; you need well under a level."] = "Die Klassenquests der Stufe 20 in {zone:1454} ({npc:3354}, {npc:5892}, die Lehrer für Hexenmeister und Schurken) gibt es erst ab Stufe 20, also schließ die Stufe hier ab, bevor du fliegst. Die Donnerfalkenjungtiere (18) auf den Ebenen südwestlich von {area:380} und die Kolkar (14-15) an {area:388} sind die nächsten Gegner, die sich lohnen; dir fehlt deutlich weniger als eine Stufe.",
		["The pirates camp on the beach south of {area:392}; {npc:3467} stands at its southern end."] = "Die Piraten lagern am Strand südlich von {area:392}; {npc:3467} steht an seinem Südende.",
		["The {area:2363}"] = "{area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960} ist die Schlucht unter dem {object:172982}.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792} liegt am Nordrand von {area:382}, beim Turm der Venture Co. Darin ist {item:15883} für {quest:30}.",
		["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "Donnerfalkenwolkenkitzler kreisen über denselben Ebenen südlich des Lagers.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "Donnerköpfe grasen auf den Ebenen gleich südlich vom {area:378}. {quest:884}, eine blaue Donnerechse, streift zwischen ihnen umher: Ihr Schwanzstachel startet eine Quest.",
		["Twitching Antennae"] = "Zuckende Fühler",
		["Twitching Antennae from the silithid"] = "Zuckende Fühler von den Silithiden",
		["Venture Co. tower"] = "Turm der Venture Co.",
		["West of Gann, the Razormane hold {area:1701}. {npc:3436} is on the east side, {npc:3434} to the south, {npc:3435} at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; {npc:5859}, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. {npc:3238} lizards and Hecklefang Stalkers roam the plain between {npc:3341} and the ridge. {quest:885}, a rare red wind serpent, flies over the ridge: its feather starts a quest."] = "Westlich von {npc:3341} halten die Grimmhauer {area:1701}. {npc:3436} ist auf der Ostseite, {npc:3434} im Süden, {npc:3435} am Westende. Lok (25) und die Kriegsberserker (24-25) sind ein paar Stufen über dir; {npc:5859}, ein seltener Elite, läuft manchmal über den Kamm: Lass ihn. Pfadfinder und Schleicher lassen den Grimmhauerrückenstecher fallen, Seher den Zauberstab, Kriegsberserker den Grimmhauerkriegsschild. {npc:3238}-Echsen und Fleischreißerpirscher streifen über die Ebene zwischen Gann und dem Kamm. {quest:885}, eine seltene rote Windnatter, fliegt über dem Kamm: Ihre Feder startet eine Quest.",
		["Wizzlecrank drives his shredder out of the camp: stay with him and kill whatever attacks him. {npc:3442} takes it in {area:392}."] = "Wizzlecrank fährt seinen Schredder aus dem Lager: Bleib bei ihm und töte alles, was ihn angreift. {npc:3442} nimmt die Abgabe in {area:392} entgegen.",
		["grind on Thunderhawk Hatchlings south-west of the {area:380}"] = "grinde Donnerfalkenjungtiere südwestlich von {area:380}",
		["{area:385}, on the coast further south. The Theramore Marines and Preservers (15-16) drop the medals; {npc:3393} (20) and the two cannoneers (19) stand in the keep and on its walls, and they are why the hold waits until now."] = "{area:385}, weiter südlich an der Küste. Die Marinesoldaten und Bewahrerinnen von Theramore (15-16) lassen die Medaillen fallen; {npc:3393} (20) und die beiden Kanoniere (19) stehen in der Feste und auf ihren Mauern, und ihretwegen wartet die Feste bis jetzt.",
		["{item:15852}: Lost Barrens Kodos on the plains around the Kolkar camp"] = "{item:15852}: Verirrte Brachlandkodos auf den Ebenen um das Lager der Kolkar",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}: Benutze eine Hälfte beim {area:2362}",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{item:2449} von {npc:3490}; Kräuterkundige pflücken es auf den Ebenen",
		["{item:2449}: herbalists pick it here"] = "{item:2449}: Kräuterkundige pflücken es hier",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} in {area:2361} fliegt Druiden dorthin",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}: der Willkommensgruß von {npc:3033}",
		["{npc:12296}: use the {item:15826} on them; they roam the plains all around the {area:380}"] = "{npc:12296}: Benutze {item:15826} an ihnen; sie streifen überall um {area:380} über die Ebenen",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, oben im Baum gleich östlich von {npc:3341}",
		["{npc:209797} swims in the harbour just off {area:392}'s docks. {npc:209797} is elite: grouping up is advised."] = "{npc:209797} schwimmt im Hafen gleich vor den Docks von {area:392}. {npc:209797} ist Elite: Eine Gruppe wird empfohlen.",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{npc:2391} in {area:272} lehrt Gifte: behalte sie",
		["{npc:246344} teaches Paladins in {area:1638}. You have no flight path there yet: fly to {area:378}, ride west through {zone:1412} and up a lift, and take the flight path from {npc:2995} on the central rise."] = "{npc:246344} bildet in {area:1638} Paladine aus. Du hast dort noch keine Flugroute: Flieg zum {area:378}, reite nach Westen durch {zone:1412} und einen Aufzug hinauf und hol dir die Flugroute bei {npc:2995} auf der mittleren Anhöhe.",
		["{npc:262119} and his marines hold the wrecked caravan south of {npc:261366}."] = "{npc:262119} und seine Marinesoldaten halten die zerstörte Karawane südlich von {npc:261366}.",
		["{npc:3238}, on the plain between {npc:3341} and the ridge"] = "{npc:3238}, auf der Ebene zwischen {npc:3341} und dem Kamm",
		["{npc:3341} waits in a small camp further south, on the road toward {area:359}."] = "{npc:3341} wartet in einem kleinen Lager weiter südlich, an der Straße Richtung {area:359}.",
		["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "{npc:3389} steht am Wachposten der Kolkar gleich westlich von {area:380}.",
		["{npc:3394} stands in the Kolkar camp north-west of {npc:3389}."] = "{npc:3394} steht im Lager der Kolkar nordwestlich von {npc:3389}.",
		["{npc:3395} walks among the Kolkar at the {area:388} south-east of the {area:380}."] = "{npc:3395} läuft zwischen den Kolkar an {area:388} südöstlich von {area:380} herum.",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. Hand his head to {npc:3389} on your last {area:380} stop."] = "{npc:3396} führt die Kolkar am Westufer von {area:387} an, südlich von {npc:3389}. Gib seinen Kopf bei deinem letzten Halt in {area:380} an {npc:3389}.",
		["{npc:3401} stands in the {object:172960}. Target him and type /salute to finish {quest:2460}."] = "{npc:3401} steht in {object:172960}. Nimm ihn ins Ziel und tippe /salute, um {quest:2460} abzuschließen.",
		["{npc:3428}: the eggs are in the {area:390}, later"] = "{npc:3428}: Die Eier sind im {area:390}, später",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, oben auf dem Turm",
		["{npc:3429}. Keep it: Kadrak at the {area:1703}, next guide"] = "{npc:3429}. Behalte sie: Kadrak am {area:1703}, nächster Guide",
		["{npc:3430}, in the cage"] = "{npc:3430}, im Käfig",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{npc:3432} bietet {quest:95774} an, sobald {quest:4921} abgegeben ist",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, am Nordrand des Lagers",
		["{npc:3442}, beside the wind rider master. Keep it: {quest:1483} is in Stonetalon, later"] = "{npc:3442}, neben dem Windreitermeister. Behalte sie: {quest:1483} ist im Steinkrallengebirge, später",
		["{npc:3453}, on the dock"] = "{npc:3453}, am Kai",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465} ist in der Feste angekettet. Sprich mit ihm, um die Eskorte zu starten, und bleib dicht dran: Soldaten von Theramore greifen auf dem Weg hinaus an. Er führt dich zurück nach {area:392}.",
		["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197} lebt in {area:2539}, dem Trolldorf gleich hinter der Grenze zum Steinkrallengebirge, am Ende der Straße westlich von {npc:3389}.",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875} steht in {object:172960}. Benutze dort {item:6626} am Beschwörungskreis und besiege die Sukkubus, um sie zu binden.",
		["{npc:5878} camps beside the road east of the {area:380}."] = "{npc:5878} lagert an der Straße östlich von {area:380}.",
		["{npc:5899}, just west of {npc:3341}"] = "{npc:5899}, gleich westlich von {npc:3341}",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901} wartet auf dem Hügel südlich von {area:392}, auf deinem Weg nach Norden.",
		["{npc:5909}, a few steps away"] = "{npc:5909}, ein paar Schritte entfernt",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018} steht im {object:172961}, auf der Westseite der Stadt.",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}: {npc:4606} in {zone:1458}, zwei Guides weiter",
		["{object:3972} poster"] = "Plakat „{object:3972}“",
		["{quest:2458}: {npc:7233}, by the {area:382}"] = "{quest:2458}: {npc:7233}, bei {area:382}",
		["{quest:882}, a big Sunscale raptor, hunts the plains north of the road from {area:392} to the {area:380}."] = "{quest:882}, ein großer Raptor der Bluthorn, jagt auf den Ebenen nördlich der Straße von {area:392} nach {area:380}.",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "Zurück auf die Straße nach Süden. Wo sie nach Osten nach {area:287} abbiegt, wartet {npc:2214} am {area:285}.",
		["Back to {npc:8582}"] = "Zurück zu {npc:8582}",
		["East of Ziz, the Venture Company is clear-cutting {area:461}; one of the Operators carries the blueprints. {npc:4276} mines in the small mine on the east side: stay with him while he mines, Venture Co. thugs come for him."] = "Östlich von Ziz holzt die Venture Co. {area:461} kahl; einer der Maschinenführer trägt die Baupläne. {npc:4276} baut in der kleinen Mine auf der Ostseite ab: Bleib bei ihm, während er abbaut, Schläger der Venture Co. kommen ihn holen.",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Jeder Naga der Rächerflossen am Strand nördlich des Außenpostens lässt Köpfe fallen.",
		["Fly to {area:431} and ride south down the road to the {area:1703}."] = "Flieg nach {area:431} und reite die Straße nach Süden hinunter zum {area:1703}.",
		["Follow the road east along the river, then north-east up into the hills to {area:272}."] = "Folge der Straße nach Osten am Fluss entlang, dann nach Nordosten hinauf in die Hügel nach {area:272}.",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Folge der Straße nach Norden Richtung {area:467}. Gehörnte Renner grasen am Weg; die Blutsaftbestien, Mondlichtläufer und Siechdrachen streifen durch die Wälder unterhalb des Gipfels, und die Cenarischen Druiden halten den Hain dort.",
		["Follow the road west to {area:460}."] = "Folge der Straße nach Westen zum {area:460}.",
		["From the {area:380} follow the road north. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}. Open the {item:16783} he gives you."] = "Folge von {area:380} der Straße nach Norden. {npc:8582} steht auf dem Wachturm am {area:1703}, wo die Straße nach {zone:1440} führt. Öffne {item:16783}, das er dir gibt.",
		["Gaea Dirt Mounds"] = "Gaeaerdhügel",
		["Gaea Seeds"] = "Gaeasamenkörner",
		["If you already know the {area:272} flight path, fly there and skip to {area:272}. Otherwise fly from the {zone:1458} to the {area:228} and ride south down the road past Pyrewood. The Ravenclaw undead haunt the ruins of {area:231} east of the road in the south-east of the forest; a {npc:1973} drops the {item:271343} that leads to the {object:645153}."] = "Kennst du die Flugroute von {area:272} schon, flieg dorthin und spring weiter zu {area:272}. Sonst flieg von {zone:1458} zum {area:228} und reite die Straße nach Süden an Pyrewood vorbei. Die Untoten von Rabenklaue spuken in den Ruinen von {area:231} östlich der Straße im Südosten des Waldes; ein {npc:1973} lässt {item:271343} fallen, der zu {object:645153} führt.",
		["Keep north on the road. The {npc:12862} waits at the Warsong lumber camp, south of Splintertree."] = "Bleib auf der Straße nach Norden. {npc:12862} wartet im Holzfällerlager der Warsong, südlich von Splintertree.",
		["Naga heads"] = "Nagaköpfe",
		["On the ride west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "Auf dem Ritt nach Westen steckt {npc:267214} in einer Schlucht südlich der Hauptstraße fest, südöstlich von {area:415}. Schattenhornhirsche und Ashenvalebären streifen überall durch die Wälder drumherum.",
		["Ride back down the {area:1076} to {area:2539}."] = "Reite den {area:1076} zurück hinunter nach {area:2539}.",
		["Ride east to the {area:380} and fly to {zone:1454}. Take the zeppelin from the towers outside {zone:1454} to {zone:1420}; the {area:1497} lies below the {area:153}. The bat handler is in the {object:36078}."] = "Reite nach Osten nach {area:380} und flieg nach {zone:1454}. Nimm den Zeppelin von den Türmen vor {zone:1454} nach {zone:1420}; {area:1497} liegt unter den {area:153}. Der Fledermausführer ist im {object:36078}.",
		["Ride south to the {area:380}, then west along the road out of the {zone:1413} into Stonetalon. The troll village of {area:2539} sits at the entrance of the canyon."] = "Reite nach Süden nach {area:380}, dann auf der Straße nach Westen aus dem {zone:1413} ins Steinkrallengebirge. Das Trolldorf {area:2539} liegt am Eingang der Schlucht.",
		["Ride west along the main road across {zone:1440}, past {area:415} (Alliance: keep to the road), to the coast. {area:2897} is on the {area:414} in the north-west. Its other quests are for the next visit, at 27."] = "Reite auf der Hauptstraße nach Westen durch {zone:1440}, an {area:415} vorbei (Allianz: bleib auf der Straße), bis zur Küste. {area:2897} liegt am {area:414} im Nordwesten. Seine anderen Quests sind für den nächsten Besuch, mit 27.",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "Südwestlich vom Sonnenfels liegt das {area:465}. Pflanz die Gaeasamenkörner in die Erdhügel auf dem Talgrund; die Feuerelementare lassen {item:16312} fallen. Harpyien und Wegelagerinnen der Blutfurien nisten auf der Nordseite, Töterinnen und Wildfedern im Süden.",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "Sprich mit {npc:10181} im {object:36126}: {quest:93739}",
		["Sputtervalve in {area:392}: the next guide passes there"] = "Sputtervalve in {area:392}: Der nächste Guide kommt dort vorbei",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Steuere {npc:267214}s {npc:271181} innerhalb von vier Minuten aus der Schlucht zur Hauptstraße; bricht die Kanalisierung ab, frag {npc:267214} erneut.",
		["The Gaea Seeds lie in the grass around the southern shore of {area:464}, north of Sun Rock."] = "Die Gaeasamenkörner liegen im Gras am Südufer von {area:464}, nördlich vom Sonnenfels.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "Die Straße steigt als {area:1076} nach Norden an. {quest:1483} hat eine Hütte, wo die Straße nach Osten zum {area:461} abzweigt.",
		["The {npc:12864} patrols the road east of {area:428} toward the {area:430}."] = "{npc:12864} patrouilliert auf der Straße östlich von {area:428} Richtung {area:430}.",
		["To the {area:1497}"] = "Nach {area:1497}",
		["Use the {npc:212753} at the {object:645153} for a willing sacrifice and kill the {npc:212753} that answers. {quest:95883} is elite: grouping up is advised."] = "Benutze {npc:212753} an {object:645153} für ein freiwilliges Opfer und töte {npc:212753}, die antwortet. {quest:95883} ist Elite: Such dir am besten eine Gruppe.",
		["{area:431} is just north up the road."] = "{area:431} liegt gleich nördlich die Straße hinauf.",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}, von einem {npc:1973}",
		["{item:271350}, from the Tortured Souls among the ruins"] = "{item:271350}, von den Gequälten Seelen in den Ruinen",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}, von jeder Harpyie der Blutfurien",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}: Glitzernde Sonnensteine von den Harpyien der Blutfurien",
		["{npc:11860}: Grish is at the {object:19844}, in the next guide"] = "{npc:11860}: Grish ist am {object:19844}, im nächsten Guide",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, neben {npc:11862}",
		["{npc:11862}, up on the ledge"] = "{npc:11862}, oben auf dem Felsvorsprung",
		["{npc:12696} stands at {area:428}, the Warsong camp just north-east of Splintertree, beside the hunt board."] = "{npc:12696} steht bei {area:428}, dem Lager der Warsong gleich nordöstlich von Splintertree, neben dem Jagdbrett.",
		["{npc:12696}'s hunt targets (Ursangous, Shadumbra, Sharptalon) are for the next {zone:1440} visit, at 27."] = "{npc:12696}s Jagdziele (Ursangus, Schattumbra, Scharfkralle) sind für den nächsten Besuch in {zone:1440}, mit 27.",
		["{npc:12736} at Zoram'gar, at 27"] = "{npc:12736} in Zoram'gar, mit 27",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}: Darthalia in {area:272}",
		["{npc:271181}, on the road"] = "{npc:271181}, auf der Straße",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "{npc:4198}s nächste Quest, Ordanus, liegt auf der Allianzseite von {zone:1440}. Überspring sie.",
		["{npc:4198}, outside the gate"] = "{npc:4198}, vor dem Tor",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606} steht im {object:36070}.",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["Bears, creepers and lions"] = "Bären, Krabbler und Löwen",
		["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings; open both locks."] = "Drull und {npc:2238} sind in Gebäuden im Hof der {area:275} angekettet; öffne beide Schlösser.",
		["Drull's ball and chain"] = "Drulls Kugel und Kette",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "Füll den {item:7768} am {object:107045} neben dem Gasthaus",
		["Follow the road south to the dwarf dig site at {area:359}. {npc:3421} hides at the south edge of the dig; {object:3646} sits at the bottom of the excavation."] = "Folge der Straße nach Süden zur Ausgrabungsstätte der Zwerge bei {area:359}. {npc:3421} versteckt sich am Südrand der Grabung; {object:3646} steht ganz unten in der Ausgrabung.",
		["From {area:272} go south-east into the hills on the way to {area:275}. Rogues and Watchmen hold the camps along the way."] = "Geh von {area:272} nach Südosten in die Hügel auf dem Weg zur {area:275}. Schurken und Wachmänner des Syndikats halten die Lager unterwegs.",
		["From {zone:1454} (zeppelin from the towers outside the {zone:1458}) fly to {area:1638} and train on {area:1639}, then fly on to {area:378}."] = "Flieg von {zone:1454} (Zeppelin von den Türmen vor {zone:1458}) nach {area:1638}, trainiere im Ort {area:1639} und flieg dann weiter nach {area:378}.",
		["From {zone:1454} (zeppelin from the towers outside the {zone:1458}) fly to {area:378}."] = "Flieg von {zone:1454} (Zeppelin von den Türmen vor {zone:1458}) nach {area:378}.",
		["Hearth to {area:378} and fly to {area:392}. {quest:874} camps on the shore north of {area:392}."] = "Ruhestein nach {area:378} und flieg nach {area:392}. {quest:874} lagert am Ufer nördlich von {area:392}.",
		["Keep it: the {area:287} coast, later on the route"] = "Behalte es: die Küste von {area:287}, später auf der Route",
		["Masoj hides on the hillside above {area:290}, south of Durnholde, on the way down to the blossoms."] = "Masoj versteckt sich am Hang über {area:290}, südlich von Burg Durnholde, auf dem Weg hinunter zu den Blüten.",
		["No Gallywix yet? The Class guide Poisons (Horde) runs the chain from Shenthul again, with a group for Gallywix."] = "Noch kein Gallywix? Der Klassenguide Gifte (Horde) führt die Questreihe ab Shenthul erneut, mit einer Gruppe für Gallywix.",
		["Only if Gallywix fell in the {zone:1413} (Mission: Possible But Not Probable): {npc:2391} stands in {area:272}. Wait beside him while he brews the cure, then take your reward: Poisons."] = "Nur wenn Gallywix im {zone:1413} gefallen ist (Mission: möglich, aber nicht sehr wahrscheinlich): {npc:2391} steht in {area:272}. Warte bei ihm, während er das Heilmittel braut, und hol dir dann deine Belohnung: Gifte.",
		["Peasants and skulls"] = "Arbeiter und Schädel",
		["South-west of Bael Modan, {npc:12576} waits at the top of the {area:1718}."] = "Südwestlich von Bael Modan wartet {npc:12576} oben am Aufzug ({area:1718}).",
		["South-west of Durnholde, the {item:3502} grow on the hillsides above the river."] = "Südwestlich von Burg Durnholde wachsen die {item:3502} an den Hängen über dem Fluss.",
		["Syndicate camps"] = "Lager des Syndikats",
		["Take the zeppelin from the towers outside the {zone:1458} to {zone:1454} and train before you fly on."] = "Nimm den Zeppelin von den Türmen vor {zone:1458} nach {zone:1454} und trainiere, bevor du weiterfliegst.",
		["The Peasants work the fields south of the farmhouses. Every {area:287} human drops skulls; the Peasants drop them most often."] = "Die Arbeiter von Hillsbrad bestellen die Felder südlich der Bauernhäuser. Jeder Mensch aus {area:287} droppt Schädel; die Arbeiter am häufigsten.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "Die Höfe östlich des Orts {area:287}. {npc:232} bestellt das Feld beim nördlichen Bauernhaus, {npc:2403} das weiter südöstlich; Landarbeiter und Bauern von Hillsbrad sind überall. {npc:2451} pflegt das Feld südlich der Höfe.",
		["The smithy"] = "Die Schmiede",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "Die Schmiede steht mitten im Ort {area:287}. {npc:2404} und seine Lehrlinge arbeiten an der Esse; die {object:1736} ist daneben gestapelt. {npc:2449} läuft die Straße nördlich davon entlang.",
		["The town hall is on the west side of {area:287}. {npc:2335} (30) and {npc:2448} are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town."] = "Das Rathaus liegt auf der Westseite von {area:287}. {npc:2335} (30) und {npc:2448} sind drinnen beim Stadtverzeichnis von Hillsbrad; die Proklamation von Hillsbrad hängt daneben. Ratsherren von Hillsbrad laufen durch den Ort.",
		["The {area:288} lies south of {area:287} town. Miners work the tunnels; {npc:2305} (30) and {npc:2450} (29) are deep inside."] = "Der Ort {area:288} liegt südlich des Orts {area:287}. Minenarbeiter von Hillsbrad arbeiten in den Stollen; {npc:2305} (30) und {npc:2450} (29) sind tief drinnen.",
		["The {object:1763} poster by the inn"] = "Das Plakat {object:1763} beim Gasthaus",
		["The {quest:567} poster: its targets come up along the way"] = "Das Plakat {quest:567}: Seine Ziele triffst du unterwegs",
		["Town hall"] = "Rathaus",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "Westlich von Tarrens Mühle streifen Graubären, Waldmooskrabbler und Verhungernde Berglöwen auf dem Weg hinunter zu den Höfen durch die Hügel. Die Krabbler droppen {item:3477} selten; du brauchst nur eins.",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}, im Apothekarium",
		["{npc:2055}, in the {zone:1458}"] = "{npc:2055}, in {zone:1458}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215}: Befehle für {npc:270438}, auf dem Weg nach Burg Durnholde",
		["{npc:2230}, next to Lydon"] = "{npc:2230}, neben Lydon",
		["{npc:2238}'s ball and chain"] = "Kugel und Kette von {npc:2238}",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274} ist der Hund von {npc:232}, beim nördlichen Bauernhaus im Gebiet {area:286}.",
		["{npc:2391}: Poisons"] = "{npc:2391}: Gifte",
		["{npc:3442}, by the docks in {area:392}"] = "{npc:3442}, bei den Docks in {area:392}",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "Die Hütte von {npc:5899} steht auf dem Grat über dem Wasserloch der Stacheleber, südlich von {area:378}, auf dem Weg nach {area:359}.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}: Der blaue Wasserschlauch wird im {zone:1440} gefüllt, nächster Guide",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}: der rote Wasserschlauch aus {area:272}",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}, ein großer Dreschadon, schwimmt im seichten Wasser vor der Küste ({area:391}), östlich von {npc:3388} Skyseer.",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["Back south to the camp, then up into {area:1638} for the flight to {area:378}."] = "Zurück nach Süden zum Lager, dann hinauf nach {area:1638} für den Flug nach {area:378}.",
		["Back south-west to {area:421}. Befouled Water Elementals drift around its shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "Zurück nach Südwesten zum {area:421}. Beschmutzte Wasserelementare treiben an seinen Ufern; der Pavillon steht auf der Insel mit Blick auf den Außenposten der Allianz.",
		["Back west to Zoram'gar before heading east for good."] = "Zurück nach Westen nach Zoram'gar, bevor es endgültig nach Osten geht.",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Steig den Pfad hinauf auf den {area:2097}. {npc:10646} wird neben {npc:10896} (29) gefangen gehalten: Besiege zuerst die Wachen und {npc:10896}, befreie sie dann und beschütze sie auf dem Weg hinunter; unterwegs greifen dich Grimmtotem aus dem Hinterhalt an.",
		["East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold."] = "Östlich von Zoram'gar bevölkern die Furbolgs der Distelfelle das Dorf und die Hügel um ihre Höhle.",
		["Felmusk satyrs"] = "Satyrn der Teufelshufe",
		["Fly from {area:1638} to {area:378} and take the road south to the {area:1718} at the bottom of the {zone:1413}."] = "Flieg von {area:1638} nach {area:378} und nimm die Straße nach Süden zum Aufzug ({area:1718}) ganz im Süden des {zone:1413}s.",
		["Fly from {area:1638} to {area:378}. {npc:5899}'s hut stands on the ridge above the quilboar watering hole south of the camp, on the road to the {area:1718}."] = "Flieg von {area:1638} nach {area:378}. Die Hütte von {npc:5899} steht auf dem Kamm über dem Wasserloch der Stacheleber südlich des Lagers, an der Straße zum Aufzug ({area:1718}).",
		["Fly from {area:392} to {area:2897} on the {zone:1440} coast."] = "Flieg von {area:392} zum {area:2897} an der Küste von {zone:1440}.",
		["Fly to {area:1638} if you know the flight path. If not, fly to {area:378}, ride west into {zone:1412} past {area:222} to {area:1638} and take its flight path from {npc:2995} on the central rise."] = "Flieg nach {area:1638}, wenn du die Flugroute kennst. Wenn nicht, flieg nach {area:378}, reite nach Westen nach {zone:1412} an {area:222} vorbei bis {area:1638} und hol dir die Flugroute bei {npc:2995} auf der mittleren Anhöhe.",
		["Follow the canyon east out of the mesas onto the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Folge der Schlucht nach Osten aus den Tafelbergen hinaus auf die Salzebenen. Die Goblins und Gnome der {area:2240} sind neutral und geben beiden Fraktionen Quests.",
		["Follow the canyon west to {area:2237}."] = "Folge der Schlucht nach Westen zum {area:2237}.",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Folge der Hauptstraße nach Osten an {area:415} vorbei (Allianz: bleib auf der Straße). {npc:12678}, ein großer Grizzly, streift durch die Ruinen ({area:418}) südlich der Straße, westlich von {area:421}. Seine Pranke startet die nächste Jagdquest.",
		["Galak centaurs"] = "Zentauren der Galak",
		["Gazebo"] = "Pavillon",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "Toxinproben der Düsteranhöhe, von den Angenagten Leichnamen",
		["Grimtotem camps"] = "Lager der Grimmtotem",
		["His crate is for Stranglethorn, later on the route"] = "Seine Kiste ist fürs Schlingendorntal, später auf der Route",
		["Inside the hold, Troll Chests lie along the tunnels. {npc:12818} is held deep inside: free him and protect him all the way out, then he runs home to {area:428}."] = "In der Höhle stehen Trolltruhen entlang der Tunnel. {npc:12818} wird tief drinnen festgehalten: Befreie ihn und beschütze ihn den ganzen Weg hinaus, dann läuft er heim nach {area:428}.",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "Bleib auf der Straße nach Osten. {npc:12858} wartet südwestlich vom Holzfällerlager der Warsong. Er und seine Grunzer stürmen den {area:2360}: Lass sie die Aggro ziehen und bleib bei {npc:12858}, bis {npc:12860} tot ist.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "Töte den {npc:10720}, der für {npc:10638} kommt",
		["Naga brazier"] = "Nagakohlenpfanne",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "Nördlich des Lagers überrennen Spinnen die Grabstätte {area:17044}. Benutze den {item:273015} von {npc:264074} an den Angenagten Leichnamen; die Spinner lassen {item:273181} fallen. {npc:264082} sitzt am Nordende: Ihr {item:273658} startet {quest:96294}.",
		["North up the road to {area:431} and {area:428} beside it."] = "Die Straße hinauf nach Norden zum {area:431} und nach {area:428} daneben.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "Nordwestlich vom Splintertreeposten lagern die Satyrn der Teufelshufe im Wald. Jeder Satyr kann Hörner fallen lassen.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Fahr mit dem Aufzug hinunter und folge dann der Straße nach Osten durch die Schluchten zum {area:484}, einem Taurendorf oben auf den Tafelbergen. Sein Aufzug ist auf der Nordseite.",
		["Sapphires of Aku'Mai"] = "Saphire von Aku'Mai",
		["South of Darkcloud, the harpies of {area:487}. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s."] = "Südlich vom Düsterwolkengipfel: die Harpyien im {area:487}. {npc:4490} (31) läuft zwischen ihnen umher: Dünn die Harpyien um sie aus, bevor du sie pullst. Die Kreischenden Harpyien, Wildfedern und Windruferinnen dort sind für {npc:4877}.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "Sprich mit {npc:3057} in {area:1638}: {quest:93739}",
		["Take a lift down from {area:1638}. The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}."] = "Fahr mit einem Aufzug von {area:1638} hinunter. Das Lager des Irdenen Rings steht nördlich der Klippen: {npc:264074}, {npc:264072} und {npc:259118}.",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Fahr mit dem Aufzug hinunter. Das Ei liegt in einem Nest am Schluchtboden an einer von drei Stellen: südöstlich der Tafelberge (52.3,55.2), östlich (56.4,50.4) oder südwestlich (37.6,56.1).",
		["The Earthen Ring"] = "Der Irdene Ring",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Die Furbolgs der Fäulnisklauen halten die Wälder östlich von {area:421}, südlich der Straße. Stell {item:16972} auf den {object:178206} und bewache es: Die Furbolgs kommen, um es niederzureißen. {npc:12918} kommt zuletzt; sein Totem fällt in den Korb.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks between the camps: kill him when you meet him, his note starts a quest for {area:2237}."] = "Die Lager der Galak füllen die Schlucht nördlich vom Freiwindposten; Späher, Zänker und Windhetzerinnen der Galak teilen sich jedes Lager. Ein einzelner {npc:10617} läuft zwischen den Lagern: Töte ihn, wenn du ihn triffst, seine Notiz startet eine Quest für den {area:2237}.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "Die Saphire sind blaue Kristalle an den Wänden der Tunnel zum Portal der {area:2797}, unterirdisch und außerhalb der Instanz: Schwimm aus der Grube hinab, unter der Mauer hindurch, in die Höhle. Die Satyrn und Naga in den Tunneln sind Elite: Eine Gruppe wird empfohlen. Die Kristalle erscheinen schnell wieder, du musst also nicht tief hinein.",
		["The Wanted poster beside {npc:10537}"] = "Der Steckbrief neben {npc:10537}",
		["The fountain stands in the middle of the {area:418}: use the {item:7767} there."] = "Der Brunnen steht mitten in den Ruinen ({area:418}): Benutze dort den {item:7767}.",
		["The next guide flies on from here to {zone:1454}."] = "Der nächste Guide fliegt von hier weiter nach {zone:1454}.",
		["The salt flats"] = "Die Salzebenen",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "Der Weg zu den Saphiren führt durch die versunkenen Ruinen am Nordende des Strands: Geh die Treppe hinunter in die Grube.",
		["Thistlefur Hold"] = "Höhle der Distelfelle",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "Westlich vom Freiwindposten liegen die Lager der Grimmtotem unterhalb vom {area:2097}. Die Geheimnotizen liegen in Dokumententruhen im südöstlichen, südwestlichen und nordwestlichen Lager.",
		["West of Whitereach the wyverns nest on the {area:482} cliffs; the eggs lie in the nests. {npc:10427} waits on the east side of the nesting grounds: free him and keep him alive on the walk back to {area:2237}."] = "Westlich vom Weißgipfelposten nisten die Flügeldrachen auf den Klippen ({area:482}); die Eier liegen in den Nestern. {npc:10427} wartet auf der Ostseite der Nistplätze: Befreie ihn und halte ihn auf dem Rückweg zum {area:2237} am Leben.",
		["for {npc:5901}, south of {area:392}: next guide"] = "für {npc:5901}, südlich von {area:392}: nächster Guide",
		["{area:2797} ruins"] = "Ruinen: {area:2797}",
		["{area:418} fountain"] = "Brunnen: {area:418}",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}, von Spinnern der Düsteranhöhe",
		["{item:273658}, from {npc:264082}"] = "{item:273658}, von {npc:264082}",
		["{npc:10079}, at the top of the lift"] = "{npc:10079}, oben am Aufzug",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}, beim Windreitermeister",
		["{npc:10428}'s next quest, Sacred Fire, ends in {area:1638}, off this route. Skip it."] = "{npc:10428}s nächste Quest, Hochheiliges Feuer, endet in {area:1638}, abseits dieser Route. Überspring sie.",
		["{npc:12676}, a big nightsaber, prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest."] = "{npc:12676}, ein großer Nachtsäbler, streift durch die Wälder südöstlich vom Holzfällerlager der Warsong. Ihre Klaue startet die nächste Jagdquest.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, ein Schattenpanther, pirscht durch die Wälder um {area:426}, westlich vom Lager der Teufelshufe. Ihr Kopf startet die nächste Jagdquest.",
		["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead."] = "{npc:12717} geht den Strand hinauf nach Norden zu einer Nagakohlenpfanne. Lösch die Kohlenpfanne und beschütze ihn dann durch die Wellen der Naga, bis Vorsha die Peitscherin tot ist.",
		["{npc:12717}: starts his escort at once"] = "{npc:12717}: Seine Eskorte beginnt sofort",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}: nur, wenn du die Handbuchseiten dabeihast",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736} bietet als Nächstes eine Quest für die {area:2797} an; lass sie aus, außer du hast eine Gruppe.",
		["{npc:12759}, a corrupted water elemental, drifts in {area:421}. Her {item:16408} starts a quest for Splintertree."] = "{npc:12759}, ein verderbter Wasserelementar, treibt im {area:421}. Ihr {item:16408} startet eine Quest für den Splintertreeposten.",
		["{npc:12867} stands at the lumber camp. The night elf Outrunners stalk the woods south-east of it; they stealth, so watch for them."] = "{npc:12867} steht im Holzfällerlager. Die Kundschafter von Ashenvale pirschen durch die Wälder südöstlich davon; sie sind getarnt, also halte nach ihnen Ausschau.",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}, eine Ergänzung von Forever, steht am Westufer von {area:421} mit drei schnellen Drachentöter-Quests.",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986} steht oben auf einem Tafelberg östlich der Lager der Galak. Für {quest:1149} geh über das Ende der Planken neben ihm hinaus: Du landest sicher.",
		["{npc:4454}: his letter goes to Martek in the {zone:1418}, around level 38"] = "{npc:4454}: Sein Brief geht an Martek im {zone:1418}, etwa auf Stufe 38",
		["{npc:4499}, a hard-hitting rock elemental, walks the cliffs of {area:482}. {npc:4499} is elite: grouping up is advised."] = "{npc:4499}, ein hart zuschlagender Felselementar, wandert über die Klippen ({area:482}). {npc:4499} ist Elite: Eine Gruppe wird empfohlen.",
		["{npc:4877}, the trade supplies vendor: the Screeching harpies of {area:487}"] = "{npc:4877}, die Handwerkswarenhändlerin: die kreischenden Harpyien im {area:487}",
		["{object:176344}, north-west camp"] = "{object:176344}, nordwestliches Lager",
		["{object:176344}, south-east camp"] = "{object:176344}, südöstliches Lager",
		["{object:176344}, south-west camp"] = "{object:176344}, südwestliches Lager",
		["{object:19868} lies all over the flats north of the raceway. Scorpid Reavers and Sparkleshell Tortoises roam the north half, Salt Flats Scavengers circle overhead, and Saltstone Basilisks graze west of the track. The Crystalhides roam the middle of the flats and the Gazers (34-35, five levels above you: one at a time) the far south."] = "{object:19868} liegen überall auf den Ebenen nördlich der Rennbahn. Skorpidhäscher und Spiegelpanzerschildkröten streifen durch die Nordhälfte, Salzwüstenaasfresser kreisen am Himmel, und Salzsteinbasilisken grasen westlich der Strecke. Die Salzsteinkristallhäute streifen durch die Mitte der Ebenen und die Salzsteinstarrer (34-35, fünf Stufen über dir: einzeln) durch den äußersten Süden.",
} end)()
t.guides["forever/horde/30-40/01-desolace"] = (function() return {
		["Back at {area:609}, every Kolkar can drop an ear."] = "Zurück in {area:609} kann jeder Kolkar ein Ohr fallen lassen.",
		["Back to {area:272}"] = "Zurück nach {area:272}",
		["Clam beds"] = "Muschelbänke",
		["Daggerspine naga"] = "Naga der Säbelflossen",
		["Daggerspine shore"] = "Ufer der Säbelflossen",
		["Do your shopping in the {area:1497} first, then fly to the {area:228}. The {object:113791} stands on the hill just south-west of it: beat the Corrupt Manifestation of Water beside it, place its bracers in the brazier, speak to the {npc:5895} and keep the {item:7813} for {npc:5901}. Fly on to {area:272} from the {area:228}."] = "Erledige zuerst deine Einkäufe in {area:1497} und flieg dann zum {area:228}. {object:113791} steht auf dem Hügel gleich südwestlich davon: Besiege die Verderbte schwache Wassermanifestation daneben, leg ihre Armschienen in die Kohlenpfanne, sprich mit {npc:5895} und behalte {item:7813} für {npc:5901}. Flieg vom {area:228} weiter nach {area:272}.",
		["Fly to the {area:1497}"] = "Flieg nach {area:1497}",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:1638} from Shadowprey and train with {npc:3033} on {area:1639}, then fly on to {zone:1454}."] = "Flieg von Shadowprey nach {area:1638}, trainiere bei {npc:3033} auf der Anhöhe ({area:1639}) und flieg dann weiter nach {zone:1454}.",
		["Fly to {area:392}. {npc:5901} camps on the coast a short ride south of the town."] = "Flieg nach {area:392}. {npc:5901} lagert an der Küste, ein kurzer Ritt südlich der Stadt.",
		["Fly to {area:460}"] = "Flieg nach {area:460}",
		["Fly to {area:484}. {npc:5905} hides in a small cave in the canyon wall north-east of the post."] = "Flieg zum {area:484}. {npc:5905} versteckt sich in einer kleinen Höhle in der Schluchtwand nordöstlich des Postens.",
		["Follow the road north out of {area:272} into the Alterac foothills. {quest:535} waits by the Syndicate camp; hand him the stout."] = "Folge der Straße nach Norden aus {area:272} hinaus in die Ausläufer des Alteracgebirges. {quest:535} wartet beim Lager des Syndikats; gib ihm das Starkbier.",
		["Follow the road south-west out of Sun Rock into {zone:1443} and on south past {area:608}. {npc:11625}'s kodo caravan waits by the road north of {area:609}; if it has already left, ride on."] = "Folge der Straße nach Südwesten aus Sonnenfels hinaus nach {zone:1443} und weiter nach Süden an der Nijelspitze ({area:608}) vorbei. Die Kodokarawane von {npc:11625} wartet an der Straße nördlich von {area:609}; ist sie schon abgefahren, reite weiter.",
		["Follow the shore west past {area:271}'s bay; the Torn Fin murlocs camp on the beaches beyond it."] = "Folge dem Ufer nach Westen an der Bucht von {area:271} vorbei; die Murlocs der Fetzenflossen lagern an den Stränden dahinter.",
		["From {area:484}, fly to {area:1637}."] = "Flieg vom {area:484} nach {area:1637}.",
		["Gizelton caravan"] = "Karawane der Gizeltons",
		["Head west along the foot of the mountains to the violet dome of {area:279}. {npc:2411}, {npc:2412} and {npc:2413} (33-34) stand together inside the crater's eastern rim, {npc:2414} (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-32) around them drop the Worn Stone Tokens."] = "Geh am Fuß der Berge entlang nach Westen zur violetten Kuppel von {area:279}. {npc:2411}, {npc:2412} und {npc:2413} (33-34) stehen zusammen innerhalb des östlichen Kraterrands, {npc:2414} (35) etwas westlich von ihnen; jeder trägt ein Blutsteinstück. Die Schildwachen und Theurgiker (31-32) um sie herum lassen die Abgenutzten Steinmarken fallen.",
		["Hearth back (or ride north if it is on cooldown)."] = "Nimm den Ruhestein zurück (oder reite nach Norden, wenn er Abklingzeit hat).",
		["His next errand is not on this route."] = "Sein nächster Auftrag ist nicht auf dieser Route.",
		["Keep north to {area:598}. The Oracles stand among the other naga at its north end; pull one at a time."] = "Weiter nach Norden zum {area:598}. Die Orakel stehen zwischen den anderen Naga an seinem Nordende; pull sie einzeln.",
		["Kolkar ears"] = "Kolkarohren",
		["Leave {zone:1454} by the main gate; the zeppelin tower stands just north-east of it. Take the {area:1497} zeppelin."] = "Verlass {zone:1454} durch das Haupttor; der Zeppelinturm steht gleich nordöstlich davon. Nimm den Zeppelin nach {area:1497}.",
		["North along the eastern hills, the satyrs hold the ruins of {area:603}. The Shadowstalkers walk unseen; the four kinds you need do not."] = "Nördlich entlang der östlichen Hügel halten die Satyrn die Ruinen von {area:603}. Die Schattenpirscher sind unsichtbar; die vier Arten, die du brauchst, nicht.",
		["Place the {object:1729} on the {object:1728} beside the inn"] = "Stell das {object:1729} auf den {object:1728} neben dem Gasthaus",
		["Ride back east to {area:272}."] = "Reite zurück nach Osten nach {area:272}.",
		["Ride back north to {area:272}, keeping west of {area:271}."] = "Reite zurück nach Norden nach {area:272} und halte dich westlich von {area:271}.",
		["Ride back south to the post."] = "Reite zurück nach Süden zum Posten.",
		["Ride back south to {area:272}."] = "Reite zurück nach Süden nach {area:272}.",
		["Ride north past {quest:535}'s camp to {area:280}, the Syndicate-held village (35-37). {npc:2431} carries the {item:3704}; {quest:503} sits in a cage in the house on the north side."] = "Reite nach Norden am Lager von {quest:535} vorbei nach {area:280}, dem vom Syndikat besetzten Dorf (35-37). {npc:2431} trägt den {item:3704}; {quest:503} sitzt in einem Käfig im Haus auf der Nordseite.",
		["Ride north up the coast. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach; open each clam in your bags for its meat."] = "Reite die Küste hinauf nach Norden. Riesenweichpanzermuscheln liegen im seichten Wasser und Wütende Riffkriecher laufen am Strand; öffne jede Muschel in deinen Taschen für ihr Fleisch.",
		["Ride north-east to {area:609}. {quest:1365} (35) walks among the tents on the east side with a Battle Lord or two (32-33): clear around him, then pull him alone at full health."] = "Reite nach Nordosten nach {area:609}. {quest:1365} (35) läuft mit ein oder zwei Kampflords der Kolkar (32-33) zwischen den Zelten auf der Ostseite: Räum um ihn herum auf und pull ihn dann allein mit voller Gesundheit.",
		["Ride south, east of {area:271}, down to the coast. The Daggerspine naga line the shore south-east of the town."] = "Reite nach Süden, östlich an {area:271} vorbei, hinunter zur Küste. Die Naga der Säbelflossen säumen das Ufer südöstlich des Orts.",
		["Ride south-east to the post."] = "Reite nach Südosten zum Posten.",
		["Ride south-west to the troll village on the coast, keeping clear of the {area:606} on the way."] = "Reite nach Südwesten zum Trolldorf an der Küste und halte dich unterwegs von {area:606} fern.",
		["Ride south-west towards Shadowprey. The Gelkis centaurs (32-35) around their village are a good camp; fight them until level 32."] = "Reite nach Südwesten Richtung Shadowprey. Die Zentauren der Gelkis (32-35) um ihr Dorf sind ein guter Platz; kämpfe dort bis Stufe 32.",
		["Ride west to {area:599}. Beat a Burning Blade cultist down, then use the {item:6436} on it before it dies to fill one {item:6435}. They also drop a {item:20310} now and then (1-5%); if one drops, read it."] = "Reite nach Westen zur {area:599}. Prügle einen Kultisten der Burning Blade runter und benutze dann {item:6436} an ihm, bevor er stirbt, um einen {item:6435} zu füllen. Sie lassen ab und zu auch {item:20310} fallen (1-5%); falls eine fällt, lies sie.",
		["Shadowstalker scalp"] = "Skalp eines Schattenpirschers",
		["Shindigger keg"] = "Fässchen Shindigger-Starkbier",
		["Slitherblade Oracles"] = "Orakel der Zackenkämme",
		["South-west, the Cave and Ferocious Yetis (30-31) fill the caves in the hills west of {area:272}; about one in sixteen carries the rod."] = "Im Südwesten füllen Höhlenyetis und Wilde Yetis (30-31) die Höhlen in den Hügeln westlich von {area:272}; etwa jeder sechzehnte trägt die Rute.",
		["Syndicate missives"] = "Schreiben des Syndikats",
		["Thaivand's next task ends at {area:271}'s graveyard and the magus offers a dungeon errand: leave both."] = "Thaivands nächste Aufgabe endet auf dem Friedhof von {area:271}, und der Magus bietet einen Dungeonauftrag an: Lass beide aus.",
		["The Hatefury Shadowstalkers at {area:603} walk unseen until they strike; about one in three carries a scalp."] = "Die Schattenpirscher der Zornsäer in {area:603} sind unsichtbar, bis sie zuschlagen; etwa jeder dritte trägt einen Skalp.",
		["The Seer stands on the south side of {area:599}, east of {area:2405}. Clear the cultists around it first."] = "Der Seher steht auf der Südseite der {area:599}, östlich von {area:2405}. Räum zuerst die Kultisten um ihn herum weg.",
		["The Syndicate Footpads and Thieves (32-33) around the camps west of the road carry the missives; about one in three drops one."] = "Die Schleicher und Diebe des Syndikats (32-33) um die Lager westlich der Straße tragen die Schreiben; etwa jeder dritte lässt eins fallen.",
		["The caravan rolls south past {area:609}. Kolkar raiders ambush it in waves: kill them before they reach {npc:11625}. It stops by {area:2617}, east of {area:597}."] = "Die Karawane zieht nach Süden an {area:609} vorbei. Kolkar überfallen sie in Wellen: Töte sie, bevor sie {npc:11625} erreichen. Sie hält bei {area:2617}, östlich vom {area:597}.",
		["The keg stands with a few others at the Syndicate camp on the south-east coast of {area:287}."] = "Das Fässchen steht mit einigen anderen im Lager des Syndikats an der Südostküste von {area:287}.",
		["The next guide starts in the {area:1497}, at the {object:3202} zeppelin."] = "Der nächste Guide beginnt in {area:1497}, am Zeppelin nach {object:3202}.",
		["The {area:279} traitors"] = "Die Verräter von {area:279}",
		["Torn Fin beach"] = "Strand der Fetzenflossen",
		["Torn Fin murlocs"] = "Murlocs der Fetzenflossen",
		["Train"] = "Trainieren",
		["Train your new spells."] = "Lerne deine neuen Zauber.",
		["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. Five kodos, one at a time."] = "Benutze {npc:11596}s {item:13892} an einem Gealterten, Sterbenden oder {npc:4702} auf dem Friedhof und führe den gezähmten Kodo zurück zu {npc:11596}. Fünf Kodos, einer nach dem anderen.",
		["Your trainer is in {area:1638}, one flight away: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly on to {area:460} from there."] = "Dein Lehrer ist in {area:1638}, einen Flug entfernt: {npc:3033} (Druiden) auf der Anhöhe ({area:1639}), {npc:246344} (Paladine). Flieg von dort weiter nach {area:460}.",
		["Zeppelin to the {area:1497}"] = "Zeppelin nach {area:1497}",
		["Zeppelin tower"] = "Zeppelinturm",
		["for {npc:5901}: from Stranglethorn, next guide"] = "für {npc:5901}: aus dem Schlingendorntal, nächster Guide",
		["grind on Gelkis Stampers and Windchasers at the {area:606}, {zone:1443}"] = "Stampfer und Windhetzer der Gelkis grinden: {area:606}, {zone:1443}",
		["{area:2408} flight master"] = "Flugmeister: {area:2408}",
		["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388}: Auktionshaus oder ein Alchemist, für {quest:515}.",
		["{item:3703}, for {npc:2333}"] = "{item:3703}, für {npc:2333}",
		["{npc:11863} waits in the ruined tower of {area:2405}, inland to the south-east."] = "{npc:11863} wartet im verfallenen Turm von {area:2405}, landeinwärts im Südosten.",
		["{npc:11877}: for {npc:715} in Stranglethorn"] = "{npc:11877}: für {npc:715} im Schlingendorntal",
		["{npc:2229}: for the {zone:1413}, later on the route"] = "{npc:2229}: fürs {zone:1413}, später auf der Route",
		["{npc:260093} trains Paladins in the {area:1497}."] = "{npc:260093} bildet in {area:1497} Paladine aus.",
		["{npc:2770}: for {area:321} in Arathi, later on the route"] = "{npc:2770}: für {area:321} im Arathihochland, später auf der Route",
		["{npc:4551}, the bat handler"] = "{npc:4551}, der Fledermausführer",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}, Grommash Hold, falls du sie dabeihast",
		["{npc:5395} stands in the post; {npc:5641} and {npc:4498} wait on the rise west of it, above the {area:596}."] = "{npc:5395} steht im Posten; {npc:5641} und {npc:4498} warten auf der Anhöhe westlich davon, über dem Friedhof ({area:596}).",
		["{npc:5639} waits in the Drag; {npc:5640} stands in the {object:172961} on the west side of the city. Skyborne: {npc:4949} waits in Grommash Hold, in the {object:172957}."] = "{npc:5639} wartet in der Gasse; {npc:5640} steht im {object:172961} auf der Westseite der Stadt. Himmelsgeborene: {npc:4949} wartet in der Feste Grommash im {object:172957}.",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "{npc:5641}s nächster Auftrag schickt dich zu einem Dämonenfürsten mit Elitewache: Überspring ihn.",
		["{npc:5641}'s next {quest:1431} sends you back to {zone:1454} for nothing: leave it."] = "{npc:5641}s nächste Quest {quest:1431} schickt dich umsonst zurück nach {zone:1454}: Lass sie aus.",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892} steht im {object:172957}.",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905} startet auch Elementare Hilfe ({area:1717}), die Kette (33-40) zu The Tempest's Weapons: forever/class/shaman/call-of-air-horde.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: dein {item:5178}",
		["{quest:515} needs a {item:3388}, an {skill:171} item: buy one at the auction house here if you can (or ask an alchemist). No potion: skip the Elixir steps in {area:287}."] = "{quest:515} braucht einen {item:3388}, einen Gegenstand aus {skill:171}: Kauf einen hier im Auktionshaus, wenn du kannst (oder frag einen Alchemisten). Kein Trank: Überspring die Elixier-Schritte in {area:287}.",
		["{zone:1454} class quests"] = "Klassenquests in {zone:1454}",
} end)()
t.guides["forever/horde/30-40/02-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Zurück nach Norden zum Lager.",
		["Back to {object:3202}"] = "Zurück nach {object:3202}",
		["Back to {object:3202}."] = "Zurück nach {object:3202}.",
		["Basilisks and the Bloodscalp village"] = "Basilisken und das Dorf der Bloodscalp",
		["Bloodscalp headhunters"] = "Kopfjäger der Bloodscalp",
		["Bloodscalp ruins"] = "Ruinen der Bloodscalp",
		["East of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}."] = "Östlich der Oger schleichen Schattentatzenpanther (37-38) ungesehen, bis sie zuschlagen; Schlingendorntigerinnen streifen im selben Gebiet und droppen ab und zu einen makellosen Fangzahn. Schnappkieferkrokilisken säumen den Fluss gleich westlich des Dschungels; behalte ihre Häute für {npc:2495}.",
		["Elder tigers and Lashtail raptors"] = "Alte Tiger und Schmetterschwänze",
		["Fly to {area:35}"] = "Flieg nach {area:35}",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "Folge der Straße von {object:3202} nach Norden; Nesingwarys Jagdlager liegt auf dem Hügel nordöstlich des Flusses. Ab hier behältst du jede Seite von {quest:338}, die du erbeutest: {npc:716} Stonepot will sie später.",
		["Follow the road on south into {area:35}."] = "Folge der Straße weiter nach Süden nach {area:35}.",
		["Follow the road south to {area:35} at the southern tip of the vale and enter through the tunnel in the cliffs. Stay on the road: the jungle beside it is well above your level. {npc:2858}, the Horde flight master, waits on the upper deck."] = "Folge der Straße nach Süden nach {area:35} an der Südspitze des Tals und geh durch den Tunnel in den Klippen hinein. Bleib auf der Straße: Der Dschungel daneben liegt weit über deiner Stufe. {npc:2858}, der Flugmeister der Horde, wartet auf dem oberen Deck.",
		["Follow the road south to {object:3202}."] = "Folge der Straße nach Süden nach {object:3202}.",
		["Green Hills pages"] = "Seiten der Grünen Hügel",
		["Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it."] = "Geh westlich am Lager vorbei. Schlingendornraptoren (33-34) jagen auf den Lichtungen, und die Trolle der Bloodscalp halten die Ruinen an der Küste: Jeder von ihnen kann einen Hauer droppen. Ein {item:4614} ist ein sehr seltener Drop von ihnen: Wenn einer droppt, lies ihn.",
		["Hearth to {area:35}"] = "Ruhestein nach {area:35}",
		["Hearth to {object:3202}"] = "Ruhestein nach {object:3202}",
		["Jungle Stalkers"] = "Dschungelpirscher",
		["Lashtail raptors"] = "Schmetterschwänze",
		["Leave the {zone:1458} by the lift and walk up through the ruins to the zeppelin towers; the {object:3202} zeppelin is the one on the south-west tower."] = "Verlass {zone:1458} mit dem Aufzug und geh durch die Ruinen hinauf zu den Zeppelintürmen; der Zeppelin nach {object:3202} ist der am südwestlichen Turm.",
		["Mistvale gorillas"] = "Nebeltalgorillas",
		["Mosh'Ogg camp"] = "Lager der Mosh'Ogg",
		["Nesingwary's camp"] = "Lager von Nesingwary",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "Nordwestlich von Grom'gol liegt {area:104} unter Wasser vor der Küste. Die {item:4094} liegt auf dem Meeresgrund bei den versunkenen Ruinen; achte auf deinen Atem und die Murlocs.",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "Seiten von {item:2755} droppen mit je etwa 1% von den Trollen der Bloodscalp und der Skullsplitter; behalte jede Seite, die du erbeutest, und schau im Auktionshaus nach dem Rest. {npc:716} Stonepot nimmt die Kapitel später in diesem Guide.",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; take what drops and check the Auction House for the rest."] = "Seiten von {item:2755} droppen mit je etwa 1% von den Trollen der Bloodscalp und der Skullsplitter; nimm, was droppt, und schau im Auktionshaus nach dem Rest.",
		["Raptors and the Bloodscalp trolls"] = "Raptoren und die Trolle der Bloodscalp",
		["Ride back south to {object:3202}."] = "Reite zurück nach Süden nach {object:3202}.",
		["Ride north past Nesingwary's camp to the lake. The Venture Co. Geologists (34-36) work the camps along its western shore; they carry the Tumbled Crystals."] = "Reite nördlich an Nesingwarys Lager vorbei zum See. Die Geologen der Venture Co. (34-36) arbeiten in den Lagern am Westufer; sie tragen die Gerommelten Kristalle.",
		["Ride south down the coast to {object:3202} and fly to {area:35}."] = "Reite die Küste hinunter nach Süden nach {object:3202} und flieg nach {area:35}.",
		["Shadowmaw jungle and the Snapjaw river"] = "Dschungel der Schattentatzen und Fluss der Schnappkiefer",
		["Shadowmaw panthers"] = "Schattentatzenpanther",
		["Stranglethorn Tigers and Panthers (32-33) roam the hills east of the camp, along the lake shore."] = "Schlingendorntiger und Panther (32-33) streifen durch die Hügel östlich des Lagers am Seeufer.",
		["Take the road south towards {area:35}. The Elder Mistvale Gorillas (40-41) live in {area:1737}, east of the road; about one in twenty carries an aged sinew."] = "Nimm die Straße nach Süden Richtung {area:35}. Die Alten Nebeltalgorillas (40-41) leben im {area:1737}, östlich der Straße; etwa jeder zwanzigste trägt eine Sehne eines alten Gorillas.",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202} and fly to {area:392}. {npc:5901} camps on the coast a short ride south of it."] = "Nimm den Zeppelin nach {zone:1454} vom Turm auf der Westseite von {object:3202} und flieg nach {area:392}. {npc:5901} lagert an der Küste, ein kurzes Stück südlich davon.",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202} and train in the city before you fly on."] = "Nimm den Zeppelin nach {zone:1454} vom Turm auf der Westseite von {object:3202} und trainiere in der Stadt, bevor du weiterfliegst.",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads."] = "Die Kopfjäger der Bloodscalp (36-37) im Dorf an der Küste tragen die Schrumpfköpfe.",
		["The Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of {quest:338}."] = "Die Trolle der Bloodscalp halten die Ruinen an der Küste nördlich des Riffs und das Dorf dahinter; jeder kann eine {item:3915} droppen. Erbeute weiter Seiten von {quest:338}.",
		["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp; the Lashtail Raptors (35-36) hunt further south, towards {object:3202}."] = "Die Alten Schlingendorntiger (34-35) streifen durch die Hügel südwestlich des Lagers; die Schmetterschwänze (35-36) jagen weiter südlich, Richtung {object:3202}.",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "Die Dschungelpirscher (40-41) jagen an der Küste südlich von {object:3202}. Sie liegen weit über dir: Zieh sie einzeln und ruh dich zwischen den Kämpfen aus.",
		["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "Die Schmetterschwänze (35-36) jagen im Dschungel gleich nordöstlich von {object:3202}.",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}. Kill one Brute and one Witch Doctor (36-37); pull them one at a time."] = "Die Oger der Mosh'Ogg lagern in den Hügeln gleich östlich von {object:3202}. Töte einen Schläger der Mosh'Ogg und einen Hexendoktor der Mosh'Ogg (36-37); zieh sie einzeln.",
		["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "Die Schattentatzenpanther (37-38) schleichen durch den Dschungel östlich der Hügel der Mosh'Ogg und nordöstlich Richtung See; sie greifen aus der Verstohlenheit an. Erbeute unterwegs jede Seite der Grünen Hügel.",
		["The camp by the river"] = "Das Lager am Fluss",
		["The next guide flies you north to {area:272} and into the {zone:1417}."] = "Der nächste Guide fliegt dich nach Norden nach {area:272} und ins {zone:1417}.",
		["The zeppelin lands at the tower on the west side of the camp."] = "Der Zeppelin landet am Turm auf der Westseite des Lagers.",
		["Tigers and panthers"] = "Tiger und Panther",
		["Venture Co. camp"] = "Lager der Venture Co.",
		["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear."] = "Westlich am Lager vorbei sitzen Kristallrückenbasilisken (34-35) auf den Felsen; jeder Troll der Bloodscalp im Dorf dahinter kann ein Ohr droppen.",
		["Young Stranglethorn Tigers prowl west of the camp, Young Panthers south and east of it."] = "Junge Schlingendorntiger streifen westlich des Lagers umher, Junge Panther südlich und östlich davon.",
		["Young tigers and panthers"] = "Junge Tiger und Panther",
		["Zeppelin to {object:3202}"] = "Zeppelin nach {object:3202}",
		["Zeppelin towers"] = "Zeppelintürme",
		["{npc:2495}: the Snapjaw skins gathered earlier"] = "{npc:2495}: die Schnappkieferkrokiliskenhäute von vorhin",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}: für das Arathihochland, später auf der Route",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527} und dein {item:5177}",
		["{npc:729}, a level 37 tiger, prowls the hilltop south-west of the camp."] = "{npc:729}, ein Tiger der Stufe 37, streift über die Hügelkuppe südwestlich des Lagers.",
		["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "Das Lager der vermissten Jäger von {npc:773} ist das von Nesingwary: Geh zwischen den Zelten umher, dann ist die Untersuchung abgeschlossen. Flusskrokilisken liegen am Fluss unterhalb des Lagers.",
} end)()
t.guides["forever/horde/30-40/03-arathi-highlands"] = (function() return {
		["Back to {area:321}"] = "Zurück nach {area:321}",
		["Boulderfist camp"] = "Lager der Felsfäuste",
		["Cast {spell:18960} and take {npc:11798}'s flight to {area:1638}; {npc:3033} trains you on {area:1639}. Then fly to {zone:1454} and take the {zone:1458} zeppelin from the tower outside the main gate."] = "Wirke {spell:18960} und nimm den Flug von {npc:11798} nach {area:1638}; {npc:3033} bildet dich auf der {area:1639} aus. Flieg dann nach {zone:1454} und nimm vom Turm vor dem Haupttor den Zeppelin nach {zone:1458}.",
		["Coyotes and buzzards"] = "Kojoten und Bussarde",
		["Daggerspine shore"] = "Ufer der Säbelflossen",
		["Each {object:180105} is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of {area:321}."] = "Jeder {object:180105} ist ein Ring aus Menhiren; der Schlüssel liegt auf dem Stein in seiner Mitte. Der östliche Kreis liegt in den Hügeln nordwestlich von {area:321}.",
		["Escort the professor down to the shore. Two Daggerspine naga ambush him on the way: stay close."] = "Eskortiere den Professor hinunter zum Ufer. Zwei Naga der Säbelflossen überfallen ihn unterwegs: Bleib dicht dran.",
		["Fleshstalker raptors"] = "Hochlandfleischpirscher",
		["Fly to {area:272}"] = "Flieg nach {area:272}",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Follow the road north; {npc:4618}'s camp is on the way."] = "Folge der Straße nach Norden; {npc:4618}s Lager liegt auf dem Weg.",
		["From {area:35}, fly to {object:3202}. {object:1661} zeppelin leaves from the tower on the west side of the camp."] = "Flieg von {area:35} nach {object:3202}. Der Zeppelin nach {object:1661} startet vom Turm auf der Westseite des Lagers.",
		["Greater Rock Elementals"] = "Große Felselementare",
		["Hearth to {area:340}"] = "Ruhestein nach {area:340}",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "Hochlandfleischpirscher (36-37) jagen im südlichen Hochland, ein Rudel nördlich von {area:316} und ein weiteres auf der Ebene westlich davon. Zieh sie einzeln.",
		["Highland Striders roam the hills all around {area:321}; both they and the Thrashers further west drop the eyes."] = "Hochlandschreiter streifen überall um {area:321} durch die Hügel; sie und die Hochlandhauer weiter westlich lassen die Augen fallen.",
		["Highland raptors"] = "Hochlandraptoren",
		["Into the {zone:1418}"] = "Ins {zone:1418}",
		["Keep north on the road; the chest lies in the {area:1517} dig site, at the foot of the ruins north-west of the road."] = "Bleib auf der Straße nach Norden; die Truhe liegt in der Grabungsstätte von {area:1517}, am Fuß der Ruinen nordwestlich der Straße.",
		["Lesser Rock Elementals"] = "Kleine Felselementare",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael."] = "Nordöstlich von Hammerfall graben die Kobolde der Trockenstoppel in der Schlucht; die Kobolde am Eingang und die Buddler und Feldvermesser weiter drinnen lassen alle die Körner von Myzrael fallen.",
		["Ride back south down the road, past the {area:1877}."] = "Reite die Straße zurück nach Süden, am {area:1877} vorbei.",
		["Ride back south to the {area:380} and fly to {area:392}."] = "Reite zurück nach Süden nach {area:380} und flieg nach {area:392}.",
		["Ride east out of {area:272} through {area:1857} and follow the road east. The Boulderfist Ogres and Enforcers (32-34) camp south of the road, south-east of {area:313}."] = "Reite von {area:272} nach Osten durch {area:1857} und folge der Straße nach Osten. Die Oger und Vollstrecker der Felsfäuste (32-34) lagern südlich der Straße, südöstlich von {area:313}.",
		["Ride north back to {area:340}."] = "Reite nach Norden zurück nach {area:340}.",
		["Ride north up the road from the {area:380} to the {area:386}; {npc:3389} keeps watch on the rise above the water."] = "Reite von {area:380} die Straße nach Norden zu {area:386}; {npc:3389} hält auf der Anhöhe über dem Wasser Wache.",
		["Ride north; the outer circle stands in the middle of the highlands."] = "Reite nach Norden; der äußere Kreis steht mitten im Hochland.",
		["Ride south along the coast from {area:392} to {area:720}. {npc:6236} stands by the arena: step on the grate to start the fight; the challengers come one at a time, then {npc:6238} (33)."] = "Reite von {area:392} die Küste entlang nach Süden zur {area:720}. {npc:6236} steht bei der Arena: Tritt auf das Gitter, um den Kampf zu starten; die Herausforderer kommen einzeln, dann {npc:6238} (33).",
		["Ride south-west out of Arathi over {area:880}, south through the {zone:1437} (keep clear of {area:150}) and east into {zone:1432}; the road leaves {zone:1432} to the south into the {zone:1418}. Follow it south to the goblin camp in the {area:1877}."] = "Reite nach Südwesten aus Arathi über den {area:880}, nach Süden durch das {zone:1437} (meide {area:150}) und nach Osten nach {zone:1432}; die Straße verlässt {zone:1432} nach Süden ins {zone:1418}. Folge ihr nach Süden zum Goblinlager im {area:1877}.",
		["Ride south-west to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "Reite nach Südwesten zur Bucht der Goblins an der Südküste. {npc:2766} hält auf der Klippe darüber Wache.",
		["Ride west along the road; {npc:2921}'s camp sits in the {area:1878} halfway to {area:340}."] = "Reite auf der Straße nach Westen; {npc:2921}s Lager liegt im {area:1878} auf halbem Weg nach {area:340}.",
		["Rock Elementals"] = "Felselementare",
		["Stonevault troggs"] = "Steingrufttroggs",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202}."] = "Nimm den Zeppelin nach {zone:1454} vom Turm auf der Westseite von {object:3202}.",
		["The Boulderfist Brutes camp outside the ogres' hall south of {area:321}; the Magus stand among them. Pull them one at a time."] = "Die Schläger der Felsfäuste lagern vor der Halle der Oger südlich von {area:321}; die Magier der Felsfäuste stehen zwischen ihnen. Zieh sie einzeln.",
		["The Elder Crag Coyotes and Giant Buzzards roam the basin south of the {area:1878}. Coyotes drop both the jawbones and the fangs; only the buzzards drop wings and gizzards."] = "Die Alten Klippenkojoten und Riesenbussarde streifen durch das Becken südlich vom {area:1878}. Kojoten lassen Kieferknochen und Fangzähne fallen; nur die Bussarde lassen Flügel und Muskelmägen fallen.",
		["The Greater Rock Elementals (42-44, well above you) wander the gulches in the south-west; the bracers drop about one kill in five. Pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way."] = "Die Großen Felselementare (42-44, deutlich über dir) wandern durch die Rinnen im Südwesten; die Armschienen fallen etwa bei jedem fünften Kill. Zieh sie einzeln und ruh dich zwischen den Kämpfen aus, oder lass sie. Töte unterwegs weiter Kojoten und Bussarde, die du noch brauchst.",
		["The Stonevault troggs dig around the cave mouths south of the {area:1877}, on the way to {area:345}; the Bonesnappers and Shamans drop the flakes."] = "Die Steingrufttroggs graben um die Höhleneingänge südlich vom {area:1877}, auf dem Weg zur {area:345}; die Knochenknacker und Schamanen lassen die Splitter fallen.",
		["The Syndicate hold the walled manor and its farm in the north-west; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets."] = "Das Syndikat hält das ummauerte Gut und seinen Hof im Nordwesten; seine Straßenräuber, Söldner und Pfadpirscher tragen die Blutsteinamulette.",
		["The Witherbark trolls hold the village in the south-eastern hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village."] = "Die Trolle der Witherbark halten das Dorf in den südöstlichen Hügeln. Axtwerfer bewachen die äußeren Hütten; die Hexendoktoren und Kopfjäger halten das Herz des Dorfs.",
		["The bigger Rock Elementals stand on the slopes north-west of the {area:1878}; each one drops a slab."] = "Die größeren Felselementare stehen an den Hängen nordwestlich vom {area:1878}; jedes lässt eine Steinplatte fallen.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "Der innere Kreis liegt südlich des westlichen Kreises, östlich von Stromgarde.",
		["The next guide heads into {zone:1445}."] = "Der nächste Guide führt in die {zone:1445}.",
		["The orc stronghold at the eastern end of the road. Urda, the wind rider master, stands by the gate."] = "Die Orcfestung am östlichen Ende der Straße. Urda, die Windreitermeisterin, steht beim Tor.",
		["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "Die kleinen Elementare treiben über die Ebene gleich westlich von {npc:2921}s Lager. Jedes Felselementar im Gebiet kann {npc:6868}s Felselementarsplitter fallen lassen: Behalte sie.",
		["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "Die nächste Aufgabe des Steins erfordert Fozruk, einen Elite der Stufe 42: Lass sie liegen.",
		["The violet shards glow just off the road a short way west of {area:321}."] = "Die violetten Splitter leuchten gleich neben der Straße, ein kurzes Stück westlich von {area:321}.",
		["The western circle is near {area:1857}, where you rode in."] = "Der westliche Kreis liegt nahe {area:1857}, wo du hereingeritten bist.",
		["The zeppelin lands at the towers outside the {zone:1458}: ride down into the city and fly to {area:272}."] = "Der Zeppelin landet an den Türmen vor {zone:1458}: Reite hinunter in die Stadt und flieg nach {area:272}.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2689}"] = "{object:2689}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} liegen am hinteren Ende der Schlucht.",
		["The {object:2702}"] = "{object:2702}",
		["Theldurin sits among the dwarven ruins at {area:345}, south of the {area:1877}."] = "Theldurin sitzt zwischen den Zwergenruinen an der {area:345}, südlich vom {area:1877}.",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Trainiere, solange du in {zone:1458} bist: Die Lehrer stehen im {object:36070}, im {object:36073} und im {object:36082} (Paladine: {npc:260093}).",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "Westlich der Bucht halten die Räuber und Zauberhexerinnen der Säbelflossen (38-40) das Ufer: Zieh sie einzeln. Die beiden Wracks liegen davor im seichten Wasser, die Karten und Logbücher darin; die Edelsteine liegen um die Wracks auf dem Meeresgrund.",
		["Your trainer is in {area:1638}, one flight from {zone:1454}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly on to the {area:380} from there."] = "Dein Lehrer ist in {area:1638}, einen Flug von {zone:1454} entfernt: {npc:3033} (Druiden) auf der {area:1639}, {npc:246344} (Paladine). Flieg von dort weiter nach {area:380}.",
		["Zeppelin to the {zone:1458}"] = "Zeppelin nach {zone:1458}",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["Zeppelin tower"] = "Zeppelinturm",
		["for Helgrum in {area:75}, around level 42"] = "für Helgrum in {area:75}, etwa ab Stufe 42",
		["for {npc:2487} in {area:35}, around level 44"] = "für {npc:2487} in {area:35}, etwa ab Stufe 44",
		["for {npc:5395} in {zone:1443}, in the next guide"] = "für {npc:5395} in {zone:1443}, im nächsten Guide",
		["{area:340} is the Horde fortress built into the cliffs at the zone's western edge."] = "{area:340} ist die Hordefestung, in die Klippen am Westrand des Gebiets gebaut.",
		["{item:3713}, for \"Swamp Eye\" Jarl in {zone:1445}"] = "{item:3713}, für Sumpfauge Jarl in {zone:1445}",
		["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "{quest:678} von {npc:2771} geht als Nächstes gegen Elite-Felsfäuste: Lass sie liegen.",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920}: nur wenn du {item:2868} dabeihast ({skill:164} oder Auktionshaus)",
		["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "{object:1661} hat keinen Jäger- oder Schamanenlehrer: Nimm stattdessen vom selben Turm den Zeppelin nach {zone:1454} und trainiere in der Stadt, dann nimm vom Turm vor dem Haupttor von {zone:1454} den Zeppelin nach {zone:1458}.",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106}: Fizzles Brief aus {area:439}",
		["{zone:1458} trainers"] = "Lehrer in {zone:1458}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Darkfang spiders"] = "Dunkelzahnspinnen",
		["Fly to {area:378}"] = "Flieg nach {area:378}",
		["For {npc:2519} at {object:3202}, in the next guide"] = "Für {npc:2519} in {object:3202}, im nächsten Guide",
		["Hearth to Shadowprey"] = "Ruhestein nach Shadowprey",
		["Hearth to {area:392}"] = "Ruhestein nach {area:392}",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "Jarl wohnt im {area:497} südöstlich vom {area:502}.",
		["Kodo bones and ghosts"] = "Kodoknochen und Geister",
		["Maraudine totems"] = "Totems der Maraudine",
		["Mirefin murlocs"] = "Murlocs der Schlammflossen",
		["Pick up the kodo bones scattered across the graveyard, and use the {item:15848} among the bones: the ghosts it draws drop the ghost-o-plasm."] = "Sammle die über den Friedhof verstreuten Kodoknochen und benutze die {item:15848} zwischen den Knochen: Die angelockten Geister lassen das Geisterplasma fallen.",
		["Ride back west to Brackenwall with the head."] = "Reite mit dem Kopf zurück nach Westen nach Brackenwall.",
		["Ride east back to the {area:497}."] = "Reite nach Osten zurück zum {area:497}.",
		["Ride east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "Reite von {area:378} die Straße entlang nach Osten in die Marschen. Das ausgebrannte {area:403} steht gleich hinter der Grenze daneben; der Schild, die Plakette und die Hufspuren sind in und neben der Ruine.",
		["Ride east to {area:602}. Use the Rod of Banishing by each demon portal to close six of them."] = "Reite nach Osten zu {area:602}. Benutze den Rod of Banishing an jedem Dämonenportal, um sechs davon zu schließen.",
		["Ride north from the coven to {npc:5412} at {area:597}."] = "Reite vom Koven nach Norden zu {npc:5412} am {area:597}.",
		["Ride north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "Reite nach Norden zum {area:502}. Stinki steht am Fuß des Hügels; eskortiere ihn, während er gleich südlich davon Blätter von Sumpfbohnenpflanzen sammelt.",
		["Ride north up the road to the hut by the road north of the graveyard."] = "Reite die Straße hinauf nach Norden zur Hütte an der Straße nördlich des Friedhofs.",
		["Ride north-east to the {area:607}. {npc:12277} is held in the Maraudine centaur camp; free her and escort her out east of the valley."] = "Reite nach Nordosten ins Tal ({area:607}). {npc:12277} wird im Zentaurenlager der Maraudine festgehalten; befreie sie und eskortiere sie nach Osten aus dem Tal hinaus.",
		["Ride on south-west to Shadowprey."] = "Reite weiter nach Südwesten nach Shadowprey.",
		["Ride south from {area:2405} into the {area:607}. The Maraudine Scouts, Wranglers, Maulers, Windchasers and Marauders (36-39) drop the {quest:93225}."] = "Reite von {area:2405} nach Süden ins Tal ({area:607}). Die Späher, Zänker, Raufer, Windhetzer und Marodeure der Maraudine (36-39) lassen {quest:93225} fallen.",
		["Ride west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely."] = "Reite nach Westen zurück durch die Marschen. Die Dunkelzahngiftspucker auf den Kämmen nördlich von Brackenwall lassen die Giftbeutel fallen. Spitzel von Theramore (35-36) schleichen durch dieselben Wälder: Sie sind getarnt, also schau genau hin.",
		["Ride west to {npc:11863}'s tower at {area:2405} on the north-west coast."] = "Reite nach Westen zum Turm von {npc:11863} in {area:2405} an der Nordwestküste.",
		["Slitherblade coast"] = "Küste der Zackenkämme",
		["Stinky Ignatz"] = "Stinki Ignatz",
		["Swamp Eye Jarl"] = "Sumpfauge Jarl",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "Nimm an der Gabelung die Straße nach Norden zum Ogerdorf Brackenwall.",
		["The Burning Blade hold the fortress north-west of {area:2407}. Use the {item:14523} on the {npc:11876} in the fortress to get the {item:13542}."] = "Die Burning Blade hält die Festung nordwestlich von {area:2407}. Benutze {item:14523} an {npc:11876} in der Festung, um {item:13542} zu bekommen.",
		["The Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes."] = "Die Graunebelspinnen wimmeln am Höhleneingang nordwestlich von Brackenwall; jede Art lässt Augen fallen.",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "Die Murlocs der Schlammflossen drängen sich an der Küste östlich und nordöstlich vom {area:502}; jede Art lässt Köpfe fallen.",
		["The Slitherblade naga hold the coast north of {area:2405}, up to {area:598}. {npc:12369} guards the {quest:6027} at the far northern tip."] = "Die Naga der Zackenkämme halten die Küste nördlich von {area:2405} bis zum {area:598}. {npc:12369} bewacht {quest:6027} an der äußersten Nordspitze.",
		["The caravan ends at {npc:11596}'s camp on the east side of the {area:596}."] = "Die Karawane endet in {npc:11596}s Lager auf der Ostseite des Friedhofs ({area:596}).",
		["The next guide takes you back to {zone:1434}."] = "Der nächste Guide bringt dich zurück ins {zone:1434}.",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "nur, wenn du ein {item:3853} dabeihast ({skill:164} oder Auktionshaus)",
		["{npc:11626}'s caravan stops on the road at the edge of {area:602}. Escort it east past the coven; demons attack it twice."] = "Die Karawane von {npc:11626} hält auf der Straße am Rand von {area:602}. Eskortiere sie nach Osten am Koven vorbei; Dämonen greifen sie zweimal an.",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, am Südrand des Dorfs, wo die Straße hereinkommt",
		["{npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out."] = "{npc:4983} wartet im Morast ({area:2302}) östlich des Dorfs. Folge ihm zu Reethe und halte ihn im ausbrechenden Kampf am Leben.",
		["{npc:5395} and {npc:5412} stand in the post just west of {npc:11596}'s camp."] = "{npc:5395} und {npc:5412} stehen im Posten gleich westlich von {npc:11596}s Lager.",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019} wartet im Goblinlager auf der Westseite des Friedhofs ({area:596}).",
		["{object:20985}, beside the manor"] = "{object:20985}, neben dem Anwesen",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, jetzt wo {npc:4791} den Bericht gelesen hat",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Boat to {area:35}"] = "Schiff nach {area:35}",
		["Draenethyst crystals"] = "Draenethystkristalle",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "Folge der Küste nach Süden. Die Forscher der Naga waten am Ufer entlang und tragen die Schilfbündel; {object:759} sprudelt in den Hügeln gleich östlich davon.",
		["From {area:2408} fly to {area:392}."] = "Flieg von {area:2408} nach {area:392}.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals."] = "Weiter nördlich graben die Goblins der Venture Co. in der Mine östlich der Straße; Minenarbeiter, Großknechte, Feldmesser und Tüftler lassen alle die Kristalle fallen.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "Gib Unbagwa die Fangzähne und bleib bei ihm: Er ruft drei Wellen Gorillas, dann {npc:1514}. Kämpf einzeln gegen sie.",
		["Hearth to {area:35}"] = "Ruhestein nach {area:35}",
		["Hearth to {object:3202}"] = "Ruhestein nach {object:3202}",
		["His strongbox waits at his old camp north of {area:75}."] = "Seine Geldkassette wartet in seinem alten Lager nördlich von {area:75}.",
		["Into the {zone:1435}"] = "In die {zone:1435}",
		["Jungle stalkers"] = "Dschungelpirscher",
		["Keep riding north into {zone:1431}, then east along the road through {zone:1430} into the swamp. {npc:1776} waits at the {area:657}, the draenei camp near the way in from {zone:1430}."] = "Reite weiter nach Norden in den {zone:1431}, dann auf der Straße nach Osten durch den {zone:1430} in den Sumpf. {npc:1776} wartet bei {area:657}, dem Draeneilager nahe dem Weg vom {zone:1430} herein.",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "Verlass den Ort durch den Tunnel; die Notiz liegt in der Piratenbucht gleich nördlich von {area:35}.",
		["Mistvale gorillas"] = "Nebeltalgorillas",
		["Naga shore and the {object:759}"] = "Nagaufer und {object:759}",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "Noboru wandert über die Lichtung südwestlich vom {area:76}; sein Knüppel startet eine Quest.",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "Nordöstlich des Nebeltals lagern Zanzils Anhänger im Dschungel; jeder von ihnen kann die Mixtur tragen.",
		["Pirate ghosts"] = "Piratengeister",
		["Ride back east past {area:75} and follow the road south-east to the small Horde post on the shore."] = "Reite zurück nach Osten an {area:75} vorbei und folge der Straße nach Südosten zum kleinen Hordeposten am Ufer.",
		["Ride east to {area:75}, in the reeds south of the road."] = "Reite nach Osten nach {area:75}, im Schilf südlich der Straße.",
		["Ride north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "Reite nach Norden zu den Ruinen der Skullsplitter östlich der Mine der Venture Co.; zieh die Kopfjäger und Berserker einzeln. {npc:1059} bewacht die südwestlichen Ruinen, und ein Haufen Trophäenschädel steht auf der Nordseite der Ruinen. Jeder Skullsplitter kann einen Hauer oder eine Halskette fallen lassen: Die Halsketten dauern am längsten, also töte im Kriegerlager nördlich der Ruinen weiter, bis du alle hast.",
		["Ride north up the road to the hunters' camp."] = "Reite die Straße nach Norden hinauf zum Lager der Jäger.",
		["Ride north up the road; the hunters camp on the hill above the river."] = "Reite die Straße nach Norden hinauf; die Jäger lagern auf dem Hügel über dem Fluss.",
		["Ride north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "Reite nach Nordosten zum {area:76}. Die Kristalle stehen am Weg hinauf zum Käfig von {npc:5391}.",
		["Ride north-west to {object:3202}."] = "Reite nach Nordwesten nach {object:3202}.",
		["Ride south to {area:35}. Shaky Phillipe waits on the docks."] = "Reite nach Süden nach {area:35}. Der zittrige Phillipe wartet an den Docks.",
		["Ride west along the road to the draenei camp at the {area:657}, near the way in from {zone:1430}."] = "Reite auf der Straße nach Westen zum Draeneilager bei {area:657}, nahe dem Weg vom {zone:1430} herein.",
		["Ride west to {object:3202}."] = "Reite nach Westen nach {object:3202}.",
		["Sawtooth crocolisks"] = "Sägezahnkrokilisken",
		["Sawtooth snappers"] = "Sägezahnschnapper",
		["Skullsplitter warriors"] = "Krieger der Skullsplitter",
		["South of Booty Bay the Bloodsail swashbucklers camp on the {area:43}; the charts and the orders lie in their tents. Any Bloodsail can carry snuff and {npc:2493}'s eye, so keep killing until you have both."] = "Südlich von Booty Bay lagern die Schwadroneure der Blutsegelbukaniere an der {area:43}; die Karten und Befehle liegen in ihren Zelten. Jeder Blutsegelbukanier kann Schnupftabak und {npc:2493}s Auge tragen, also töte weiter, bis du beides hast.",
		["Take the road north out of {area:35}; Unbagwa sits on a hill in {area:1737}, east of the road."] = "Nimm die Straße nach Norden aus {area:35}; Unbagwa sitzt auf einem Hügel in {area:1737}, östlich der Straße.",
		["The Bloodsail ships"] = "Die Schiffe der Blutsegelbukaniere",
		["The boat lands in {area:35}'s harbour. The quest givers stand on the boardwalks around the harbour and in the inn."] = "Das Schiff legt im Hafen von {area:35} an. Die Questgeber stehen auf den Stegen rund um den Hafen und im Gasthaus.",
		["The boat to {area:35} docks at the end of {area:392}'s pier."] = "Das Schiff nach {area:35} legt am Ende des Piers von {area:392} an.",
		["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank."] = "Die Krokilisken suhlen sich in den Tümpeln um {npc:5391}s Lager und südlich Richtung {area:75}; etwa jeder vierte lässt eine Flanke fallen.",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "Die Gorillas streifen durch das Tal um Unbagwa. Die Alten lassen die Innereien fallen; jeder kann einen Fangzahn fallen lassen.",
		["The last skulls are in the ruins a short ride west, on the way back to {object:3202}."] = "Die letzten Schädel sind in den Ruinen ein kurzes Stück westlich, auf dem Rückweg nach {object:3202}.",
		["The next guide starts here and takes you to {zone:1446}."] = "Der nächste Guide beginnt hier und bringt dich nach {zone:1446}.",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp."] = "Die nächsten Trophäenschädel stehen in den kleinen Ruinen gleich nördlich des Kriegerlagers.",
		["The snappers line the strand south of the post."] = "Die Schnapper säumen den Strand südlich des Postens.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "Die Pirscher-Raptoren jagen im Dschungel südlich von {object:3202}, hinaus Richtung Westküste.",
		["The three ghostly pirates haunt the jungle north of {area:35}, near Zanzil's camps: {npc:2535} and {npc:2536} stand together, {npc:2537} further east."] = "Die drei geisterhaften Piraten spuken im Dschungel nördlich von {area:35}, nahe Zanzils Lagern: {npc:2535} und {npc:2536} stehen zusammen, {npc:2537} weiter östlich.",
		["The three ships lie off the {area:43}. The crews are 42-45, Stillwater 45, Keelhaul 46 and {npc:2546} 48: at 41 this is a fight for a group, or for the end of the guide. If you go, swim out and pull the crew to the rail one at a time. A scroll, {quest:624}, lies on the ships' decks: take it."] = "Die drei Schiffe liegen vor der {area:43}. Die Besatzungen sind 42-45, Stillwasser 45, Kielhol 46 und {npc:2546} 48: Mit 41 ist das ein Kampf für eine Gruppe oder für das Ende des Guides. Wenn du hingehst, schwimm hinaus und zieh die Besatzung einzeln an die Reling. Eine Schriftrolle, {quest:624}, liegt auf den Decks der Schiffe: Nimm sie mit.",
		["The {area:43}"] = "{area:43}",
		["Venture Co. mine"] = "Mine der Venture Co.",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "Westlich der Expedition stehen die Häuptlinge der Bloodscalp, {npc:1061} und {npc:1062}, zusammen in den Ruinen von Zul'Kunda. Räum zuerst ihre Wachen weg und zieh dann die beiden.",
		["Zanzil's camps"] = "Lager von Zanzil",
		["Zul'Kunda"] = "Ruinen von Zul'Kunda",
		["Zul'Mamwe"] = "Ruinen von Zul'Mamwe",
		["for Stoley in {zone:1446}"] = "für Stoley in {zone:1446}",
		["for a later stop in the {zone:1435}"] = "für einen späteren Halt in den {zone:1435}",
		["for later: the {zone:1425}, around level 48"] = "für später: das {zone:1425}, etwa ab Stufe 48",
		["the {object:2076}"] = "{object:2076}",
		["the {object:2076}, beside {npc:2497}"] = "{object:2076}, neben {npc:2497}",
		["{area:392} pier"] = "Pier von {area:392}",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391} wird im {area:76} im Nordosten des Sumpfs gefangen gehalten. Befrei ihn und folge ihm hinaus; wehr die Sumpfkreaturen ab, die ihn verfolgen.",
		["{npc:773}: for {quest:2864} in {area:976}"] = "{npc:773}: für {quest:2864} in {area:976}",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Eastern Wastewander camps"] = "Östliche Lager der Wüstenläufer",
		["Fly to {area:1637}. The Droffers brothers run their shop in the Drag."] = "Flieg nach {area:1637}. Die Gebrüder Droffers führen ihren Laden in der Gasse.",
		["Fly to {area:484}"] = "Flieg zum {area:484}",
		["Fly to {area:484}, ride down the lift east of the post and across the salt flats, then south into {zone:1446}."] = "Flieg zum {area:484}, fahr mit dem Aufzug östlich des Postens hinunter und reite über die Salzebenen, dann nach Süden nach {zone:1446}.",
		["Fly to {area:484}, then ride west through the canyons past {area:2237}; the road climbs into the {zone:1444} jungle and on to {area:1099}."] = "Flieg zum {area:484} und reite dann nach Westen durch die Schluchten am {area:2237} vorbei; die Straße steigt in den Dschungel von {zone:1444} hinauf und führt weiter zum {area:1099}.",
		["Fly to {area:75}"] = "Flieg nach {area:75}",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Galestriders: {npc:265756}, in {area:16638} on Zephras Isle."] = "Windschreiter: {npc:265756}, in {area:16638} auf der Insel Zephras.",
		["Grimtotem camp"] = "Lager der Grimmtotem",
		["Hearth to {area:1099}"] = "Ruhestein zum {area:1099}",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "Reite weiter nach Westen zur Küste. Die Küstenkriechertiefseher und Küstenkriecherschnappklauen an den Stränden lassen etwa bei jedem vierzigsten Kill das Notsignal von OOX-22/FE fallen: Fällt eins, benutze es, um die Quest zu starten.",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "Kodos: {npc:3685}, neben {npc:3690} in {area:222}.",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "Nördlich der Gnolle halten die Oger einen Außenposten auf einem Hügel; zieh die Ogermagier zu dir. Das Kobalt ist in den Erdhügeln um den Außenposten, und die Schriftrolle liegt drinnen auf dem Boden.",
		["Only with the distress beacon: the robot sits in a small cave on the north side of {area:1105}. Escort it to the dock on the {area:1108}; yetis and gorillas ambush you on the way. Its reward waits in {area:35} for a later visit."] = "Nur mit dem Notsignalgeber: Der Roboter sitzt in einer kleinen Höhle auf der Nordseite von {area:1105}. Eskortiere ihn zum Steg an {area:1108}; Yetis und Gorillas überfallen euch unterwegs. Seine Belohnung wartet in {area:35} auf einen späteren Besuch.",
		["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "Raptoren: Zjolnir, neben {npc:7953} in {area:367}.",
		["Ride back north-west from {area:1978} to {area:75} and fly to {object:3202}."] = "Reite von {area:1978} zurück nach Nordwesten nach {area:75} und flieg nach {object:3202}.",
		["Ride back west to {area:976}."] = "Reite zurück nach Westen nach {area:976}.",
		["Ride north-east to the goblin harbour on the coast."] = "Reite nach Nordosten zum Goblinhafen an der Küste.",
		["Ride south-west to the ogre ruins below {area:1105}. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb."] = "Reite nach Südwesten zu den Ogerruinen unterhalb von {area:1105}. Schamanen, Hexenmeister und Raufer füllen sie; die Magierlords am Südende tragen die Kugel.",
		["Ride west into the middle of {zone:1444}. Kill a {npc:5308}, use {item:10699} on its body and kill the spirit that rises."] = "Reite nach Westen in die Mitte von {zone:1444}. Töte einen {npc:5308}, benutze {item:10699} an seiner Leiche und töte den Geist, der aufsteigt.",
		["Riding at 40"] = "Reiten mit 40",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is {npc:3690} in {area:222}, with {npc:3685}'s kodos (20 gold each) beside him. Forever may let any race learn from any riding trainer (not confirmed): try {npc:4752} in {zone:1454}'s {object:172958} first, as he is the nearest, and skip this step if he teaches you."] = "Reiten erfordert Stufe 40 und kostet 100 Gold; beim Erlernen erhältst du ein Reittier. In Classic lernt es jedes Volk beim Lehrer seines eigenen Volkes: Deiner ist {npc:3690} in {area:222}, mit den Kodos von {npc:3685} (je 20 Gold) neben ihm. Forever lässt vielleicht jedes Volk bei jedem Reitlehrer lernen (nicht bestätigt): Versuch es zuerst bei {npc:4752} im {object:172958} von {zone:1454}, er ist am nächsten, und überspring diesen Schritt, wenn er es dir beibringt.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is {npc:4773} in {area:159}, with {npc:4731}'s skeletal horses (20 gold each) beside her. Forever may let any race learn from any riding trainer (not confirmed): try {npc:4752} in {zone:1454}'s {object:172958} first, as he is the nearest, and skip this step if he teaches you."] = "Reiten erfordert Stufe 40 und kostet 100 Gold; beim Erlernen erhältst du ein Reittier. In Classic lernt es jedes Volk beim Lehrer seines eigenen Volkes: Deiner ist {npc:4773} in {area:159}, mit den Skelettpferden von {npc:4731} (je 20 Gold) neben ihr. Forever lässt vielleicht jedes Volk bei jedem Reitlehrer lernen (nicht bestätigt): Versuch es zuerst bei {npc:4752} im {object:172958} von {zone:1454}, er ist am nächsten, und überspring diesen Schritt, wenn er es dir beibringt.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is {npc:7953} in {area:367} on the {zone:1411} coast, with Zjolnir's raptors (20 gold each) beside him. Forever may let any race learn from any riding trainer (not confirmed): try {npc:4752} in {zone:1454}'s {object:172958} first, as he is the nearest, and skip this step if he teaches you."] = "Reiten erfordert Stufe 40 und kostet 100 Gold; beim Erlernen erhältst du ein Reittier. In Classic lernt es jedes Volk beim Lehrer seines eigenen Volkes: Deiner ist {npc:7953} in {area:367} an der Küste von {zone:1411}, mit Zjolnirs Raptoren (je 20 Gold) neben ihm. Forever lässt vielleicht jedes Volk bei jedem Reitlehrer lernen (nicht bestätigt): Versuch es zuerst bei {npc:4752} im {object:172958} von {zone:1454}, er ist am nächsten, und überspring diesen Schritt, wenn er es dir beibringt.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel; no Skyborne riding trainer is known, so Skyborne try {npc:4752} too. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "Reiten erfordert Stufe 40 und kostet 100 Gold; beim Erlernen erhältst du ein Reittier. {npc:4752} lehrt Orcs im {object:172958}, beim Zwinger von {npc:3362}; es ist kein Reitlehrer der Himmelsgeborenen bekannt, also versuchen es Himmelsgeborene ebenfalls bei {npc:4752}. Die übrigen Reittiere deines Volkes kosten je 20 Gold: Sammelobjekte, Reittiere · Stufe 40 hat für jedes einen Guide.",
		["Rogue Vale screechers"] = "Kreischer",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "Skelettpferde: {npc:4731}, neben {npc:4773} in {area:159}.",
		["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often."] = "Weiter südlich an der Küste halten die Südmeerfreibeuter die Bucht. {npc:7883} und die gestohlene Fracht sind auf den Docks am hinteren Ende. Jeder Pirat kann einen Hut fallen lassen, die Entführer am häufigsten.",
		["Southern Gordunni ruins"] = "Südliche Ruinen der Gordunni",
		["Southern Wastewander camps"] = "Südliche Lager der Wüstenläufer",
		["Sprite darters and Woodpaw alphas"] = "Grimmlingflitzer und Alphas der Waldpfoten",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "Die Tauren der Grimmtotem lagern neben dem Hain der Grimmlingflitzer; Räuber, Naturalisten und Schamanen tragen alle Hörner.",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane."] = "Die Gnolle der Waldpfoten lagern in den Hügeln gleich nordwestlich von Mojache; jeder kann eine Mähne fallen lassen.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "Der Bau der Zukk'ash gräbt sich in die Hügel südöstlich des Lagers; {quest:7731} wartet in seiner tiefsten Kammer.",
		["The bandits and thieves camp in the dunes east of {area:976}. Every Wastewander can carry a water pouch: keep ten, five for each of Luglunket's bounties."] = "Die Banditen und Diebe lagern in den Dünen östlich von {area:976}. Jeder Wüstenläufer kann einen Wasserbeutel tragen: Behalte zehn, fünf für jedes von Luglunkets Kopfgeldern.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "Der Schlachtplan liegt im Lager der Waldpfoten südlich von Mojache.",
		["The shadow mages, rogues and assassins camp south-east of {area:976}."] = "Die Schattenmagier, Schurken und Auftragsmörder lagern südöstlich von {area:976}.",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour."] = "Die Grimmlingflitzer schwirren über dem Hain gleich westlich von Mojache; fast jeder lässt einen Flügel fallen. Die Alphas der Waldpfoten führen die Lager südwestlich davon: Töte sie innerhalb der Stunde.",
		["The {object:3202} zeppelin leaves from the tower just north-east of {zone:1454}'s main gate."] = "Der Zeppelin nach {object:3202} startet vom Turm gleich nordöstlich des Haupttors von {zone:1454}.",
		["The {zone:1454} zeppelin leaves from the tower beside {object:3202}; it lands just outside {zone:1454}'s main gate."] = "Der Zeppelin nach {zone:1454} startet vom Turm neben {object:3202}; er landet gleich vor dem Haupttor von {zone:1454}.",
		["Thysta, the flight master, stands just east of the zeppelin tower. Fly to {area:75}: the next guide starts there."] = "Thysta, die Flugmeisterin, steht gleich östlich des Zeppelinturms. Flieg nach {area:75}: Dort beginnt der nächste Guide.",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Wölfe: {npc:3362}, neben {npc:4752}.",
		["Woodpaw battle map"] = "Schlachtplan der Waldpfoten",
		["Woodpaw north camp"] = "Nördliches Lager der Waldpfoten",
		["Your trainer is in {area:1638}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly there from {zone:1454}, then on to {area:484}."] = "Dein Lehrer ist in {area:1638}: {npc:3033} (Druiden) auf der {area:1639}, {npc:246344} (Paladine). Flieg von {zone:1454} dorthin, dann weiter zum {area:484}.",
		["Zeppelin to {object:3202}"] = "Zeppelin nach {object:3202}",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["Zeppelin tower"] = "Zeppelinturm",
		["for the {zone:1425}, around level 48"] = "für das {zone:1425}, etwa ab Stufe 48",
		["for {area:35}, around level 50"] = "für {area:35}, etwa ab Stufe 50",
		["for {zone:1454}, around level 45"] = "für {zone:1454}, etwa ab Stufe 45",
		["the {object:150075} in the square"] = "{object:150075} auf dem Platz",
		["water pouches in your bags"] = "Wasserbeutel in deinen Taschen",
		["{area:392} for the Felsteed"] = "{area:392} für das Teufelsross",
		["{area:976} is the walled goblin town just past the {zone:1446} border."] = "{area:976} ist die ummauerte Goblinstadt gleich hinter der Grenze von {zone:1446}.",
		["{npc:3690}, riding trainer"] = "{npc:3690}, Reitlehrer",
		["{npc:4752}, riding trainer"] = "{npc:4752}, Reitlehrer",
		["{npc:4773}, riding trainer"] = "{npc:4773}, Reitlehrerin",
		["{npc:7953}, riding trainer"] = "{npc:7953}, Reitlehrer",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}: für {zone:1454}, etwa ab Stufe 45",
		["{npc:8579}: the screechers live in {zone:1444}"] = "{npc:8579}: Die Kreischer leben in {zone:1444}",
		["{quest:2863}: one hour from now"] = "{quest:2863}: eine Stunde ab jetzt",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "Zurück nach Osten an {area:75} vorbei: Die Artefakte der Atal'ai liegen im Wasser und an den Ufern des {quest:1424}.",
		["Dragon caves"] = "Drachenhöhlen",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Forest walkers"] = "Waldgänger",
		["Frayfeather hippogryphs"] = "Fransenfederhippogryphen",
		["Monstrous Crawlers"] = "Monströse Kriecher",
		["Murlocs of the Misty Reed"] = "Murlocs am Nebelschilf",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "Nordwestlich an der Straße leben die Wutschrammyetis um die Höhlen in den Hügeln. Jeder kann auch {quest:7738} fallen lassen, der eine eigene Quest startet.",
		["Northspring harpies"] = "Harpyien der Nordschwingen",
		["Onyxia's eggs"] = "Onyxias Eier",
		["Rage Scar yetis"] = "Wutschrammyetis",
		["Ride back east to the camp. Stay here: the next guide starts with the flight to {area:976}."] = "Reite zurück nach Osten zum Lager. Bleib hier: Der nächste Guide beginnt mit dem Flug nach {area:976}.",
		["Ride back north to Brackenwall."] = "Reite zurück nach Norden nach Brackenwall.",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "Reite nach Nordwesten zur {area:1108}; {npc:14637} wartet am Steg.",
		["Ride south-west to the {object:2555}, then east through the {area:511}. The Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "Reite nach Südwesten zu {object:2555}, dann nach Osten durch {area:511}. Die Späher und Aschenschweife der Feuermähnen streifen mit den Sengenden Jungtieren und Welpen über seinen Nordrand; die Bannschuppen bewachen die Drachenhöhlen weiter südöstlich. Mok'Morokks Schnupftabak, Grog und Geldkassette liegen in den Lagern der Drachkin.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Reite auf der Straße nach Westen; die Schriftrolle liegt am Wasser im äußersten Westen des Sumpfs.",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "Meereselementare und Meeresschauer spülen um den Steg am Ufer entlang. Schrumpfe die Riesen zuerst mit {item:18904}: Geschrumpft verlieren sie ihre Elitestärke. Uferschreiter waten im Wasser; die Landgänger und Klippenriesen streifen weiter nördlich durch die Hügel.",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "Südlich des Tals nisten die Fransenfederhippogryphen an den Hängen; fast jeder lässt Sehnen und metallische Fragmente fallen.",
		["South-west, the yetis den in {area:1105}; every yeti there can drop a thick hide."] = "Im Südwesten hausen die Yetis in {area:1105}; jeder Yeti dort kann einen dicken Balg fallen lassen.",
		["Sprite darters and forest walkers"] = "Grimmlingflitzer und Waldgänger",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "Die Eier von Onyxia liegen in den Drachenhöhlen im Südosten von {area:511}, bewacht von den Bannschuppen; zerschlag fünf.",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "Die Marschenmurlocs leben am Strand südlich des Postens; die Marschentintenspucker sind am Ufer östlich davon und die Marschenfleischfresser weiter westlich, um die Hütten am Westufer.",
		["The Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see on the way south."] = "Die Monströsen Kriecher laufen über die Strände der Ostküste, nur vereinzelt: Töte jeden, den du auf dem Weg nach Süden siehst.",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "Die Harpyien der Nordschwingen nisten auf den Kämmen im äußersten Nordwesten. Sie sind 48-50, ein paar Stufen über dir: Die Windruferinnen heilen, also töte sie zuerst und zieh einzeln.",
		["The same murlocs again, plus the Oracles, who stay near the huts on the western shore."] = "Wieder dieselben Murlocs, dazu die Orakel, die nahe den Hütten am Westufer bleiben.",
		["The small Horde post on the southern shore."] = "Der kleine Hordeposten am Südufer.",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "Die Grimmlingflitzer schwirren über dem Hain gleich westlich des Lagers und tragen {item:9589}; die Wandernden Waldgänger, etwas weiter westlich, tragen die Abgesplitterten Baumstämme.",
		["The zeppelin to {zone:1454} leaves from the tower beside {object:3202}; it lands just north-east of {zone:1454}'s main gate."] = "Der Zeppelin nach {zone:1454} startet vom Turm neben {object:3202}; er landet gleich nordöstlich des Haupttors von {zone:1454}.",
		["The {area:511}"] = "{area:511}",
		["You start in {area:75}. Bind here: you hearth back after the coast."] = "Du beginnst in {area:75}. Binde dich hier: Nach der Küste kehrst du mit dem Ruhestein zurück.",
		["Your trainer is in {area:1638}: fly there (no flight path there yet? fly to {area:378} and ride west through {zone:1412}), then on to {area:496}."] = "Dein Lehrer ist in {area:1638}: Flieg dorthin (noch keine Flugroute dort? Flieg zum {area:378} und reite nach Westen durch {zone:1412}), dann weiter nach {area:496}.",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["Zeppelin tower"] = "Zeppelinturm",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "für {npc:5598} im {zone:1425}, etwa ab Stufe 48",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "für {object:2555} in {zone:1445}, später in diesem Guide",
		["for the {zone:1425} owlbeasts, around level 48"] = "für die Eulenbestien im {zone:1425}, etwa ab Stufe 48",
		["the {object:2555}"] = "{object:2555}",
		["{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "{npc:4500} ist Elite: Such dir am besten eine Gruppe. Prügle ihn runter, bis er aufgibt, und melde dich dann bei {npc:4501}.",
		["{npc:7875}: for {npc:7010} in {zone:1454}, around level 50"] = "{npc:7875}: für {npc:7010} in {zone:1454}, etwa ab Stufe 50",
		["{object:172958}, then the {object:172960} and the {object:172961}."] = "{object:172958}, dann {object:172960} und {object:172961}.",
		["{quest:7738}, a rare drop"] = "{quest:7738}, eine seltene Beute",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Boat to {area:35}"] = "Boot nach {area:35}",
		["Dark Iron Lookouts"] = "Ausgucke der Dunkeleisenzwerge",
		["Fly to {area:1637} and train: the next guide's training stop is the {zone:1458}, which has no Hunter or Shaman trainer. Then fly to {area:392}."] = "Flieg nach {area:1637} und trainiere: Der Trainingshalt im nächsten Guide ist {zone:1458}, wo es keinen Jäger- oder Schamanenlehrer gibt. Flieg dann nach {area:392}.",
		["Fly to {area:1638} and train with {npc:3033} on {area:1639}, then fly to {area:392}."] = "Flieg nach {area:1638}, trainiere bei {npc:3033} auf der Anhöhe ({area:1639}) und flieg dann nach {area:392}.",
		["Fly to {area:340}"] = "Flieg nach {area:340}",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Fly to {area:976}"] = "Flieg nach {area:976}",
		["From the {area:35} flight master, above the harbour."] = "Vom Flugmeister in {area:35}, oberhalb des Hafens.",
		["From {area:1099}'s flight master."] = "Vom Flugmeister in {area:1099}.",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive."] = "Weiter südlich liegt die Ausrüstung von Junior Surveyor Scrimshank am Eingang eines Baus der Centipaar.",
		["Greater Lava Spiders"] = "Große Lavaspinnen",
		["Heavy War Golems patrol the Cauldron below Kalaran and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it."] = "Schwere Kriegsgolems patrouillieren im Kessel unter Kalaran und lassen das Öl fallen; die Magmaelementare und Lodernden Elementare zwischen ihnen lassen die Herzen fallen. Die Zuchtmeister und Sklavenhändler der Dunkeleisenzwerge treiben die Sklaven auf den Wegen an; ein Sklavenhändler kann {item:11818} fallen lassen: Behalte ihn.",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Seine nächste Bitte braucht das {item:10552} von Elitekultisten: Lass sie aus.",
		["Kalaran stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "Kalaran steht allein südlich von {area:1446}, am Rand des Kessels. Hör dir seine Geschichte an.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to {area:977}; its reward waits with Oglethorpe in {area:35}."] = "Nur mit dem Notsignalgeber: OOX-17/TN sitzt südöstlich von Scrimshanks Bau. Eskortiere ihn nach Norden nach {area:977}; seine Belohnung wartet bei Oglethorpe in {area:35}.",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Nur mit dem {item:11818}: zurück nach Osten zum {object:173265} an der Grabungsstätte.",
		["Ride back north to {area:1446}. Stay here: the next guide starts with the flight to {area:75}."] = "Reite zurück nach Norden zur {area:1446}. Bleib hier: Der nächste Guide beginnt mit dem Flug nach {area:75}.",
		["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "Reite nach Nordwesten durch die Schlucht; {area:1446} ist das Lager mit den Gerüsten im Nordwesten.",
		["Ride south-west to {area:976}."] = "Reite nach Südwesten nach {area:976}.",
		["Scrimshank's gear"] = "Scrimshanks Ausrüstung",
		["South down the road again."] = "Wieder die Straße hinunter nach Süden.",
		["South of the {area:982} the Dunemaul ogres hold their compound, with {npc:12046} at its eastern end. Dig up {quest:3161} ornaments between the fights."] = "Südlich von {area:982} halten die Oger der Dünenbrecher ihr Truppenlager, mit {npc:12046} am östlichen Ende. Grab zwischen den Kämpfen {quest:3161}-Ornamente aus.",
		["South-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp."] = "Südöstlich von Gadgetzan lagern die Banditen der Wüstenläufer in den Dünen; {npc:7847} steht im östlichen Lager.",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south-west to the dig site. The {object:173265} stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 {item:4306} (the Auction House sells it)."] = "Nimm den Pass auf der Westseite von {area:340} in die {zone:1427} und reite dann nach Südwesten zur Grabungsstätte. {object:173265} steht an ihrem Südende; die Geologen der Dunkeleisenzwerge graben gleich nördlich davon. Bring 15 {item:4306} mit (gibt es im Auktionshaus).",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "Die Ausgucke der Dunkeleisenzwerge stehen auf den Kämmen um die Wachtürme südlich des Kessels; etwa jeder zehnte trägt {item:18960}.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Die Dampfschmiede der Dunkeleisenzwerge arbeiten an den Öfen mitten im Kessel; die Hälfte trägt {item:10551}, jeder zehnte {item:18959}. Sklaven, Sklavenhändler und Zuchtmeister tragen auch Dolche.",
		["The Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge."] = "Die Großen Lavaspinnen streifen über die Plateaus und Lavabecken im Südwesten der Schlucht.",
		["The Steamsmiths' furnaces"] = "Die Öfen der Dampfschmiede",
		["The boat to {area:35} docks at {area:392}'s pier, below the flight master's hill."] = "Das Boot nach {area:35} legt am Pier von {area:392} an, unterhalb des Hügels des Flugmeisters.",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "Das Brett {object:179827}",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "Nach Westen entlang der Straße nach Süden; {npc:7771} lagert bei den Ruinen an der {area:1938}. Leg seinen {item:9978} an: Er zeigt die vergrabenen Ornamente, hier und rund um das {area:983}.",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "Benutze westlich von Gadgetzan das {item:8584} neben dem Wasserloch im Trolllager.",
		["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in {zone:1446} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one."] = "Westlich des Truppenlagers füllen die Kakteenwesen das Tal; nur die Disteltausammler tragen eine Taudrüse. Die meisten Mobs in {zone:1446} können selten den OOX-17/TN-Notsignalgeber fallen lassen: Behalte ihn, wenn du einen siehst.",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts."] = "Im Westen schwärmen die Insekten der Centipaar um ihre Baue; jedes kann die Teile fallen lassen.",
		["for {npc:7010} in {area:1637}, around level 50"] = "für {npc:7010} in {area:1637}, etwa auf Stufe 50",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526} wächst im {zone:1425}, etwa auf Stufe 48",
		["the {object:150075} in the square"] = "der {object:150075} auf dem Platz",
		["the {object:173265}"] = "das {object:173265}",
		["{area:1443} opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge."] = "{area:1443} öffnet sich im Norden des Kessels. Incendosaurier schwimmen in ihren Lavabecken: Pull sie an den Rand. Die geheimen Pläne liegen auf dem oberen Sims der Grube.",
		["{area:392} pier"] = "Pier von {area:392}",
		["{item:11818}, a rare drop"] = "{item:11818}, seltene Beute",
		["{item:8623}, a rare drop"] = "{item:8623}, seltene Beute",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955} wartet im Tal. Bring ihn den ganzen Weg zu seiner Frau {npc:6015} in {area:977}, nach Nordosten durch die Wüste: Bleib nah bei ihm, geh langsam für ihn und wehr ab, was ihn angreift. Steig nicht auf und nutz keinen Ruhestein außerhalb seiner Reichweite. {npc:8579} steht auch im Hafen.",
		["{npc:5955}'s escort"] = "Eskorte: {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, neben dem Windreitermeister",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "Zurück nach Westen zur {area:350}; Waldläuferinnen und Schützen bleiben nahe der Jagdhütte, Späher und Kundschafterinnen an den Hängen südlich davon.",
		["East of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south."] = "Östlich der Straße wühlen Aschmähneneber und Suhlamane an den Hängen neben den Rotsteinbasilisken. Halte dich von den Höllenebern der Stufe 52 weiter südlich fern.",
		["East of the village, the violet flower grows in the hills."] = "Östlich des Dorfs wächst der Violette Tragan in den Hügeln.",
		["Fly to the {area:1497}"] = "Flieg nach {area:1497}",
		["Fly to {area:272}"] = "Flieg nach {area:272}",
		["Fly to {area:75}"] = "Flieg nach {area:75}",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "Folge den Straßen nach Osten durch das {zone:1425} zum Trolldorf an der Ostküste.",
		["From {area:1446}'s flight master."] = "Vom Flugmeister am {area:1446}.",
		["Grind to 48"] = "Bis 48 grinden",
		["Highvale"] = "Hochtal",
		["His next request, going on to the {area:355}, is for a group."] = "Seine nächste Bitte, weiter zu {area:355}, ist etwas für eine Gruppe.",
		["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. Keep to the paths: the trolls inside are elite."] = "Malkors Schädel liegt auf einem Haufen unterhalb der Ruinen der Vilebranch, Malkors Knochen auf einem Haufen am Fuß von {area:354}. Die Gefäße mit besudelten Blut stehen auf den unteren Terrassen, und {npc:14757} wird oben festgehalten. Bleib auf den Wegen: Die Trolle drinnen sind Elite.",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "Nördlich an der Küste steht der Picknickkorb von {npc:14731} auf der kleinen Insel; ein {npc:14748} bewacht ihn.",
		["OOX-09/HL"] = "OOX-09/HL",
		["On the way back east, the Vilebranch soothsayers hold the {area:355}, the troll temple south of the central hills. Qiaga and {npc:8636} (elite, 50) stand at its top: take the soothsayers on the lower steps."] = "Auf dem Rückweg nach Osten halten die Sterndeuter der Vilebranch {area:355}, den Trolltempel südlich der zentralen Hügel. Qiaga und {npc:8636} (Elite, 50) stehen oben: Nimm dir die Sterndeuter auf den unteren Stufen vor.",
		["Only if you are not level 48 yet."] = "Nur wenn du noch nicht Stufe 48 bist.",
		["Only with the distress beacon: the robot sits at the head of the river west of {area:351}. Escort it east to the shore beyond the {area:307}; its reward waits with Oglethorpe in {area:35}."] = "Nur mit dem Notsignal: Der Roboter sitzt an der Quelle des Flusses westlich vom {area:351}. Eskortiere ihn nach Osten zum Ufer hinter den {area:307}; seine Belohnung wartet bei Oglethorpe in {area:35}.",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "Reite ganz nach Westen zur Stadt der Wildhammer, {area:348}, und leg die Nachricht beim Brunnen in ihrer Mitte ab. Die Stadt ist voller Wachen der Allianz: Rein, ablegen, raus.",
		["Ride back north to the bloodmages."] = "Reite zurück nach Norden zu den Blutmagiern.",
		["Ride north back to {area:75} and fly to the {area:1497}."] = "Reite nach Norden zurück nach {area:75} und flieg nach {area:1497}.",
		["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "Reite von {area:272} nach Nordosten ins {zone:1425} und auf der Straße nach Osten; {npc:7801} lagert auf dem Hügel südlich der {area:350} der Elfen.",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "Reite nach Westen aus {area:75} und nach Süden durch die Schlucht in die {zone:1419}; die beiden Blutmagier stehen gleich dahinter an der Straße.",
		["Saltwater Snapjaws"] = "Salzwasserschnappkiefer",
		["Silvermane Howlers"] = "Silbermähnenheuler",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "Südlich der Jagdhütte halten die Trolle der Witherbark ihre Dörfer. Jeder von ihnen trägt einen Schädel: Mit zwanzig benutzt du {item:15002}, um Nimboyas geladene Pike zu machen, und pflanzt sie dann im Dorf auf.",
		["South-west again, the exile hides by the ruins of {area:353}."] = "Wieder nach Südwesten: Der Verbannte versteckt sich bei den Ruinen von {area:353}.",
		["South-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "Im Südwesten streifen die Silbermähnenheuler durch die Hügel östlich der Dörfer der Witherbark.",
		["The Highvale elves camp around {area:350}. Burn the report, the notes and the records in their camps. {npc:7780} is held inside the lodge: lead him out and fight off the ambush on the way."] = "Die Elfen des Hochtals lagern um {area:350}. Verbrenne den Bericht, die Notizen und die Aufzeichnungen in ihren Lagern. {npc:7780} wird in der Jagdhütte festgehalten: Führ ihn hinaus und wehr unterwegs den Hinterhalt ab.",
		["The Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and {area:351}. Use the {item:9618} on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for {npc:14738}'s second message."] = "Die Silbermähnenpirscher, Wilden Eulenbestien und Klingenschnabelhimmelsfürsten teilen sich die Hügel zwischen den Tempeln und {area:351}. Benutze {item:9618} an den Eulenbestien, die du tötest. Die Himmelsfürsten lassen auch Lange elegante Federn fallen: Behalte zehn für {npc:14738}s zweite Nachricht.",
		["The Vilebranch temples"] = "Die Tempel der Vilebranch",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "Die großen Schildkröten kriechen über die Strände nördlich des Dorfs. Die Portweinflaschen von {npc:2491} liegen auch an diesen Stränden, aber seine Quest ist nicht auf dieser Route. Ein Schnappkiefer kann selten das Notsignal von OOX-09/HL fallen lassen: Behalte es.",
		["The bloodmages"] = "Die Blutmagier",
		["The central hills"] = "Die zentralen Hügel",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "Die Kisten mit {item:8684} liegen um das verlassene Hordelager am {area:351}, zwischen den Schlammen.",
		["The eastern slopes"] = "Die östlichen Hänge",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills."] = "Die fünf Quests teilen sich dieselben Teile: Sammle alle auf einem Durchgang. Westlich der Straße teilen sich {npc:5982}-Geier, Verhungernde Kicherfänge, Skorpokstecher und Todesaugen-Basilisken die Hügel.",
		["The next guide starts here, at {area:3317}."] = "Der nächste Guide beginnt hier, in {area:3317}.",
		["The northern beasts"] = "Die nördlichen Bestien",
		["The secret lies on the {area:307}, above the beach."] = "Das Geheimnis liegt auf den {area:307}, über dem Strand.",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Ihre Folgequests wollen dieselben Teile noch einmal für einen Buffgegenstand und geben keine Erfahrung: Lass sie liegen.",
		["Vilebranch soothsayers"] = "Sterndeuter der Vilebranch",
		["Vulture hills"] = "Geierhügel",
		["West of the island, the Vilebranch scalpers hold the temples of {area:1884} and {area:1917}. Slagtree's tools lie at one of the temples."] = "Westlich der Insel halten die Skalpierer der Vilebranch die Tempel von {area:1884} und {area:1917}. Schmied Slagtrees Werkzeug liegt bei einem der Tempel.",
		["for {npc:6986} in {zone:1454}, around level 50"] = "für {npc:6986} in {zone:1454}, etwa ab Stufe 50",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "für {npc:7825} in {zone:1458}, etwa ab Stufe 50",
		["grind on {npc:5982} at the northern hills, {zone:1419}"] = "grinde {npc:5982} in den nördlichen Hügeln, {zone:1419}",
		["{area:348} well"] = "Brunnen von {area:348}",
		["{item:8704}, a rare drop"] = "{item:8704}, eine seltene Beute",
		["{npc:14731}'s lunch"] = "Mittagessen von {npc:14731}",
		["{npc:14757}, at the top of {area:354}"] = "{npc:14757}, oben in {area:354}",
		["{npc:6741}: for {zone:1456}, around level 50"] = "{npc:6741}: für {zone:1456}, etwa ab Stufe 50",
		["{npc:7801}'s camp"] = "{npc:7801}s Lager",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}, {object:36126}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "Zurück nach Nordosten zu {npc:8420}.",
		["Back to {area:1099}"] = "Zurück nach {area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "Zurück zu {npc:11548} am Schrein; bleib westlich der Wachen an der {area:3137}.",
		["Back to {object:3202}"] = "Zurück nach {object:3202}",
		["Continue south to {area:35}. {npc:7406} has his workshop on the upper ring of the bay."] = "Reite weiter nach Süden nach {area:35}. {npc:7406} hat seine Werkstatt auf dem oberen Ring der Bucht.",
		["Fly from {area:1237} to {zone:1454}, walk out of the main gate to the zeppelin towers and take the zeppelin to {object:3202}."] = "Flieg von {area:1237} nach {zone:1454}, geh durch das Haupttor hinaus zu den Zeppelintürmen und nimm den Zeppelin nach {object:3202}.",
		["Fly to the {area:1497}"] = "Flieg nach {area:1497}",
		["Fly to {area:1638}; it is on the way to {area:1099}. No flight path there yet? Fly to {area:378} and ride west through {zone:1412}. Hamuul and {npc:4046} are on the {area:1639}; Druids and Paladins train here ({npc:3033}, {npc:246344})."] = "Flieg nach {area:1638}; es liegt auf dem Weg nach {area:1099}. Noch keine Flugroute dort? Flieg nach {area:378} und reite nach Westen durch {zone:1412}. Hamuul und {npc:4046} sind im Gebiet {area:1639}; Druiden und Paladine trainieren hier ({npc:3033}, {npc:246344}).",
		["Follow the road north to {area:1237}, the Horde camp."] = "Folge der Straße nach Norden nach {area:1237}, dem Lager der Horde.",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "Folge der Straße nach Süden; die Basilisken sonnen sich mitten im Dschungel auf den Felsen östlich davon. Ihre Splitter fallen oft.",
		["Frayfeather Hippogryphs"] = "Fransenfederhippogryphen",
		["From {area:3317}'s flight master, fly to the {area:1497}."] = "Flieg vom Flugmeister in {area:3317} nach {area:1497}.",
		["Highborne and Haldarr satyrs"] = "Hochgeborene und Satyrn der Haldarr",
		["Ironjaw Basilisks"] = "Eisenkieferbasilisken",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "Behalte die Lieferungen für {npc:4046}, {npc:8659} und {npc:6522}: Du kommst später durch {zone:1456}, {zone:1454} und {zone:1458}.",
		["Keep {area:1417} for {npc:7771} in {zone:1446}."] = "Behalte {area:1417} für {npc:7771} in {zone:1446}.",
		["Keep {npc:8659}'s payment and Ag'tor's {quest:3504}: they go back to {area:1237} on a later visit."] = "Behalte die Bezahlung von {npc:8659} und Ag'tors {quest:3504}: Sie gehen bei einem späteren Besuch zurück nach {area:1237}.",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Behalte {quest:3444}: {npc:7771}s Truhe wird bei einem späteren Besuch geöffnet.",
		["Only once all three robots are home"] = "Erst wenn alle drei Roboter zu Hause sind",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "Reite auf der Straße vom Splintertreeposten aus nach Osten. {npc:11548} wartet am {area:1235} gleich neben der Straße, ein paar Schritte westlich der {area:3137} der Allianz: Komm von Westen und halte dich von den Azshara-Schildwachen und Jarrodenus (Elite) fern.",
		["Ride into {zone:1447}"] = "Reite nach {zone:1447}",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}."] = "Reite nach Nordosten zum Lager des Goblins auf den Klippen über dem Gebiet {area:1227}.",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "Reite nach Nordwesten zum Ort {area:1108}; {npc:14637} wartet am Steg.",
		["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "Reite auf der Straße nach Süden zur {area:1938}; {npc:7771} lagert daneben. Von hier führt die Straße nach Westen hinab in {zone:1449}, wo der nächste Guide beginnt.",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "Reite nach Südwesten zu den Ruinen. Die vier Tafeln liegen in den Ruinen, bewacht von Naga der Grollflossen; jede Sirene oder Myrmidone kann die Rune von {npc:8420} tragen.",
		["Ride west back to {area:1237}."] = "Reite nach Westen zurück nach {area:1237}.",
		["Sea elementals"] = "Meereselementare",
		["Sprite Darters"] = "Grimmlingflitzer",
		["Take the zeppelin back to {zone:1454}."] = "Nimm den Zeppelin zurück nach {zone:1454}.",
		["Take the zeppelin to {zone:1454} from the tower outside the {zone:1458}, then fly to {area:431}."] = "Nimm den Zeppelin nach {zone:1454} am Turm vor {zone:1458} und flieg dann zum {area:431}.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Die Geister der Hochgeborenen spuken in den Ruinen gleich nördlich des Schreins; die Satyrn der Haldarr lagern etwas weiter nördlich.",
		["The Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "Die Landgänger und Klippenriesen streifen durch die Hügel nördlich des Stegs. Schrumpfe jeden zuerst mit {item:18904}: Geschrumpft sind sie keine Elite mehr. Jeder geschrumpfte Riese hinterlässt Rückstände; benutze auch das Muisekgefäß an seiner Leiche.",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock."] = "Die Meereselementare und Meeresschauer treiben an der Küste rund um den Steg.",
		["The Thunderhead Hippogryphs fly over the hills just south of {area:1237}."] = "Die Donnerkopfhippogryphen fliegen über die Hügel gleich südlich von {area:1237}.",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "Das Lager der Blutelfen liegt gleich südlich von {npc:8420}. Seine vier Ausrüstungsteile liegen in den Kisten im Lager.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "Die Feendrachen schwirren durch den Wald gleich westlich des Lagers. Benutze das Gefäß an jedem, den du tötest.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Die Hippogryphen nisten auf den Hügeln südwestlich des Lagers. Töte einen und benutze dann das Muisekgefäß an seiner Leiche.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "Die Treants wandern auf den Waldwegen zwischen dem Lager und der Mitte von {zone:1444}; es gibt nur wenige, also such entlang der Pfade.",
		["The {object:2076} beside {npc:2519}"] = "Der {object:2076} neben {npc:2519}",
		["To {object:3202}"] = "Nach {object:3202}",
		["Undamaged Hippogryph Feathers"] = "Unbeschädigte Hippogryphenfedern",
		["Wandering Forest Walkers"] = "Wandernde Waldgänger",
		["Xylem's tower stands on the cliff just north of {area:1237}; the path winds up its north side."] = "Der Turm von Xylem steht auf der Klippe gleich nördlich von {area:1237}; der Pfad windet sich an seiner Nordseite hinauf.",
		["Zapped giants"] = "Geschrumpfte Riesen",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}, die Gasse",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}: Die Bären sind im {zone:1448}",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825} steht im {object:36082}.",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "Der Teer für {npc:7876} und Pestlezuggs Proben stammen aus {zone:1449}.",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, neben dem Windreitermeister",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}, am Ostrand des Lagers: keine Erfahrung, nur ein Teleport zum Azsharaturm",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761} wird im nächsten Guide gesammelt; {npc:4046}s Bezahlung geht später zurück an {npc:8587}.",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back north-east to {area:251}."] = "Zurück nach Nordosten zum {area:251}.",
		["Back to {area:2268}"] = "Zurück zur {area:2268}",
		["Black Broodlings"] = "Schwarze Brutlinge",
		["Black Broodlings nest in the hills just east of {area:251}. Use {npc:10267}'s {item:12284} on a broodling when it is almost dead to capture its essence."] = "Schwarze Brutlinge nisten in den Hügeln gleich östlich vom {area:251}. Benutze {npc:10267}s {item:12284} an einem fast toten Brutling, um seine Essenz einzufangen.",
		["Bloodpetal Flayers"] = "Blutblütenschinder",
		["Bridge into {area:254}"] = "Brücke in den Berg ({area:254})",
		["Cross the south of the crater to the pylon on the western cliffs."] = "Durchquere den Süden des Kraters zum Pylon auf den westlichen Klippen.",
		["Darrowshire Spirits"] = "Geister von Darrowshire",
		["Eastern Pylon"] = "Östlicher Kristallpylon",
		["Escort {npc:9999}"] = "Eskortiere {npc:9999}",
		["Fly to {area:1637} and train before the {object:3202} zeppelin: the {zone:1458} stop later in this guide has no Hunter or Shaman trainer."] = "Flieg nach {area:1637} und trainiere vor dem Zeppelin nach {object:3202}: Der Halt in {zone:1458} später in diesem Guide hat keinen Jäger- oder Schamanenlehrer.",
		["Fly to {area:1637}, take the zeppelin to {object:3202} and fly from there to {area:340}, built into the cliffs on the {zone:1418}' west edge."] = "Flieg nach {area:1637}, nimm den Zeppelin nach {object:3202} und flieg von dort nach {area:340}, das in die Klippen am Westrand des Gebiets {zone:1418} gebaut ist.",
		["Fly to {area:1638} and train with {npc:3033} on {area:1639}, then fly to {area:1637} for the {object:3202} zeppelin."] = "Flieg nach {area:1638} und trainiere bei {npc:3033} im Gebiet {area:1639}; flieg dann nach {area:1637} zum Zeppelin nach {object:3202}.",
		["Fly to {area:340}"] = "Flieg nach {area:340}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Folge den Klippen nach Süden zum {quest:3821}, dem Hügel der Oger der Feuermägen. Die Überreste von {npc:9136} liegen an seinem Fuß.",
		["Follow the road east through the {zone:1422} and across the river into the {zone:1423}; leave it north for {area:2627}, the ruined town in the north-west. {npc:12384} sits in a hut at its edge."] = "Folge der Straße nach Osten durch das Gebiet {zone:1422} und über den Fluss ins Gebiet {zone:1423}; verlass es nach Norden zum {area:2627}, der zerstörten Stadt im Nordwesten. {npc:12384} sitzt in einer Hütte an ihrem Rand.",
		["Free Darrowshire Spirits: talk to them"] = "Befreie Geister von Darrowshire: Sprich mit ihnen",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "Sammle ab jetzt jeden Machtkristall (blau, grün, rot, gelb) und jeden Haufen {quest:3761} auf deinem Weg ein: insgesamt 25 Erde, 20 für Hamuul und 5 für Pestlezugg.",
		["From the {area:1938} ride west to the long ramp that winds down into {zone:1449}, then follow the crater's north wall to {area:541}, a camp in the cliff caves. Everyone here is neutral."] = "Reite von der {area:1938} nach Westen zur langen Rampe, die sich in den {zone:1449} hinabwindet, und folge dann der Nordwand des Kraters nach {area:541}, einem Lager in den Klippenhöhlen. Alle hier sind neutral.",
		["Gorillas"] = "Gorillas",
		["Into the {zone:1427}"] = "In die {zone:1427}",
		["Into {zone:1449}"] = "Hinab in den {zone:1449}",
		["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "Behalte den Köder: {npc:9684} ist Stufe 56, und die zweite Runde führt an seinem Unterschlupf vorbei.",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "Behalte {npc:10267}s Brief: {quest:4808} ist in {area:2255}, {zone:1452}.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Behalte {quest:4147} von {npc:9118} und den Brief von {npc:8737} für spätere Guides.",
		["Keep {quest:5152}: Marlene lives at {area:197} in the {zone:1422}."] = "Behalte {quest:5152}: Marlene wohnt am {area:197} im Gebiet {zone:1422}.",
		["Lar'korwi Mates"] = "Lar'korwi-Weibchen",
		["Lashers and Threshers"] = "Peitscher und Drescher",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Führe {npc:9999} nach Norden nach {area:541}. Wenn er ohnmächtig wird, benutze {item:11804} an ihm, um ihn zu wecken.",
		["Leave the {zone:1458} and ride east along the road through {zone:1420} to the {area:152}, the Forsaken fort on the border."] = "Verlass {zone:1458} und reite auf der Straße nach Osten durch {zone:1420} zum {area:152}, der Festung der Verlassenen an der Grenze.",
		["North of Torwa, a dead Threshadon lies by the water."] = "Nördlich von Torwa liegt ein toter Dreschadon am Wasser.",
		["Northern Pylon"] = "Nördlicher Kristallpylon",
		["Out of the refuge"] = "Raus aus der Zuflucht",
		["Pestlezugg's next quest needs the {npc:10041}, an elite boss. Skip it."] = "Pestlezuggs nächste Quest braucht die {npc:10041}, einen Elite-Boss. Überspringe sie.",
		["Power Crystals and soil"] = "Machtkristalle und Erde",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Reite die Ostseite des Kraters hinab zum Pylon auf den östlichen Klippen.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "Reite nach Osten zum Ort {area:537}, steig hinauf und benutze {npc:10541} am Lavaschlot nahe dem Gipfel; reite dann zurück nach Westen zu {npc:10302}.",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "Reite an der Ostseite nach Norden. Blutblütenpeitscher und -drescher füllen den Dschungel.",
		["Ride north back to {area:541}."] = "Reite nach Norden zurück nach {area:541}.",
		["Ride south back to the road and follow it east across the whole zone to {area:2268}."] = "Reite nach Süden zurück zur Straße und folge ihr nach Osten durch das ganze Gebiet zur {area:2268}.",
		["Ride south-west along the western cliffs. {npc:9167} fly over the west side, and Bloodpetal Trappers grow in the same jungle."] = "Reite an den westlichen Klippen entlang nach Südwesten. {npc:9167} fliegen über die Westseite, und Blutblütenfallen wachsen im selben Dschungel.",
		["Ride south-west to {area:537}, the volcano in the middle of the crater. Bloodpetal Flayers grow around its foot."] = "Reite nach Südwesten zum Ort {area:537}, dem Vulkan in der Mitte des Kraters. Blutblütenschinder wachsen um seinen Fuß.",
		["Ride west to the dig site. {npc:7039} golems (53) stomp around it and drop the shards often; the {quest:4296} stands in its middle among the Thaurissan dwarves. Copy it."] = "Reite nach Westen zur Ausgrabungsstätte. {npc:7039}-Golems (53) stampfen dort herum und lassen oft die Splitter fallen; die {quest:4296} steht in der Mitte zwischen den Thaurissanischen Zwergen. Kopiere sie.",
		["South of the hot springs, Stegodons graze and Dinosaur Bones drop from them or lie on the ground; Diemetradons nearby carry the scales {npc:9998} wants. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon."] = "Südlich der heißen Quellen grasen Stegodons; Dinosaurierknochen fallen von ihnen oder liegen am Boden. Dimetrodons in der Nähe tragen die Schuppen, die {npc:9998} will. Ravasaurier jagen im Südwesten in Rudeln: Ihre Klauen sind für {npc:8659}, und ab und zu trägt einer Ein zerfleddertes Tagebuch (seltene Beute: Nimm dessen Quest nur an, wenn du eins bekommst). Meide Gruff, einen Stegodon der Stufe 57.",
		["Stegodons and ravasaurs"] = "Stegodons und Ravasaurier",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "Nimm einen {object:176092} aus der Kiste neben Derrington für {quest:5096}, die du auf dem Rückweg erledigst. Leg die {quest:5401} an: Geißelsteine fallen nur, solange du sie trägst.",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south across the gorge to the long bridge into {area:254}. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals."] = "Nimm den Pass an der Westseite von {area:340} in die {zone:1427} und reite dann nach Süden durch die Schlucht zur langen Brücke in den Berg ({area:254}). Folge drinnen den Kettenstegen nach unten und verlass ihn durch den Südausgang; bleib von den Wegen zu den Dungeonportalen fern.",
		["Termite mounds"] = "Termitenhügel",
		["Thaurissan dig site"] = "Thaurissanische Ausgrabungsstätte",
		["The Gorishi hive"] = "Der Schwarm der Gorishi",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "Die Lar'korwi-Weibchen streifen durch den Dschungel nordwestlich von {npc:9619}.",
		["The Large Termite Mounds stand all over the hills east of {area:2627}. Use the {item:15042} on each mound you pass."] = "Die Großen Termitenhügel stehen überall in den Hügeln östlich von {area:2627}. Benutze den {item:15042} an jedem Hügel, an dem du vorbeikommst.",
		["The book lies in the ruined inn of {area:2627}."] = "Das Buch liegt im zerstörten Gasthaus von {area:2627}.",
		["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "Die Kristallgruppen stehen überall im Krater, viele rund um den Ort {area:537}. Nimm von jeder Farbe ein paar mehr für die Pylonen mit.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "Der Kopf der Puppe und ihre beiden Seiten liegen in den Häusern um {npc:10926}; füge sie in deinen Taschen zusammen.",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "Die Kiste der Expedition steht in einem verlassenen Lager im östlichen Dschungel.",
		["The expedition's lost equipment lies in the south-west jungle."] = "Die verlorene Ausrüstung der Expedition liegt im südwestlichen Dschungel.",
		["The gorillas live on the north-east plateau. Stay out of the deepest cave: {npc:9622} lives there."] = "Die Gorillas leben auf dem nordöstlichen Plateau. Bleib aus der hintersten Höhle fern: Dort lebt {npc:9622}.",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "Der Berg lässt dich neben der {area:252} hinaus, voller Orcs der Stufe 55-57. Folge der Straße an den nördlichen Klippen nach Osten zum Lager der Horde am {area:251}.",
		["The next guide starts here, at the chapel's flight master."] = "Der nächste Guide beginnt hier, beim Flugmeister der Kapelle.",
		["The pylon stands on the slope east of the refuge."] = "Der Pylon steht am Hang östlich der Zuflucht.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "Das Floß liegt am Ufer des südöstlichen Sees; das kleine Bündel liegt daneben im Wasser.",
		["The silithid hive fills the south of the crater. Gorishi wasps and workers drop the scent gland; use the Scraping Vial on the egg mass inside the first chamber. The Hive Queen at the bottom is an elite boss: stay out of her chamber. {npc:9166} nest on the cliffs above the hive; their scales are for {npc:9998}."] = "Der Silithidenschwarm füllt den Süden des Kraters. Wespen und Arbeiter der Gorishi lassen die Duftdrüse fallen; benutze die Kratzphiole an der Eiermasse in der ersten Kammer. Die Schwarmkönigin ganz unten ist ein Elite-Boss: Bleib aus ihrer Kammer fern. {npc:9166} nisten auf den Klippen über dem Schwarm; ihre Schuppen sind für {npc:9998}.",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}."] = "Die Teergruben liegen gleich südlich der Zuflucht. Teerbestien, Teerlauerer und Teerkriecher lassen {item:11834} fallen.",
		["The wooden sign beside {npc:9997}"] = "Das Holzschild neben {npc:9997}",
		["Theodora's next errand goes to Lotwil east of town and then into {area:1584}: skip it."] = "Theodoras nächster Auftrag führt zu Lotwil östlich der Stadt und dann in die {area:1584}: Überspringe ihn.",
		["Theodora's quest in {area:340} needs level 52. The Tar Lurkers and Tar Lords just south of the refuge are the closest camp."] = "Theodoras Quest in {area:340} braucht Stufe 52. Die Teerlauerer und Teerfürsten gleich südlich der Zuflucht sind das nächste Lager.",
		["Use the Mangled Journal to start it"] = "Benutze Ein zerfleddertes Tagebuch, um sie zu starten",
		["Western Pylon"] = "Westlicher Kristallpylon",
		["Western jungle"] = "Westlicher Dschungel",
		["With {npc:11063}'s quest in your log, slain Scourge sometimes leave a {npc:11064}; talk to it to free it. Kill undead on the ride south-west to {area:2262}."] = "Mit {npc:11063}s Quest im Questlog hinterlässt erschlagene Geißel manchmal einen {npc:11064}; sprich mit ihm, um ihn zu befreien. Töte Untote auf dem Ritt nach Südwesten nach {area:2262}.",
		["grind on Tar Lurkers at {area:538}, {zone:1449}"] = "Töte Teerlauerer an den {area:538}, {zone:1449}",
		["{item:11116}, a rare drop"] = "{item:11116}, seltene Beute",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302} schickt dich zu {npc:9298} in {zone:1452}: Behalte es.",
		["{npc:10302} the goblin sits at {area:543}, just east of the pylon."] = "Der Goblin {npc:10302} sitzt am Ort {area:543}, gleich östlich des Pylons.",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, {object:36078}, neben dem Fledermausführer",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "{npc:10926}s Geist steht in den Ruinen von {area:2262} im Südwesten.",
		["{npc:12250} lurks just west of {area:2262}."] = "{npc:12250} lauert gleich westlich von {area:2262}.",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}, {object:36073}",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}, im Apothekarium: Die Phiolen füllst du später in {zone:1447}",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}, hinten in der Höhle",
		["{npc:9618}, just outside"] = "{npc:9618}, gleich draußen",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} lagert in der Südostecke des Kraters.",
		["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "{npc:9619} will jetzt das Fell von {npc:9622}, zurück in der nordöstlichen Höhle: Überspringe es.",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "{npc:9623} will dann ein {item:10561}, einen Gegenstand aus {skill:202}. Überspringe das, außer du hast eins.",
		["{npc:9623}, the robot on the plateau"] = "{npc:9623}, der Roboter auf dem Plateau",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "Der Unterschlupf von {npc:9684} liegt gleich südlich des Pylons. Benutze dort {npc:9619}s Köder; {npc:9684} ist Stufe 56 und schlägt hart zu, also fang mit voller Gesundheit an.",
		["{npc:9998}, at the entrance"] = "{npc:9998}, am Eingang",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, am Eingang der Zuflucht",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999} sitzt verirrt und erschöpft auf dem Grat.",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} durchstreift die Höhlen und Minenstollen des {quest:3821}; ist er nicht da, räum die Oger an den Eingängen weg, bis er zurückkommt.",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back at {area:1762}, the Deadwood furbolgs (53-54) are close to the tunnel and every kill raises your Timbermaw reputation."] = "Zurück in {area:1762}: Die Furbolgs der Totenwaldfelle (53-54) sind nah am Tunnel, und jeder Kill erhöht deinen Ruf bei der Holzschlundfeste.",
		["Back north to {area:1763}. Fill {npc:10922}'s canteen at the corrupted moonwell in the middle of the southern camp."] = "Zurück nach Norden nach {area:1763}. Füll {npc:10922}s Feldflasche am verderbten Mondbrunnen mitten im südlichen Lager.",
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "Derringtons Wachtürme, Vandis' Kessel und {npc:11615}s Fass erledigst du bei einem späteren Besuch: Behalte sie.",
		["Diseased Grizzlies"] = "Kranke Grizzlys",
		["Diseased Wolves"] = "Kranke Wölfe",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "Östlich vom Blutgiftposten liegt das kraterübersäte Tal, wo die Entropischen Bestien und Schrecken umherstreifen. Töte je zwei davon und geh dann zu jedem der drei Krater mit Teufelswasser.",
		["Fly to the {area:1497}"] = "Flieg nach {area:1497}",
		["Follow the road north-east to {area:1767}. The Warpwood Moss Flayers and Shredders on the east side of the woods each carry a {item:11503}; Angerclaw Grizzlies and Felpaw Ravagers roam the same woods for Talo."] = "Folge der Straße nach Nordosten zum {area:1767}. Die Wucherborkenschinder und -schredder auf der Ostseite des Waldes tragen je einen {item:11503}; Wutklauengrizzlys und Teufelspfotenverheerer streifen für Talo durch denselben Wald.",
		["Follow the road north-west. The south of {area:1763}, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "Folge der Straße nach Nordwesten. Den Süden von {area:1763}, um seinen verderbten Mondbrunnen, halten Kultisten, Adepten, Wachen und Hunde des Schattenrats.",
		["From {area:2268}'s flight master, fly to the {area:1497}."] = "Flieg vom Flugmeister der {area:2268} nach {area:1497}.",
		["He camps by the {area:202}, south-east of {area:200}."] = "Er lagert beim {area:202}, südöstlich von {area:200}.",
		["Jadefire moonwell"] = "Mondbrunnen der Jadefeuersatyrn",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "Behalte den Zweig: {npc:5770} ist in {zone:1456}.",
		["Keep the parcel: {npc:10781} is in the {area:1497}."] = "Behalte das Paket: {npc:10781} ist in {area:1497}.",
		["Keep {quest:5142}: Pamela is in {area:2262}, visited again later."] = "Behalte {quest:5142}: Pamela ist in {area:2262}, das du später noch einmal besuchst.",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "Behalte {quest:5158}: {npc:5901} ist im {zone:1413}.",
		["Keep {quest:8465} for {zone:1452}."] = "Behalte {quest:8465} für {zone:1452}.",
		["Knights and magi work the {area:192}; the medics and hunters camp south of it."] = "Ritter und Magier arbeiten im {area:192}; die Sanitäter und Jäger lagern südlich davon.",
		["Leave the {area:1497} and ride east along the road through {zone:1420}, past the {area:152}. Felstone Farm is the first farm along the road; {npc:10778} waits in the house."] = "Verlass {area:1497} und reite auf der Straße nach Osten durch {zone:1420}, am {area:152} vorbei. Der Teufelssteinhof ist der erste Hof an der Straße; {npc:10778} wartet im Haus.",
		["Northern crater"] = "Nördlicher Krater",
		["Only if a {item:13140} dropped: use it to start the quest, then free {npc:11018} in her cage in {area:1770}, the cave at the north end of {area:1763}, and escort her out."] = "Nur wenn {item:13140} gefallen ist: Benutze ihn, um die Quest zu starten, befrei dann {npc:11018} aus ihrem Käfig in {area:1770}, der Höhle am Nordende von {area:1763}, und eskortiere sie hinaus.",
		["Only if you rescued {npc:11018}: the succubus {npc:9518} waits in the middle of {area:1763}, beside the {npc:11020}."] = "Nur wenn du {npc:11018} gerettet hast: Die Sukkubus {npc:9518} wartet mitten in {area:1763}, neben {npc:11020}.",
		["Only with 5 Deadwood Headdress Feathers"] = "Nur mit 5 Kopfputzfedern der Totenwaldfelle",
		["Radley and Durgen"] = "Radley und Durgen",
		["Ride back south past {area:1763} to the corrupted moonwell of the Jadefire satyrs and fill {npc:9996}'s flasket there."] = "Reite zurück nach Süden an {area:1763} vorbei zum verderbten Mondbrunnen der Jadefeuersatyrn und füll dort {npc:9996}s Fläschchen.",
		["Ride back south-east to the Sanctuary."] = "Reite zurück nach Südosten zum Refugium.",
		["Ride back to the {area:1497}, take the zeppelin to {zone:1454} and fly to {area:431}. Follow the road west out of Splintertree and take the fork north into {zone:1448}."] = "Reite zurück nach {area:1497}, nimm den Zeppelin nach {zone:1454} und flieg zum {area:431}. Folge der Straße vom Splintertreeposten nach Westen und nimm die Abzweigung nach Norden in den {zone:1448}.",
		["Ride north along the eastern hills; Tirion lives in a small house by the {area:2620}, at the border with the {zone:1423}."] = "Reite an den östlichen Hügeln entlang nach Norden; Tirion lebt in einem kleinen Haus am {area:2620}, an der Grenze zu den {zone:1423}.",
		["Ride north up the road again."] = "Reite die Straße wieder nach Norden hinauf.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Reite nach Nordwesten nach Andorhal. {npc:10667} wartet im zerstörten Gasthaus auf der Westseite der Stadt; die Skelette drinnen sind 54-57, also bleib am Rand.",
		["Ride south past the {area:202} to {area:197}; {npc:10927}'s house stands by the road, and {npc:10936}'s monument is in the graveyard behind it. Kill the Diseased Wolves you meet in the fields on the way."] = "Reite nach Süden am {area:202} vorbei zum {area:197}; {npc:10927}s Haus steht an der Straße, und das Denkmal von {npc:10936} ist auf dem Friedhof dahinter. Töte unterwegs die Kranken Wölfe auf den Feldern.",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "Reite nach Südwesten am Teufelssteinhof vorbei und folge der Straße nach Westen zurück zum {area:152}.",
		["Ride the road south through {zone:1448} to the Sanctuary."] = "Reite die Straße nach Süden durch den {zone:1448} zum Refugium.",
		["Ride west to the {area:192}; {npc:11610} hides on the hill north-east of it."] = "Reite nach Westen zum {area:192}; {npc:11610} versteckt sich auf dem Hügel nordöstlich davon.",
		["Ror stands at the far south end of {area:1761}."] = "Ror steht am äußersten Südende von {area:1761}.",
		["Scarlet Crusade"] = "Scharlachroter Kreuzzug",
		["Scarlet forward camp"] = "Vorgeschobenes Lager des Scharlachroten Kreuzzugs",
		["Southern crater"] = "Südlicher Krater",
		["Southern {area:1763}"] = "Südliches {area:1763}",
		["Take the kitten to the same moonwell and release it there; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "Bring das Kätzchen zum selben Mondbrunnen und lass es dort frei; sobald es sich in {npc:10042} verwandelt hat, bring es zurück zu {npc:9996} und klick es an, um es zu übergeben.",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "Die Annalen liegen zwischen den Modrigen Folianten im Rathaus von Andorhal; öffne sie, bis du den richtigen findest.",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "Das Furbolgdorf der Totenwaldfelle gleich westlich des Tunnels. {npc:9462} (56) steht zwischen ihnen. {npc:11557}, ein freundlicher Furbolg, sitzt am Nordende des Dorfs.",
		["The Deadwood furbolg village lies just south of the Sanctuary. Every Deadwood kill also raises your {area:1769} reputation; keep the headdress feathers."] = "Das Furbolgdorf der Totenwaldfelle liegt gleich südlich des Refugiums. Jeder getötete Totenwaldfell erhöht auch deinen Ruf bei der {area:1769}; behalte die Kopfputzfedern.",
		["The Horde camp just north of {area:1763}."] = "Das Hordelager gleich nördlich von {area:1763}.",
		["The Jadefire moonwell"] = "Der Mondbrunnen der Jadefeuersatyrn",
		["The Scarlet Crusade's tents stand between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner."] = "Die Zelte des Scharlachroten Kreuzzugs stehen zwischen {area:199} und {area:200}. Zünde das Kommandozelt mit {object:176092} an und pflanz das Banner der Geißel auf.",
		["The bears roam the hills north and east of the {area:202}."] = "Die Bären streifen durch die Hügel nördlich und östlich vom {area:202}.",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "Das Tagebuch liegt im Bauernhaus, der Schrank steht drinnen und der Abort dahinter. Ein {npc:10816} trägt den Schlüssel zum Abort; {npc:10836} kommt heraus, wenn du den Abort öffnest, und trägt den Schlüssel zum Schrank.",
		["The druids' camp is just past the border."] = "Das Lager der Druiden liegt gleich hinter der Grenze.",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "Die Straße endet bei {npc:15395}, vor dem Tunnel der {area:1769} im äußersten Nordosten.",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east."] = "Die Wölfe streifen über die Felder zwischen Andorhal, {area:200} und {area:202}. Erledige sie auf dem Rückritt nach Osten.",
		["The {area:1763} moonwell"] = "Der Mondbrunnen von {area:1763}",
		["Through {area:1769}"] = "Durch die {area:1769}",
		["Tirion's hunts are in the {zone:1423}: keep them for later."] = "Tirions Jagden sind in den {zone:1423}: Behalte sie für später.",
		["To {zone:1448}"] = "Nach {zone:1448}",
		["Walk into the {area:1769} tunnel beside {npc:15395} and never attack the Timbermaw furbolgs inside. The tunnel opens into {zone:1452}; follow the road east to {area:2255}, the goblin town where the next guide starts."] = "Geh neben {npc:15395} in den Tunnel der {area:1769} und greif niemals die Furbolgs der Holzschlundfeste darin an. Der Tunnel öffnet sich nach {zone:1452}; folge der Straße nach Osten nach {area:2255}, der Goblinstadt, in der der nächste Guide beginnt.",
		["Western crater"] = "Westlicher Krater",
		["grind on Deadwood Avengers at {area:1762}, {zone:1448}"] = "grinde Rächer der Totenwaldfelle in {area:1762}, {zone:1448}",
		["grind on Scarlet Knights at {area:192}, {zone:1422}"] = "grinde Scharlachrote Ritter im {area:192}, {zone:1422}",
		["{area:190}'s Scarlets are level 58-60. Ride in to the high point marked on your map, look over the town, and get out."] = "Die Scharlachroten in {area:190} sind Stufe 58-60. Reite zum auf deiner Karte markierten Aussichtspunkt, sieh dir die Stadt an und verschwinde wieder.",
		["{area:200} farmhouse"] = "Bauernhaus von {area:200}",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}: Die Eulenbestien sind in {zone:1452}",
		["{npc:10840}, at the graveyard's south end"] = "{npc:10840}, am Südende des Friedhofs",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}, am Südrand des Lagers",
		["{npc:11557}: keep 30 {quest:6031} for him; he trades only at Neutral with the Timbermaw"] = "{npc:11557}: Behalte 30 {quest:6031} für ihn; er handelt erst ab neutralem Ruf bei der Holzschlundfeste",
		["{npc:11558}, at the tunnel mouth"] = "{npc:11558}, am Tunneleingang",
		["{npc:11610}'s last task needs level 53. The Scarlet Knights and Magi (54-55) working the lumber camp just south-west of her are the closest camp."] = "{npc:11610}s letzte Aufgabe erfordert Stufe 53. Die Scharlachroten Ritter und Magier (54-55) im Holzfällerlager gleich südwestlich von ihr sind das nächste Lager.",
		["{npc:11613} stands east of the lumber camp; {npc:11611} guards the road north-east of {npc:11610}, toward {area:190}."] = "{npc:11613} steht östlich des Holzfällerlagers; {npc:11611} bewacht die Straße nordöstlich von {npc:11610}, Richtung {area:190}.",
		["{npc:9529}, just west of the camp"] = "{npc:9529}, gleich westlich des Lagers",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}, auf der Westseite des Refugiums",
		["{npc:9996}'s kitten"] = "{npc:9996}s Kätzchen",
		["{object:175894}, beside the house"] = "{object:175894}, neben dem Haus",
		["{quest:5210} goes to {area:2268}: keep it for later."] = "{quest:5210} führt zur {area:2268}: Behalte sie für später.",
		["{quest:8470}, a rare drop"] = "{quest:8470}, eine seltene Beute",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Any Winterfall furbolg can carry the beads; the camps just south of {npc:11556} are the closest."] = "Jeder Furbolg der Winterfelle kann die Perlen tragen; die Lager gleich südlich von {npc:11556} sind am nächsten.",
		["Back at {area:1099}."] = "Zurück im {area:1099}.",
		["Back to {area:2255}"] = "Zurück nach {area:2255}",
		["Chillwind chimaeras"] = "Eiswindschimären",
		["Fly to {area:1099}"] = "Flieg zum {area:1099}",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["From Krakle in Un'Goro"] = "Von Krakle in Un'Goro",
		["Frostfire Winterfall camp"] = "Lager der Winterfelle an den Frostfeuerquellen",
		["Frostfire Winterfall camps"] = "Lager der Winterfelle an den Frostfeuerquellen",
		["Gregor's and Harlo's quests lead to other zones: keep them."] = "Gregors und Harlos Quests führen in andere Gebiete: Behalte sie.",
		["Grind to 55"] = "Bis 55 grinden",
		["He stands on {area:1641}. Each donation wants cloth from your bags; hand them in when you have it, later in the route."] = "Er steht auf der {area:1641}. Jede Spende will Stoff aus deinen Taschen; gib sie ab, wenn du ihn hast, später auf der Route.",
		["Ice Thistle yetis"] = "Eisdistelyetis",
		["In the {object:172958}."] = "Im {object:172958}.",
		["In the {object:172961}."] = "Im {object:172961}.",
		["Linken's letter"] = "Linkens Brief",
		["Matriarchs and Patriarchs hit hard: pull them one at a time."] = "Matriarchinnen und Patriarchen schlagen hart zu: Zieh sie einzeln.",
		["Pathfinders, Den Watchers and Totemics share the furbolg camps around the hot springs; Ragged Owlbeasts roam the slopes between them. Kill Totemics first. Save every {item:14047} you loot for Meilosh."] = "Pfadfinder, Höhlenbehüter und Totemiker teilen sich die Furbolglager um die heißen Quellen; Struppige Eulenbestien streifen über die Hänge dazwischen. Töte zuerst die Totemiker. Heb jeden {item:14047}, den du plünderst, für Meilosh auf.",
		["Pristine Yeti Horns"] = "Makellose Yetihörner",
		["Raging Owlbeasts"] = "Tobende Eulenbestien",
		["Ride back west to {area:2246}."] = "Reite zurück nach Westen zu {area:2246}.",
		["Ride east, then south down {area:2249}. The Frostmaul giants there are elite level 59: keep to the middle and keep moving. The strange source is at the mouth of {area:2256}, at the south end."] = "Reite nach Osten, dann nach Süden die {area:2249} hinunter. Die Frosthagelriesen dort sind Elite der Stufe 59: Halte dich in der Mitte und bleib in Bewegung. Die seltsame Quelle ist am Eingang von {area:2256}, am Südende.",
		["Ride west along the road past {area:2251}; Raging Owlbeasts roam the hills north of it."] = "Reite auf der Straße nach Westen am {area:2251} vorbei; Tobende Eulenbestien streifen durch die Hügel nördlich davon.",
		["The chimaeras roam the snowfields south and west of {area:2255}. Stay clear of {area:2245}'s cave: its blue dragonkin are elite."] = "Die Schimären streifen über die Schneefelder südlich und westlich von {area:2255}. Halte dich von der Höhle von {area:2245} fern: Ihre blauen Drachkin sind Elite.",
		["The furbolg village fills the valley north-east of {area:2255}. Kill Shamans first; they heal. {npc:10738} in the cave at the back is elite: stay out."] = "Das Furbolgdorf füllt das Tal nordöstlich von {area:2255}. Töte zuerst die Schamanen; sie heilen. {npc:10738} in der Höhle hinten ist Elite: Bleib draußen.",
		["The yeti hills start just south-east of {area:2255}. Every yeti drops fur; only Matriarchs and Patriarchs drop horns, so keep those for after the turn-in."] = "Die Yetihügel beginnen gleich südöstlich von {area:2255}. Jeder Yeti lässt Fell fallen; nur Matriarchinnen und Patriarchen lassen Hörner fallen, also heb die für nach der Abgabe auf.",
		["Umi's third prank targets goblins in {area:976} and Un'Goro: keep it for later."] = "Umis dritter Streich gilt Goblins in {area:976} und Un'Goro: Behalte ihn für später.",
		["grind on {npc:7440} at {area:2244}, {zone:1452}"] = "grinde {npc:7440} in {area:2244}, {zone:1452}",
		["{area:2255} is the goblin town on the east side of the valley."] = "{area:2255} ist die Goblinstadt auf der Ostseite des Tals.",
		["{item:12771}, a rare drop from the Winterfall furbolgs"] = "{item:12771}, eine seltene Beute der Winterfell-Furbolgs",
		["{npc:10307}, beside him"] = "{npc:10307}, neben ihm",
		["{npc:11556} stands by the {zone:1452} exit of {area:1769}'s tunnel, north of the hot springs."] = "{npc:11556} steht am Ausgang des Tunnels der {area:1769} nach {zone:1452}, nördlich der heißen Quellen.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} auf der {area:1639}; {npc:246344}",
		["{npc:7775}, a dwarf, camps in the {area:1137} north-west of {area:1099}; he has the elixir."] = "{npc:7775}, ein Zwerg, lagert in {area:1137} nordwestlich vom {area:1099}; er hat das Elixier.",
		["{npc:9087} buys {item:11040} grown from your {quest:3761}."] = "{npc:9087} kauft {item:11040}, das aus deiner {quest:3761} gewachsen ist.",
		["{npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "{npc:9298} lagert zwischen den dampfenden Becken von {area:2246}, im Westen des Tals.",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123} wartet in {zone:1450}: Behalte sie für später.",
		["{quest:3909} comes from {npc:7775} in {zone:1444}, later in this guide."] = "{quest:3909} kommt von {npc:7775} in {zone:1444}, später in diesem Guide.",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084} wird bei {object:176091} im {zone:1448} abgegeben, auf einer späteren Reise.",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}, eine seltene Beute der Winterfell-Furbolgs",
} end)()
t.guides["forever/horde/50-60/04-azshara"] = (function() return {
		["Both {item:14047} donations are handed in later in the route: start saving {item:14047}."] = "Beide Spenden von {item:14047} gibst du später auf der Route ab: Fang an, {item:14047} zu sammeln.",
		["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "Gesäubertes Wasser wird zum Teufelswald gebracht führt zum {area:2479} im {zone:1448}: Behalte sie für später.",
		["Fly to the {area:380}"] = "Flieg nach {area:380}",
		["Fly to {area:1237}"] = "Flieg nach {area:1237}",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:1637}; {npc:4485} is in the {object:172958}."] = "Flieg nach {area:1637}; {npc:4485} ist im {object:172958}.",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["In the {object:172958}."] = "Im {object:172958}.",
		["In the {object:172961}. Have the Wool, Silk and Mageweave in your bags."] = "Im {object:172961}. Hab Wolle, Seide und Magiestoff in deinen Taschen.",
		["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "Livs Werkstatt ist am Nordende der Docks von {area:392}; {object:149036} steht darin.",
		["Ride back west to {area:1237}."] = "Reite zurück nach Westen nach {area:1237}.",
		["Ride east to the ruins on the coast. Fill Cuely's four vials at the tide pools along the shore; Spitelash naga patrol between them."] = "Reite nach Osten zu den Ruinen an der Küste. Füll Cuelys vier Phiolen an den Gezeitentümpeln am Ufer; Naga der Grollflossen patrouillieren dazwischen.",
		["Rimtori's camp is at the east end of the base camp. Read the {object:151286} there, then kill the Magus."] = "Rimtoris Lager ist am Ostende des Stützpunkts. Lies dort {object:151286} und töte dann den Magus.",
		["The blood elves camp on the cliffs in the north-east, by the {area:1227}."] = "Die Blutelfen lagern auf den Klippen im Nordosten, an der {area:1227}.",
		["The zeppelin tower stands just north-east of {zone:1454}'s main gate; take the {zone:1458} zeppelin."] = "Der Zeppelinturm steht gleich nordöstlich des Haupttors von {zone:1454}; nimm den Zeppelin nach {zone:1458}.",
		["Zeppelin to the {zone:1458}"] = "Zeppelin nach {zone:1458}",
		["Zeppelin tower"] = "Zeppelinturm",
		["{npc:11044}, in the Apothecarium"] = "{npc:11044}, im Apothekarium",
		["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{npc:15188}, {object:172957}: Behalte sie für {zone:1451}",
		["{npc:256386} stands in the {area:380}. Open each crate she hands you and bring back what is inside."] = "{npc:256386} steht in {area:380}. Öffne jede Kiste, die sie dir gibt, und bring zurück, was darin ist.",
		["{npc:256386}'s crates"] = "Kisten von {npc:256386}",
		["{npc:5901} camps on the shore just north of {area:392}."] = "{npc:5901} lagert am Ufer gleich nördlich von {area:392}.",
		["{npc:8393}, beside him"] = "{npc:8393}, neben ihm",
		["{npc:8403}, nearby"] = "{npc:8403}, in der Nähe",
		["{npc:8578}'s camp"] = "Lager von {npc:8578}",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050} geht zurück zu {npc:10778} in den {zone:1422}: Behalte sie.",
} end)()
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["A torn scroll lies at the entrance of the {area:2261}, the crypt south of the {area:2260}."] = "Eine zerrissene Schriftrolle liegt am Eingang von {area:2261}, der Gruft südlich von {area:2260}.",
		["Back through the tunnel and take the {zone:1452} exit, then ride south to {area:2246}."] = "Zurück durch den Tunnel, nimm den Ausgang nach {zone:1452} und reite dann nach Süden zu {area:2246}.",
		["Back to {area:1638}"] = "Zurück nach {area:1638}",
		["Both quests lead to {zone:1451}: keep them."] = "Beide Quests führen nach {zone:1451}: Behalte sie.",
		["Fly to the {zone:1458}, take the zeppelin to {zone:1454} and fly on to {area:1638}."] = "Flieg nach {zone:1458}, nimm den Zeppelin nach {zone:1454} und flieg weiter nach {area:1638}.",
		["Fly to {area:1099}. The hippogryph nests are in the south of {zone:1444}; each holds an egg for the {object:142071}."] = "Flieg zum {area:1099}. Die Hippogryphennester sind im Süden von {zone:1444}; jedes enthält ein Ei für {object:142071}.",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Fly to {area:2268}"] = "Flieg zur {area:2268}",
		["Fly to {area:541}, then ride south-west through Un'Goro to the pass into {zone:1451}. The next guide opens at {area:3077}, where the pass comes out."] = "Flieg zur {area:541} und reite dann nach Südwesten durch Un'Goro zum Pass nach {zone:1451}. Der nächste Guide beginnt bei {area:3077}, wo der Pass herauskommt.",
		["Frenzied Plaguehounds and Monstrous Plaguebats share the fields around {area:2272} and {area:2271}, south of {area:2273}."] = "Rasende Seuchenhunde und Monströse Seuchenfledermäuse teilen sich die Felder um {area:2272} und den {area:2271}, südlich von {area:2273}.",
		["Go through {area:1769} and take the {zone:1450} branch of the tunnel. {npc:11801} is in {area:2361}."] = "Geh durch die {area:1769} und nimm die Abzweigung des Tunnels nach {zone:1450}. {npc:11801} ist in {area:2361}.",
		["Hameya hides among the Mossflayer trolls of {area:2273}, in the north-east corner."] = "Hameya versteckt sich zwischen den Trollen der Moosschinder in {area:2273}, in der Nordostecke.",
		["Hameya's mound"] = "Hameyas Hügel",
		["Hameya's scroll"] = "Hameyas Schriftrolle",
		["Hippogryph eggs"] = "Hippogryphen-Eier",
		["Moontouched Owlbeasts"] = "Mondbestrahlte Eulenbestien",
		["On to {zone:1451}"] = "Weiter nach {zone:1451}",
		["On {area:1641}. Have the Wool, Silk and Mageweave in your bags."] = "Auf der {area:1641}. Hab Wolle, Seide und Magiestoff in deinen Taschen.",
		["Only if a {quest:8471} dropped for you: {npc:11558} waits at the {zone:1448} entrance of {area:1769}, and speaks to you only at Neutral with the Timbermaw."] = "Nur wenn {quest:8471} für dich gefallen ist: {npc:11558} wartet am Eingang der {area:1769} im {zone:1448} und spricht erst ab neutralem Ruf bei der Holzschlundfeste mit dir.",
		["Only if you found a {item:12820} flask in {zone:1452}: ride north up the road. The cauldron stands in {area:1762}, just south-west of {area:1769}; the Deadwood furbolgs there are hostile."] = "Nur wenn du in {zone:1452} eine Flasche {item:12820} gefunden hast: Reite die Straße nach Norden hinauf. Der Kessel steht in {area:1762}, gleich südwestlich der {area:1769}; die Furbolgs der Totenwaldfelle dort sind feindselig.",
		["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "Kleine Seuchenhunde und Seuchenfledermäuse streifen durch die Hügel nördlich von {area:2260}, Aaslarven kriechen zwischen ihnen; arbeite dich nach Norden Richtung {area:2627} vor.",
		["Plaguehounds and their runts roam the shores of the lake south-west of the chapel."] = "Seuchenhunde und ihre Kleinen streifen an den Ufern des Sees südwestlich der Kapelle umher.",
		["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Pull them one at a time."] = "Reite nach Osten nach {area:2255} und von dort nach Norden; die Mondbestrahlten Eulenbestien streifen durch die Hügel an den Südhängen von {area:2241}. Zieh sie einzeln.",
		["Ride west to the {area:2260}."] = "Reite nach Westen zu {area:2260}.",
		["Sword of Marduk"] = "Zertrümmertes Schwert von Marduk",
		["The high elf Rangers, Pathstriders and Woodsmen guard the lodge by {area:2275}; the Registry lies inside. Rangers reach 60: pull one at a time. Noxious Plaguebats fly over the fields on the way."] = "Die Waldläufer, Pfadschreiter und Waldmänner der Hochelfen bewachen die Lodge beim {area:2275}; das Register liegt drinnen. Waldläufer erreichen Stufe 60: Zieh sie einzeln. Giftige Seuchenfledermäuse fliegen auf dem Weg über die Felder.",
		["The shattered sword lies on the ground north-west of the lake."] = "Das zertrümmerte Schwert liegt nordwestlich des Sees auf dem Boden.",
		["The skull sits in the {area:2622}, among Blighted Horrors and Plague Monstrosities."] = "Der Schädel liegt in {area:2622}, zwischen Verseuchten Schrecken und Seuchenmonstern.",
		["The western hills"] = "Die westlichen Hügel",
		["The {area:2622}"] = "{area:2622}",
		["The {object:142071} machine"] = "Die Maschine {object:142071}",
		["The {object:177675} is just behind the {area:2261}."] = "{object:177675} liegt gleich hinter {area:2261}.",
		["Use {npc:10980} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "Benutze {npc:10980} an {npc:7583}, dem Goblinmädchen in {area:976}. {npc:10977} und {npc:10978} erschreckst du später auf der Route.",
		["{item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once."] = "{item:15447} verdirbt binnen zehn Minuten: Töte die Geißel des Orts zügig und zerreibe die sieben Stücke sofort mit {item:15454}.",
		["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner."] = "Der Geist {npc:11140} steht bei einer Hütte im {area:2627}, in der Nordwestecke.",
		["{npc:15193}'s champion holds the {area:2260} farmhouse."] = "Der Champion von {npc:15193} hält das Bauernhaus von {area:2260}.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} auf der {area:1639}; {npc:246344}",
		["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771} lagert an der Straße zur {area:1336}, südlich von {area:976}.",
		["{npc:9299} is a ghost at the graveyard just north of {area:976}; the Conspicuous Gravestone is south of it, outside the town wall."] = "{npc:9299} ist ein Geist auf dem Friedhof gleich nördlich von {area:976}; Ein verdächtiger Grabstein liegt südlich davon, außerhalb der Stadtmauer.",
		["{object:1661}'s flight master is in the {object:36078}'s west tower, outside the walls."] = "Der Flugmeister von {object:1661} ist im Westturm des {object:36078}, außerhalb der Mauern.",
		["{quest:3914} goes back to Linken in Un'Goro: keep it."] = "{quest:3914} geht zurück zu Linken in Un'Goro: Behalte sie.",
		["{quest:5086} are in {zone:1448}, on a later trip: keep it if you have it."] = "{quest:5086} sind im {zone:1448}, auf einer späteren Reise: Behalte sie, falls du sie hast.",
		["{quest:5168}'s items lie in the later Plaguelands zones: keep it."] = "Die Gegenstände für {quest:5168} liegen in den späteren Gebieten der Pestländer: Behalte sie.",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["Andorhal watchtowers and silos"] = "Wachtürme und Silos von Andorhal",
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "Zurück zum Südwindposten und steig auf den Turm. Wenn du oben den Bau aufscheuchst, kommen Wegelagerer des Ashischwarms heraus; einer trägt {item:17346}.",
		["Back to {area:3425}"] = "Zurück nach {area:3425}",
		["Dithers offers {item:14619} ({quest:838}). Skip it."] = "Dithers bietet {item:14619} an ({quest:838}). Überspring sie.",
		["Dredge Crushers and Pincers"] = "Baggerbrecher und Steinpanzerzangen",
		["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "Baggerschläger, Steinpanzerskorpide und Sandhuscher teilen sich den Sand gleich nördlich der Burg.",
		["Dredge and scorpids"] = "Bagger und Skorpide",
		["East along the road, {npc:11077} guards the cauldron at {area:200}."] = "Weiter östlich an der Straße bewacht {npc:11077} den Kessel bei {area:200}.",
		["Flayers and Rock Stalkers"] = "Schinder und Felspirscher",
		["Fly to {area:1637} and train."] = "Flieg nach {area:1637} und trainiere.",
		["Fly to {area:976}. The {object:142071} stands in the middle of town."] = "Flieg nach {area:976}. Der {object:142071} steht mitten in der Stadt.",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "Geh nach Norden entlang der westlichen Dünen; Baggerbrecher und Steinpanzerzangen ziehen von hier bis zurück zur Burg umher.",
		["Keep {quest:3942}: {npc:9116} is at the {area:2479}, on the next guide's way through {zone:1448}."] = "Behalte {quest:3942}: {npc:9116} ist im Refugium ({area:2479}), auf dem Weg des nächsten Guides durch den {zone:1448}.",
		["Mar'alith's Dearest Natalia needs level 58 and leads into {area:2744} among elites. Skip it."] = "Mar'aliths Liebste Natalia braucht Stufe 58 und führt in den {area:2744} zwischen Elitegegner. Überspring sie.",
		["Mark {npc:10902} with the {item:12815}"] = "Markiere {npc:10902} mit der {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Markiere {npc:10903} mit der {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Markiere {npc:10904} mit der {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Markiere {npc:10905} mit der {item:12815}",
		["North to the lumber camp; set the termite barrel down in the middle of the mill."] = "Nach Norden zum Holzlager Northridge; stell das Fass mit Pestland-Termiten mitten in der Mühle ab.",
		["Ride east across the plaguelands to the chapel."] = "Reite nach Osten durch die Pestländer zur Kapelle.",
		["Ride east along the road to the {area:152} on the border."] = "Reite die Straße entlang nach Osten zum {area:152} an der Grenze.",
		["Ride east to {npc:1855}'s hut by the {area:2619} and hear him out."] = "Reite nach Osten zu {npc:1855}s Hütte am Fluss {area:2619} und hör ihn an.",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "Reite nach Nordosten zur {area:3077}; du verlässt {zone:1451} durch den Pass daneben.",
		["Ride north-east to {area:3447}."] = "Reite nach Nordosten zu {area:3447}.",
		["Ride north-west to {npc:1855}'s hut."] = "Reite nach Nordwesten zu {npc:1855}s Hütte.",
		["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "Reite nach Süden nach Andorhal. {npc:10667} wartet im verfallenen Gasthaus auf der Westseite der Stadt. Stell dich mit der {item:12815} in den Eingang jedes der vier Türme, um ihn zu markieren; halte dich an den Stadtrand. Benutze den {item:12627} bei den Silos mitten in der Stadt, um Temporale Parasiten hervorzulocken.",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "Reite nach Südosten zu {area:3447} unter den Klippen des Un'Goro-Kraters.",
		["Ride south-west to the ruins of {area:2738}. The {object:179565} for {npc:11801} sits inside one of the ruined houses."] = "Reite nach Südwesten zu den Ruinen vom {area:2738}. Der {object:179565} für {npc:11801} steht in einem der verfallenen Häuser.",
		["Ride south-west to {npc:10667} in Andorhal."] = "Reite nach Südwesten zu {npc:10667} in Andorhal.",
		["Ride to {area:2262} in the south-west; {npc:10926} plays among the houses. {npc:11886} lurks in the {area:2261}, the crypt just west of the town."] = "Reite nach {area:2262} im Südwesten; {npc:10926} spielt zwischen den Häusern. {npc:11886} lauert im Tiefgewölbe ({area:2261}), der Gruft gleich westlich des Orts.",
		["Ride west to the Horde camp north of {area:2744}."] = "Reite nach Westen zum Lager der Horde nördlich vom {area:2744}.",
		["Ride west to the walled hold in the middle of the desert."] = "Reite nach Westen zur ummauerten Burg mitten in der Wüste.",
		["Scourge Champions"] = "Champions der Geißel",
		["Scourge Champions roam the {area:2270}, north of the chapel. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants."] = "Champions der Geißel streifen durch das Tal ({area:2270}) nördlich der Kapelle. Führe {npc:11063}s {item:13156} über jeden, den du tötest: Die Schädel, die mitschwingen, sind die, die er will.",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "Silithystgeysire brechen überall in der südlichen Wüste aus. Lauf in das Silithyst, das einer zurücklässt, und bring es zum Silithyst Extractor der Horde in Kirikas Lager; Kämpfen oder Aufsteigen lässt es fallen.",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "Steinpanzerschinder und Felspirscher streifen durch die Dünen südwestlich von Kirikas Lager.",
		["Take the zeppelin from the tower outside {area:1637} to {zone:1420} and ride into the {zone:1458}. Lady Sylvanas holds the {object:36126}."] = "Nimm den Zeppelin vom Turm vor {area:1637} nach {zone:1420} und reite nach {zone:1458}. Fürstin Sylvanas hält das {object:36126}.",
		["The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too."] = "Die leuchtenden Tafelbruchstücke liegen um das Lager der Twilight im äußersten Nordwesten; die Staubstürmer und Wüstenrumpler dort lassen sie auch fallen.",
		["The libram lies further north, on the way to {area:190}."] = "Davils Buchband liegt weiter nördlich, auf dem Weg nach {area:190}.",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "Der Pass aus dem Un'Goro-Krater endet an der {area:3077}, dem Friedhof im Nordosten von {zone:1451}. {npc:13220} steht zwischen den Gräbern.",
		["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "Der Ranzen liegt in den Bergen im äußersten Süden, hinter Bronzebeards Lager. Totenstachel, ein Eliteskorpid, patrouilliert in der Nähe: Schnapp ihn dir, während er weg ist.",
		["The shield lies at {area:201}, south of {npc:1855}'s hut."] = "Der Schild liegt bei {area:201}, südlich von {npc:1855}s Hütte.",
		["The spare texts from the cultists"] = "Die übrigen Texte von den Kultisten",
		["Through the pass and east along the northern cliffs to {area:541}. {npc:8737} stands by the cave; {npc:9117} is inside it."] = "Durch den Pass und nach Osten entlang der nördlichen Klippen zu {area:541}. {npc:8737} steht bei der Höhle; {npc:9117} ist drinnen.",
		["Twilight Vanguard"] = "Vorhut der Twilight",
		["Use {npc:10980} on {npc:10977}"] = "Benutze {npc:10980} an {npc:10977}",
		["West to the {area:152}. The next guide starts in the {zone:1458}, a short ride west."] = "Nach Westen zum {area:152}. Der nächste Guide beginnt in {zone:1458}, ein kurzer Ritt nach Westen.",
		["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "Die Schlacht um Darrowshire von {npc:10667} endet gegen Elitegegner. Überspring sie.",
		["{npc:10778}'s farm is the first one east of the {area:152}. Jabbering Ghouls on the farm carry the other half of her charm; {npc:11075} guards the cauldron in the field."] = "Der Hof von {npc:10778} ist der erste östlich vom {area:152}. Plappernde Ghule auf dem Hof tragen die andere Hälfte ihres Amuletts; {npc:11075} bewacht den Kessel auf dem Feld.",
		["{npc:10926} and the {area:2261}"] = "{npc:10926} und {area:2261}",
		["{npc:10926}'s own errand is not on this route. Skip it."] = "{npc:10926}s eigener Auftrag ist nicht auf dieser Route. Überspring ihn.",
		["{npc:11803} walks the Vanguard camp in the far south-west. Every cultist here drops Encrypted Twilight Texts, quest or not: collect twenty, ten for {npc:15306} and ten for Ortell."] = "{npc:11803} läuft durch das Lager der Vorhut im äußersten Südwesten. Jeder Kultist hier lässt Verschlüsselte Texte der Twilight fallen, ob Quest oder nicht: Sammle zwanzig, zehn für {npc:15306} und zehn für Ortell.",
		["{npc:11804} stands in the outpost west of {area:3425}. Top your Encrypted Twilight Texts up to twenty on the cultists here."] = "{npc:11804} steht im Außenposten westlich von {area:3425}. Füll deine Verschlüsselten Texte der Twilight bei den Kultisten hier auf zwanzig auf.",
		["{npc:11878}' errands are not on this route. Skip them."] = "Die Aufträge von {npc:11878} sind nicht auf dieser Route. Überspring sie.",
		["{npc:15193}'s champion holds the {area:2260} farmhouse, north of the {area:2261}."] = "Der Champion von {npc:15193} hält das Bauernhaus von {area:2260}, nördlich vom Tiefgewölbe ({area:2261}).",
		["{npc:15200} holds the camp in the west."] = "{npc:15200} hält das Lager im Westen.",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}, auf der Westseite der Burg",
		["{npc:1855}'s next task, Of Lost Honor, is not on this route. Skip it."] = "{npc:1855}s nächste Aufgabe, Von verlorener Ehre, ist nicht auf dieser Route. Überspring sie.",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "Zurück in den Tunnel der Holzschlundfeste und nimm den Ausgang nach {zone:1452}; {npc:9298} lagert gleich draußen bei den heißen Quellen.",
		["Back south to the Sanctuary, a short ride."] = "Zurück nach Süden zum Refugium, ein kurzer Ritt.",
		["Dungeon instead of grinding"] = "Dungeon statt Grinden",
		["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "Flieg zum {area:431} und reite auf der Straße nach Nordwesten aus {zone:1440} in den {zone:1448}. {area:2479} ist das Lager der Druiden gleich hinter der Grenze.",
		["From the {zone:1458}, take the zeppelin from the tower outside the city to {zone:1454}."] = "Nimm in {zone:1458} den Zeppelin am Turm vor der Stadt nach {zone:1454}.",
		["Grind to 60"] = "Grinde bis 60",
		["In {zone:1454}: fly from {area:2255}"] = "In {zone:1454}: Flieg von {area:2255}",
		["In {zone:1456}: fly from {area:2255}"] = "In {zone:1456}: Flieg von {area:2255}",
		["Only if you carry {quest:5087}: the runners walk the road from {area:1769} toward {area:2244} in small groups; wait by the road near {npc:9298} and kill them as they pass. Each one carries a crate."] = "Nur wenn du {quest:5087} hast: Die Läufer gehen in kleinen Gruppen die Straße von der {area:1769} zum {area:2244}; warte an der Straße nahe {npc:9298} und töte sie im Vorbeigehen. Jeder trägt eine Kiste.",
		["Only if {npc:9298} gave you {quest:5086}: ride north up the {zone:1448} road to {area:1767}; the {quest:5086} ooze between the trees."] = "Nur wenn {npc:9298} dir {quest:5086} gegeben hat: Reite die Straße im {zone:1448} nach Norden zum Gebiet {area:1767}; die {quest:5086} kriechen zwischen den Bäumen.",
		["Only with 30 {quest:6031}, and only at Neutral with the Timbermaw: follow the road north to {area:1769}; {npc:11557} trades just inside the entrance."] = "Nur mit 30 {quest:6031} und nur bei Neutral mit der Holzschlundfeste: Folge der Straße nach Norden zur {area:1769}; {npc:11557} handelt gleich hinter dem Eingang.",
		["Optional. Running {area:2279}, {area:2057}, Lower Blackrock Spire or {area:1584} with a group instead of grinding gets you there faster."] = "Optional. {area:2279}, {area:2057}, die Untere Blackrockspitze oder {area:1584} mit einer Gruppe statt Grinden bringt dich schneller ans Ziel.",
		["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "Optional: Mit einer Gruppe ersetzt ein Dungeon der Stufe 55-60 das Grinden unten.",
		["Ride east along the road to {area:2255}."] = "Reite auf der Straße nach Osten nach {area:2255}.",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "Reite auf der Straße nach Norden an {area:1763} vorbei zum {area:1997}.",
		["Ride north-west to {area:1763}. The four braziers stand among the Shadow Council's buildings; use the Cleansed Water on each one."] = "Reite nach Nordwesten nach {area:1763}. Die vier Kohlenbecken stehen zwischen den Gebäuden des Schattenrats; benutze das gereinigte Wasser an jedem.",
		["South to the Sanctuary once more."] = "Noch einmal nach Süden zum Refugium.",
		["The quests run out here. Rabid Shardtooths prowl {area:2249} in southern {zone:1452}, south of the road from {area:2255}."] = "Hier gehen die Quests aus. Tollwütige Splitterzähne streifen durch die {area:2249} im südlichen {zone:1452}, südlich der Straße von {area:2255}.",
		["The {area:2479}"] = "{area:2479}",
		["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "Durch den Tunnel der Holzschlundfeste nach {zone:1450}. {npc:11939} liest in einem Haus in {area:2361}.",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["grind on {npc:7446} at {area:2249}, {zone:1452}"] = "Töte {npc:7446} in der {area:2249}, {zone:1452}",
		["{npc:10306}'s next {quest:4741} would bring you back here from {zone:1452}. Skip it."] = "{npc:10306}s nächste Quest {quest:4741} würde dich aus {zone:1452} hierher zurückbringen. Überspringe sie.",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "{npc:11801}s Die Splitter der Teufelsranke braucht {area:2577}. Überspringe sie.",
		["{npc:9116}'s Silver Heart needs an {item:11173} from northern {zone:1448} and a ride back here. Skip it."] = "{npc:9116}s Quest Silberherz braucht ein {item:11173} aus dem nördlichen {zone:1448} und einen Ritt zurück hierher. Überspringe sie.",
		["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "{npc:9298} schickt dich als Nächstes zu {npc:10738}, einem Elite in seiner Höhle. Überspringe es.",
		["{npc:9861}, {npc:9860} and {npc:9517} wait at the back of {area:1770}, the cave in {area:1763}'s north. Clear the tunnel as you go."] = "{npc:9861}, {npc:9860} und {npc:9517} warten hinten in der {area:1770}, der Höhle im Norden von {area:1763}. Räum den Tunnel auf dem Weg frei.",
} end)()
t.guides["forever/horde/orc-troll/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Gepanzerte Skorpide kriechen über die Ebenen westlich von {area:362}. Zähm einen und kehr dann zu {npc:3171} zurück.",
		["Back at the Den"] = "Zurück am Höhlenbau",
		["Back east to the shore north of {npc:275657}. Spitelash Scouts and Attendants hold the beach below {area:370}. Hunters: tame a {npc:3107} on the beach."] = "Zurück nach Osten zum Ufer nördlich von {npc:275657}. Späher und Bedienstete der Grollflossen halten den Strand unterhalb von {area:370}. Jäger: Zähm am Strand einen {npc:3107}.",
		["Back south to {area:362}."] = "Zurück nach Süden nach {area:362}.",
		["Back to the Den"] = "Zurück zum Höhlenbau",
		["Back to {area:362}."] = "Zurück nach {area:362}.",
		["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "Zurück zu {npc:5875} in {object:172960}. Benutze dort {item:7464} am Beschwörungskreis und besiege den Leerwandler, um ihn zu binden.",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Kultisten der Burning Blade halten die Höhlen von {quest:827}; jeder lässt {item:4871} fallen. {npc:3204}, ein Hexenmeister der Stufe 14, steht tief drinnen und lässt {item:4903} fallen.",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Teufelspirscher streifen über den Hang unterhalb der Höhle, auf der Nordseite des Tals.",
		["Fizzle holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the {item:15908} on the way."] = "Fizzle hält das Lager der Burning Blade auf dem {area:369}, nordwestlich von {area:362}. Jäger: Zähm unterwegs einen {npc:3099} mit {item:15908}.",
		["Follow the road east out of the valley to {area:367} on the coast."] = "Folge der Straße nach Osten aus dem Tal nach {area:367} an der Küste.",
		["Follow the road north from {area:362} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "Folge der Straße von {area:362} nach Norden zum Haupttor von {zone:1454}, gleich westlich von {area:817}. {npc:3352} steht bei den Jägerlehrern im {object:172958}.",
		["Follow the road north to {area:362}."] = "Folge der Straße nach Norden nach {area:362}.",
		["Follow the road north toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Folge der Straße nach Norden Richtung {zone:1454}. {npc:3293} lagert daneben; die gestohlenen Säcke liegen an der Straße südlich von ihm.",
		["Follow the road south-west from {area:379} to the {area:380}. {zone:1413} guide starts here."] = "Folge der Straße von {area:379} nach Südwesten nach {area:380}. Hier beginnt der Guide für {zone:1413}.",
		["Follow the road west from {area:362} over the {area:814} bridge; {area:379} sits just above it on the {zone:1413} side."] = "Folge der Straße von {area:362} nach Westen über die Brücke am {area:814}; {area:379} liegt gleich darüber auf der Seite des {zone:1413}.",
		["Free {npc:275811} and see her safely out of the crag"] = "Befrei {npc:275811} und bring sie sicher aus dem Felsen",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "Geh nach Süden über die Inseln. Die Loa-Götzen liegen überall auf den südlichen Inseln; Voodootrolle und Verhexte Trolle halten sie und lassen die Verhexten Anhänger ({item:275724}) fallen. {quest:826} und Minshinas Käfig sind auf der südlichsten Insel.",
		["Hit the sleeping peons north of the Den with the {item:16114}."] = "Schlag die schlafenden Peons nördlich des Höhlenbaus mit {item:16114}.",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Geh in der Höhle an der ersten Gabelung geradeaus, dann rechts, und folge dem Bach zu deiner Linken bis zum Wasserfall: Die Hacke leuchtet am Wasser, hinter einer Felssäule.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Halte dich in der Höhle immer an der rechten Wand, über den Bach: {npc:3183} wartet am Ende.",
		["Makrura and crawlers"] = "Makrura und Kriecher",
		["Makrura and surf crawlers line the beaches north-east of Sen'jin."] = "Makrura und Brandungskriecher säumen die Strände nordöstlich von Sen'jin.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "Mishas Hütte steht südlich der Echsen. Die Krokilisken am {area:814} im Westen tragen {item:4891}.",
		["North end of the valley"] = "Nordende des Tals",
		["Prickly pears"] = "Kaktusfeigen",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Stacheleber und Späher halten die Hütten westlich des Orts; Staubläufer und Schlachtwachen halten die Lager weiter westlich.",
		["Ridgeshade spiders"] = "Kammschattenspinnen",
		["Savages and Storm Witches nest in {area:370}, east of {npc:3293}. A Storm Witch drops the {item:277661}."] = "Wilde und Sturmhexen der Staubschwingen nisten in {area:370}, östlich von {npc:3293}. Eine Sturmhexe lässt {item:277661} fallen.",
		["South-east shore"] = "Südostufer",
		["Spitelash naga"] = "Naga der Grollflossen",
		["Talk to {npc:3191}"] = "Sprich mit {npc:3191}",
		["Tame it with the {item:15908}"] = "Zähm ihn mit {item:15908}",
		["The foreman stands at the lumber pile east of the Den."] = "Der Großknecht steht am Holzstapel östlich des Höhlenbaus.",
		["The gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin."] = "Die Gnomen-Werkzeugkästen liegen in den Trümmern am Ufer östlich und südöstlich von {area:362}. Folge dem Ufer nach Süden nach Sen'jin.",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "Die Burg steht an der Küste südöstlich von {area:362}. Axt, Bogen und Schild der Räuber liegen an ihrem Rand. Matrosen und Marinesoldaten lassen {item:4870} fallen. {npc:3192} wartet oben in der Burg; sein Schlüssel öffnet die Truhe neben ihm, in der {item:4881} liegt.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Die Kaktusfeigen wachsen zwischen den Hütten der Stacheleber gleich westlich des Orts.",
		["The spiders lurk in the hills along the road north toward {area:362}."] = "Die Spinnen lauern in den Hügeln an der Straße nach Norden Richtung {area:362}.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Die Waffen liegen um den Höhlenbau und den Übungsplatz; die Scheckigen Eber streifen über den ganzen Talboden.",
		["The wreckage"] = "Das Wrack",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595} steht in {area:817}, zwischen den Kultisten, die du gerade bekämpft hast.",
		["The {quest:792} swarm the slope below the {area:365}, the cave on the valley's north side."] = "{quest:792} schwärmen über den Hang unterhalb des {area:365}, der Höhle auf der Nordseite des Tals.",
		["Thunder Lizards and Lightning Hides graze on {area:369} across the bridge; any of them can drop a {item:6486}."] = "Donnerechsen und Blitzechsen grasen jenseits der Brücke auf dem {area:369}; jede kann {item:6486} fallen lassen.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}."] = "Donnerechsen und Blitzechsen grasen auf dem {area:369}, gleich westlich und südwestlich von {npc:3293}.",
		["Thunder lizards"] = "Donnerechsen",
		["Thunder lizards across the river"] = "Donnerechsen jenseits des Flusses",
		["Training weapons and boars"] = "Übungswaffen und Eber",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there."] = "Wate hinüber zur nördlichen Echoinsel. Die Matriarchin streift dort zwischen den Raptoren umher.",
		["Wade back west to the shore south of Sen'jin. Durotar Tigers roam it and the Taillasher eggs sit in nests along the beach."] = "Wate zurück nach Westen zum Ufer südlich von Sen'jin. Durotar-Tiger streifen dort umher, und die Schwanzpeitscher-Eier liegen in Nestern am Strand.",
		["Wake {quest:5441} with the {item:16114}"] = "Weck {quest:5441} mit {item:16114}",
		["the {object:654925} on the ground beside her"] = "{object:654925} neben ihr auf dem Boden",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} liegt westlich von Sen'jin. Die drei Angriffspläne liegen zwischen den Zentaurenzelten auf dem Boden. {npc:275811} wird ebenfalls am Felsen festgehalten.",
		["{area:817}'s mouth"] = "Eingang von {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, wo du startest",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears."] = "{npc:265809} lagert gleich südlich von {area:362}. Setz dich an sein Lagerfeuer (/sit), bis der Buff {spell:1229451} erscheint.",
		["{npc:265809}'s campfire"] = "Lagerfeuer von {npc:265809}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: nur für Verzauberer, die Rückstände werden aus Verhexten Anhängern ({item:275724}) entzaubert",
		["{npc:266940}, on the east side of town"] = "{npc:266940}, auf der Ostseite des Orts",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} steht am Ufer östlich von {area:362}. Dreizack, Banner und Dolch liegen um ihn herum am Strand.",
		["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}, ein junger Meeresriese, läuft an der Nordküste von {zone:1411} entlang, nördlich des Nagastrands. {npc:275666} ist Elite: Such dir am besten eine Gruppe.",
		["{npc:3102} hooves"] = "{npc:3102}-Hufe",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, zurück in {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, ein Elite-Meeresriese",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} steht gleich hinter dem Höhleneingang; {npc:3159} hinten in der Höhle hinter ihm.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} wartet im Höhlenbau, dem Gebäude gleich westlich von {npc:10176}.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, im Wachturm",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, der Kriegerlehrer neben dem Höhlenbau",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, der Jägerlehrer neben dem Höhlenbau",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, der Schurkenlehrer im Höhlenbau",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, der Hexenmeisterlehrer hinten in der Höhle",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, der Schamanenlehrer neben dem Höhlenbau",
		["{npc:3159}, at the back of the cave"] = "{npc:3159}, hinten in der Höhle",
		["{npc:3171}: {npc:3352} in {zone:1454} teaches {spell:5149}"] = "{npc:3171}: {npc:3352} in {zone:1454} lehrt {spell:5149}",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} liegt verwundet am Fuß der Hügel nordwestlich des Höhlenbaus.",
		["{npc:3294}, by the inn"] = "{npc:3294}, beim Gasthaus",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}, für {npc:6018} in {zone:1454}: behalte sie",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}, der Priesterlehrer am Höhlenbau",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, die Magierlehrerin, am Eingang zum Höhlenbau",
		["{npc:5887} stands just outside the Den."] = "{npc:5887} steht gleich vor dem Höhlenbau.",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} steht vor dem Höhlenbau. {area:639} ist der Hügel gleich südlich davon: Trink dort {item:6635}, um {npc:5891} zu sehen, und bring dann {item:6656} zurück zu {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} und dein {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, auf dem {area:639}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} steht auf der Straße am östlichen Ausgang des Tals.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, am Kochfeuer",
		["{quest:790}, a large scorpid, prowls the slope south of {npc:3287} among the Scorpid Workers; pick the Cactus Apples by the cactuses on the way."] = "{quest:790}, ein großer Skorpid, streift zwischen den Skorpidarbeitern über den Hang südlich von {npc:3287}; pflück unterwegs die Kaktusäpfel an den Kakteen.",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} lagert auf dem Hügel westlich des Nagastrands, südlich von {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "Das Haupttor von {zone:1454} liegt gleich westlich von {area:817}. {npc:5875} steht in {object:172960}, der Schlucht unter dem {object:172982}.",
} end)()
t.guides["forever/horde/orc-troll/02-the-barrens"] = (function() return {
		["Back to the pirate camp: the boots are in the crate marked {object:3767} at the camp's south end, the lens in the Fragile crate just east of it."] = "Zurück zum Piratenlager: Die Stiefel sind in der Kiste mit der Aufschrift {object:3767} am Südende des Lagers, die Linse in der zerbrechlichen Kiste gleich östlich davon.",
		["Back to the {area:380}"] = "Zurück nach {area:380}",
		["Back to the {area:380}; the next guide starts here."] = "Zurück nach {area:380}; der nächste Guide beginnt hier.",
		["Burning Blade Cultists hold {area:1898} in northern {zone:1411}, by {area:370}; they drop the {item:6652}."] = "Kultisten der Burning Blade halten {area:1898} im Norden von {zone:1411}, bei {area:370}; sie lassen {item:6652} fallen.",
		["Follow the road north to the {area:1703}; {npc:9316} stands just south of it."] = "Folge der Straße nach Norden zum {area:1703}; {npc:9316} steht gleich südlich davon.",
		["Follow the road south-east to {area:392} on the coast."] = "Folge der Straße nach Südosten nach {area:392} an der Küste.",
		["Head east to the Venture Co. research site west of the {area:382}. Use the {object:4141}, close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471}."] = "Geh nach Osten zur Forschungsstätte der Venture Co. westlich vom {area:382}. Benutze {object:4141}, schließ die drei Ventile um den Bohrer, benutze die Konsole erneut und nimm dann {item:5089} von {npc:3471}.",
		["Kolkar camps and the {area:386}"] = "Lager der Kolkar und {area:386}",
		["Oasis Snapjaws crowd the water of {area:387}, south-west of the {area:380}."] = "Oasenschnappkiefer drängen sich im Wasser von {area:387}, südwestlich von {area:380}.",
		["On the way back to the {area:380}, the Razormane camp again: Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "Auf dem Rückweg nach {area:380} wieder das Lager der Grimmhauer: Geomanten und Verteidiger halten die östliche Hälfte; {npc:3438} läuft zwischen ihnen herum.",
		["Plainstriders and Sunscale raptors roam the plains all around the {area:380}."] = "Ebenenschreiter und Raptoren der Bluthorn streifen überall um {area:380} über die Ebenen.",
		["Plainstriders and raptors"] = "Ebenenschreiter und Raptoren",
		["Razormane camp"] = "Lager der Grimmhauer",
		["Southsea beach"] = "Strand der Südmeerfreibeuter",
		["The Kolkar camps spread north-west of {npc:3389}; every Kolkar can drop {quest:855}. {area:386} lie in their middle, with Laden Mushrooms around the water. Savannah Prowlers roam the same plains."] = "Die Lager der Kolkar verteilen sich nordwestlich von {npc:3389}; jeder Kolkar kann {quest:855} fallen lassen. {area:386} liegen in ihrer Mitte, mit Potenten Pilzen rund ums Wasser. Savannenstreuner streifen über dieselben Ebenen.",
		["The Slayers hold the western end of the {area:383}, past the harpies you fought before; they drop the rings."] = "Die Töterinnen halten das westliche Ende von {area:383}, hinter den Harpyien, die du schon bekämpft hast; sie lassen die Ringe fallen.",
		["The Tool Buckets sit around the Venture Co. camp in the {area:382}, east of {npc:9316}."] = "Die Werkzeugkisten stehen um das Lager der Venture Co. im {area:382}, östlich von {npc:9316}.",
		["The harpies nest in the {area:383} north-west of the {area:386}; any of them can drop a talon."] = "Die Harpyien nisten in {area:383} nordwestlich von {area:386}; jede kann eine Klaue fallen lassen.",
		["The oasis lies south-east of the {area:380}. Test the seeds at the bubbling fissure in the middle of the water."] = "Die Oase liegt südöstlich von {area:380}. Teste die Samen an der blubbernden Spalte mitten im Wasser.",
		["The pirates camp along the beach south of {area:392}. The piles of complicated parts lie in and around their camp."] = "Die Piraten lagern am Strand südlich von {area:392}. Die Haufen komplizierter Teile liegen in und um ihr Lager.",
		["The {area:1697} lie south-west of the oasis. Sunscale Scytheclaws drop the feathers you use on the three nests."] = "{area:1697} liegt südwestlich der Oase. Bluthornsensenklauen lassen die Federn fallen, die du an den drei Nestern benutzt.",
		["Wade into the pools to explore them"] = "Wate in die Teiche, um sie zu erkunden",
		["Walk back up the road to the {area:380}. Savannah Prowlers hunt along it and on the plains west of town: finish the claws before you hand them in."] = "Geh die Straße zurück hinauf nach {area:380}. Savannenstreuner jagen an ihr entlang und auf den Ebenen westlich des Orts: Sammle die restlichen Klauen, bevor du sie abgibst.",
		["Water Seekers, Thornweavers and Hunters hold the camp east of the {area:380}. The supply crates sit at its eastern end. Warriors: the {object:58369} stands in the camp. Shamans: the quilboar drop the {item:5026}. Kill Savannah Prowlers you pass for their claws."] = "Wassersucher, Dornenwirker und Jäger halten das Lager östlich von {area:380}. Die Vorratskisten stehen an seinem östlichen Ende. Krieger: {object:58369} steht im Lager. Schamanen: Die Stacheleber lassen {item:5026} fallen. Töte Savannenstreuner, an denen du vorbeikommst, für ihre Klauen.",
		["Witchwing Slayers"] = "Töterinnen der Hexenschwingen",
		["Witchwing harpies"] = "Harpyien der Hexenschwingen",
		["You arrive from {area:379}. {npc:3338} stands by the inn; {npc:3429} and {npc:3449} on the tower platform; Helbrim and {npc:3464} by the north gate; {npc:3448} at the south gate."] = "Du kommst von {area:379}. {npc:3338} steht beim Gasthaus; {npc:3429} und {npc:3449} auf der Turmplattform; Helbrim und {npc:3464} am Nordtor; {npc:3448} am Südtor.",
		["Zhevra Runners graze on the same plains; finish the raptor heads as you go."] = "Zhevra-Läufer grasen auf denselben Ebenen; sammle dabei die restlichen Raptorköpfe.",
		["Zhevra and raptors"] = "Zhevras und Raptoren",
		["grind on Witchwing Slayers at the {area:383}, {zone:1413}"] = "grinde Töterinnen der Hexenschwingen in {area:383}, {zone:1413}",
		["{area:1898} cultists"] = "Kultisten in {area:1898}",
		["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "{npc:3389} steht am Wachposten der Kolkar gleich westlich von {area:380}.",
		["{npc:3449}, on the tower platform: needs level 12"] = "{npc:3449}, auf der Turmplattform: erfordert Stufe 12",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878} lagert an der Straße nach Osten Richtung {area:392}.",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900} macht aus dem Teer und dem Beutel {item:6636}. Benutze es am Kohlenbecken neben ihm, um {npc:5893} sichtbar zu machen, töte sie für {item:6655} und leg die Glut dann ins Kohlenbecken.",
		["{npc:5900} waits on the {zone:1411} bank of the {area:814}, east of the Razormane camp."] = "{npc:5900} wartet am Ufer des {area:814} auf der Seite von {zone:1411}, östlich des Lagers der Grimmhauer.",
		["{npc:5907} stands on the ridge north of the Razormane camp, east of the {area:380}."] = "{npc:5907} steht auf dem Kamm nördlich des Lagers der Grimmhauer, östlich von {area:380}.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, dein {item:5176} und {item:263412}",
		["{quest:1492}, on the dock"] = "{quest:1492}, am Kai",
		["{quest:881}'s lair lies south of the {area:382}, north-east of the {area:380}. Use the horn {npc:3338} gave you there to call the white lion out. Then hearth to {area:392}."] = "Der Unterschlupf von {quest:881} liegt südlich vom {area:382}, nordöstlich von {area:380}. Benutze dort das Horn, das {npc:3338} dir gegeben hat, um den weißen Löwen hervorzulocken. Nimm dann den Ruhestein nach {area:392}.",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sit an {npc:263664}s Lagerfeuer, bis du {spell:1229451} bekommst",
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Aanders und die gefallenen Wachen liegen gleich südwestlich des Turms. Nimm Raanis Glücksfeder und das Schattensang-Familiensiegel von den Leichen.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "Zurück in {quest:92529}: Sturmrufer und {npc:251662} füllen das Dorf, die Vorratskisten stehen zwischen den Häusern und {npc:251966} wartet an seinem Südostende.",
		["Back to {area:16624} with what you found."] = "Zurück nach {area:16624} mit dem, was du gefunden hast.",
		["Back to {area:16635}"] = "Zurück nach {area:16635}",
		["Back to {area:16638}"] = "Zurück nach {area:16638}",
		["Back to {npc:268592}, then west into the {area:16623}: {npc:268605}'s home is in the hills south of the Windsong Crawlers' lakes."] = "Zurück zu {npc:268592}, dann nach Westen in {area:16623}: {npc:268605}s Zuhause ist in den Hügeln südlich der Seen der Windweisenkriecher.",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "Zurück zu {npc:268592}. Warte, bis er {npc:268762} entzündet, und trag die Flamme dann direkt zu {npc:268679} neben {npc:252382} in {area:16638}, bevor der Timer abläuft.",
		["Bandit Highwaymen"] = "Banditenstraßenräuber",
		["Cast {spell:1259686} near the {object:460001}"] = "Wirke {spell:1259686} nahe {object:460001}",
		["Climb the watchtower in the village, jump off the top and use {spell:1259416} to float down."] = "Steig auf den Wachturm im Dorf, spring von oben und benutze {spell:1259416}, um hinabzuschweben.",
		["Faladiel stands on the hill west of the falls, north of {area:16638}."] = "Faladiel steht auf dem Hügel westlich der Fälle, nördlich von {area:16638}.",
		["Find {npc:258130}"] = "Finde {npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle."] = "Folge der Straße nach Süden nach {area:16624}, in der Mitte der Insel.",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "Geh nach Norden in {area:16631}; {npc:257944} lagert an seinem Südrand.",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "Geh nach Südwesten zum {area:17674}. {npc:252155} ist oben; {item:254871} liegt neben ihm.",
		["Heal the injured druids in the Nightfang Den"] = "Heile die verletzten Druiden im Nachtfangbau",
		["High Order Apprentices"] = "Lehrlinge des Hohen Ordens",
		["Hippogryph nests"] = "Hippogryphennester",
		["Horde airship"] = "Luftschiff der Horde",
		["Leave {zone:1456} by a lift and follow the road south past {area:222} and through the eastern pass into the {zone:1413}; from the pass, take the {area:458} north to the {area:380}, the Horde town in the middle of the {zone:1413}."] = "Verlass {zone:1456} mit einem Aufzug und folge der Straße nach Süden an {area:222} vorbei und durch den östlichen Pass ins {zone:1413}; nimm vom Pass aus die {area:458} nach Norden nach {area:380}, der Hordestadt mitten im {zone:1413}.",
		["Leaving {area:16635}"] = "Abschied von {area:16635}",
		["Listen to {npc:252448}'s story"] = "Hör dir die Geschichte von {npc:252448} an",
		["Listen to {npc:256083}"] = "Hör {npc:256083} zu",
		["Northern {zone:1412}"] = "Nördliches {zone:1412}",
		["On the way north, back to {npc:255853} by the falls."] = "Auf dem Weg nach Norden zurück zu {npc:255853} an den Fällen.",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "Lästige Zirrusfliegen und {npc:250873} streifen durch den Hain gleich südöstlich des Dorfs.",
		["Prideclaws and Galestriders"] = "Rudelkrallen und Windschreiter",
		["Prideclaws and Galestriders share the meadows south of the village. Keep the {item:5469} for {npc:251905}; the eggs come later from the hippogryphs."] = "Rudelkrallen und Windschreiter teilen sich die Wiesen südlich des Dorfs. Behalte {item:5469} für {npc:251905}; die Eier kommen später von den Hippogryphen.",
		["Raw Windstones"] = "Rohe Windsteine",
		["Ride north-east to the {area:17675}. The Al'Aketh camp is just west of it, with {npc:252666} at its north end. Every cultist can drop a windstone charm."] = "Reite nach Nordosten zum {area:17675}. Das Lager der Al'Aketh liegt gleich westlich davon, mit {npc:252666} an seinem Nordende. Jeder Kultist kann ein Windsteinamulett der Al'Aketh fallen lassen.",
		["Sit by {npc:263664}'s campfire (type /sit) until you get the {spell:1229451} buff, then find {npc:251905} at the cook fire."] = "Setz dich an {npc:263664}s Lagerfeuer (tippe /sit), bis du den Buff {spell:1229451} bekommst, und such dann {npc:251905} am Kochfeuer.",
		["Skyhoppers"] = "Himmelshüpfer",
		["Skyhoppers hop about the fields just west of Valennia."] = "Himmelshüpfer hüpfen über die Felder gleich westlich von Valennia.",
		["Spread the {item:278078} off {area:1641}"] = "Verstreu {item:278078} von der {area:1641}",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "Sturmäpfel und Flatterfliegenstaub liegen überall im Obstgarten; Hungrige Banditen plündern ihn. Windschreiter grasen auf den Feldern östlich davon. Das kaputte Konstrukt schwebt am Nordrand des Obstgartens.",
		["Take the Torch of Dormant Flame to {npc:268592} at the Shrine of Flames, south-west of {area:16638} in the {area:16626}."] = "Bring die Fackel der schlafenden Flamme zu {npc:268592} am Schrein der Flammen, südwestlich von {area:16638} in {area:16626}.",
		["Take the portal up to the {area:16630} and join {npc:252475} and {npc:251968} against the High Priestess."] = "Nimm das Portal hinauf zu {area:16630} und schließ dich {npc:252475} und {npc:251968} gegen die Hohepriesterin an.",
		["Take the road south-east to {area:16638}, the Skyborne town on the south coast. {npc:257006} and {npc:252448} stand at its western edge."] = "Nimm die Straße nach Südosten nach {area:16638}, der Stadt der Himmelsgeborenen an der Südküste. {npc:257006} und {npc:252448} stehen an ihrem Westrand.",
		["Talk to {npc:251902}"] = "Sprich mit {npc:251902}",
		["Talk to {npc:251968}"] = "Sprich mit {npc:251968}",
		["Talk to {npc:252383}"] = "Sprich mit {npc:252383}",
		["Talk to {npc:252800}"] = "Sprich mit {npc:252800}",
		["Talk to {npc:253576}"] = "Sprich mit {npc:253576}",
		["Talk to {npc:254089}"] = "Sprich mit {npc:254089}",
		["Tell {npc:252800} you're ready"] = "Sag {npc:252800}, dass du bereit bist",
		["The Al'Aketh camp"] = "Das Lager der Al'Aketh",
		["The Al'Aketh cultists in the camp beyond {npc:252095} carry the signet."] = "Die Kultisten der Al'Aketh im Lager hinter {npc:252095} tragen das Siegel.",
		["The Horde airship docks at the south-west edge of {area:16638}. Ride it to Kalimdor; it lands in northern {zone:1412}."] = "Das Luftschiff der Horde legt am Südwestrand von {area:16638} an. Fahr damit nach Kalimdor; es landet im Norden von {zone:1412}.",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "Die Rohen Windsteine sind blaue Kristalle an den Hängen rund ums Dorf.",
		["The Ursera den is west of the village. {npc:251115}, their matriarch, sits at its far end."] = "Der Bau der Ursera liegt westlich des Dorfs. {npc:251115}, ihre Matriarchin, sitzt an seinem hinteren Ende.",
		["The airship"] = "Das Luftschiff",
		["The apprentices practise north-east of the village."] = "Die Lehrlinge üben nordöstlich des Dorfs.",
		["The bandit camps are north-east of the village; \"Badwind\" Bennic holds the top camp. Bandits carry the stolen windstones."] = "Die Banditenlager liegen nordöstlich des Dorfs; \"Übelwind\" Bennic hält das oberste Lager. Banditen tragen die gestohlenen Windsteine.",
		["The crawlers scuttle along the shore south-west of town."] = "Die Kriecher krabbeln am Ufer südwestlich der Stadt entlang.",
		["The hermit lives at {area:16625}'s west shore. {item:257128} cones grow south of him; the Wind Hollows drift east of the lake."] = "Der Einsiedler lebt am Westufer von {area:16625}. Zapfen der {item:257128} wachsen südlich von ihm; die Windhüllen treiben östlich des Sees.",
		["The highland bandits"] = "Die Hochlandbanditen",
		["The highwaymen hold the hills north-east of the orchard. More {object:616468} lie near the road to {area:16638}."] = "Die Straßenräuber halten die Hügel nordöstlich des Obstgartens. Weitere {object:616468} liegen nahe der Straße nach {area:16638}.",
		["The hippogryph nests are north-west of the tower, west of {quest:92529}; the Matriarch sits at the western end. {item:263493} lies on the ground around them, and the hippogryphs drop the Small Eggs."] = "Die Hippogryphennester liegen nordwestlich des Turms, westlich von {quest:92529}; die Matriarchin sitzt am westlichen Ende. {item:263493} liegt um sie herum auf dem Boden, und die Hippogryphen lassen die Kleinen Eier fallen.",
		["The orchard"] = "Der Obstgarten",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "Die Königin schwebt am Südostende des Hains, auf deinem Rückweg von den Steinen.",
		["The refugees' belongings lie along the north shore of {area:16625}; {npc:259013} is at its north-west end."] = "Die Habseligkeiten der Flüchtlinge liegen am Nordufer von {area:16625}; {npc:259013} ist an seinem Nordwestende.",
		["The standing stones"] = "Die Menhire",
		["The turncoat"] = "Der Überläufer",
		["The turncoat's house is in the {area:16626} north-west of {area:16638}. {npc:273017} waits nearby; his assassins lurk around the house."] = "Das Haus des Überläufers ist in {area:16626} nordwestlich von {area:16638}. {npc:273017} wartet in der Nähe; seine Attentäter lauern ums Haus.",
		["The watchtower"] = "Der Wachturm",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "{area:16629} liegt nördlich von {area:16638}. Kämpf dich durch die Wachen hinauf zu {npc:253576} auf seiner Ostseite.",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {object:148418}"] = "{object:148418}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Benutze {item:278078} an der Zeremonienmatte und dem Räuchergefäß an der Südklippe der {area:1641}.",
		["Walk north to {area:16624}; finish the {item:5469} on the Galestriders along the way if you are short."] = "Geh nach Norden nach {area:16624}; erledige unterwegs an den Windschreitern das restliche {item:5469}, falls dir welches fehlt.",
		["Wind Hollows and {object:616467}"] = "Windhüllen und {object:616467}",
		["Wind Hollows drift over the lowlands around {area:16638}. The first {object:616467} lie west of the orchard road."] = "Windhüllen treiben über das Tiefland um {area:16638}. Die ersten {object:616467} liegen westlich der Obstgartenstraße.",
		["Windsong Crawlers"] = "Windweisenkriecher",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "Du verlässt die Insel endgültig. {npc:259119} wartet, wo das Luftschiff landet.",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "Du wachst in {area:16635} auf, im Norden der Insel. {npc:251362} steht am Pfad, {npc:251361} in der Dorfmitte.",
		["search the dead cultist in the house"] = "durchsuch den toten Kultisten im Haus",
		["search the wardrobe"] = "durchsuch den Kleiderschrank",
		["talk to {npc:251684}"] = "sprich mit {npc:251684}",
		["talk to {npc:251902}"] = "sprich mit {npc:251902}",
		["talk to {npc:251905}"] = "sprich mit {npc:251905}",
		["talk to {npc:251968}"] = "sprich mit {npc:251968}",
		["talk to {npc:252155}"] = "sprich mit {npc:252155}",
		["talk to {npc:252383}"] = "sprich mit {npc:252383}",
		["talk to {npc:252476}"] = "sprich mit {npc:252476}",
		["talk to {npc:257554}"] = "sprich mit {npc:257554}",
		["the bounty board"] = "das Kopfgeldbrett",
		["{area:1638} is beside the landing: ride up a lift and learn the flight path from {npc:2995}, the wind rider master."] = "{area:1638} liegt neben der Landestelle: Fahr mit einem Aufzug hinauf und hol dir die Flugroute bei {npc:2995}, dem Windreitermeister.",
		["{area:16624} turn-ins"] = "Abgaben in {area:16624}",
		["{area:16624}, last time"] = "{area:16624}, ein letztes Mal",
		["{area:16635} turn-ins"] = "Abgaben in {area:16635}",
		["{area:16663} is west of {area:16638} along the coast road."] = "{area:16663} liegt westlich von {area:16638} an der Küstenstraße.",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "{item:265105} wächst um {npc:257944}s Lager, und Kreischlinge fliegen darüber. Das Lager der Al'Aketh östlich von ihr enthält {item:265141}.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, von {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, von {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, von {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, von {npc:3027}",
		["{npc:249363} stands at the {area:17678}, east of the village. {npc:251143} and Al'Aketh Converts gather just north of her. The {object:460001} is just north-east of her: cast your {spell:1259686} racial ability next to it."] = "{npc:249363} steht bei {area:17678}, östlich des Dorfs. {npc:251143} und Konvertiten der Al'Aketh sammeln sich gleich nördlich von ihr. {object:460001} ist gleich nordöstlich von ihr: Wirk daneben deine Volksfähigkeit {spell:1259686}.",
		["{npc:250926} prowl the slopes south-west of the village, on the way to {npc:252095}."] = "{npc:250926} streifen über die Hänge südwestlich des Dorfs, auf dem Weg zu {npc:252095}.",
		["{npc:251361}'s errands"] = "{npc:251361}s Besorgungen",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: eine Notiz von deinem Lehrer",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361}: Untersuche {item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: Lies {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, der Druidenlehrer, im Erdgeschoss des Baums hinter {npc:251361}",
		["{npc:251374} sends you to the {area:16988}, just east of the village: drink the {item:6635} there to see the {npc:251166}, then take the {item:6656} back to him."] = "{npc:251374} schickt dich zur {area:16988}, gleich östlich des Dorfs: Trink dort {item:6635}, um {npc:251166} zu sehen, und bring dann {item:6656} zu ihm zurück.",
		["{npc:251374} stands in the village."] = "{npc:251374} steht im Dorf.",
		["{npc:251374}, at the village centre"] = "{npc:251374}, in der Dorfmitte",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}: {npc:5873} und dein {item:5175}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, im Wachturm",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, im Wachturm",
		["{npc:252095} waits in {area:16622}, south-west of the village. The Al'Aketh camp is just beyond her; {npc:256935} leads it."] = "{npc:252095} wartet in {area:16622}, südwestlich des Dorfs. Das Lager der Al'Aketh liegt gleich hinter ihr; {npc:256935} führt es an.",
		["{npc:252359} stands on {area:16638}'s east side."] = "{npc:252359} steht auf der Ostseite von {area:16638}.",
		["{npc:252377} stands in the middle of {area:16638}."] = "{npc:252377} steht mitten in {area:16638}.",
		["{npc:252382} stands on {area:16638}'s west side."] = "{npc:252382} steht auf der Westseite von {area:16638}.",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382}: {npc:2523}, dein {item:5176} und {item:263412}",
		["{npc:252389} in {area:16638} hands you a {item:15908} three times: tame a {npc:254588} by the lakes north-west of town, an {npc:251707} in the fields west of town and a {npc:250874} at {area:16663}, returning to her after each. {npc:254411} stands beside her."] = "{npc:252389} in {area:16638} gibt dir dreimal {item:15908}: Zähm {npc:254588} an den Seen nordwestlich der Stadt, {npc:251707} auf den Feldern westlich der Stadt und {npc:250874} bei {area:16663}, und kehr nach jedem zu ihr zurück. {npc:254411} steht neben ihr.",
		["{npc:252448} and {npc:256083}"] = "{npc:252448} und {npc:256083}",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}, {npc:258130} und {npc:258134} sind im Kultlager östlich von {npc:257944}. {npc:254151} steht an seinem Rand. Haalien lässt auch {quest:94490} fallen: Lies ihn, um die nächste Quest zu starten. Für {quest:94489} betrittst du den Nachtfangbau, heilst 7 verletzte Druiden und findest {npc:258130}.",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} lauert südlich des Dorfs zwischen den Rudelkrallen. {npc:254589} ist Elite: Such dir am besten eine Gruppe.",
		["{npc:255853} waits by the falls just north of the watchtower."] = "{npc:255853} wartet an den Fällen gleich nördlich des Wachturms.",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083} steht in {area:16626} gleich nordwestlich der Stadt.",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247} wartet auf der Straße nördlich von {area:16638}, Richtung {area:16629}.",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196} hält {item:263993} auf der Westseite des Schreins.",
		["{npc:257944} again"] = "Wieder {npc:257944}",
		["{npc:257944}, last time"] = "{npc:257944}, ein letztes Mal",
		["{npc:258443} roams the slopes just south of the turncoat's house."] = "{npc:258443} streift über die Hänge gleich südlich des Hauses des Überläufers.",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "{npc:259118}, bei der Landestelle: für {npc:3033} in {zone:1456}",
		["{npc:259119}: keep it, Thrall in {zone:1454} comes two guides later"] = "{npc:259119}: Behalte sie, Thrall in {zone:1454} kommt zwei Guides später",
		["{npc:263664}'s campfire"] = "{npc:263664}s Lagerfeuer",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} will Taurenweihrauch: Kauf seine vier Teile bei {npc:3014}, der Kräuterhändlerin, {npc:3012}, der Händlerin für Verzauberkunstbedarf, {npc:3005}, dem Händler für Lederverarbeitungsbedarf, und {npc:3027}, dem Händler für Kochbedarf, und kombiniere sie dann zu {item:278078}.",
		["{npc:3033} trains druids on {area:1639}. He teaches you {spell:18960}; {npc:11802}'s welcome waits for your {spell:499} trip at about 23 (forever/horde/04-the-barrens)."] = "{npc:3033} bildet Druiden auf der {area:1639} aus. Er lehrt dich {spell:18960}; der Willkommensgruß von {npc:11802} wartet etwa mit 23 auf deine Reise für {spell:499} (forever/horde/04-the-barrens).",
		["{npc:3615}, the wind rider master"] = "{npc:3615}, der Windreitermeister",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529} liegt südlich von Shen'dar. {npc:257065} trifft dich an seinem Rand; durchsuch den Kleiderschrank im Haus hinter ihm.",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["/sit by Kaga's campfire until you get {spell:1229451}"] = "/sit an Kagas Lagerfeuer, bis du {spell:1229451} bekommst",
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "Zurück nach Osten zur {area:358}: Die Schamanen der Borstennacken stehen dort zwischen den Stacheleber.",
		["Back south-east to the {area:396}."] = "Zurück nach Südosten zum {area:396}.",
		["Back to Bloodhoof"] = "Zurück nach Bloodhoof",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "Zurück zu {npc:5888} im Lager. {npc:5891} wartet auf dem Tafelberg östlich des Lagers: Trink dort {item:6635}, um sie zu sehen, und bring dann {item:6656} zurück zum Seher.",
		["Back west to the camp."] = "Zurück nach Westen zum Lager.",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "Kampfeber grasen nördlich des Schreins; die Stacheleber der Borstennacken halten die Schlucht im Nordosten. {npc:8554} steht an ihrem östlichen Ende, und {object:3076} liegt im Lager auf dem Boden.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the north-western woods."] = "Wirke {spell:18960}. {npc:11802} ist in {area:2361}; {quest:5930} sitzt im Wald im Nordwesten.",
		["Class turn-ins in {area:1638}"] = "Klassenabgaben in {area:1638}",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "Zieh nach Nordwesten an {zone:1456} vorbei zum {area:398} im äußersten Norden von {zone:1412}.",
		["Finish the wolf heart, cougar femur, plainstrider scale and swoop gizzard on the plains around the village."] = "Sammle das restliche Wolfsherz, den Pumaknochen, die Ebenenschreiterschuppe und den Sturzfliegermagen auf den Ebenen ums Dorf.",
		["Follow the path south out of camp to the Seer's tent at the foot of the hills."] = "Folge dem Pfad nach Süden aus dem Lager zum Zelt des Sehers am Fuß der Hügel.",
		["Follow the road north out of {area:220}. {npc:265810} waits on the road just south of {area:222}; /sit by her campfire until you get {spell:1229451}."] = "Folge der Straße nach Norden aus {area:220}. {npc:265810} wartet auf der Straße gleich südlich von {area:222}; /sit an ihrem Lagerfeuer, bis du {spell:1229451} bekommst.",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "Geh nach Norden zu {area:225}, östlich von {zone:1456}. {npc:3233} steht am Fuß der Felsen; die Eindringlinge der Borstennacken graben auf der Grabstätte, und {npc:2994} wartet oben.",
		["Hearth to {area:222} and ride north to {area:1639}."] = "Ruhestein nach {area:222} und reite nach Norden zur {area:1639}.",
		["Leave {zone:1412} by the south-eastern pass and follow the road to the {area:380}. {quest:860} stands by the inn, {npc:3448} at the south gate. {zone:1413} guide starts here."] = "Verlass {zone:1412} durch den südöstlichen Pass und folge der Straße nach {area:380}. {quest:860} steht beim Gasthaus, {npc:3448} am Südtor. Hier beginnt der Guide für das {zone:1413}.",
		["Plainstriders roam the grass all around the camp."] = "Ebenenschreiter streifen überall ums Lager durchs Gras.",
		["Prairie Wolves and Adult Plainstriders roam the plains around the village."] = "Präriewölfe und Erwachsene Ebenenschreiter streifen über die Ebenen ums Dorf.",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Fahr mit einem Aufzug hinauf zu den Tafelbergen. {npc:2995} hält die Windreiter auf der mittleren Anhöhe; {npc:3057} steht dort im großen Zelt.",
		["Ride down to {area:222} and tame with the {item:15908}: an {npc:2956} on the plains, a {npc:2959} north of the village, a Swoop to the north-west."] = "Reite hinunter nach {area:222} und zähm mit {item:15908}: einen {npc:2956} auf den Ebenen, einen {npc:2959} nördlich des Dorfs und einen Sturzflieger im Nordwesten.",
		["Speak with {npc:3067}"] = "Sprich mit {npc:3067}",
		["Spread the {item:278078} off {area:1641}"] = "Verstreu {item:278078} von der {area:1641}",
		["Swoops glide over the plains all around Bloodhoof."] = "Sturzflieger gleiten überall um Bloodhoof über die Ebenen.",
		["Tame it with the {item:15908}"] = "Zähm ihn mit {item:15908}",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "Die Gnolle der Bleichmähnen halten den {area:818}, südlich der Grabungsstätte und westlich von Bloodhoof. {npc:272203} wird in ihrem Lager festgehalten: Führ ihn hinaus.",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "Die Harpyien der Windfurien halten {area:819}, nördlich und westlich des Brunnens.",
		["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine."] = "Die Goblins arbeiten in der Mine in den Hügeln nordöstlich des Brunnens. {quest:765} steht hinten in der Mine; seine {item:281031} starten {quest:98424}, und die anderen Seiten liegen in der Mine.",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "Der Weihrauch brennt in zehn Minuten ab: Lauf an den südlichen Hügeln entlang direkt nach Osten zum {object:660739}.",
		["The shrine of An'she and Mu'sha"] = "Der Schrein von An'she und Mu'sha",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "Der Stein steht im Pass aus {zone:1412} hinaus, auf deinem Weg nach Osten. Benutze dort {item:15710} und besiege Mondklaue.",
		["The well lies south-east of the village."] = "Der Brunnen liegt südöstlich des Dorfs.",
		["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "Die zerstörte Karawane liegt nordwestlich der Zentauren, östlich der Straße nach {zone:1456}.",
		["The {object:177525}"] = "{object:177525}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Benutze {item:278078} an der Zeremonienmatte und dem Räuchergefäß an der Südklippe der {area:1641}.",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "Du beginnst auf dem Tafelberg von {area:221}. {npc:2980} und der Häuptling stehen beim großen Zelt in der Mitte.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, von {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, von {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, von {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, von {npc:3027}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} will Taurenweihrauch: Kauf seine vier Teile bei {npc:3014}, der Kräuterhändlerin, {npc:3012}, der Händlerin für Verzauberkunstbedarf, {npc:3005}, dem Händler für Lederverarbeitungsbedarf, und {npc:3027}, dem Händler für Kochbedarf, und kombiniere sie dann zu {item:278078}.",
		["{npc:275789} stands on the {area:821} a little east of the well."] = "{npc:275789} steht auf den {area:821} ein Stück östlich des Brunnens.",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182} steht am Nordrand des Dorfs. Kyle will {item:287505} von Ebenenschreitern.",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}, am Nordende des Dorfs",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}, für Hamuul in {zone:1456}",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984} steht am Rand der {area:404}, südlich des Brunnens.",
		["{npc:2988} camps by the {area:396} south-east of Bloodhoof."] = "{npc:2988} lagert beim {area:396} südöstlich von Bloodhoof.",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}, für {npc:3057} in {zone:1456}",
		["{npc:3059}, the warrior trainer"] = "{npc:3059}, der Kriegerlehrer",
		["{npc:3060}, the druid trainer beside him"] = "{npc:3060}, der Druidenlehrer neben ihr",
		["{npc:3061}, the hunter trainer"] = "{npc:3061}, die Jägerlehrerin",
		["{npc:3062}, the shaman trainer in camp"] = "{npc:3062}, die Schamanenlehrerin im Lager",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "Die Quest von {npc:3063}: Besiege drei Kriegernovizen (oder Spieler im Duell) neben ihm.",
		["{npc:3209}, next to {npc:2980}"] = "{npc:3209}, neben {npc:2980}",
		["{npc:3441}: for {quest:860} at the {area:380}"] = "{npc:3441}: für {quest:860} in {area:380}",
		["{npc:5769}: for {npc:3448} at the {area:380}"] = "{npc:5769}: für {npc:3448} in {area:380}",
		["{npc:5888} stands in {area:221}. {quest:1516} needs level 4, which you reach with the turn-ins here."] = "{npc:5888} steht im {area:221}. {quest:1516} erfordert Stufe 4, die du mit den Abgaben hier erreichst.",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}: {npc:5873} und dein {item:5175}",
		["{npc:6746} on the central rise sends you to {npc:3033} on {area:1639}."] = "{npc:6746} auf der mittleren Anhöhe schickt dich zu {npc:3033} auf der {area:1639}.",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to {npc:2980}."] = "{npc:6775} steht am Westende des Lagers, an der Nordwestecke der Hügel, wo die Bergpumas umherstreifen: Nimm seine Quest an, jag die Pumas von dort nach Süden und Osten und komm dann zurück hinauf zu {npc:2980}.",
		["{quest:96130} and {quest:756}"] = "{quest:96130} und {quest:756}",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "{quest:96130}, ein einsamer Wolf, streift über die Ebenen westlich des Dorfs. Präriepirscher und Flachlandpumas streifen über die Ebenen nördlich und westlich davon.",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["/sit by her campfire until you get {spell:1229451}"] = "/sit an ihrem Lagerfeuer, bis du {spell:1229451} bekommst",
		["Ask {npc:10666} for his report"] = "Bitte {npc:10666} um seinen Bericht",
		["Ask {npc:1496} for his report"] = "Bitte {npc:1496} um seinen Bericht",
		["Ask {npc:251001} for his report"] = "Bitte {npc:251001} um seinen Bericht",
		["Back to the church"] = "Zurück zur Kirche",
		["Back to {area:154}"] = "Zurück nach {area:154}",
		["Back to {area:159}."] = "Zurück nach {area:159}.",
		["Back up the road to {area:159}."] = "Die Straße hinauf zurück nach {area:159}.",
		["Balnir graves"] = "Gräber von Balnirs Bauernhof",
		["Beat {npc:6784} in the duel"] = "Besiege {npc:6784} im Duell",
		["Crusader's Outpost"] = "Außenposten der Kreuzzügler",
		["Dry Branches"] = "Trockene Äste",
		["Duskbats and Darkhounds roam all along the road back west; finish the wings and hides on the way."] = "Nachtsauger und Schattenhunde streifen überall entlang der Straße zurück nach Westen umher; sammle unterwegs die restlichen Flügel und Felle.",
		["Eleanor camps just south-west of town."] = "Eleanor lagert direkt südwestlich des Ortes.",
		["Escort {npc:275954} out of the outpost"] = "Eskortiere {npc:275954} aus dem Außenposten",
		["Fields west of {area:159}"] = "Felder westlich von {area:159}",
		["Follow the path north into {area:154}; Sarvis stands in front of the church."] = "Folge dem Pfad nach Norden nach {area:154}; Sarvis steht vor der Kirche.",
		["Follow the road east to {area:159}. {npc:10665} stands at the north-west edge of town; the {area:2119} is the big inn in the middle, with {npc:1515} in front of it."] = "Folge der Straße nach Osten nach {area:159}. {npc:10665} steht am Nordwestrand des Ortes; {area:2119} ist das große Gasthaus in der Mitte, mit {npc:1515} davor.",
		["Follow the road east. Bleeding Horrors and Wandering Spirits haunt the graves on the east side of the farmstead, where the {quest:99142} grows."] = "Folge der Straße nach Osten. Blutende Schrecken und Wandernde Geister spuken bei den Gräbern auf der Ostseite des Hofs, wo {quest:99142} wächst.",
		["Follow the road north-east from {area:159} past {area:162}. {npc:1665} and his two Scarlet Bodyguards hold the Scarlet watchtower on the north-east coast, north of the {area:459}: pull the bodyguards first."] = "Folge der Straße von {area:159} nach Nordosten an {area:162} vorbei. {npc:1665} und seine zwei Scharlachroten Leibwachen halten den scharlachroten Wachturm an der Nordostküste, nördlich von {area:459}: Zieh zuerst die Leibwachen.",
		["Follow the road north-west to {area:157}. {npc:1657} walks the graveyard south of the mills; Nissa, Gregor and {npc:1656} haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop {item:2839}. From here on, kill the Duskbats and Darkhounds you pass: {npc:3549} wants their wings and hides."] = "Folge der Straße nach Nordwesten zu {area:157}. {npc:1657} geht über den Friedhof südlich der Mühlen; Nissa, Gregor und {npc:1656} spuken in den Mühlen selbst. Klappernde Skelettsoldaten und Trümmerschädelsoldaten lassen die Rippen fallen, Dunkle Skelettmagier die Schädel, und jeder von ihnen kann {item:2839} fallen lassen. Töte ab hier die Nachtsauger und Schattenhunde, an denen du vorbeikommst: {npc:3549} will ihre Flügel und Felle.",
		["Follow the road south back to {area:159}."] = "Folge der Straße nach Süden zurück nach {area:159}.",
		["Follow the road south-east from {area:159} past the zeppelin towers. Linnea, Kristof and {npc:3549} camp by the road."] = "Folge der Straße von {area:159} nach Südosten an den Zeppelintürmen vorbei. Linnea, Kristof und {npc:3549} lagern an der Straße.",
		["Follow the road south-west from {area:159} to the Scarlet Crusade camp. {npc:1662} stands at its south end; every Scarlet there can drop a ring."] = "Folge der Straße von {area:159} nach Südwesten zum Lager des Scharlachroten Kreuzzugs. {npc:1662} steht an seinem Südende; jeder Scharlachrote dort kann einen Ring fallen lassen.",
		["Follow the road west past {area:157} to the {area:16616}. Leonid stands just north of {npc:246389}'s camp."] = "Folge der Straße nach Westen an {area:157} vorbei zu {area:16616}. Leonid steht direkt nördlich von {npc:246389}s Lager.",
		["Free six Webbed Victims inside the cave for {npc:244808}"] = "Befreie sechs eingesponnene Opfer in der Höhle für {npc:244808}",
		["Greater Duskbats"] = "Große Nachtsauger",
		["Greater Duskbats fly over the fields around {area:159} and along the road north."] = "Große Nachtsauger fliegen über die Felder um {area:159} und entlang der Straße nach Norden.",
		["Head west into the {area:16616}; {npc:246389} and {npc:259190} camp at its edge."] = "Geh nach Westen in {area:16616}; {npc:246389} und {npc:259190} lagern an seinem Rand.",
		["Head west to the cave. The Young Night Web Spiders sit outside; the Night Web Spiders and the Webbed Victims are inside."] = "Geh nach Westen zur Höhle. Die Jungen Nachtweber sitzen draußen; die Nachtweber und die eingesponnenen Opfer sind drinnen.",
		["Hearth to {area:159}"] = "Ruhestein nach {area:159}",
		["Leave {area:154} by the road north-east. {npc:6784} stands by the farmhouse at the {area:156}."] = "Verlass {area:154} über die Straße nach Nordosten. {npc:6784} steht beim Bauernhaus auf {area:156}.",
		["Listen to Leonid and {npc:246378}, then talk to him again"] = "Hör Leonid und {npc:246378} zu, dann sprich erneut mit ihm",
		["Mindless Zombies"] = "Hirnlose Zombies",
		["More Vile Fin murlocs walk the shore just north of the outpost."] = "Weitere Murlocs der Finsterflossen laufen am Ufer direkt nördlich des Außenpostens.",
		["Offer aid to the {npc:246143}"] = "Biete dem {npc:246143} Hilfe an",
		["Only if the letter dropped"] = "Nur wenn der Brief gedroppt ist",
		["Paladin: {area:16616}"] = "Paladin: {area:16616}",
		["Paladins: {quest:90902} is done once you have healed five {npc:259377} around the church with {spell:635}."] = "Paladine: {quest:90902} ist erledigt, sobald du fünf {npc:259377} rund um die Kirche mit {spell:635} geheilt hast.",
		["Rattlecage Skeletons wander the ruined houses in the north half of {area:154}. Young Scavengers and Duskbats roam all around the village; the Ragged Scavengers and Mangy Duskbats are on its east side."] = "Klappernde Skelette streifen durch die zerstörten Häuser in der Nordhälfte von {area:154}. Junge Aasfresser und Nachtsauger streifen überall im Dorf umher; die Struppigen Aasfresser und Räudigen Nachtsauger sind auf seiner Ostseite.",
		["Rattlecage skulls"] = "Schädel klappernder Skelette",
		["Rattlecages, scavengers and duskbats"] = "Klappernde Skelette, Aasfresser und Nachtsauger",
		["Rot Hide graveyards"] = "Friedhöfe der Moderfelle",
		["Scarlet Warriors guard the outpost just west of the pumpkin fields. {npc:275954} is held inside: talk to him and stay with him until he is out."] = "Scharlachrote Krieger bewachen den Außenposten direkt westlich der Kürbisfelder. {npc:275954} wird drinnen festgehalten: Sprich mit ihm und bleib bei ihm, bis er draußen ist.",
		["Take the road south-east out of {area:159}; Terrence stands on it short of the zeppelin towers."] = "Nimm die Straße von {area:159} nach Südosten; Terrence steht darauf, kurz vor den Zeppelintürmen.",
		["Talk to {npc:265944}"] = "Sprich mit {npc:265944}",
		["The Dry Branches lie on the ground around the south-west edge of {area:159}."] = "Die Trockenen Äste liegen am Boden rund um den Südwestrand von {area:159}.",
		["The Rattlecage Skeletons in the ruined houses drop the skulls."] = "Die Klappernden Skelette in den zerstörten Häusern lassen die Schädel fallen.",
		["The Rot Hide Graverobbers dig through the graveyards north of {area:159}; all the Rot Hides drop the ichor."] = "Die Grabräuber der Moderfelle graben auf den Friedhöfen nördlich von {area:159}; alle Moderfelle lassen das Sekret fallen.",
		["The Rot Hide Mongrels hold the hills further north. {npc:1753} (level 11) stands in their camp on the hill south of the shore: clear the gnolls around him first."] = "Die Bastarde der Moderfelle halten die Hügel weiter nördlich. {npc:1753} (Stufe 11) steht in ihrem Lager auf dem Hügel südlich des Ufers: Räum zuerst die Gnolle um ihn herum weg.",
		["The Scarlet Converts and Initiates hold the farm east of {area:154}. {npc:1919} wanders between the farmhouses: his remains are for {quest:6395}."] = "Die Scharlachroten Konvertiten und Initianden halten den Bauernhof östlich von {area:154}. {npc:1919} wandert zwischen den Bauernhäusern umher: Seine Überreste sind für {quest:6395}.",
		["The Scarlet Friars camp just north-east of the graves; {npc:1664} stands among them."] = "Die Scharlachroten Ordensmitglieder lagern direkt nordöstlich der Gräber; {npc:1664} steht zwischen ihnen.",
		["The Scarlet camp"] = "Das scharlachrote Lager",
		["The Scarlet farm"] = "Der scharlachrote Bauernhof",
		["The Vile Fin murlocs line the north shore."] = "Die Murlocs der Finsterflossen säumen das Nordufer.",
		["The Wanted poster by the inn"] = "Der Steckbrief beim Gasthaus",
		["The zeppelin lands at the tower just north-east of {zone:1454}'s main gate. Follow the road south into {zone:1411}, cross the {area:815} bridge below {area:379} and follow the road west to the {area:380}."] = "Der Zeppelin landet am Turm direkt nordöstlich des Haupttors von {zone:1454}. Folge der Straße nach Süden nach {zone:1411}, überquere die Brücke über {area:815} unterhalb von {area:379} und folge der Straße nach Westen nach {area:380}.",
		["The zombies shamble around the graveyard and the houses just east of the church."] = "Die Zombies schlurfen über den Friedhof und um die Häuser direkt östlich der Kirche.",
		["The {area:154} trainers stand around the church"] = "Die Lehrer von {area:154} stehen rund um die Kirche",
		["The {area:159} trainers are in and around the inn"] = "Die Lehrer von {area:159} sind im Gasthaus und drumherum",
		["The {npc:1931}, in the town hall basement"] = "Der {npc:1931}, im Keller des Rathauses",
		["The {npc:2211}, in the town hall basement"] = "Der {npc:2211}, im Keller des Rathauses",
		["The {npc:246143}"] = "Der {npc:246143}",
		["The {object:164662} lie beside the ruined houses in the north of {area:154}."] = "Die {object:164662} liegen neben den zerstörten Häusern im Norden von {area:154}.",
		["The {quest:5482} grows in the graveyard fields just north of {area:159}."] = "{quest:5482} wächst auf den Friedhofsfeldern direkt nördlich von {area:159}.",
		["Tirisfal Pumpkins"] = "Tirisfalkürbisse",
		["Use the {item:286176} on five idle Deathguards around town"] = "Benutze den {item:286176} an fünf untätigen Todeswachen im Ort",
		["Vicious Night Web Spiders"] = "Heimtückische Nachtweber",
		["Vile Fin murlocs"] = "Murlocs der Finsterflossen",
		["Vile Fin shore"] = "Ufer der Finsterflossen",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:4568} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "Geh von {area:159} nach Süden zu {area:153} und hinab nach {zone:1458}. {npc:4568} steht im {object:36082}. Das scharlachrote Lager liegt direkt westlich der Ruinen.",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:5675} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "Geh von {area:159} nach Süden zu {area:153} und hinab nach {zone:1458}. {npc:5675} steht im {object:36082}. Das scharlachrote Lager liegt direkt westlich der Ruinen.",
		["Walk south-east from {area:159} to the zeppelin towers outside the {area:153} and board the zeppelin to {zone:1454} (the other one goes to {object:3202})."] = "Geh von {area:159} nach Südosten zu den Zeppelintürmen vor {area:153} und steig in den Zeppelin nach {zone:1454} (der andere fliegt nach {object:3202}).",
		["Webbed Victims"] = "Eingesponnene Opfer",
		["You rise in the crypt at the south end of {area:154}. {npc:1568} waits just outside."] = "Du erwachst in der Gruft am Südende von {area:154}. {npc:1568} wartet direkt draußen.",
		["Zeppelin to {zone:1411}"] = "Zeppelin nach {zone:1411}",
		["Zeppelin tower"] = "Zeppelinturm",
		["in the inn: ask him about cooking"] = "im Gasthaus: Frag ihn nach dem Kochen",
		["{area:16881} is the hollow at the west edge of the glades. The Shadowvale Lurchers and Mystics drop the bones; the bottles lie on the ground among them, and the {item:286269} is at the south end."] = "{area:16881} ist die Senke am Westrand von Tirisfal. Die Schattentalschlinger und Schattentalmystiker lassen die Knochen fallen; die Flaschen liegen zwischen ihnen am Boden, und {item:286269} ist am Südende.",
		["{item:16333}, from {npc:1919}"] = "{item:16333}, von {npc:1919}",
		["{item:2320} from {npc:2118}, for Gretchen"] = "{item:2320} von {npc:2118}, für Gretchen",
		["{item:2839}, a rare drop"] = "{item:2839}, ein seltener Drop",
		["{item:7227}, in the farmstead's garden"] = "{item:7227}, im Garten des Hofs",
		["{npc:10666}, the big abomination, walks the road a little further east. The {item:12737} grows along the road around him."] = "{npc:10666}, die große Monstrosität, geht ein Stück weiter östlich die Straße entlang. Das {item:12737} wächst entlang der Straße um ihn herum.",
		["{npc:1495}'s camp"] = "Lager von {npc:1495}",
		["{npc:1496} stands in {area:159}. {npc:6390} waits in the mausoleum on the hill just north of town: open the gate and fight him."] = "{npc:1496} steht in {area:159}. {npc:6390} wartet im Mausoleum auf dem Hügel direkt nördlich des Ortes: Öffne das Tor und kämpfe gegen ihn.",
		["{npc:1499}, in the town hall"] = "{npc:1499}, im Rathaus",
		["{npc:1500}, in the inn"] = "{npc:1500}, im Gasthaus",
		["{npc:1525} and Ravaged Corpses shamble through the fields just west of {area:159}; Darkhounds roam a little further west, toward {npc:10666}."] = "{npc:1525} und Verheerte Kadaver schlurfen über die Felder direkt westlich von {area:159}; Schattenhunde streifen etwas weiter westlich umher, Richtung {npc:10666}.",
		["{npc:1560}, in the inn"] = "{npc:1560}, im Gasthaus",
		["{npc:1569}: the scroll for {npc:244808}"] = "{npc:1569}: die Schriftrolle für {npc:244808}",
		["{npc:1570}, in the church"] = "{npc:1570}, in der Kirche",
		["{npc:1661}, beside the church"] = "{npc:1661}, neben der Kirche",
		["{npc:1667} stands at the south end of the Scarlet farm."] = "{npc:1667} steht am Südende des scharlachroten Bauernhofs.",
		["{npc:2119}, the warrior trainer"] = "{npc:2119}, der Kriegerlehrer",
		["{npc:2122}, the rogue trainer"] = "{npc:2122}, der Schurkenlehrer",
		["{npc:2123}, the priest trainer in the church"] = "{npc:2123}, der Priesterlehrer in der Kirche",
		["{npc:2124}, the mage trainer, in the church"] = "{npc:2124}, die Magierlehrerin, in der Kirche",
		["{npc:2126}, the warlock trainer"] = "{npc:2126}, der Hexenmeisterlehrer",
		["{npc:2128}: {npc:4568} in the {zone:1458} takes it"] = "{npc:2128}: {npc:4568} in {zone:1458} nimmt es an",
		["{npc:2132}, beside Johaan"] = "{npc:2132}, neben Johaan",
		["{npc:244808} and {npc:5667}"] = "{npc:244808} und {npc:5667}",
		["{npc:244808} and {npc:5667} stand beside the church."] = "{npc:244808} und {npc:5667} stehen neben der Kirche.",
		["{npc:246152}, the Paladin trainer"] = "{npc:246152}, die Paladinlehrerin",
		["{npc:267009} stands at {npc:1495}'s camp."] = "{npc:267009} steht im Lager von {npc:1495}.",
		["{npc:3615}, the wind rider master"] = "{npc:3615}, der Windreitermeister",
		["{object:1661} is under the {area:153}, beside the zeppelin towers. {npc:5675} is in the {object:36082}: use the {item:6284} on the summoning circle beside him and defeat the voidwalker. {npc:4606} is in the {object:36070}. {npc:4568} is in the {object:36082} too."] = "{object:1661} liegt unter {area:153}, neben den Zeppelintürmen. {npc:5675} ist im {object:36082}: Benutze die {item:6284} am Beschwörungskreis neben ihm und besiege den Leerwandler. {npc:4606} ist im {object:36070}. {npc:4568} ist ebenfalls im {object:36082}.",
		["{object:178090} is in the {area:154} graveyard, beside the church."] = "{object:178090} liegt auf dem Friedhof von {area:154}, neben der Kirche.",
		["{object:37098} stands beside {npc:1662} at the camp's south end."] = "{object:37098} steht neben {npc:1662} am Südende des Lagers.",
		["{quest:91208}: the {npc:246143} fled into the hills just west of the church."] = "{quest:91208}: Der {npc:246143} ist in die Hügel direkt westlich der Kirche geflohen.",
		["{quest:96897} holds the farm just south-east of the camp. The Necrotic Crystal Fragments lie on the ground among the cultists, and the cultists carry some too."] = "{quest:96897} hält den Hof direkt südöstlich des Lagers. Die Nekrotischen Kristallfragmente liegen zwischen den Kultisten am Boden, und die Kultisten tragen auch einige bei sich.",
} end)()
t.guides["forever/legacy/legacy-challenges"] = (function() return {
		["Adventure: explore the world map"] = "Abenteuer: die Weltkarte erkunden",
		["Adventure: {npc:16042}"] = "Abenteuer: {npc:16042}",
		["Adventure: {quest:8997} (Alliance)"] = "Abenteuer: {quest:8997} (Allianz)",
		["Adventure: {quest:8998} (Horde)"] = "Abenteuer: {quest:8998} (Horde)",
		["All 13 Hyjal Summit bosses are a point. Hyjal Summit is a new Forever raid; its bosses are not in our data, so tick it off once all 13 are down."] = "Alle 13 Bosse des Hyjalgipfels sind einen Punkt wert. Der Hyjalgipfel ist ein neuer Forever-Schlachtzug; seine Bosse sind nicht in unseren Daten, hak ihn also ab, sobald alle 13 besiegt sind.",
		["All 8 Barrow Deeps bosses are a point. Barrow Deeps is a new Forever raid; its bosses are not in our data, so tick it off once all 8 are down."] = "Alle 8 Bosse der Barrow Deeps sind einen Punkt wert. Barrow Deeps ist ein neuer Forever-Schlachtzug; seine Bosse sind nicht in unseren Daten, hak ihn also ab, sobald alle 8 besiegt sind.",
		["Blizzard counts four battleground reputations, but our faction data has three per side ({zone:1460}, {zone:1461}, {zone:1459}). The fourth is likely tied to Forever's new PvP content; check the in-game Legacy panel."] = "Blizzard zählt vier Schlachtfeld-Rufe, aber unsere Fraktionsdaten haben drei pro Seite ({zone:1460}, {zone:1461}, {zone:1459}). Der vierte hängt wohl mit den neuen PvP-Inhalten von Forever zusammen; sieh im Vermächtnis-Fenster im Spiel nach.",
		["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "Klassen geben 27 Punkte: jede Klasse, die 25, 45 und 60 erreicht. Sie zählen einmal pro Klasse im ganzen Account, ein zweiter Charakter einer bereits hochgespielten Klasse bringt also nichts; eine neue Klasse schon. Der erste Charakter auf Stufe 25 schaltet meist das Vermächtnissystem selbst frei.",
		["Classes: level 25"] = "Klassen: Stufe 25",
		["Classes: level 45"] = "Klassen: Stufe 45",
		["Classes: level 60"] = "Klassen: Stufe 60",
		["Dire Maul East"] = "Düsterbruch Ost",
		["Dire Maul North"] = "Düsterbruch Nord",
		["Dire Maul West"] = "Düsterbruch West",
		["Dungeons: level 15-25"] = "Dungeons: Stufe 15-25",
		["Dungeons: level 26-45"] = "Dungeons: Stufe 26-45",
		["Dungeons: level 46-60"] = "Dungeons: Stufe 46-60",
		["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "Jeder Herstellungsberuf gibt 3 Punkte, bei 150, 225 und 300. Ränge zählen einmal pro Beruf im ganzen Account. Folge dem Polestar-Guide „{skill:171} 1-300“ (Berufe). Ein Herstellungsberuf auf 150 schaltet auch das Vermächtnissystem frei.",
		["Exalted with each battleground faction is worth a point (4 in all; this page shows three, see the note). Follow the Polestar Reputation guides Warsong Gulch Reputation, Arathi Basin Reputation and Alterac Valley Reputation. The Diplomat Legacy perk increases reputation gains."] = "Ehrfürchtig bei jeder Schlachtfeldfraktion ist einen Punkt wert (insgesamt 4; diese Seite zeigt drei, siehe Hinweis). Folge den Polestar-Rufguides Ruf: Warsongschlucht, Ruf: Arathibecken und Ruf: Alteractal. Der Vermächtnis-Vorteil „Diplomat“ erhöht den Rufgewinn.",
		["Exploring the entire world map on one character is a point, and it can also unlock the Legacy System. It must all be on the same character."] = "Die ganze Weltkarte mit einem Charakter zu erkunden ist einen Punkt wert und kann auch das Vermächtnissystem freischalten. Alles muss mit demselben Charakter geschehen.",
		["Follow the Polestar Exploration guides: Exploration: Eastern Kingdoms 1-30, 30-45 and 45-60, and Exploration: Kalimdor 1-30, 30-45 and 45-60. They track every area as you discover it."] = "Folge den Polestar-Erkundungsguides: Erkundung: Östliche Königreiche 1-30, 30-45 und 45-60, und Erkundung: Kalimdor 1-30, 30-45 und 45-60. Sie verfolgen jedes Gebiet, sobald du es entdeckst.",
		["Follow the Polestar guide \"{skill:164} 1-300\" (Professions)."] = "Folge dem Polestar-Guide „{skill:164} 1-300“ (Berufe).",
		["Follow the Polestar guide \"{skill:165} 1-300\" (Professions)."] = "Folge dem Polestar-Guide „{skill:165} 1-300“ (Berufe).",
		["Follow the Polestar guide \"{skill:197} 1-300\" (Professions)."] = "Folge dem Polestar-Guide „{skill:197} 1-300“ (Berufe).",
		["Follow the Polestar guide \"{skill:202} 1-300\" (Professions)."] = "Folge dem Polestar-Guide „{skill:202} 1-300“ (Berufe).",
		["Follow the Polestar guide \"{skill:333} 1-300\" (Professions)."] = "Folge dem Polestar-Guide „{skill:333} 1-300“ (Berufe).",
		["Forever adds the dungeons {area:16919} and {area:153}; their bosses and brackets are not in our data yet."] = "Forever fügt die Dungeons {area:16919} und {area:153} hinzu; ihre Bosse und Stufenbereiche sind noch nicht in unseren Daten.",
		["Forever's new dungeons"] = "Neue Dungeons von Forever",
		["Killing {npc:10184} is a point. In Classic her lair needs an attunement: {item:16309} for the Alliance, {item:16663} for the Horde."] = "{npc:10184} zu töten ist einen Punkt wert. In Classic braucht ihr Hort eine Zugangsquest: {item:16309} für die Allianz, {item:16663} für die Horde.",
		["Legacy Challenges"] = "Vermächtnisherausforderungen",
		["Level 45 with this character's class."] = "Stufe 45 mit der Klasse dieses Charakters.",
		["Level 60 with this character's class."] = "Stufe 60 mit der Klasse dieses Charakters.",
		["Lower {area:1583}"] = "Untere {area:1583}",
		["PvP: Field of Honor"] = "PvP: Field of Honor",
		["PvP: battleground reputations (Alliance)"] = "PvP: Schlachtfeld-Ruf (Allianz)",
		["PvP: battleground reputations (Horde)"] = "PvP: Schlachtfeld-Ruf (Horde)",
		["PvP: honor ranks"] = "PvP: Ehrenränge",
		["Raids: Barrow Deeps"] = "Schlachtzüge: Barrow Deeps",
		["Raids: Hyjal Summit"] = "Schlachtzüge: Hyjalgipfel",
		["Raids: {npc:10184}"] = "Schlachtzüge: {npc:10184}",
		["Ranks 3, 7, 10, 13 and 14 are a point each. Polestar cannot read your highest rank yet, so tick each one off yourself. Forever's honor rules for reaching a rank have not been published in detail; in Classic, ranks come from your weekly honor standing, and 13-14 take many weeks of top standing."] = "Die Ränge 3, 7, 10, 13 und 14 sind je einen Punkt wert. Polestar kann deinen höchsten Rang noch nicht lesen, hak also jeden selbst ab. Die Ehrenregeln von Forever für das Erreichen eines Rangs sind nicht im Detail veröffentlicht; in Classic kommen Ränge aus deiner wöchentlichen Ehrenplatzierung, und 13-14 brauchen viele Wochen Spitzenplatzierung.",
		["The Field of Honor PvP season has weekly journey quests; finishing the ones for weeks 4, 7 and 10 is a point each. These quests are new in Forever and not in our data, so tick each one off yourself."] = "Die PvP-Saison Field of Honor hat wöchentliche Reisequests; die für die Wochen 4, 7 und 10 abzuschließen ist je einen Punkt wert. Diese Quests sind neu in Forever und nicht in unseren Daten, hak also jede selbst ab.",
		["The final boss of every level 15-25 dungeon earns one point together. Tick each boss off when you kill it; the grouping follows the usual Classic level ranges, so check the in-game Legacy panel for the exact list."] = "Der Endboss jedes Dungeons der Stufe 15-25 bringt zusammen einen Punkt. Hak jeden Boss ab, wenn du ihn tötest; die Einteilung folgt den üblichen Classic-Stufenbereichen, prüf also die genaue Liste im Vermächtnis-Fenster im Spiel.",
		["The final boss of every level 26-45 dungeon earns one point together."] = "Der Endboss jedes Dungeons der Stufe 26-45 bringt zusammen einen Punkt.",
		["The final boss of every level 46-60 dungeon earns one point together."] = "Der Endboss jedes Dungeons der Stufe 46-60 bringt zusammen einen Punkt.",
		["This step cannot check the whole map by itself yet; it becomes a tracked goal once the Legacy achievement ids are recorded."] = "Dieser Schritt kann die ganze Karte noch nicht selbst prüfen; er wird zu einem verfolgten Ziel, sobald die Vermächtnis-Erfolgs-IDs erfasst sind.",
		["Tradeskills: {skill:164}"] = "Berufe: {skill:164}",
		["Tradeskills: {skill:165}"] = "Berufe: {skill:165}",
		["Tradeskills: {skill:171}"] = "Berufe: {skill:171}",
		["Tradeskills: {skill:197}"] = "Berufe: {skill:197}",
		["Tradeskills: {skill:202}"] = "Berufe: {skill:202}",
		["Tradeskills: {skill:333}"] = "Berufe: {skill:333}",
		["Upper {area:1583}"] = "Obere {area:1583}",
		["Which quest Blizzard counts as the end of the questline ({quest:8996} or your class's Saving the Best for Last) is unconfirmed until the Legacy data is recorded."] = "Welche Quest Blizzard als Ende der Questreihe zählt ({quest:8996} oder Das Beste gibt's zum Schluss deiner Klasse), ist unbestätigt, bis die Vermächtnis-Daten erfasst sind.",
		["all 13 Hyjal Summit bosses"] = "alle 13 Bosse des Hyjalgipfels",
		["all 8 Barrow Deeps bosses"] = "alle 8 Bosse der Hügelgrabtiefen",
		["enemy players and finish the Field of Honor week 10 journey quest"] = "feindliche Spieler und schließe die Reisequest der Woche 10 des Ehrenfelds ab",
		["enemy players and finish the Field of Honor week 4 journey quest"] = "feindliche Spieler und schließe die Reisequest der Woche 4 des Ehrenfelds ab",
		["enemy players and finish the Field of Honor week 7 journey quest"] = "feindliche Spieler und schließe die Reisequest der Woche 7 des Ehrenfelds ab",
		["enemy players for honor until PvP Rank 10"] = "feindliche Spieler für Ehre bis zum PvP-Rang 10",
		["enemy players for honor until PvP Rank 13"] = "feindliche Spieler für Ehre bis zum PvP-Rang 13",
		["enemy players for honor until PvP Rank 14"] = "feindliche Spieler für Ehre bis zum PvP-Rang 14",
		["enemy players for honor until PvP Rank 3"] = "feindliche Spieler für Ehre bis zum PvP-Rang 3",
		["enemy players for honor until PvP Rank 7"] = "feindliche Spieler für Ehre bis zum PvP-Rang 7",
		["the final boss of {area:153}"] = "den Endboss von {area:153}",
		["the final boss of {area:16919}"] = "den Endboss von {area:16919}",
		["{area:1517} (level 41-51; may count in the 46-60 bracket)"] = "{area:1517} (Stufe 41-51; zählt evtl. im Bereich 46-60)",
		["{area:16919} and {area:153} are new in Forever. Their bosses, levels and Legacy bracket are not in our data, so tick them off yourself."] = "{area:16919} und {area:153} sind neu in Forever. Ihre Bosse, Stufen und Vermächtnis-Bereiche sind nicht in unseren Daten, hak sie also selbst ab.",
		["{area:2279}, Live side"] = "{area:2279}, lebende Seite",
		["{area:2279}, Undead side"] = "{area:2279}, untote Seite",
		["{area:717}: the usual last kill; the {area:717} has no fixed final boss"] = "{area:717}: der übliche letzte Kill; das {area:717} hat keinen festen Endboss",
		["{area:718} (appears after the {npc:3678}'s event)"] = "{area:718} (erscheint nach dem Ereignis des {npc:3678})",
		["{area:796}: Armory"] = "{area:796}: Waffenkammer",
		["{area:796}: Cathedral"] = "{area:796}: Kathedrale",
		["{area:796}: Graveyard"] = "{area:796}: Friedhof",
		["{area:796}: Library"] = "{area:796}: Bibliothek",
		["{npc:16012} then offers your class's Saving the Best for Last, the final upgrade of the dungeon set."] = "{npc:16012} bietet dann Das Beste gibt's zum Schluss deiner Klasse an, die letzte Aufwertung des Dungeonsets.",
		["{npc:16013} then offers your class's Saving the Best for Last, the final upgrade of the dungeon set."] = "{npc:16013} bietet dann Das Beste gibt's zum Schluss deiner Klasse an, die letzte Aufwertung des Dungeonsets.",
		["{npc:16033} offers it once {quest:8996} is turned in"] = "{npc:16033} bietet sie an, sobald {quest:8996} abgegeben ist",
} end)()
t.guides["forever/professions/alchemy"] = (function() return {
		["Apprentice {skill:171}"] = "Lehrling: {skill:171}",
