		["{npc:12096}: Irondeep and {item:17542} from the mines"] = "{npc:12096}: Irondeep und {item:17542} aus den Minen",
		["{npc:12097}: Coldtooth and {item:17522} from the mines"] = "{npc:12097}: Coldtooth und {item:17522} aus den Minen",
